DROP TABLE IF EXISTS agente_juridico CASCADE;
CREATE TABLE agente_juridico (
    id INTEGER NOT NULL DEFAULT nextval('agente_juridico_id_seq'::regclass),
    nome VARCHAR(100) NOT NULL,
    classe VARCHAR(100) NOT NULL,
    descricao TEXT,
    detalhes_tecnicos TEXT,
    categoria_id INTEGER,
    nivel_especializacao INTEGER,
    ativo BOOLEAN,
    data_criacao TIMESTAMP,
    data_atualizacao TIMESTAMP,
    nivel VARCHAR(50),
    modelo_ai VARCHAR(50),
    temperatura DOUBLE PRECISION,
    top_p DOUBLE PRECISION,
    top_k INTEGER,
    max_tokens INTEGER,
    icone VARCHAR(100),
    cor_destaque VARCHAR(20),
    template_prompt TEXT,
    modo_fragmentacao VARCHAR(20),
    identificador_segmento VARCHAR(10),
    comprimento_max_fragmento INTEGER,
    sobreposicao_blocos INTEGER,
    comprimento_fragmento_filho INTEGER,
    preprocessamento_texto BOOLEAN,
    capacidades JSON,
    provider VARCHAR(50) DEFAULT 'openai'::character varying,
    tokens_entrada_max INTEGER DEFAULT 4000,
    tokens_saida_max INTEGER DEFAULT 1000,
    timeout INTEGER DEFAULT 30,
    retry_attempts INTEGER DEFAULT 3,
    max_tokens_resposta INTEGER DEFAULT 2000,
    filho_pedaco_recuperacao BOOLEAN DEFAULT false,
    ai_description TEXT,
    ai_assistant_ativo BOOLEAN DEFAULT true,
    base_vetorial_ativa BOOLEAN DEFAULT false,
    processamento_inteligente BOOLEAN DEFAULT true,
    documentos_contexto INTEGER DEFAULT 5,
    threshold_relevancia NUMERIC DEFAULT 0.7,
    max_tokens_contexto INTEGER DEFAULT 8000,
    PRIMARY KEY (id)
);

