-- TABELA: cash_flow_categoria
-- ========================================

DROP TABLE IF EXISTS cash_flow_categoria CASCADE;
CREATE TABLE cash_flow_categoria (
    id INTEGER NOT NULL DEFAULT nextval('cash_flow_categoria_id_seq'::regclass),
    nome VARCHAR(100) NOT NULL,
    tipo VARCHAR(20) NOT NULL,
    descricao TEXT,
    ativa BOOLEAN,
    data_criacao TIMESTAMP,
    criado_por_id INTEGER,
    PRIMARY KEY (id)
);

-- Tabela cash_flow_categoria está vazia

-- ========================================
-- TABELA: cash_flow_lancamento
-- ========================================

DROP TABLE IF EXISTS cash_flow_lancamento CASCADE;
CREATE TABLE cash_flow_lancamento (
    id INTEGER NOT NULL DEFAULT nextval('cash_flow_lancamento_id_seq'::regclass),
    data_lancamento TIMESTAMP NOT NULL,
    descricao VARCHAR(255) NOT NULL,
    valor DOUBLE PRECISION NOT NULL,
    tipo VARCHAR(20) NOT NULL,
    categoria_id INTEGER,
    processo_id INTEGER,
    data_criacao TIMESTAMP,
    criado_por_id INTEGER,
    PRIMARY KEY (id)
);

-- Tabela cash_flow_lancamento está vazia

-- ========================================
-- TABELA: cash_flow_operacional
-- ========================================

DROP TABLE IF EXISTS cash_flow_operacional CASCADE;
CREATE TABLE cash_flow_operacional (
    id INTEGER NOT NULL DEFAULT nextval('cash_flow_operacional_id_seq'::regclass),
    ano INTEGER NOT NULL,
    mes INTEGER NOT NULL,
    honorarios_processos DOUBLE PRECISION NOT NULL,
    consultorias DOUBLE PRECISION NOT NULL,
    due_diligence DOUBLE PRECISION NOT NULL,
    pareceres_juridicos DOUBLE PRECISION NOT NULL,
    contratos_especiais DOUBLE PRECISION NOT NULL,
    outras_receitas DOUBLE PRECISION NOT NULL,
    custos_processuais DOUBLE PRECISION NOT NULL,
    despesas_operacionais DOUBLE PRECISION NOT NULL,
    pagamento_colaboradores DOUBLE PRECISION NOT NULL,
    impostos_taxas DOUBLE PRECISION NOT NULL,
    marketing_captacao DOUBLE PRECISION NOT NULL,
    tecnologia_sistemas DOUBLE PRECISION NOT NULL,
    outras_despesas DOUBLE PRECISION NOT NULL,
    total_entradas DOUBLE PRECISION NOT NULL,
    total_saidas DOUBLE PRECISION NOT NULL,
    resultado_operacional DOUBLE PRECISION NOT NULL,
    margem_operacional DOUBLE PRECISION NOT NULL,
    processos_quantidade INTEGER NOT NULL,
    ciclo_medio_dias INTEGER NOT NULL,
    data_criacao TIMESTAMP,
    data_atualizacao TIMESTAMP,
    criado_por_id INTEGER,
    PRIMARY KEY (id)
);

