-- ========================================
-- TABELA: categoria_juridica
-- ========================================

DROP TABLE IF EXISTS categoria_juridica CASCADE;
CREATE TABLE categoria_juridica (
    id INTEGER NOT NULL DEFAULT nextval('categoria_juridica_id_seq'::regclass),
    nome VARCHAR(100) NOT NULL,
    descricao TEXT,
    icone VARCHAR(50),
    cor VARCHAR(20),
    ativa BOOLEAN,
    created_at TIMESTAMP,
    updated_at TIMESTAMP,
    PRIMARY KEY (id)
);

