DROP TABLE IF EXISTS configuracoes_global_agente CASCADE;
CREATE TABLE configuracoes_global_agente (
    id INTEGER NOT NULL DEFAULT nextval('configuracoes_global_agente_id_seq'::regclass),
    chave VARCHAR(100) NOT NULL,
    valor TEXT NOT NULL,
    descricao TEXT,
    tipo VARCHAR(50) DEFAULT 'texto'::character varying,
    categoria VARCHAR(100) DEFAULT 'geral'::character varying,
    criado_em TIMESTAMP DEFAULT now(),
    atualizado_em TIMESTAMP DEFAULT now(),
    PRIMARY KEY (id)
);

