DROP TABLE IF EXISTS content_safety CASCADE;
CREATE TABLE content_safety (
    id INTEGER NOT NULL DEFAULT nextval('content_safety_id_seq'::regclass),
    transcricao_id INTEGER,
    text TEXT,
    label VARCHAR(100),
    confidence DOUBLE PRECISION,
    severity DOUBLE PRECISION,
    start_time INTEGER,
    end_time INTEGER,
    PRIMARY KEY (id)
);

