-- ========================================
-- TABELA: execucao_fluxo
-- ========================================

DROP TABLE IF EXISTS execucao_fluxo CASCADE;
CREATE TABLE execucao_fluxo (
    id INTEGER NOT NULL DEFAULT nextval('execucao_fluxo_id_seq'::regclass),
    fluxo_id INTEGER NOT NULL,
    usuario_id INTEGER,
    dados_entrada TEXT,
    resultado TEXT,
    status VARCHAR(20) NOT NULL,
    mensagem_erro TEXT,
    data_inicio TIMESTAMP,
    data_conclusao TIMESTAMP,
    duracao_segundos DOUBLE PRECISION,
    log_execucao TEXT,
    PRIMARY KEY (id)
);

-- Tabela execucao_fluxo está vazia

-- ========================================
-- TABELA: fluxo
-- ========================================

DROP TABLE IF EXISTS fluxo CASCADE;
CREATE TABLE fluxo (
    id INTEGER NOT NULL DEFAULT nextval('fluxo_id_seq'::regclass),
    nome VARCHAR(100) NOT NULL,
    descricao TEXT,
    agentes TEXT,
    conexoes TEXT,
    configuracao TEXT,
    ativo BOOLEAN,
    data_criacao TIMESTAMP,
    data_atualizacao TIMESTAMP,
    ultima_execucao TIMESTAMP,
    criado_por_id INTEGER,
    PRIMARY KEY (id)
);

