-- ========================================
-- TABELA: fluxo_resultado
-- ========================================

DROP TABLE IF EXISTS fluxo_resultado CASCADE;
CREATE TABLE fluxo_resultado (
    id INTEGER NOT NULL DEFAULT nextval('fluxo_resultado_id_seq'::regclass),
    uuid_resultado UUID DEFAULT gen_random_uuid(),
    fluxo_id INTEGER NOT NULL,
    input_original TEXT,
    template_gerado TEXT,
    analise_juridica TEXT,
    componentes_processados INTEGER DEFAULT 0,
    tempo_execucao VARCHAR(50),
    data_execucao TIMESTAMP DEFAULT CURRENT_TIMESTAMP,
    resultado_completo JSONB,
    status VARCHAR(20) DEFAULT 'concluido'::character varying,
    hash_resultado VARCHAR(64),
    PRIMARY KEY (id)
);

INSERT INTO fluxo_resultado (id, uuid_resultado, fluxo_id, input_original, template_gerado, analise_juridica, componentes_processados, tempo_execucao, data_execucao, resultado_completo, status, hash_resultado) VALUES (4, '4621fe71-2c85-4954-9d97-5907a674fb0c', 1, 'Análise de contrato de prestação de serviços entre empresa de tecnologia e cliente corporativo', 'CONTRATO DE PRESTAÇÃO DE SERVIÇOS TECNOLÓGICOS\n\nPARTES:\nCONTRATANTE: [Empresa Cliente]\nCONTRATADA: [Empresa de Tecnologia]\n\nOBJETO:\nPrestação de serviços de desenvolvimento de software...', 'Contrato analisado com identificação de 5 pontos críticos: 1) Cláusula de propriedade intelectual; 2) SLA inadequado; 3) Forma de pagamento; 4) Rescisão; 5) Confidencialidade. Risco: MÉDIO.', 8, '62.3s', '2025-07-22 18:45:00', '{"conformidade": "parcial", "areas_juridicas": ["direito_empresarial", "direito_digital"], "clausulas_analisadas": 15}', 'concluido', 'hash_original_001');
