-- ========================================
-- TABELA: legal_areas_juridicas
-- ========================================

DROP TABLE IF EXISTS legal_areas_juridicas CASCADE;
CREATE TABLE legal_areas_juridicas (
    id INTEGER NOT NULL DEFAULT nextval('legal_areas_juridicas_id_seq'::regclass),
    nome VARCHAR(100) NOT NULL,
    icone VARCHAR(50) NOT NULL,
    descricao TEXT,
    cor_tema VARCHAR(7),
    ativo BOOLEAN,
    ordem_exibicao INTEGER,
    criado_em TIMESTAMP,
    PRIMARY KEY (id)
);

