-- TABELA: legal_design_pieces
-- ========================================

DROP TABLE IF EXISTS legal_design_pieces CASCADE;
CREATE TABLE legal_design_pieces (
    id INTEGER NOT NULL DEFAULT nextval('legal_design_pieces_id_seq'::regclass),
    user_id INTEGER NOT NULL,
    title VARCHAR(255) NOT NULL,
    content TEXT,
    piece_type VARCHAR(100),
    area_juridica VARCHAR(100),
    created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,
    updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,
    PRIMARY KEY (id)
);

