28', '21324.00', NULL, NULL, NULL, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, '2025-08-15 21:44:36.456786+00:00', '2025-08-15 21:44:36.456787+00:00', 1, '34.826.197/0001-34', NULL, NULL, 'Arquivado', 'Passivo', 'Martins S/A Consultoria Estratégica EPP', NULL, NULL, NULL, NULL, NULL, NULL, 'Instrução', FALSE, NULL, NULL, NULL, NULL, NULL, NULL, '89.890.234/0001-98', 4, NULL, NULL, NULL, NULL, '61.77', NULL, '240.98', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, FALSE, NULL, '692.23', '285.70', '236.97', NULL, NULL, '2088.86', '15039.81', '0.5058', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
