SE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, TRUE, TRUE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, '2025-08-14 01:47:59.491182+00:00', '2025-08-14 01:47:59.491182+00:00', 1, NULL, NULL, NULL, 'Aguardando decisão', 'Passivo', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'Contestação', FALSE, NULL, NULL, NULL, 'Improcedente', NULL, NULL, '67.600.012/0001-66', 1, NULL, NULL, NULL, NULL, '83.13', NULL, '1105.95', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, FALSE, NULL, '10735.78', '4690.07', '3429.38', NULL, NULL, '42106.56', '152636.27', '0.5821', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
