, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, TRUE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, '2025-08-14 01:47:59.491182+00:00', '2025-08-14 01:47:59.491182+00:00', 1, NULL, NULL, NULL, 'Em andamento', 'Passivo', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'Contestação', FALSE, NULL, NULL, NULL, 'Procedente', NULL, NULL, '90.900.345/0001-99', 1, NULL, NULL, NULL, NULL, '68.11', NULL, '7861.16', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, FALSE, NULL, '12577.97', '6920.43', '9296.27', NULL, NULL, '119654.80', '211696.95', '0.9404', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
