 taxa_sucesso, tempo_tramitacao_dias, custas_processuais, honorarios_sucumbencia, motivo_encerramento, satisfacao_cliente, judit_request_id, judit_ultima_consulta, judit_dados_processo, judit_movimentacoes, judit_partes, judit_anexos, judit_monitoramento_id, judit_status_monitoramento, judit_sincronizado, remuneracao_cargo_colaborador, previsao_custos_futuros, honorarios_periciais, depositos_judiciais, data_ultimo_pagamento, projecao_gastos_fase, cenario_melhor_caso, cenario_pior_caso, indice_viabilidade_economica, recebimentos_honorarios, ciclo_financeiro_dias, capital_giro_necessario, sazonalidade_mes, produtividade_financeira, risco_concentracao, margem_lucro_caso, custo_operacional_caso, valor_honorarios_contratados, estimativa_desembolso) VALUES (44, '4455667-89.2024.1.23.0024', 'Direito Digital', 'National Bank S.A.', 'Ana Privacy Oliveira', '445.566.789-01', 'Dra. Privacy Law', 'Data Controller', '2025-08-14 01:49:55.843331+00:00', '2024-04-18 00:00:00+00:00', 'DF', 'Brasília', '1ª Vara Federal Digital', 'Ação de indenização por danos morais decorrentes de vazamento de dados pessoais em plataforma digital. Empresa não adotou medidas de segurança.
A plataforma de e-commerce sofreu ataque cibernético resultando na exposição de dados de 15.000 usuários, incluindo CPF, endereços e cartões.
A empresa não notificou os usuários no prazo legal nem implementou protocolos adequados de segurança para proteção das informações.
Os dados vazados foram disponibilizados em fóruns da internet, resultando em tentativas de fraude e uso indevido das informações.
O autor sofreu prejuízos financeiros e teve seu nome negativado devido a transações fraudulentas realizadas com seus dados pessoais.
Requer-se indenização por danos morais e materiais, além da implementação obrigatória de medidas de segurança adequadas.', '65000.00', NULL, NULL, NULL, NULL, '5901.43', 'Médio', NULL, '19473.01', '6338.48', NULL, NULL, NULL, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, '2025-08-14 01:49:55.843331+00:00', '2025-08-14 01:49:55.843331+00:00', 1, NULL, NULL, NULL, 'Aguardando decisão', 'Passivo', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'Inicial', FALSE, NULL, NULL, NULL, 'Obrigação de fazer', NULL, NULL, '45.400.890/0001-44', 1, NULL, NULL, NULL, NULL, '61.39', NULL, '1198.96', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, FALSE, NULL, '4484.51', '2223.75', '2328.80', NULL, NULL, '26000.00', '94250.00', '0.7697', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
