Requer-se o reconhecimento judicial da usucapião com registro da propriedade em nome do autor consolidando situação fática.', '363123.93', '466621.55', '213987.55', '241797.34', NULL, '32715.47', 'Médio', NULL, '55689.56', '30515.08', NULL, NULL, NULL, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, '2025-08-15 21:44:38.057004+00:00', '2025-08-15 21:44:38.057004+00:00', 1, '18.907.235/0001-27', NULL, NULL, 'Recurso', 'Passivo', 'Sampaio Consultoria Estratégica ME', NULL, NULL, NULL, NULL, NULL, NULL, 'Contestação', FALSE, NULL, NULL, NULL, NULL, NULL, NULL, '67.670.012/0001-76', 4, NULL, NULL, NULL, NULL, '62.89', NULL, '9698.38', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, FALSE, NULL, '26541.24', '16628.97', '7555.12', NULL, NULL, '145249.57', '526529.70', '0.7876', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
