LL, '54088.59', '45992.25', NULL, NULL, NULL, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, TRUE, TRUE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, TRUE, '2025-08-14 01:47:46.441654+00:00', '2025-08-14 01:47:46.441654+00:00', 1, '23.456.789/0001-01', NULL, NULL, 'Recurso', 'Passivo', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'Instrução', FALSE, NULL, NULL, NULL, 'Arquivado', NULL, NULL, '23.200.678/0001-22', 1, NULL, NULL, NULL, NULL, '71.61', NULL, '6805.37', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, FALSE, NULL, '9254.15', '11905.20', '6852.06', NULL, NULL, '58745.61', '422968.39', '0.4928', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
