NULL, NULL, NULL, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, '2025-08-15 21:44:36.961667+00:00', '2025-08-15 21:44:36.961667+00:00', 1, '79.362.108/0001-84', NULL, NULL, 'Ausência', 'Passivo', 'Cardoso S/A Logística Avançada ME', NULL, NULL, NULL, NULL, NULL, NULL, 'Instrução', FALSE, NULL, NULL, NULL, NULL, NULL, NULL, '01.010.456/0001-10', 4, NULL, NULL, NULL, NULL, '66.48', NULL, '44923.00', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, FALSE, NULL, '141104.98', '25443.60', '40991.47', NULL, NULL, '641274.74', '1134563.00', '0.8219', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
