ULL, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, '2025-08-14 01:49:25.909143+00:00', '2025-08-14 01:49:25.909143+00:00', 1, '34.567.890/0001-12', NULL, NULL, 'Em andamento', 'Passivo', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'Inicial', FALSE, NULL, NULL, NULL, 'Quitado', NULL, NULL, '34.300.789/0001-33', 1, NULL, NULL, NULL, NULL, '75.40', NULL, '54634.46', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, FALSE, NULL, '164607.36', '58253.93', '57194.23', NULL, NULL, '1170000.00', '2070000.00', '0.9325', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
