ULL, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, '2025-08-14 01:49:25.909143+00:00', '2025-08-14 01:49:25.909143+00:00', 1, '45.678.901/0001-23', NULL, NULL, 'Aguardando decisão', 'Passivo', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'Inicial', FALSE, NULL, NULL, NULL, 'Acordo', NULL, NULL, '45.400.890/0001-44', 1, NULL, NULL, NULL, NULL, '75.48', NULL, '4247.04', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, FALSE, NULL, '15321.85', '11756.90', '31252.29', NULL, NULL, '140000.00', '507500.00', '0.6199', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
