E, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, '2025-08-14 01:47:46.441654+00:00', '2025-08-14 01:47:46.441654+00:00', 1, '56.789.012/0001-34', NULL, NULL, 'Recurso', 'Passivo', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'Instrução', FALSE, NULL, NULL, NULL, 'Extinto', NULL, NULL, '56.500.901/0001-55', 1, NULL, NULL, NULL, NULL, '82.94', NULL, '12037.89', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, FALSE, NULL, '46501.73', '20572.50', '13379.33', NULL, NULL, '111951.10', '806047.88', '0.4685', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
