L, NULL, NULL, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, '2025-08-15 21:44:37.213643+00:00', '2025-08-15 21:44:37.213643+00:00', 1, '68.123.509/0001-65', NULL, NULL, 'Em andamento', 'Passivo', 'Almeida Gestão Patrimonial EIRELI', NULL, NULL, NULL, NULL, NULL, NULL, 'Instrução', FALSE, NULL, NULL, NULL, NULL, NULL, NULL, '67.670.012/0001-76', 4, NULL, NULL, NULL, NULL, '74.74', NULL, '15673.03', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, FALSE, NULL, '33172.58', '19294.93', '36497.33', NULL, NULL, '155785.75', '564723.34', '0.7369', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
