E, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, '2025-08-15 21:44:36.037141+00:00', '2025-08-15 21:44:36.037142+00:00', 1, '24.681.357/0001-99', NULL, NULL, 'Suspenso', 'Passivo', 'Ramos S/A Logística Avançada Ltda', NULL, NULL, NULL, NULL, NULL, NULL, 'Contestação', FALSE, NULL, NULL, NULL, NULL, NULL, NULL, '90.900.345/0001-99', 4, NULL, NULL, NULL, NULL, '69.00', NULL, '6629.21', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, FALSE, NULL, '15591.17', '4905.74', '10581.76', NULL, NULL, '58059.57', '210465.93', '0.7023', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
