 taxa_sucesso, tempo_tramitacao_dias, custas_processuais, honorarios_sucumbencia, motivo_encerramento, satisfacao_cliente, judit_request_id, judit_ultima_consulta, judit_dados_processo, judit_movimentacoes, judit_partes, judit_anexos, judit_monitoramento_id, judit_status_monitoramento, judit_sincronizado, remuneracao_cargo_colaborador, previsao_custos_futuros, honorarios_periciais, depositos_judiciais, data_ultimo_pagamento, projecao_gastos_fase, cenario_melhor_caso, cenario_pior_caso, indice_viabilidade_economica, recebimentos_honorarios, ciclo_financeiro_dias, capital_giro_necessario, sazonalidade_mes, produtividade_financeira, risco_concentracao, margem_lucro_caso, custo_operacional_caso, valor_honorarios_contratados, estimativa_desembolso) VALUES (83, '0002009-99.2024.8.26.0009', 'Direito Digital', 'FinanceBank S.A.', 'Usuário Digital', '999.000.111-22', 'Dr. Digital', 'Dra. Tech Legal', '2025-08-14 07:04:58.866410+00:00', '2024-08-10 00:00:00+00:00', 'DF', 'Brasília', 'Vara Cível Tecnológica', 'Ação de indenização por danos morais decorrentes de vazamento de dados pessoais em plataforma digital. Empresa não adotou medidas de segurança.
A plataforma de e-commerce sofreu ataque cibernético resultando na exposição de dados de 15.000 usuários, incluindo CPF, endereços e cartões.
A empresa não notificou os usuários no prazo legal nem implementou protocolos adequados de segurança para proteção das informações.
Os dados vazados foram disponibilizados em fóruns da internet, resultando em tentativas de fraude e uso indevido das informações.
O autor sofreu prejuízos financeiros e teve seu nome negativado devido a transações fraudulentas realizadas com seus dados pessoais.
Requer-se indenização por danos morais e materiais, além da implementação obrigatória de medidas de segurança adequadas.', '95000.00', '0.00', '0.00', NULL, NULL, '2410.75', 'Alto', NULL, '16102.92', '15184.92', NULL, NULL, NULL, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, '2025-08-14 07:04:58.866410+00:00', '2025-08-14 07:04:58.866410+00:00', 1, '99.111.222/0001-22', NULL, NULL, 'Recurso', 'Passivo', 'Tech Startup Ltda', NULL, NULL, NULL, NULL, NULL, NULL, 'Inicial', FALSE, NULL, NULL, NULL, 'Extinto', NULL, NULL, '34.300.789/0001-33', 4, NULL, NULL, NULL, NULL, '66.80', NULL, '1254.36', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, FALSE, NULL, '5239.17', '1537.29', '7230.76', NULL, NULL, '23750.00', '171000.00', '0.5209', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
