E, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, '2025-08-15 21:44:36.836547+00:00', '2025-08-15 21:44:36.836548+00:00', 1, '98.234.710/0001-80', NULL, NULL, 'Arquivado', 'Passivo', 'Leão Energia Renovável ME', NULL, NULL, NULL, NULL, NULL, NULL, 'Denúncia', FALSE, NULL, NULL, NULL, NULL, NULL, NULL, '89.800.234/0001-88', 5, NULL, NULL, NULL, NULL, '84.07', NULL, '2573.86', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, FALSE, NULL, '18819.63', '2577.12', '19740.28', NULL, NULL, '152376.24', '269588.73', '0.8203', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
