 taxa_sucesso, tempo_tramitacao_dias, custas_processuais, honorarios_sucumbencia, motivo_encerramento, satisfacao_cliente, judit_request_id, judit_ultima_consulta, judit_dados_processo, judit_movimentacoes, judit_partes, judit_anexos, judit_monitoramento_id, judit_status_monitoramento, judit_sincronizado, remuneracao_cargo_colaborador, previsao_custos_futuros, honorarios_periciais, depositos_judiciais, data_ultimo_pagamento, projecao_gastos_fase, cenario_melhor_caso, cenario_pior_caso, indice_viabilidade_economica, recebimentos_honorarios, ciclo_financeiro_dias, capital_giro_necessario, sazonalidade_mes, produtividade_financeira, risco_concentracao, margem_lucro_caso, custo_operacional_caso, valor_honorarios_contratados, estimativa_desembolso) VALUES (169, '4842076-19.2020.5.01.8555', 'Negociação e Conflitos', 'ArbitragemTech S.A.', 'Liam Novais', '972.140.538-88', 'Dr(a). Isabel Fernandes', 'Dr(a). Maitê das Neves', '2025-08-15 21:44:39.407483+00:00', '2024-05-24 00:00:00+00:00', 'MG', 'Belo Horizonte', 'Vara Judicial de Belo Horizonte', 'Ação de mediação empresarial para resolução de conflito societário entre sócios de empresa familiar. Divergências impedem continuidade.
A empresa familiar possui dois sócios com participação de 50% cada, que desenvolveram conflitos irreconciliáveis sobre gestão.
As divergências envolvem estratégias de investimento, distribuição de lucros e contratação de funcionários para expansão dos negócios.
Tentativas internas de composição falharam devido à rigidez das posições e ausência de diálogo construtivo entre as partes.
O impasse prejudica significativamente as operações da empresa e gera insegurança para funcionários e clientes estratégicos.
Requer-se a instauração de processo de mediação para buscar solução consensual que preserve a continuidade empresarial.', '227773.19', '243934.41', '96399.17', '198170.64', NULL, '6584.64', 'Alto', NULL, '53156.50', '40936.24', NULL, NULL, NULL, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, '2025-08-15 21:44:39.407483+00:00', '2025-08-15 21:44:39.407484+00:00', 1, '17.943.280/0001-74', NULL, NULL, 'Extinto', 'Passivo', 'Farias Porto - ME Consultoria Estratégica S/A', NULL, NULL, NULL, NULL, NULL, NULL, 'Denúncia', FALSE, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 4, NULL, NULL, NULL, NULL, '73.41', NULL, '3175.87', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, FALSE, NULL, '24570.21', '5465.21', '22289.94', NULL, NULL, '56943.30', '409991.74', '0.4577', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
