, NULL, NULL, NULL, FALSE, FALSE, FALSE, FALSE, TRUE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, TRUE, TRUE, TRUE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, TRUE, '2025-08-14 01:47:46.441654+00:00', '2025-08-14 01:47:46.441654+00:00', 1, '12.345.678/0001-90', NULL, NULL, 'Aguardando decisão', 'Passivo', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'Instrução', FALSE, NULL, NULL, NULL, 'Administrativo', NULL, NULL, '12.100.567/0001-11', 1, NULL, NULL, NULL, NULL, '73.11', NULL, '8704.79', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, FALSE, NULL, '9278.27', '10550.47', '8378.79', NULL, NULL, '93274.38', '338119.63', '0.7298', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
