LSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, '2025-08-15 21:44:36.541248+00:00', '2025-08-15 21:44:36.541248+00:00', 1, '72.810.394/0001-54', NULL, NULL, 'Ausência', 'Passivo', 'Albuquerque Santos Ltda. Indústria e Produção S/A', NULL, NULL, NULL, NULL, NULL, NULL, 'Contestação', FALSE, NULL, NULL, NULL, NULL, NULL, NULL, '12.100.567/0001-11', 4, NULL, NULL, NULL, NULL, '77.88', NULL, '7880.79', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, FALSE, NULL, '21293.50', '5853.31', '13552.64', NULL, NULL, '44429.97', '319895.80', '0.5011', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
