E, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, '2025-08-15 21:44:36.584206+00:00', '2025-08-15 21:44:36.584206+00:00', 1, '06.348.527/0001-98', NULL, NULL, 'Recurso', 'Passivo', 'Almeida Tecnologia e Inovação ME', NULL, NULL, NULL, NULL, NULL, NULL, 'Denúncia', FALSE, NULL, NULL, NULL, NULL, NULL, NULL, '23.200.678/0001-22', 5, NULL, NULL, NULL, NULL, '79.28', NULL, '6231.54', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, FALSE, NULL, '22290.21', '3223.74', '16426.13', NULL, NULL, '51023.51', '367369.25', '0.4220', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
