SE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, '2025-08-15 21:44:37.171679+00:00', '2025-08-15 21:44:37.171679+00:00', 1, '39.652.180/0001-21', NULL, NULL, 'Extinto', 'Passivo', 'Aragão Rocha S.A. Indústria e Produção S/A', NULL, NULL, NULL, NULL, NULL, NULL, 'Instrução', FALSE, NULL, NULL, NULL, NULL, NULL, NULL, '56.560.901/0001-65', 5, NULL, NULL, NULL, NULL, '75.82', NULL, '9398.09', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, FALSE, NULL, '20440.48', '9192.68', '21772.84', NULL, NULL, '97262.85', '352577.82', '0.5692', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
