'47560.83', NULL, NULL, NULL, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, '2025-08-15 21:44:37.045138+00:00', '2025-08-15 21:44:37.045138+00:00', 1, '72.189.560/0001-47', NULL, NULL, 'Arquivado', 'Passivo', 'Jesus Soluções Digitais EPP', NULL, NULL, NULL, NULL, NULL, NULL, 'Contestação', FALSE, NULL, NULL, NULL, NULL, NULL, NULL, '23.230.678/0001-32', 4, NULL, NULL, NULL, NULL, '66.32', NULL, '4858.19', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, FALSE, NULL, '34494.90', '17820.98', '22033.76', NULL, NULL, '186772.13', '677048.98', '0.6173', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
