 taxa_sucesso, tempo_tramitacao_dias, custas_processuais, honorarios_sucumbencia, motivo_encerramento, satisfacao_cliente, judit_request_id, judit_ultima_consulta, judit_dados_processo, judit_movimentacoes, judit_partes, judit_anexos, judit_monitoramento_id, judit_status_monitoramento, judit_sincronizado, remuneracao_cargo_colaborador, previsao_custos_futuros, honorarios_periciais, depositos_judiciais, data_ultimo_pagamento, projecao_gastos_fase, cenario_melhor_caso, cenario_pior_caso, indice_viabilidade_economica, recebimentos_honorarios, ciclo_financeiro_dias, capital_giro_necessario, sazonalidade_mes, produtividade_financeira, risco_concentracao, margem_lucro_caso, custo_operacional_caso, valor_honorarios_contratados, estimativa_desembolso) VALUES (19, '9999999-99.2024.3.04.0004', 'Direito Tributário', 'ShopCenter S.A.', 'Lucia Contribuinte Costa', '012.345.678-99', 'Dra. Carla Fazendária', 'Fazenda Municipal', '2025-08-14 01:48:57.532206+00:00', '2024-04-22 00:00:00+00:00', 'RS', 'Porto Alegre', '1ª Vara Fazenda Pública POA', 'Mandado de segurança contra fechamento de empresa por débitos trabalhistas. Empresa de segurança com débitos previdenciários de R$ 180.000,00 teve estabelecimento lacrado pela Receita Federal sem observância do devido processo legal. Medida desproporcional considerando que empresa possui parcelamento em dia (apenas 2 parcelas em atraso), mantém 45 empregos, presta serviços essenciais. Lacração gerou impossibilidade de cumprimento de contratos, demissão em massa, agravamento da situação financeira. Empresa ofereceu garantias reais para manutenção do parcelamento, não foi aceito. Procedimento de lacração sem intimação prévia, oportunidade de defesa. Pleiteia-se desconstituição da lacração, restauração das atividades, danos morais pela medida abusiva. Questões: proporcionalidade da medida, devido processo legal, interesse público, preservação do emprego.', '137917.97', '50000.00', '45000.00', NULL, NULL, '12318.70', 'Baixo', NULL, '35860.33', '17044.50', NULL, NULL, NULL, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, '2025-08-14 01:48:57.532206+00:00', '2025-08-14 01:48:57.532206+00:00', 1, '90.123.456/0001-78', NULL, NULL, 'Em andamento', 'Passivo', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'Inicial', FALSE, NULL, NULL, NULL, 'Não é parte', NULL, NULL, '89.890.234/0001-98', 1, NULL, NULL, NULL, NULL, '69.52', NULL, '5114.50', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, FALSE, NULL, '10804.85', '7469.32', '4537.31', NULL, NULL, '89646.68', '158605.67', '0.9291', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
