', NULL, '14295.25', '24698.05', NULL, NULL, NULL, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, '2025-08-14 01:48:57.532206+00:00', '2025-08-14 01:48:57.532206+00:00', 1, '67.890.123/0001-45', NULL, NULL, 'Recurso', 'Passivo', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'Inicial', FALSE, NULL, NULL, NULL, 'Exclusão da Lide', NULL, NULL, '56.560.901/0001-65', 1, NULL, NULL, NULL, NULL, '66.53', NULL, '5393.78', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, FALSE, NULL, '7243.06', '5927.75', '6560.41', NULL, NULL, '34323.34', '247128.05', '0.5894', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
