LSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, '2025-08-15 21:44:37.086706+00:00', '2025-08-15 21:44:37.086706+00:00', 1, '18.734.256/0001-98', NULL, NULL, 'Extinto', 'Passivo', 'Rios Nascimento - ME Alimentação e Bebidas EIRELI', NULL, NULL, NULL, NULL, NULL, NULL, 'Denúncia', FALSE, NULL, NULL, NULL, NULL, NULL, NULL, '34.340.789/0001-43', 5, NULL, NULL, NULL, NULL, '67.40', NULL, '1497.25', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, FALSE, NULL, '7259.42', '1914.77', '1713.26', NULL, NULL, '24830.86', '90011.85', '0.7068', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
