LSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, '2025-08-14 07:04:58.866410+00:00', '2025-08-14 07:04:58.866410+00:00', 1, '44.555.666/0001-77', NULL, NULL, 'Aguardando decisão', 'Passivo', 'Comércio ABC S.A.', NULL, NULL, NULL, NULL, NULL, NULL, 'Inicial', FALSE, NULL, NULL, NULL, 'Quitado', NULL, NULL, '78.780.123/0001-87', 5, NULL, NULL, NULL, NULL, '71.42', NULL, '3821.10', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, FALSE, NULL, '9871.07', '976.21', '5048.92', NULL, NULL, '31462.28', '114050.78', '0.7850', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
