 taxa_sucesso, tempo_tramitacao_dias, custas_processuais, honorarios_sucumbencia, motivo_encerramento, satisfacao_cliente, judit_request_id, judit_ultima_consulta, judit_dados_processo, judit_movimentacoes, judit_partes, judit_anexos, judit_monitoramento_id, judit_status_monitoramento, judit_sincronizado, remuneracao_cargo_colaborador, previsao_custos_futuros, honorarios_periciais, depositos_judiciais, data_ultimo_pagamento, projecao_gastos_fase, cenario_melhor_caso, cenario_pior_caso, indice_viabilidade_economica, recebimentos_honorarios, ciclo_financeiro_dias, capital_giro_necessario, sazonalidade_mes, produtividade_financeira, risco_concentracao, margem_lucro_caso, custo_operacional_caso, valor_honorarios_contratados, estimativa_desembolso) VALUES (139, '3407081-53.2024.8.26.5896', 'Direito Imobiliário', 'ShopCenter S.A.', 'Lunna Fernandes', '654.897.230-92', 'Dr(a). Maria Clara Cavalcanti', 'Dr(a). Maria Fernanda Brito', '2025-08-15 21:44:38.141076+00:00', '2024-06-13 00:00:00+00:00', 'SP', 'Santos', 'Vara de Registros Públicos de Santos', 'Ação de usucapião extraordinária de bem imóvel urbano localizado em área central da cidade. Autor exerce posse há 18 anos ininterruptos.
A posse é exercida com animus domini, realizando benfeitorias significativas, pagando impostos e utilizando como residência familiar exclusiva.
Durante todo o período, não houve qualquer oposição do proprietário registral nem interferência de terceiros interessados no imóvel.
Foram realizadas melhorias substanciais: construção de casa de 200m², muro, garagem, jardim e instalação de infraestrutura completa.
A posse é pública, pacífica, contínua e de boa-fé, atendendo rigorosamente todos os requisitos legais para usucapião.
Requer-se o reconhecimento judicial da usucapião com registro da propriedade em nome do autor consolidando situação fática.', '69820.46', '81216.18', '42815.79', '76715.41', NULL, '5598.42', 'Alto', NULL, '16411.98', '5092.63', NULL, NULL, NULL, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, '2025-08-15 21:44:38.141077+00:00', '2025-08-15 21:44:38.141077+00:00', 1, '38.615.720/0001-34', NULL, NULL, 'Ausência', 'Passivo', 'Cavalcante Comércio e Distribuição ME', NULL, NULL, NULL, NULL, NULL, NULL, 'Denúncia', FALSE, NULL, NULL, NULL, NULL, NULL, NULL, '89.890.234/0001-98', 4, NULL, NULL, NULL, NULL, '74.94', NULL, '1860.04', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, FALSE, NULL, '4311.33', '3259.97', '3952.56', NULL, NULL, '17455.12', '125676.83', '0.4078', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
