ALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, '2025-08-14 01:49:25.909143+00:00', '2025-08-14 01:49:25.909143+00:00', 1, '23.456.789/0001-01', NULL, NULL, 'Aguardando decisão', 'Passivo', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'Inicial', FALSE, NULL, NULL, NULL, 'Procedente em parte', NULL, NULL, '23.200.678/0001-22', 1, NULL, NULL, NULL, NULL, '80.44', NULL, '38213.31', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, FALSE, NULL, '93234.69', '139324.42', '203790.70', NULL, NULL, '1000000.00', '3625000.00', '0.5689', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
