, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, '2025-08-15 21:44:36.414889+00:00', '2025-08-15 21:44:36.414889+00:00', 1, '01.267.493/0001-93', NULL, NULL, 'Suspenso', 'Passivo', 'Alves Vieira S/A Metalurgia Industrial Ltda', NULL, NULL, NULL, NULL, NULL, NULL, 'Instrução', FALSE, NULL, NULL, NULL, NULL, NULL, NULL, '78.780.123/0001-87', 5, NULL, NULL, NULL, NULL, '74.44', NULL, '1195.10', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, FALSE, NULL, '1748.52', '1029.22', '1686.34', NULL, NULL, '11047.84', '40048.41', '0.6595', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
