o', NULL, '132313.84', '74540.67', NULL, NULL, NULL, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, '2025-08-14 01:49:25.909143+00:00', '2025-08-14 01:49:25.909143+00:00', 1, '12.345.678/0001-90', NULL, NULL, 'Recurso', 'Passivo', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'Inicial', FALSE, NULL, NULL, NULL, 'Procedente', NULL, NULL, '12.100.567/0001-11', 1, NULL, NULL, NULL, NULL, '84.11', NULL, '8093.80', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, FALSE, NULL, '16425.44', '12737.71', '15846.43', NULL, NULL, '125000.00', '900000.00', '0.5188', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
