 FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, '2025-08-15 21:44:36.794877+00:00', '2025-08-15 21:44:36.794877+00:00', 1, '35.970.268/0001-30', NULL, NULL, 'Ausência', 'Passivo', 'Fogaça Silva S/A Comércio e Distribuição EPP', NULL, NULL, NULL, NULL, NULL, NULL, 'Contestação', FALSE, NULL, NULL, NULL, NULL, NULL, NULL, '78.700.123/0001-77', 4, NULL, NULL, NULL, NULL, '60.27', NULL, '5269.35', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, FALSE, NULL, '15547.93', '6638.98', '8517.66', NULL, NULL, '49009.54', '352868.69', '0.5463', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
