 taxa_sucesso, tempo_tramitacao_dias, custas_processuais, honorarios_sucumbencia, motivo_encerramento, satisfacao_cliente, judit_request_id, judit_ultima_consulta, judit_dados_processo, judit_movimentacoes, judit_partes, judit_anexos, judit_monitoramento_id, judit_status_monitoramento, judit_sincronizado, remuneracao_cargo_colaborador, previsao_custos_futuros, honorarios_periciais, depositos_judiciais, data_ultimo_pagamento, projecao_gastos_fase, cenario_melhor_caso, cenario_pior_caso, indice_viabilidade_economica, recebimentos_honorarios, ciclo_financeiro_dias, capital_giro_necessario, sazonalidade_mes, produtividade_financeira, risco_concentracao, margem_lucro_caso, custo_operacional_caso, valor_honorarios_contratados, estimativa_desembolso) VALUES (143, '3710854-28.2024.5.02.5330', 'Direito Digital', 'FinanceBank S.A.', 'Thales Oliveira', '980.746.235-56', 'Dr(a). Joana Rocha', 'Dr(a). Anthony Gabriel Fernandes', '2025-08-15 21:44:38.310488+00:00', '2025-06-11 00:00:00+00:00', 'MG', 'Uberlândia', 'Vara Judicial de Uberlândia', 'Ação de indenização por danos morais decorrentes de vazamento de dados pessoais em plataforma digital. Empresa não adotou medidas de segurança.
A plataforma de e-commerce sofreu ataque cibernético resultando na exposição de dados de 15.000 usuários, incluindo CPF, endereços e cartões.
A empresa não notificou os usuários no prazo legal nem implementou protocolos adequados de segurança para proteção das informações.
Os dados vazados foram disponibilizados em fóruns da internet, resultando em tentativas de fraude e uso indevido das informações.
O autor sofreu prejuízos financeiros e teve seu nome negativado devido a transações fraudulentas realizadas com seus dados pessoais.
Requer-se indenização por danos morais e materiais, além da implementação obrigatória de medidas de segurança adequadas.', '74063.93', '89222.94', '0.00', '0.00', NULL, '7185.54', 'Alto', NULL, '18432.52', '7610.95', NULL, NULL, NULL, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, '2025-08-15 21:44:38.310488+00:00', '2025-08-15 21:44:38.310488+00:00', 1, '79.018.653/0001-58', NULL, NULL, 'Suspenso', 'Passivo', 'Moreira Engenharia Especializada ME', NULL, NULL, NULL, NULL, NULL, NULL, 'Contestação', FALSE, NULL, NULL, NULL, NULL, NULL, NULL, '34.300.789/0001-33', 4, NULL, NULL, NULL, NULL, '72.41', NULL, '1994.42', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, FALSE, NULL, '4154.54', '3786.06', '1877.66', NULL, NULL, '18515.98', '133315.07', '0.4828', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
