E, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, '2025-08-15 21:44:36.878188+00:00', '2025-08-15 21:44:36.878188+00:00', 1, '69.401.325/0001-82', NULL, NULL, 'Em andamento', 'Passivo', 'Cavalcante Metalurgia Industrial S/A', NULL, NULL, NULL, NULL, NULL, NULL, 'Denúncia', FALSE, NULL, NULL, NULL, NULL, NULL, NULL, '90.900.345/0001-99', 4, NULL, NULL, NULL, NULL, '77.84', NULL, '35782.88', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, FALSE, NULL, '235584.34', '96825.46', '162091.48', NULL, NULL, '752776.74', '2728815.70', '0.7565', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
