 FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, '2025-08-14 02:07:26.159129+00:00', '2025-08-14 02:07:26.159129+00:00', 1, '23.456.789/0001-01', NULL, NULL, 'Recurso', 'Passivo', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'Instrução', FALSE, NULL, NULL, NULL, 'Acordo', NULL, NULL, '12.120.567/0001-21', 5, NULL, NULL, NULL, NULL, '79.37', NULL, '11854.78', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, FALSE, NULL, '27503.16', '12876.89', '23209.59', NULL, NULL, '59566.20', '428876.64', '0.5684', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
