DROP TABLE IF EXISTS propriedades_rurais CASCADE;
CREATE TABLE propriedades_rurais (
    id INTEGER NOT NULL DEFAULT nextval('propriedades_rurais_id_seq'::regclass),
    cliente_id INTEGER,
    nome_propriedade TEXT,
    denominacao_popular TEXT,
