    confrontante_sul TEXT,
    extensao_sul_metros NUMERIC,
    tipo_divisa_sul VARCHAR(50),
    confrontante_leste TEXT,
    extensao_leste_metros NUMERIC,
    tipo_divisa_leste VARCHAR(50),
    confrontante_oeste TEXT,
    extensao_oeste_metros NUMERIC,
    tipo_divisa_oeste VARCHAR(50),
    rios_principais TEXT,
    corregos TEXT,
    nascentes TEXT,
    acudes_represas TEXT,
    quantidade_acudes INTEGER,
    capacidade_total_litros BIGINT,
