    tempo_posse VARCHAR(100),
    base_posse TEXT,
    acoes_judiciais BOOLEAN DEFAULT false,
    acao_usucapiao BOOLEAN DEFAULT false,
    acao_reintegracao_posse BOOLEAN DEFAULT false,
    acao_demarcatoria BOOLEAN DEFAULT false,
    acao_divisoria BOOLEAN DEFAULT false,
    acao_desapropriacao BOOLEAN DEFAULT false,
    outras_acoes TEXT,
    invasoes_ocupacoes BOOLEAN DEFAULT false,
    detalhes_invasoes TEXT,
    imovel_inventario BOOLEAN DEFAULT false,
