    inventario_situacao TEXT,
    observacoes_especiais TEXT,
    restricoes TEXT,
    potencialidades TEXT,
    projetos_expansao TEXT,
    investimentos_previstos TEXT,
    mudancas_atividade TEXT,
    engenheiro_agronomo TEXT,
    engenheiro_crea VARCHAR(50),
    veterinario TEXT,
    veterinario_crmv VARCHAR(50),
    topografo TEXT,
