    data_atualizacao TIMESTAMP DEFAULT now(),
    responsavel_cadastro VARCHAR(100),
    status_propriedade VARCHAR(20) DEFAULT 'Ativa'::character varying,
    implementos_arados TEXT,
    implementos_grades TEXT,
    implementos_plantadeiras TEXT,
    implementos_pulverizadores TEXT,
    implementos_colheitadeiras TEXT,
    veiculos_caminhoes TEXT,
    veiculos_caminhonetes TEXT,
    veiculos_outros TEXT,
    profundidade_pocos TEXT,
    tipos_contrato TEXT,
    onus_reais TEXT,
    doc_itr BOOLEAN DEFAULT false,
    doc_car_obrigatorio BOOLEAN DEFAULT false,
    doc_certidao_negativa_incra BOOLEAN DEFAULT false,
