-- ========================================
-- TABELA: relatorio_consenso
-- ========================================

DROP TABLE IF EXISTS relatorio_consenso CASCADE;
CREATE TABLE relatorio_consenso (
    id INTEGER NOT NULL DEFAULT nextval('relatorio_consenso_id_seq'::regclass),
    uuid_relatorio VARCHAR(36) NOT NULL,
    numero_relatorio VARCHAR(20) NOT NULL,
    analise_numero_registro VARCHAR(20) NOT NULL,
    titulo_relatorio VARCHAR(200) NOT NULL,
    descricao TEXT,
    user_id INTEGER NOT NULL,
    consenso_geral TEXT NOT NULL,
    nivel_concordancia DOUBLE PRECISION,
    pontos_convergencia JSON,
    pontos_divergencia JSON,
    analise_riscos JSON NOT NULL,
    analise_melhorias JSON NOT NULL,
    estrategias_recomendadas JSON NOT NULL,
    riscos_criticos JSON,
    riscos_moderados JSON,
    riscos_baixos JSON,
    melhorias_urgentes JSON,
    melhorias_importantes JSON,
    melhorias_sugeridas JSON,
    estrategias_curto_prazo JSON,
    estrategias_medio_prazo JSON,
    estrategias_longo_prazo JSON,
    impacto_estimado VARCHAR(20),
    viabilidade_implementacao VARCHAR(20),
    recursos_necessarios JSON,
    modelo_ia_utilizado VARCHAR(100),
    tokens_consumidos INTEGER,
    custo_estimado DOUBLE PRECISION,
    tempo_processamento DOUBLE PRECISION,
    status VARCHAR(20),
    status_mensagem TEXT,
    versao INTEGER,
    data_criacao TIMESTAMP,
    data_atualizacao TIMESTAMP,
    data_aprovacao TIMESTAMP,
    PRIMARY KEY (id)
);

INSERT INTO relatorio_consenso (id, uuid_relatorio, numero_relatorio, analise_numero_registro, titulo_relatorio, descricao, user_id, consenso_geral, nivel_concordancia, pontos_convergencia, pontos_divergencia, analise_riscos, analise_melhorias, estrategias_recomendadas, riscos_criticos, riscos_moderados, riscos_baixos, melhorias_urgentes, melhorias_importantes, melhorias_sugeridas, estrategias_curto_prazo, estrategias_medio_prazo, estrategias_longo_prazo, impacto_estimado, viabilidade_implementacao, recursos_necessarios, modelo_ia_utilizado, tokens_consumidos, custo_estimado, tempo_processamento, status, status_mensagem, versao, data_criacao, data_atualizacao, data_aprovacao) VALUES (1, '6405983f-85dc-40de-97b1-dec1462da420', 'REL-1757641482813', 'REG-1757641434', 'Relatório de Consenso - REL-1757641482813', 'Relatório de consenso gerado automaticamente', 3, 'As análises dos agentes jurídicos sobre o contrato de arrendamento rural convergem em diversos pontos fundamentais, destacando-se a conformidade geral com o Estatuto da Terra e o Decreto 59.566/66. Todos os agentes identificaram a necessidade de ajustes nas cláusulas de prazo e de descrição do imóvel, além de reforçar a importância de cláusulas ambientais robustas. A qualidade das análises é alta, com cada agente trazendo insights valiosos e complementares. A consistência entre os agentes é notável, especialmente em relação à identificação de riscos contratuais e recomendações de ajustes. As conclusões estratégicas indicam que, embora o contrato esteja bem estruturado, há espaço para melhorias que aumentem a segurança jurídica e operacional, especialmente no que tange a prazos, descrição de áreas e responsabilidades ambientais.', 85.5, '[{'ponto': 'Necessidade de correção das datas de início e término do contrato', 'agentes_concordam': ['Todos'], 'importancia': 'Alta'}, {'ponto': 'Importância de cláusulas ambientais robustas', 'agentes_concordam': ['Agente 1', 'Agente 2'], 'importancia': 'Alta'}]', '{{"divergencia": "Descrição da duplicidade de matrícula", "agente_1_visao": "Erro material que deve ser corrigido", "agente_2_visao": "Não abordado diretamente", "recomendacao": "Revisar a descrição do imóvel para eliminar duplicidade"}}', '{'criticos': [{'risco': 'Inconsistência nas datas de início e término do contrato', 'impacto': 'Alto', 'probabilidade': 'Alta', 'impacto_financeiro': 'Potencial para litígios e multas', 'prazo_manifestacao': 'Imediato ao início do contrato', 'mitigacao': 'Revisão e correção das datas no contrato', 'fundamento_legal': 'Estatuto da Terra, Art. 95'}], 'moderados': [{'risco': 'Flutuação de preços de produtos para pagamento', 'impacto': 'Médio', 'probabilidade': 'Média', 'mitigacao': 'Considerar cláusulas de ajuste ou pagamento híbrido'}], 'baixos': [{'risco': 'Possíveis disputas sobre benfeitorias', 'impacto': 'Baixo', 'probabilidade': 'Baixa', 'mitigacao': 'Incluir cláusulas claras sobre autorização de benfeitorias'}]}', '{'urgentes': [{'melhoria': 'Correção das datas de início e término do contrato', 'beneficio': 'Alinhamento com a legislação e prevenção de litígios', 'complexidade': 'Baixa', 'custo_estimado': 'Baixo', 'prazo_implementacao': 'Imediato', 'recursos_necessarios': ['Revisão jurídica'], 'roi_esperado': 'Alto'}], 'importantes': [{'melhoria': 'Inclusão de cláusulas sobre eventos climáticos e força maior', 'beneficio': 'Proteção contra riscos não controláveis', 'complexidade': 'Média'}], 'sugeridas': [{'melhoria': 'Formalização do contrato no Cartório de Registro de Imóveis', 'beneficio': 'Maior segurança jurídica', 'complexidade': 'Baixa'}]}', '{'curto_prazo': [{'estrategia': 'Revisar e corrigir as datas de vigência do contrato', 'prazo': '0-3 meses', 'responsavel': 'Equipe Jurídica', 'entregaveis': ['Contrato revisado'], 'kpis': ['Correção de inconsistências'], 'dependencias': ['Aprovação das partes']}], 'medio_prazo': [{'estrategia': 'Implementar cláusulas de força maior e eventos climáticos', 'prazo': '3-12 meses', 'responsavel': 'Consultoria Jurídica', 'entregaveis': ['Contrato atualizado']}], 'longo_prazo': [{'estrategia': 'Registrar o contrato no Cartório de Registro de Imóveis', 'prazo': '12+ meses', 'responsavel': 'Parte Arrendante', 'entregaveis': ['Contrato registrado']}]}', '{{"risco": "Inconsistência nas datas de início e término do contrato", "impacto": "Alto", "probabilidade": "Alta", "impacto_financeiro": "Potencial para litígios e multas", "prazo_manifestacao": "Imediato ao início do contrato", "mitigacao": "Revisão e correção das datas no contrato", "fundamento_legal": "Estatuto da Terra, Art. 95"}}', '{{"risco": "Flutuação de preços de produtos para pagamento", "impacto": "Médio", "probabilidade": "Média", "mitigacao": "Considerar cláusulas de ajuste ou pagamento híbrido"}}', '{{"risco": "Possíveis disputas sobre benfeitorias", "impacto": "Baixo", "probabilidade": "Baixa", "mitigacao": "Incluir cláusulas claras sobre autorização de benfeitorias"}}', '[{'melhoria': 'Correção das datas de início e término do contrato', 'beneficio': 'Alinhamento com a legislação e prevenção de litígios', 'complexidade': 'Baixa', 'custo_estimado': 'Baixo', 'prazo_implementacao': 'Imediato', 'recursos_necessarios': ['Revisão jurídica'], 'roi_esperado': 'Alto'}]', '{{"melhoria": "Inclusão de cláusulas sobre eventos climáticos e força maior", "beneficio": "Proteção contra riscos não controláveis", "complexidade": "Média"}}', '{{"melhoria": "Formalização do contrato no Cartório de Registro de Imóveis", "beneficio": "Maior segurança jurídica", "complexidade": "Baixa"}}', '[{'estrategia': 'Revisar e corrigir as datas de vigência do contrato', 'prazo': '0-3 meses', 'responsavel': 'Equipe Jurídica', 'entregaveis': ['Contrato revisado'], 'kpis': ['Correção de inconsistências'], 'dependencias': ['Aprovação das partes']}]', '[{'estrategia': 'Implementar cláusulas de força maior e eventos climáticos', 'prazo': '3-12 meses', 'responsavel': 'Consultoria Jurídica', 'entregaveis': ['Contrato atualizado']}]', '[{'estrategia': 'Registrar o contrato no Cartório de Registro de Imóveis', 'prazo': '12+ meses', 'responsavel': 'Parte Arrendante', 'entregaveis': ['Contrato registrado']}]', 'Alto', 'Alta', '{Consultoria Jurídica", "Revisão Contratual}', 'GPT-4', 0, 0.0, 21.551241397857666, 'gerado', NULL, 1, '2025-09-12 01:44:42.815685', '2025-09-12 01:44:42.815687', NULL);
INSERT INTO relatorio_consenso (id, uuid_relatorio, numero_relatorio, analise_numero_registro, titulo_relatorio, descricao, user_id, consenso_geral, nivel_concordancia, pontos_convergencia, pontos_divergencia, analise_riscos, analise_melhorias, estrategias_recomendadas, riscos_criticos, riscos_moderados, riscos_baixos, melhorias_urgentes, melhorias_importantes, melhorias_sugeridas, estrategias_curto_prazo, estrategias_medio_prazo, estrategias_longo_prazo, impacto_estimado, viabilidade_implementacao, recursos_necessarios, modelo_ia_utilizado, tokens_consumidos, custo_estimado, tempo_processamento, status, status_mensagem, versao, data_criacao, data_atualizacao, data_aprovacao) VALUES (2, 'b384ac2a-ee88-4c76-9225-3eac6baa07dc', 'REL-1757998836926', 'REG-1757998746', 'Relatório de Consenso - REL-1757998836926', 'Relatório de consenso gerado automaticamente', 3, 'As análises dos agentes jurídicos convergem em diversos pontos fundamentais do contrato de prestação de serviços de marketing digital, destacando a necessidade de maior clareza e especificidade em várias cláusulas contratuais. Todos os agentes identificaram a importância de detalhar melhor as obrigações das partes, especialmente no que diz respeito à confidencialidade e ao uso de informações para portfólio. A questão da vigência do contrato e a ausência de cláusulas de renovação automática também foram apontadas como áreas de risco. As análises são consistentes em recomendar ajustes para proteger melhor os interesses das partes, com ênfase na proteção de dados conforme a LGPD e na definição de métricas de desempenho. A qualidade das análises é alta, com cada agente trazendo insights valiosos que se complementam, resultando em uma visão abrangente e estratégica do contrato. Conclui-se que o contrato necessita de revisões para mitigar riscos jurídicos e operacionais, garantindo segurança e clareza para ambas as partes envolvidas.', 85.5, '[{'ponto': 'Necessidade de revisão das cláusulas de confidencialidade', 'agentes_concordam': ['Agente 1', 'Agente 2', 'Agente 3'], 'importancia': 'Alta'}, {'ponto': 'Importância de detalhar obrigações contratuais', 'agentes_concordam': ['Todos'], 'importancia': 'Alta'}]', '{{"divergencia": "Especificidade das cláusulas de propriedade intelectual", "agente_1_visao": "Menor foco", "agente_2_visao": "Análise detalhada", "recomendacao": "Incluir cláusulas específicas sobre propriedade intelectual conforme sugerido pelo Agente 2"}}', '{'criticos': [{'risco': 'Inexecução ou execução insatisfatória dos serviços', 'impacto': 'Alto', 'probabilidade': 'Média', 'impacto_financeiro': 'Potencial perda de receita e reputação', 'prazo_manifestacao': 'Durante a vigência do contrato', 'mitigacao': 'Detalhar obrigações e incluir cláusulas de SLA', 'fundamento_legal': 'Código Civil, Art. 593 e seguintes'}], 'moderados': [{'risco': 'Atrasos nos pagamentos', 'impacto': 'Médio', 'probabilidade': 'Média', 'mitigacao': 'Incluir mecanismos de mediação antes da suspensão dos serviços'}], 'baixos': [{'risco': 'Uso indevido de informações para portfólio', 'impacto': 'Baixo', 'probabilidade': 'Baixa', 'mitigacao': 'Revisar cláusulas de confidencialidade'}]}', '{'urgentes': [{'melhoria': 'Revisão das cláusulas de confidencialidade', 'beneficio': 'Proteção de dados sensíveis e mitigação de riscos legais', 'complexidade': 'Média', 'custo_estimado': 'Baixo', 'prazo_implementacao': '30 dias', 'recursos_necessarios': ['Consultoria jurídica'], 'roi_esperado': 'Alto'}], 'importantes': [{'melhoria': 'Inclusão de cláusulas de propriedade intelectual', 'beneficio': 'Proteção dos direitos sobre entregáveis', 'complexidade': 'Média'}], 'sugeridas': [{'melhoria': 'Definição de métricas de desempenho (KPIs)', 'beneficio': 'Avaliação objetiva da performance', 'complexidade': 'Baixa'}]}', '{'curto_prazo': [{'estrategia': 'Revisar e ajustar cláusulas de confidencialidade', 'prazo': '0-3 meses', 'responsavel': 'Equipe jurídica interna', 'entregaveis': ['Contrato revisado'], 'kpis': ['Número de cláusulas ajustadas'], 'dependencias': ['Aprovação das partes']}], 'medio_prazo': [{'estrategia': 'Implementar cláusulas de propriedade intelectual', 'prazo': '3-12 meses', 'responsavel': 'Consultoria externa', 'entregaveis': ['Contrato atualizado']}], 'longo_prazo': [{'estrategia': 'Estabelecer sistema de monitoramento de KPIs', 'prazo': '12+ meses', 'responsavel': 'Equipe de operações', 'entregaveis': ['Relatórios de desempenho']}]}', '{{"risco": "Inexecução ou execução insatisfatória dos serviços", "impacto": "Alto", "probabilidade": "Média", "impacto_financeiro": "Potencial perda de receita e reputação", "prazo_manifestacao": "Durante a vigência do contrato", "mitigacao": "Detalhar obrigações e incluir cláusulas de SLA", "fundamento_legal": "Código Civil, Art. 593 e seguintes"}}', '{{"risco": "Atrasos nos pagamentos", "impacto": "Médio", "probabilidade": "Média", "mitigacao": "Incluir mecanismos de mediação antes da suspensão dos serviços"}}', '{{"risco": "Uso indevido de informações para portfólio", "impacto": "Baixo", "probabilidade": "Baixa", "mitigacao": "Revisar cláusulas de confidencialidade"}}', '[{'melhoria': 'Revisão das cláusulas de confidencialidade', 'beneficio': 'Proteção de dados sensíveis e mitigação de riscos legais', 'complexidade': 'Média', 'custo_estimado': 'Baixo', 'prazo_implementacao': '30 dias', 'recursos_necessarios': ['Consultoria jurídica'], 'roi_esperado': 'Alto'}]', '{{"melhoria": "Inclusão de cláusulas de propriedade intelectual", "beneficio": "Proteção dos direitos sobre entregáveis", "complexidade": "Média"}}', '{{"melhoria": "Definição de métricas de desempenho (KPIs)", "beneficio": "Avaliação objetiva da performance", "complexidade": "Baixa"}}', '[{'estrategia': 'Revisar e ajustar cláusulas de confidencialidade', 'prazo': '0-3 meses', 'responsavel': 'Equipe jurídica interna', 'entregaveis': ['Contrato revisado'], 'kpis': ['Número de cláusulas ajustadas'], 'dependencias': ['Aprovação das partes']}]', '[{'estrategia': 'Implementar cláusulas de propriedade intelectual', 'prazo': '3-12 meses', 'responsavel': 'Consultoria externa', 'entregaveis': ['Contrato atualizado']}]', '[{'estrategia': 'Estabelecer sistema de monitoramento de KPIs', 'prazo': '12+ meses', 'responsavel': 'Equipe de operações', 'entregaveis': ['Relatórios de desempenho']}]', 'Alto', 'Alta', '{Consultoria jurídica", "Equipe de TI}', 'GPT-4', 0, 0.0, 23.74896740913391, 'gerado', NULL, 1, '2025-09-16 05:00:36.929137', '2025-09-16 05:00:36.929139', NULL);
INSERT INTO relatorio_consenso (id, uuid_relatorio, numero_relatorio, analise_numero_registro, titulo_relatorio, descricao, user_id, consenso_geral, nivel_concordancia, pontos_convergencia, pontos_divergencia, analise_riscos, analise_melhorias, estrategias_recomendadas, riscos_criticos, riscos_moderados, riscos_baixos, melhorias_urgentes, melhorias_importantes, melhorias_sugeridas, estrategias_curto_prazo, estrategias_medio_prazo, estrategias_longo_prazo, impacto_estimado, viabilidade_implementacao, recursos_necessarios, modelo_ia_utilizado, tokens_consumidos, custo_estimado, tempo_processamento, status, status_mensagem, versao, data_criacao, data_atualizacao, data_aprovacao) VALUES (3, 'b2dcd2b1-1b7a-4389-a1a4-5ea7509d2107', 'REL-1758051041765', 'REG-1758050858', 'Relatório de Consenso - REL-1758051041765', 'Relatório de consenso gerado automaticamente', 3, 'As análises dos agentes jurídicos convergem em diversos aspectos fundamentais do contrato de arrendamento rural, destacando a conformidade geral com a legislação vigente, mas também apontando para a necessidade de ajustes específicos para mitigar riscos e evitar litígios futuros. Todos os agentes concordam que o contrato está em conformidade com o Estatuto da Terra e o Decreto 59.566/66, mas identificam inconsistências temporais e estruturais que precisam ser corrigidas. A qualidade das análises é alta, com cada agente trazendo insights valiosos e complementares. As conclusões estratégicas indicam que, embora o contrato seja robusto em sua estrutura básica, ajustes são necessários para garantir clareza e segurança jurídica, especialmente em relação a prazos, descrição do imóvel, e cláusulas de pagamento e benfeitorias. A consistência entre os agentes é notável, com um nível de concordância de 85.5%, refletindo uma análise detalhada e bem fundamentada das questões jurídicas envolvidas.', 85.5, '[{'ponto': 'Conformidade com o Estatuto da Terra', 'agentes_concordam': ['Agente 1', 'Agente 2', 'Agente 3'], 'importancia': 'Alta'}, {'ponto': 'Necessidade de correção de inconsistências temporais', 'agentes_concordam': ['Agente 1', 'Agente 2'], 'importancia': 'Alta'}]', '{{"divergencia": "Descrição do imóvel duplicada", "agente_1_visao": "Erro material que deve ser corrigido", "agente_2_visao": "Duplicidade sem justificativa clara", "recomendacao": "Revisar e corrigir a descrição para evitar litígios"}}', '{'criticos': [{'risco': 'Inconsistência nas datas de vigência do contrato', 'impacto': 'Alto', 'probabilidade': 'Alta', 'impacto_financeiro': 'Potencial para litígios e custos legais', 'prazo_manifestacao': 'Imediato, ao início do contrato', 'mitigacao': 'Revisar e corrigir as datas no contrato', 'fundamento_legal': 'Estatuto da Terra e Decreto 59.566/66'}], 'moderados': [{'risco': 'Ambiguidade na cláusula de renovação', 'impacto': 'Médio', 'probabilidade': 'Média', 'mitigacao': 'Especificar condições de renovação'}], 'baixos': [{'risco': 'Restrição de benfeitorias', 'impacto': 'Baixo', 'probabilidade': 'Baixa', 'mitigacao': 'Flexibilizar cláusula de benfeitorias'}]}', '{'urgentes': [{'melhoria': 'Correção das datas de vigência do contrato', 'beneficio': 'Evitar litígios e garantir clareza contratual', 'complexidade': 'Baixa', 'custo_estimado': 'Baixo', 'prazo_implementacao': 'Imediato', 'recursos_necessarios': ['Revisão jurídica'], 'roi_esperado': 'Alto'}], 'importantes': [{'melhoria': 'Especificação de critérios de medição da área', 'beneficio': 'Reduzir disputas sobre a área plantada', 'complexidade': 'Média'}], 'sugeridas': [{'melhoria': 'Inclusão de cláusula de força maior', 'beneficio': 'Proteção contra eventos climáticos extremos', 'complexidade': 'Média'}]}', '{'curto_prazo': [{'estrategia': 'Revisar e corrigir as datas de vigência do contrato', 'prazo': '0-3 meses', 'responsavel': 'Equipe jurídica', 'entregaveis': ['Contrato revisado'], 'kpis': ['Redução de litígios'], 'dependencias': []}], 'medio_prazo': [{'estrategia': 'Definir critérios técnicos para medição da área'