INSERT INTO speaker_segments (id, transcricao_id, speaker, speaker_confidence, text, start_time, end_time, confidence, words_count, channel) VALUES (713, 19, 'D', 0.71908075, 'Boa tarde, Douglas.', 43645, 45565, 0.71908075, 3, 0);
INSERT INTO speaker_segments (id, transcricao_id, speaker, speaker_confidence, text, start_time, end_time, confidence, words_count, channel) VALUES (714, 19, 'C', 0.71542776, 'Boa tarde.', 45565, 46285, 0.71542776, 2, 0);
INSERT INTO speaker_segments (id, transcricao_id, speaker, speaker_confidence, text, start_time, end_time, confidence, words_count, channel) VALUES (715, 19, 'D', 0.79165494, 'Douglas, o senhor vai ser ouvido sobre o fato número 5º da denúncia, ok? Eu vou fazer a leitura do fato para ver se o senhor se recorda, porque já faz algum tempo. No dia 22 de outubro de 2019, por volta das 22h30, na Rua Lago Azul, número 248, no bairro Santa Bárbara, cidade de Alvorada, os soldados Josimar da Silva Pereira, Felipe Ferreira Janiquim e Mateus Arcenes de Voraes, em comunhão de resposta e condição de vontade, todos de serviço pilotado no vigésimo quarto PTM, apropriaram-se de valores que tinham força e razão da função apreendido durante a ocorrência policial registrada sob o número 100-464-2019-14700, relativa aos crimes de tráfego de entorpecentes e porte legal de arma. Na oportunidade, os denunciados prenderam Douglas de Oliveira Mafalda e Rafael de Cidade Barbosa por tráfico de estropecentes e porte ilegal de arma, aprendendo, dentre outros materiais, dois coletes balísticos, uma pistola calibre .380, um revólver calibre .38, um revólver calibre .32 e uma espigada calibre .12. também 2.289 gramas de cocaína, 79 gramas de maconha e, ao menos, um grama de crack. E R$331 em dinheiro.', 47967, 142062, 0.79165494, 186, 0);
INSERT INTO speaker_segments (id, transcricao_id, speaker, speaker_confidence, text, start_time, end_time, confidence, words_count, channel) VALUES (716, 19, 'A', 0.614, 'Pergunta.', 142062, 145062, 0.614, 1, 0);
INSERT INTO speaker_segments (id, transcricao_id, speaker, speaker_confidence, text, start_time, end_time, confidence, words_count, channel) VALUES (717, 19, 'D', 0.806027, 'Douglas, sobre essa ocorrência, o que o senhor tem a nos dizer?', 149702, 154242, 0.806027, 12, 0);
INSERT INTO speaker_segments (id, transcricao_id, speaker, speaker_confidence, text, start_time, end_time, confidence, words_count, channel) VALUES (718, 19, 'A', 0.377903, 'E aí e o problema do tornozelo né é alguma coisa aconteceu e tá.', 157115, 168995, 0.377903, 14, 0);
INSERT INTO speaker_segments (id, transcricao_id, speaker, speaker_confidence, text, start_time, end_time, confidence, words_count, channel) VALUES (719, 19, 'B', 0.4907401, 'Voltou a normal E aí E aí.', 168995, 177445, 0.4907401, 7, 0);
INSERT INTO speaker_segments (id, transcricao_id, speaker, speaker_confidence, text, start_time, end_time, confidence, words_count, channel) VALUES (720, 19, 'D', 0.5180132, 'O Bernadete põe ele na tela principal.', 177445, 179135, 0.5180132, 7, 0);
INSERT INTO speaker_segments (id, transcricao_id, speaker, speaker_confidence, text, start_time, end_time, confidence, words_count, channel) VALUES (721, 19, 'A', 0.519529, 'E ele tá na tela doutor tá.', 179135, 184475, 0.519529, 7, 0);
INSERT INTO speaker_segments (id, transcricao_id, speaker, speaker_confidence, text, start_time, end_time, confidence, words_count, channel) VALUES (722, 19, 'C', 0.62781566, 'Mas dá na principal, que eu não estou vendo.', 184475, 190122, 0.62781566, 9, 0);
INSERT INTO speaker_segments (id, transcricao_id, speaker, speaker_confidence, text, start_time, end_time, confidence, words_count, channel) VALUES (723, 19, 'A', 0.62438333, 'Aqui a gente está.', 193302, 196082, 0.62438333, 4, 0);
INSERT INTO speaker_segments (id, transcricao_id, speaker, speaker_confidence, text, start_time, end_time, confidence, words_count, channel) VALUES (724, 19, 'D', 0.8230529, 'Douglas, ouviu sobre essa ocorrência?', 196082, 201222, 0.8230529, 5, 0);
INSERT INTO speaker_segments (id, transcricao_id, speaker, speaker_confidence, text, start_time, end_time, confidence, words_count, channel) VALUES (725, 19, 'C', 0.7735, 'Escutei, escutei.', 201222, 203082, 0.7735, 2, 0);
INSERT INTO speaker_segments (id, transcricao_id, speaker, speaker_confidence, text, start_time, end_time, confidence, words_count, channel) VALUES (726, 19, 'D', 0.81704307, '22 de outubro de 2019, o senhor foi preso, junto com o Rafael, por porte ilegal de drogas e arma. Sobre esse fato, o que o senhor pode nos dizer sobre isso?', 203082, 218612, 0.81704307, 32, 0);
INSERT INTO speaker_segments (id, transcricao_id, speaker, speaker_confidence, text, start_time, end_time, confidence, words_count, channel) VALUES (727, 19, 'C', 0.68094903, 'Não tenho nada a dizer sobre isso.', 218612, 222132, 0.68094903, 7, 0);
INSERT INTO speaker_segments (id, transcricao_id, speaker, speaker_confidence, text, start_time, end_time, confidence, words_count, channel) VALUES (728, 19, 'D', 0.79700947, 'O senhor estava na posse de entorpecente e armas?', 222132, 226592, 0.79700947, 9, 0);
INSERT INTO speaker_segments (id, transcricao_id, speaker, speaker_confidence, text, start_time, end_time, confidence, words_count, channel) VALUES (729, 19, 'C', 0.7912666, 'Estava na posse, estava.', 226592, 229692, 0.7912666, 4, 0);
INSERT INTO speaker_segments (id, transcricao_id, speaker, speaker_confidence, text, start_time, end_time, confidence, words_count, channel) VALUES (730, 19, 'D', 0.7679148, 'E o senhor se recorda de quantas armas o senhor tinha?', 229692, 236392, 0.7679148, 11, 0);
INSERT INTO speaker_segments (id, transcricao_id, speaker, speaker_confidence, text, start_time, end_time, confidence, words_count, channel) VALUES (731, 19, 'C', 0.70098877, 'Claro, não me lembro.', 236392, 238532, 0.70098877, 4, 0);
INSERT INTO speaker_segments (id, transcricao_id, speaker, speaker_confidence, text, start_time, end_time, confidence, words_count, channel) VALUES (732, 19, 'D', 0.9268195, 'E a quantidade de drogas?', 238532, 240612, 0.9268195, 5, 0);
INSERT INTO speaker_segments (id, transcricao_id, speaker, speaker_confidence, text, start_time, end_time, confidence, words_count, channel) VALUES (733, 19, 'C', 0.6927886, 'Também não sei, não era eu que vendia.', 241996, 244876, 0.6927886, 8, 0);
INSERT INTO speaker_segments (id, transcricao_id, speaker, speaker_confidence, text, start_time, end_time, confidence, words_count, channel) VALUES (734, 19, 'D', 0.76619697, 'Valores em dinheiro, o senhor saberia dizer quanto de dinheiro o senhor tinha nessa oportunidade, junto com o Rafael?', 244876, 255336, 0.76619697, 19, 0);
INSERT INTO speaker_segments (id, transcricao_id, speaker, speaker_confidence, text, start_time, end_time, confidence, words_count, channel) VALUES (735, 19, 'C', 0.773043, 'Não sei.', 255336, 257456, 0.773043, 2, 0);
INSERT INTO speaker_segments (id, transcricao_id, speaker, speaker_confidence, text, start_time, end_time, confidence, words_count, channel) VALUES (736, 19, 'D', 0.80529785, 'Não se recorda? Não. Durante essa ocorrência, o senhor chegou a notar se algum policial pegou algum dinheiro para ele?', 257456, 266216, 0.80529785, 20, 0);
INSERT INTO speaker_segments (id, transcricao_id, speaker, speaker_confidence, text, start_time, end_time, confidence, words_count, channel) VALUES (737, 19, 'B', 0.919, 'Ouviu, Douglas?', 272472, 276872, 0.919, 2, 0);
INSERT INTO speaker_segments (id, transcricao_id, speaker, speaker_confidence, text, start_time, end_time, confidence, words_count, channel) VALUES (738, 19, 'C', 0.849, 'Douglas.', 276872, 279872, 0.849, 1, 0);
INSERT INTO speaker_segments (id, transcricao_id, speaker, speaker_confidence, text, start_time, end_time, confidence, words_count, channel) VALUES (739, 19, 'D', 0.82240105, 'Está me ouvindo?', 281672, 284852, 0.82240105, 3, 0);
INSERT INTO speaker_segments (id, transcricao_id, speaker, speaker_confidence, text, start_time, end_time, confidence, words_count, channel) VALUES (740, 19, 'B', 0.73709244, 'De novo deu.', 286132, 290772, 0.73709244, 3, 0);
INSERT INTO speaker_segments (id, transcricao_id, speaker, speaker_confidence, text, start_time, end_time, confidence, words_count, channel) VALUES (741, 19, 'A', 0.79088366, 'Ele continua aqui na tela, doutor, PK Douglas. Douglas, você está nos ouvindo? Porque ele não caiu, ele está aqui no… Vamos ver, espera aí. Agora caiu, estou colocando ele de novo.', 290772, 317713, 0.79088366, 32, 0);
INSERT INTO speaker_segments (id, transcricao_id, speaker, speaker_confidence, text, start_time, end_time, confidence, words_count, channel) VALUES (742, 19, 'B', 0.31982422, 'Você.', 317713, 320713, 0.31982422, 1, 0);
INSERT INTO speaker_segments (id, transcricao_id, speaker, speaker_confidence, text, start_time, end_time, confidence, words_count, channel) VALUES (743, 19, 'A', 0.679965, 'Está saindo da APK que está… Coloca o Diogo de novo. Coloca o Douglas de novo.', 328033, 336490, 0.679965, 16, 0);
INSERT INTO speaker_segments (id, transcricao_id, speaker, speaker_confidence, text, start_time, end_time, confidence, words_count, channel) VALUES (744, 19, 'C', 0.67762816, 'Tá, só um momento que eu tô configurando aqui.', 336490, 339010, 0.67762816, 9, 0);
INSERT INTO speaker_segments (id, transcricao_id, speaker, speaker_confidence, text, start_time, end_time, confidence, words_count, channel) VALUES (745, 19, 'B', 0.8497435, 'Tá certo. Pronto.', 339010, 347070, 0.8497435, 3, 0);
INSERT INTO speaker_segments (id, transcricao_id, speaker, speaker_confidence, text, start_time, end_time, confidence, words_count, channel) VALUES (746, 19, 'A', 0.7671834, 'Doutor, ele tá de volta.', 356650, 359050, 0.7671834, 5, 0);
INSERT INTO speaker_segments (id, transcricao_id, speaker, speaker_confidence, text, start_time, end_time, confidence, words_count, channel) VALUES (747, 19, 'D', 0.729, 'Douglas!', 359050, 362050, 0.729, 1, 0);
INSERT INTO speaker_segments (id, transcricao_id, speaker, speaker_confidence, text, start_time, end_time, confidence, words_count, channel) VALUES (748, 19, 'B', 0.834, 'Opa!', 362630, 363610, 0.834, 1, 0);
INSERT INTO speaker_segments (id, transcricao_id, speaker, speaker_confidence, text, start_time, end_time, confidence, words_count, channel) VALUES (749, 19, 'D', 0.71159005, 'Durante essa ocorrência, o senhor chegou a notar se algum policial tinha pego o dinheiro que estava na posse de vocês? Acho que foi agora. Mas não tem certeza.', 364154, 379014, 0.71159005, 29, 0);
INSERT INTO speaker_segments (id, transcricao_id, speaker, speaker_confidence, text, start_time, end_time, confidence, words_count, channel) VALUES (750, 19, 'B', 0.62228644, 'É, não tem certeza.', 379014, 382494, 0.62228644, 4, 0);
INSERT INTO speaker_segments (id, transcricao_id, speaker, speaker_confidence, text, start_time, end_time, confidence, words_count, channel) VALUES (751, 19, 'D', 0.7664448, 'E como eu já tinha lhe perguntado quantidade de droga, quantidade de dinheiro e quantidade de arma, o senhor não se lembra.', 382994, 390634, 0.7664448, 22, 0);
INSERT INTO speaker_segments (id, transcricao_id, speaker, speaker_confidence, text, start_time, end_time, confidence, words_count, channel) VALUES (752, 19, 'C', 0.69259316, 'Não me lembro porque eles não pegaram nada com nós, os sojuíras. Eles chegaram em outra residência.', 391643, 397823, 0.69259316, 17, 0);
INSERT INTO speaker_segments (id, transcricao_id, speaker, speaker_confidence, text, start_time, end_time, confidence, words_count, channel) VALUES (753, 19, 'D', 0.7877884, 'E isso não estava com vocês?', 397823, 400243, 0.7877884, 6, 0);
INSERT INTO speaker_segments (id, transcricao_id, speaker, speaker_confidence, text, start_time, end_time, confidence, words_count, channel) VALUES (754, 19, 'C', 0.78967446, 'Não, não estava com nós. Eles pegaram em outra residência e daí botaram em nós.', 400243, 405563, 0.78967446, 15, 0);
INSERT INTO speaker_segments (id, transcricao_id, speaker, speaker_confidence, text, start_time, end_time, confidence, words_count, channel) VALUES (755, 19, 'D', 0.78441405, 'E você estava perto dessa residência?', 405563, 408923, 0.78441405, 6, 0);
INSERT INTO speaker_segments (id, transcricao_id, speaker, speaker_confidence, text, start_time, end_time, confidence, words_count, channel) VALUES (756, 19, 'C', 0.70424235, 'Ah, no caso, eu moro umas duas quartas dessa residência. Tá.', 408923, 413403, 0.70424235, 11, 0);
INSERT INTO speaker_segments (id, transcricao_id, speaker, speaker_confidence, text, start_time, end_time, confidence, words_count, channel) VALUES (757, 19, 'D', 0.8431563, 'E o senhor está preso por tráfico?', 413403, 415743, 0.8431563, 7, 0);
INSERT INTO speaker_segments (id, transcricao_id, speaker, speaker_confidence, text, start_time, end_time, confidence, words_count, channel) VALUES (758, 19, 'C', 0.69946146, 'Agora eu estou preso por tráfico? Poxa, eu fiquei quatro dias na rua só. Tá iniciado de novo.', 415743, 424297, 0.69946146, 18, 0);
INSERT INTO speaker_segments (id, transcricao_id, speaker, speaker_confidence, text, start_time, end_time, confidence, words_count, channel) VALUES (759, 19, 'D', 0.69945425, 'Tá certo. Palavra ao conselho, Capitão Marcelo.', 424297, 428797, 0.69945425, 7, 0);
INSERT INTO speaker_segments (id, transcricao_id, speaker, speaker_confidence, text, start_time, end_time, confidence, words_count, channel) VALUES (760, 19, 'B', 0.7757904, 'Sem perguntas, Excelência.', 428797, 433337, 0.7757904, 3, 0);
INSERT INTO speaker_segments (id, transcricao_id, speaker, speaker_confidence, text, start_time, end_time, confidence, words_count, channel) VALUES (761, 19, 'D', 0.69968057, 'Ao Capitão Koniki.', 433337, 435937, 0.69968057, 3, 0);
INSERT INTO speaker_segments (id, transcricao_id, speaker, speaker_confidence, text, start_time, end_time, confidence, words_count, channel) VALUES (762, 19, 'C', 0.78916794, 'Sem perguntas.', 435937, 436777, 0.78916794, 2, 0);
INSERT INTO speaker_segments (id, transcricao_id, speaker, speaker_confidence, text, start_time, end_time, confidence, words_count, channel) VALUES (763, 19, 'D', 0.8342305, 'Ministério Público.', 436777, 441077, 0.8342305, 2, 0);
INSERT INTO speaker_segments (id, transcricao_id, speaker, speaker_confidence, text, start_time, end_time, confidence, words_count, channel) VALUES (764, 19, 'E', 0.78305614, 'Boa tarde. Exatamente o que aconteceu nesse dia, Douglas? O senhor conheceu os policiais militares?', 441077, 449757, 0.78305614, 15, 0);
INSERT INTO speaker_segments (id, transcricao_id, speaker, speaker_confidence, text, start_time, end_time, confidence, words_count, channel) VALUES (765, 19, 'C', 0.7280621, 'No caso, eu estava sem medir o meio para levar meus primos para o colégio e tomei uma abordagem da polícia. Nisso eu tomei uma abordagem. Eles tinham abordado outro guri que morava em frente da minha casa e estava saindo para trabalhar. Eles queriam saber de droga, de arma. A gente, sabe, falava... Falava que a gente não sabia de nada e eles começaram a bater na gente e me enxertaram mais com as drogas. Falaram que se a gente não falasse nada, eles enxertariam mais e levariam mais primos.', 452596, 481096, 0.7280621, 91, 0);
INSERT INTO speaker_segments (id, transcricao_id, speaker, speaker_confidence, text, start_time, end_time, confidence, words_count, channel) VALUES (766, 19, 'E', 0.7521145, 'Você já conhecia os policiais?', 482785, 485525, 0.7521145, 5, 0);
INSERT INTO speaker_segments (id, transcricao_id, speaker, speaker_confidence, text, start_time, end_time, confidence, words_count, channel) VALUES (767, 19, 'C', 0.66991013, 'Não, não conhecia.', 485525, 488065, 0.66991013, 3, 0);
INSERT INTO speaker_segments (id, transcricao_id, speaker, speaker_confidence, text, start_time, end_time, confidence, words_count, channel) VALUES (768, 19, 'E', 0.8003854, 'Nem de vista?', 488065, 490045, 0.8003854, 3, 0);
INSERT INTO speaker_segments (id, transcricao_id, speaker, speaker_confidence, text, start_time, end_time, confidence, words_count, channel) VALUES (769, 19, 'C', 0.69729936, 'Não, nunca tinha visto.', 490045, 492665, 0.69729936, 4, 0);
INSERT INTO speaker_segments (id, transcricao_id, speaker, speaker_confidence, text, start_time, end_time, confidence, words_count, channel) VALUES (770, 19, 'E', 0.72353125, 'Eles te exigiram algum dinheiro, algo? Para não fazer isso?', 492665, 498105, 0.72353125, 10, 0);
INSERT INTO speaker_segments (id, transcricao_id, speaker, speaker_confidence, text, start_time, end_time, confidence, words_count, channel) VALUES (771, 19, 'C', 0.8508152, 'Não, não pediram nada.', 498105, 501085, 0.8508152, 4, 0);
INSERT INTO speaker_segments (id, transcricao_id, speaker, speaker_confidence, text, start_time, end_time, confidence, words_count, channel) VALUES (772, 19, 'E', 0.79725605, 'Você estava acompanhado de quem nesse momento?', 501085, 504685, 0.79725605, 7, 0);
INSERT INTO speaker_segments (id, transcricao_id, speaker, speaker_confidence, text, start_time, end_time, confidence, words_count, channel) VALUES (773, 19, 'C', 0.88972265, 'Acompanhada da minha irmã.', 504685, 506465, 0.88972265, 4, 0);
INSERT INTO speaker_segments (id, transcricao_id, speaker, speaker_confidence, text, start_time, end_time, confidence, words_count, channel) VALUES (774, 19, 'E', 0.8079838, 'Como é que é o nome dela?', 506465, 508225, 0.8079838, 7, 0);
INSERT INTO speaker_segments (id, transcricao_id, speaker, speaker_confidence, text, start_time, end_time, confidence, words_count, channel) VALUES (775, 19, 'C', 0.904, 'Cristiane.', 508225, 510085, 0.904, 1, 0);
INSERT INTO speaker_segments (id, transcricao_id, speaker, speaker_confidence, text, start_time, end_time, confidence, words_count, channel) VALUES (776, 19, 'E', 0.8019225, 'Só ela estava contigo? Mais ninguém?', 510085, 512525, 0.8019225, 6, 0);
INSERT INTO speaker_segments (id, transcricao_id, speaker, speaker_confidence, text, start_time, end_time, confidence, words_count, channel) VALUES (777, 19, 'C', 0.72663534, 'Estava só eu e as minhas crianças em casa.', 513160, 515340, 0.72663534, 9, 0);
INSERT INTO speaker_segments (id, transcricao_id, speaker, speaker_confidence, text, start_time, end_time, confidence, words_count, channel) VALUES (778, 19, 'E', 0.72180855, 'E por que eles fizeram isso contigo? Tu afirma que não conhecia eles, que.', 515340, 524360, 0.72180855, 14, 0);
INSERT INTO speaker_segments (id, transcricao_id, speaker, speaker_confidence, text, start_time, end_time, confidence, words_count, channel) VALUES (779, 19, 'C', 0.7487738, 'Não foi exigido... Nada, eu já não sei. Não tenho o que dizer.', 524360, 533140, 0.7487738, 13, 0);
INSERT INTO speaker_segments (id, transcricao_id, speaker, speaker_confidence, text, start_time, end_time, confidence, words_count, channel) VALUES (780, 19, 'E', 0.8020814, 'Tu está preso por esse fato?', 533140, 536780, 0.8020814, 6, 0);
INSERT INTO speaker_segments (id, transcricao_id, speaker, speaker_confidence, text, start_time, end_time, confidence, words_count, channel) VALUES (781, 19, 'C', 0.7264756, 'Não, no caso desse fato, eu fui embora e voltei de novo para uma outra pronta.', 536780, 542060, 0.7264756, 16, 0);
INSERT INTO speaker_segments (id, transcricao_id, speaker, speaker_confidence, text, start_time, end_time, confidence, words_count, channel) VALUES (782, 19, 'E', 0.7795394, 'Além de droga, arma, teve alguma questão envolvendo arma em relação a esse fato que o juiz questionou para ti?', 543738, 554478, 0.7795394, 20, 0);
INSERT INTO speaker_segments (id, transcricao_id, speaker, speaker_confidence, text, start_time, end_time, confidence, words_count, channel) VALUES (783, 19, 'C', 0.8512734, 'Não entendi.', 554478, 555998, 0.8512734, 2, 0);
INSERT INTO speaker_segments (id, transcricao_id, speaker, speaker_confidence, text, start_time, end_time, confidence, words_count, channel) VALUES (784, 19, 'E', 0.6748876, 'Em relação a arma, tem alguma coisa de enxertar um arma também ou não?', 555998, 561438, 0.6748876, 14, 0);
INSERT INTO speaker_segments (id, transcricao_id, speaker, speaker_confidence, text, start_time, end_time, confidence, words_count, channel) VALUES (785, 19, 'C', 0.5796897, 'Podemos enxertar também um revólver.', 561438, 564758, 0.5796897, 5, 0);
INSERT INTO speaker_segments (id, transcricao_id, speaker, speaker_confidence, text, start_time, end_time, confidence, words_count, channel) VALUES (786, 19, 'E', 0.8969453, 'Qual revólver?', 564758, 566798, 0.8969453, 2, 0);
INSERT INTO speaker_segments (id, transcricao_id, speaker, speaker_confidence, text, start_time, end_time, confidence, words_count, channel) VALUES (787, 19, 'C', 0.66213214, 'Calibre 38.', 566798, 569718, 0.66213214, 2, 0);
INSERT INTO speaker_segments (id, transcricao_id, speaker, speaker_confidence, text, start_time, end_time, confidence, words_count, channel) VALUES (788, 19, 'E', 0.8207299, 'E como é que foi esse enxerto?', 569718, 572178, 0.8207299, 7, 0);
INSERT INTO speaker_segments (id, transcricao_id, speaker, speaker_confidence, text, start_time, end_time, confidence, words_count, channel) VALUES (789, 19, 'C', 0.66026735, 'Na hora da abordagem.', 573505, 575965, 0.66026735, 4, 0);
INSERT INTO speaker_segments (id, transcricao_id, speaker, speaker_confidence, text, start_time, end_time, confidence, words_count, channel) VALUES (790, 19, 'E', 0.76930076, 'O que eles falaram?', 575965, 579205, 0.76930076, 4, 0);
INSERT INTO speaker_segments (id, transcricao_id, speaker, speaker_confidence, text, start_time, end_time, confidence, words_count, channel) VALUES (791, 19, 'C', 0.74619275, 'Eles falaram que se a gente não falasse nada, eles iam chutar nós. Iam botar droga, arma e iam botar nós na cadeira.', 579205, 588105, 0.74619275, 23, 0);
INSERT INTO speaker_segments (id, transcricao_id, speaker, speaker_confidence, text, start_time, end_time, confidence, words_count, channel) VALUES (792, 19, 'E', 0.6953336, 'Tu tem vínculo com alguma facção?', 589245, 592865, 0.6953336, 6, 0);
INSERT INTO speaker_segments (id, transcricao_id, speaker, speaker_confidence, text, start_time, end_time, confidence, words_count, channel) VALUES (793, 19, 'C', 0.873, 'Não, não.', 592865, 594665, 0.873, 2, 0);
INSERT INTO speaker_segments (id, transcricao_id, speaker, speaker_confidence, text, start_time, end_time, confidence, words_count, channel) VALUES (794, 19, 'E', 0.77933985, 'Nada mais.', 594665, 597225, 0.77933985, 2, 0);
INSERT INTO speaker_segments (id, transcricao_id, speaker, speaker_confidence, text, start_time, end_time, confidence, words_count, channel) VALUES (795, 19, 'D', 0.73941714, 'Doutora Edna, pelo soldado Josimar.', 597225, 601205, 0.73941714, 5, 0);
INSERT INTO speaker_segments (id, transcricao_id, speaker, speaker_confidence, text, start_time, end_time, confidence, words_count, channel) VALUES (796, 19, 'B', 0.57749087, 'Nada, em silêncio.', 604302, 606462, 0.57749087, 3, 0);
INSERT INTO speaker_segments (id, transcricao_id, speaker, speaker_confidence, text, start_time, end_time, confidence, words_count, channel) VALUES (797, 19, 'D', 0.7052441, 'A doutora Ciomara pelo soldado Felipe.', 606462, 609702, 0.7052441, 6, 0);
INSERT INTO speaker_segments (id, transcricao_id, speaker, speaker_confidence, text, start_time, end_time, confidence, words_count, channel) VALUES (798, 19, 'B', 0.86127216, 'Nada, em silêncio.', 609702, 612302, 0.86127216, 3, 0);
INSERT INTO speaker_segments (id, transcricao_id, speaker, speaker_confidence, text, start_time, end_time, confidence, words_count, channel) VALUES (799, 19, 'D', 0.8705577, 'Pelo soldado Mateus, doutor Márcio Barcelos.', 612302, 616602, 0.8705577, 6, 0);
INSERT INTO speaker_segments (id, transcricao_id, speaker, speaker_confidence, text, start_time, end_time, confidence, words_count, channel) VALUES (800, 19, 'F', 0.74845076, 'Sim, doutor. Só para confirmar com ele, se o Mateus Alicênio, ele lembra do Mateus nessa data, presente no fato da abordagem?', 616602, 626802, 0.74845076, 22, 0);
INSERT INTO speaker_segments (id, transcricao_id, speaker, speaker_confidence, text, start_time, end_time, confidence, words_count, channel) VALUES (801, 19, 'B', 0.7406413, 'Eu não entendi.', 626802, 629762, 0.7406413, 3, 0);
INSERT INTO speaker_segments (id, transcricao_id, speaker, speaker_confidence, text, start_time, end_time, confidence, words_count, channel) VALUES (802, 19, 'F', 0.7200159, 'Se ele lembra os policiais que abordaram ele, especialmente no meu caso, o Mateus Arsene.', 631505, 636805, 0.7200159, 15, 0);
INSERT INTO speaker_segments (id, transcricao_id, speaker, speaker_confidence, text, start_time, end_time, confidence, words_count, channel) VALUES (803, 19, 'D', 0.80663544, 'O senhor lembra quem foram os policiais que lhe abordaram?', 636805, 641285, 0.80663544, 10, 0);
INSERT INTO speaker_segments (id, transcricao_id, speaker, speaker_confidence, text, start_time, end_time, confidence, words_count, channel) VALUES (804, 19, 'C', 0.78309196, 'Ah, se eu olhar pelo rosto até lembro, mas pelo nome eu não lembro.', 641285, 648185, 0.78309196, 14, 0);
INSERT INTO speaker_segments (id, transcricao_id, speaker, speaker_confidence, text, start_time, end_time, confidence, words_count, channel) VALUES (805, 19, 'F', 0.81894606, 'Chegaram a te convidar para fazer a cariação no inquérito?', 650065, 654765, 0.81894606, 10, 0);
INSERT INTO speaker_segments (id, transcricao_id, speaker, speaker_confidence, text, start_time, end_time, confidence, words_count, channel) VALUES (806, 19, 'C', 0.77893084, 'Vocês chegaram a me bater?', 654765, 657045, 0.77893084, 5, 0);
INSERT INTO speaker_segments (id, transcricao_id, speaker, speaker_confidence, text, start_time, end_time, confidence, words_count, channel) VALUES (807, 19, 'F', 0.774598, 'Não, fazer a cariação para te reconhecer os policiais.', 657045, 659525, 0.774598, 9, 0);
INSERT INTO speaker_segments (id, transcricao_id, speaker, speaker_confidence, text, start_time, end_time, confidence, words_count, channel) VALUES (808, 19, 'C', 0.6902643, 'Não, não fizeram. Isso eu vi só em uma audiência na rua. Em uma audiência na rua eu vi isso.', 660293, 668073, 0.6902643, 20, 0);
INSERT INTO speaker_segments (id, transcricao_id, speaker, speaker_confidence, text, start_time, end_time, confidence, words_count, channel) VALUES (809, 19, 'B', 0.85796076, 'Chegou a ser agredido? Quase me mataram.', 668073, 677353, 0.85796076, 7, 0);
INSERT INTO speaker_segments (id, transcricao_id, speaker, speaker_confidence, text, start_time, end_time, confidence, words_count, channel) VALUES (810, 19, 'F', 0.6855556, 'Tu reagiu ou só um apanhado de graça?', 677933, 682593, 0.6855556, 8, 0);
INSERT INTO speaker_segments (id, transcricao_id, speaker, speaker_confidence, text, start_time, end_time, confidence, words_count, channel) VALUES (811, 19, 'C', 0.64039135, 'Eu reagi contra quatro, não tem condições. Os caras quase me mataram.', 682593, 686813, 0.64039135, 12, 0);
INSERT INTO speaker_segments (id, transcricao_id, speaker, speaker_confidence, text, start_time, end_time, confidence, words_count, channel) VALUES (812, 19, 'F', 0.7464871, 'Tu não viu os nomes deles nas fardas no dia?', 690078, 694558, 0.7464871, 10, 0);
INSERT INTO speaker_segments (id, transcricao_id, speaker, speaker_confidence, text, start_time, end_time, confidence, words_count, channel) VALUES (813, 19, 'C', 0.7254081, 'Não via, não via porque eles me afogavam, eles estavam me afogando com água e botando pano na minha cara.', 694558, 700578, 0.7254081, 20, 0);
INSERT INTO speaker_segments (id, transcricao_id, speaker, speaker_confidence, text, start_time, end_time, confidence, words_count, channel) VALUES (814, 19, 'F', 0.6679251, 'Afogaram onde?', 700578, 701518, 0.6679251, 2, 0);
INSERT INTO speaker_segments (id, transcricao_id, speaker, speaker_confidence, text, start_time, end_time, confidence, words_count, channel) VALUES (815, 19, 'B', 0.5681553, 'Na camisa.', 701518, 703818, 0.5681553, 2, 0);
INSERT INTO speaker_segments (id, transcricao_id, speaker, speaker_confidence, text, start_time, end_time, confidence, words_count, channel) VALUES (816, 19, 'F', 0.8741045, 'Aonde isso?', 703818, 706038, 0.8741045, 2, 0);
INSERT INTO speaker_segments (id, transcricao_id, speaker, speaker_confidence, text, start_time, end_time, confidence, words_count, channel) VALUES (817, 19, 'C', 0.8736531, 'Na casa da minha irmã.', 706038, 707858, 0.8736531, 5, 0);
INSERT INTO speaker_segments (id, transcricao_id, speaker, speaker_confidence, text, start_time, end_time, confidence, words_count, channel) VALUES (818, 19, 'F', 0.6733156, 'Foi dentro, eles entraram na tua casa?', 707858, 709798, 0.6733156, 7, 0);
INSERT INTO speaker_segments (id, transcricao_id, speaker, speaker_confidence, text, start_time, end_time, confidence, words_count, channel) VALUES (819, 19, 'C', 0.8884495, 'Dentro da casa, na frente das crianças.', 709798, 712658, 0.8884495, 7, 0);
INSERT INTO speaker_segments (id, transcricao_id, speaker, speaker_confidence, text, start_time, end_time, confidence, words_count, channel) VALUES (820, 19, 'F', 0.82803386, 'Alguém viu, alguém filmou? O senhor registrou isso?', 712658, 717018, 0.82803386, 8, 0);
INSERT INTO speaker_segments (id, transcricao_id, speaker, speaker_confidence, text, start_time, end_time, confidence, words_count, channel) VALUES (821, 19, 'C', 0.7774581, 'Eu não sei se a minha irmã já vai registrar, mas ela viu. Isso foi de manhã cedo, umas oito e meia da manhã.', 718107, 727947, 0.7774581, 24, 0);
INSERT INTO speaker_segments (id, transcricao_id, speaker, speaker_confidence, text, start_time, end_time, confidence, words_count, channel) VALUES (822, 19, 'B', 0.8415, 'Satisfeito, doutor.', 727947, 730907, 0.8415, 2, 0);
INSERT INTO speaker_segments (id, transcricao_id, speaker, speaker_confidence, text, start_time, end_time, confidence, words_count, channel) VALUES (823, 19, 'C', 0.9115, 'Certo, doutor.', 730907, 734187, 0.9115, 2, 0);
INSERT INTO speaker_segments (id, transcricao_id, speaker, speaker_confidence, text, start_time, end_time, confidence, words_count, channel) VALUES (824, 19, 'D', 0.7872133, 'Doutor Márcio Rossano.', 734187, 738087, 0.7872133, 3, 0);
INSERT INTO speaker_segments (id, transcricao_id, speaker, speaker_confidence, text, start_time, end_time, confidence, words_count, channel) VALUES (825, 19, 'F', 0.92025554, 'Sem perguntas, doutor Francisco.', 738087, 741507, 0.92025554, 4, 0);
INSERT INTO speaker_segments (id, transcricao_id, speaker, speaker_confidence, text, start_time, end_time, confidence, words_count, channel) VALUES (826, 19, 'D', 0.8994798, 'Doutor Alfredo.', 741507, 743167, 0.8994798, 2, 0);
INSERT INTO speaker_segments (id, transcricao_id, speaker, speaker_confidence, text, start_time, end_time, confidence, words_count, channel) VALUES (827, 19, 'C', 0.5951634, 'Sem perguntas, doutor.', 747487, 749347, 0.5951634, 3, 0);
INSERT INTO speaker_segments (id, transcricao_id, speaker, speaker_confidence, text, start_time, end_time, confidence, words_count, channel) VALUES (828, 19, 'D', 0.66517645, 'A doutora Paloma?', 749347, 751767, 0.66517645, 3, 0);
INSERT INTO speaker_segments (id, transcricao_id, speaker, speaker_confidence, text, start_time, end_time, confidence, words_count, channel) VALUES (829, 19, 'B', 0.8847656, 'Sem perguntas.', 751767, 754287, 0.8847656, 2, 0);
INSERT INTO speaker_segments (id, transcricao_id, speaker, speaker_confidence, text, start_time, end_time, confidence, words_count, channel) VALUES (830, 19, 'D', 0.82061243, 'Não ficou nenhum advogado de fora?', 754287, 757167, 0.82061243, 6, 0);
INSERT INTO speaker_segments (id, transcricao_id, speaker, speaker_confidence, text, start_time, end_time, confidence, words_count, channel) VALUES (831, 19, 'B', 0.439, 'Ok.', 757167, 759807, 0.439, 1, 0);
INSERT INTO speaker_segments (id, transcricao_id, speaker, speaker_confidence, text, start_time, end_time, confidence, words_count, channel) VALUES (832, 19, 'D', 0.8296425, 'Está liberado, então, a testemunha. O Douglas pode deixar a sala. Obrigado pela colaboração da Suzette.', 759807, 768327, 0.8296425, 16, 0);
INSERT INTO speaker_segments (id, transcricao_id, speaker, speaker_confidence, text, start_time, end_time, confidence, words_count, channel) VALUES (833, 19, 'C', 0.80823046, 'Muito obrigado.', 768327, 771647, 0.80823046, 2, 0);
INSERT INTO speaker_segments (id, transcricao_id, speaker, speaker_confidence, text, start_time, end_time, confidence, words_count, channel) VALUES (834, 21, 'A', 0.75352925, 'Douglas, tu me diz o teu nome completo.', 42, 4322, 0.75352925, 8, 0);
INSERT INTO speaker_segments (id, transcricao_id, speaker, speaker_confidence, text, start_time, end_time, confidence, words_count, channel) VALUES (835, 21, 'B', 0.726, 'Nome?', 4322, 7322, 0.726, 1, 0);
INSERT INTO speaker_segments (id, transcricao_id, speaker, speaker_confidence, text, start_time, end_time, confidence, words_count, channel) VALUES (836, 21, 'A', 0.7632965, 'Tu me diz o teu nome completo, por favor.', 8442, 11442, 0.7632965, 9, 0);
INSERT INTO speaker_segments (id, transcricao_id, speaker, speaker_confidence, text, start_time, end_time, confidence, words_count, channel) VALUES (837, 21, 'C', 0.886487, 'Douglas Oliveira Mafalda.', 11442, 13982, 0.886487, 3, 0);
INSERT INTO speaker_segments (id, transcricao_id, speaker, speaker_confidence, text, start_time, end_time, confidence, words_count, channel) VALUES (838, 21, 'A', 0.81675136, 'Tu me diz a tua filiação, o nome dos teus pais.', 13982, 19502, 0.81675136, 11, 0);
INSERT INTO speaker_segments (id, transcricao_id, speaker, speaker_confidence, text, start_time, end_time, confidence, words_count, channel) VALUES (839, 21, 'C', 0.7998016, 'José Leomar de Oliveira Mafalda e Eliane Silva de Oliveira.', 19502, 23962, 0.7998016, 10, 0);
INSERT INTO speaker_segments (id, transcricao_id, speaker, speaker_confidence, text, start_time, end_time, confidence, words_count, channel) VALUES (840, 21, 'A', 0.78990275, 'E qual é o princípio que tu está aí?', 23962, 26982, 0.78990275, 9, 0);
INSERT INTO speaker_segments (id, transcricao_id, speaker, speaker_confidence, text, start_time, end_time, confidence, words_count, channel) VALUES (841, 21, 'C', 0.43456835, 'Não entendi.', 29945, 31005, 0.43456835, 2, 0);
INSERT INTO speaker_segments (id, transcricao_id, speaker, speaker_confidence, text, start_time, end_time, confidence, words_count, channel) VALUES (842, 21, 'A', 0.698109, 'Tu tá preso em qual presídio?', 31005, 34025, 0.698109, 6, 0);
INSERT INTO speaker_segments (id, transcricao_id, speaker, speaker_confidence, text, start_time, end_time, confidence, words_count, channel) VALUES (843, 21, 'C', 0.70301366, 'Tô na APK.', 34025, 35345, 0.70301366, 3, 0);
INSERT INTO speaker_segments (id, transcricao_id, speaker, speaker_confidence, text, start_time, end_time, confidence, words_count, channel) VALUES (844, 21, 'A', 0.67789453, 'Na APK.', 35345, 37085, 0.67789453, 2, 0);
INSERT INTO speaker_segments (id, transcricao_id, speaker, speaker_confidence, text, start_time, end_time, confidence, words_count, channel) VALUES (845, 21, 'B', 0.89524025, 'Tá certo.', 37085, 39445, 0.89524025, 2, 0);
INSERT INTO speaker_segments (id, transcricao_id, speaker, speaker_confidence, text, start_time, end_time, confidence, words_count, channel) VALUES (846, 21, 'D', 0.479, 'Ok.', 39445, 40885, 0.479, 1, 0);
INSERT INTO speaker_segments (id, transcricao_id, speaker, speaker_confidence, text, start_time, end_time, confidence, words_count, channel) VALUES (847, 21, 'A', 0.8647018, 'Aqui sim, doutor.', 40885, 43645, 0.8647018, 3, 0);
INSERT INTO speaker_segments (id, transcricao_id, speaker, speaker_confidence, text, start_time, end_time, confidence, words_count, channel) VALUES (848, 21, 'D', 0.71908075, 'Boa tarde, Douglas.', 43645, 45565, 0.71908075, 3, 0);
INSERT INTO speaker_segments (id, transcricao_id, speaker, speaker_confidence, text, start_time, end_time, confidence, words_count, channel) VALUES (849, 21, 'C', 0.71542776, 'Boa tarde.', 45565, 46285, 0.71542776, 2, 0);
INSERT INTO speaker_segments (id, transcricao_id, speaker, speaker_confidence, text, start_time, end_time, confidence, words_count, channel) VALUES (850, 21, 'D', 0.79165494, 'Douglas, o senhor vai ser ouvido sobre o fato número 5º da denúncia, ok? Eu vou fazer a leitura do fato para ver se o senhor se recorda, porque já faz algum tempo. No dia 22 de outubro de 2019, por volta das 22h30, na Rua Lago Azul, número 248, no bairro Santa Bárbara, cidade de Alvorada, os soldados Josimar da Silva Pereira, Felipe Ferreira Janiquim e Mateus Arcenes de Voraes, em comunhão de resposta e condição de vontade, todos de serviço pilotado no vigésimo quarto PTM, apropriaram-se de valores que tinham força e razão da função apreendido durante a ocorrência policial registrada sob o número 100-464-2019-14700, relativa aos crimes de tráfego de entorpecentes e porte legal de arma. Na oportunidade, os denunciados prenderam Douglas de Oliveira Mafalda e Rafael de Cidade Barbosa por tráfico de estropecentes e porte ilegal de arma, aprendendo, dentre outros materiais, dois coletes balísticos, uma pistola calibre .380, um revólver calibre .38, um revólver calibre .32 e uma espigada calibre .12. também 2.289 gramas de cocaína, 79 gramas de maconha e, ao menos, um grama de crack. E R$331 em dinheiro.', 47967, 142062, 0.79165494, 186, 0);
INSERT INTO speaker_segments (id, transcricao_id, speaker, speaker_confidence, text, start_time, end_time, confidence, words_count, channel) VALUES (851, 21, 'A', 0.614, 'Pergunta.', 142062, 145062, 0.614, 1, 0);
INSERT INTO speaker_segments (id, transcricao_id, speaker, speaker_confidence, text, start_time, end_time, confidence, words_count, channel) VALUES (852, 21, 'D', 0.806027, 'Douglas, sobre essa ocorrência, o que o senhor tem a nos dizer?', 149702, 154242, 0.806027, 12, 0);
INSERT INTO speaker_segments (id, transcricao_id, speaker, speaker_confidence, text, start_time, end_time, confidence, words_count, channel) VALUES (853, 21, 'A', 0.377903, 'E aí e o problema do tornozelo né é alguma coisa aconteceu e tá.', 157115, 168995, 0.377903, 14, 0);
INSERT INTO speaker_segments (id, transcricao_id, speaker, speaker_confidence, text, start_time, end_time, confidence, words_count, channel) VALUES (854, 21, 'B', 0.4907401, 'Voltou a normal E aí E aí.', 168995, 177445, 0.4907401, 7, 0);
INSERT INTO speaker_segments (id, transcricao_id, speaker, speaker_confidence, text, start_time, end_time, confidence, words_count, channel) VALUES (855, 21, 'D', 0.5180132, 'O Bernadete põe ele na tela principal.', 177445, 179135, 0.5180132, 7, 0);
INSERT INTO speaker_segments (id, transcricao_id, speaker, speaker_confidence, text, start_time, end_time, confidence, words_count, channel) VALUES (856, 21, 'A', 0.519529, 'E ele tá na tela doutor tá.', 179135, 184475, 0.519529, 7, 0);
INSERT INTO speaker_segments (id, transcricao_id, speaker, speaker_confidence, text, start_time, end_time, confidence, words_count, channel) VALUES (857, 21, 'C', 0.62781566, 'Mas dá na principal, que eu não estou vendo.', 184475, 190122, 0.62781566, 9, 0);
INSERT INTO speaker_segments (id, transcricao_id, speaker, speaker_confidence, text, start_time, end_time, confidence, words_count, channel) VALUES (858, 21, 'A', 0.62438333, 'Aqui a gente está.', 193302, 196082, 0.62438333, 4, 0);
INSERT INTO speaker_segments (id, transcricao_id, speaker, speaker_confidence, text, start_time, end_time, confidence, words_count, channel) VALUES (859, 21, 'D', 0.8230529, 'Douglas, ouviu sobre essa ocorrência?', 196082, 201222, 0.8230529, 5, 0);
INSERT INTO speaker_segments (id, transcricao_id, speaker, speaker_confidence, text, start_time, end_time, confidence, words_count, channel) VALUES (860, 21, 'C', 0.7735, 'Escutei, escutei.', 201222, 203082, 0.7735, 2, 0);
INSERT INTO speaker_segments (id, transcricao_id, speaker, speaker_confidence, text, start_time, end_time, confidence, words_count, channel) VALUES (861, 21, 'D', 0.81704307, '22 de outubro de 2019, o senhor foi preso, junto com o Rafael, por porte ilegal de drogas e arma. Sobre esse fato, o que o senhor pode nos dizer sobre isso?', 203082, 218612, 0.81704307, 32, 0);
INSERT INTO speaker_segments (id, transcricao_id, speaker, speaker_confidence, text, start_time, end_time, confidence, words_count, channel) VALUES (862, 21, 'C', 0.68094903, 'Não tenho nada a dizer sobre isso.', 218612, 222132, 0.68094903, 7, 0);
INSERT INTO speaker_segments (id, transcricao_id, speaker, speaker_confidence, text, start_time, end_time, confidence, words_count, channel) VALUES (863, 21, 'D', 0.79700947, 'O senhor estava na posse de entorpecente e armas?', 222132, 226592, 0.79700947, 9, 0);
INSERT INTO speaker_segments (id, transcricao_id, speaker, speaker_confidence, text, start_time, end_time, confidence, words_count, channel) VALUES (864, 21, 'C', 0.7912666, 'Estava na posse, estava.', 226592, 229692, 0.7912666, 4, 0);
INSERT INTO speaker_segments (id, transcricao_id, speaker, speaker_confidence, text, start_time, end_time, confidence, words_count, channel) VALUES (865, 21, 'D', 0.7679148, 'E o senhor se recorda de quantas armas o senhor tinha?', 229692, 236392, 0.7679148, 11, 0);
INSERT INTO speaker_segments (id, transcricao_id, speaker, speaker_confidence, text, start_time, end_time, confidence, words_count, channel) VALUES (866, 21, 'C', 0.70098877, 'Claro, não me lembro.', 236392, 238532, 0.70098877, 4, 0);
INSERT INTO speaker_segments (id, transcricao_id, speaker, speaker_confidence, text, start_time, end_time, confidence, words_count, channel) VALUES (867, 21, 'D', 0.9268195, 'E a quantidade de drogas?', 238532, 240612, 0.9268195, 5, 0);
INSERT INTO speaker_segments (id, transcricao_id, speaker, speaker_confidence, text, start_time, end_time, confidence, words_count, channel) VALUES (868, 21, 'C', 0.6927886, 'Também não sei, não era eu que vendia.', 241996, 244876, 0.6927886, 8, 0);
INSERT INTO speaker_segments (id, transcricao_id, speaker, speaker_confidence, text, start_time, end_time, confidence, words_count, channel) VALUES (869, 21, 'D', 0.76619697, 'Valores em dinheiro, o senhor saberia dizer quanto de dinheiro o senhor tinha nessa oportunidade, junto com o Rafael?', 244876, 255336, 0.76619697, 19, 0);
INSERT INTO speaker_segments (id, transcricao_id, speaker, speaker_confidence, text, start_time, end_time, confidence, words_count, channel) VALUES (870, 21, 'C', 0.773043, 'Não sei.', 255336, 257456, 0.773043, 2, 0);
INSERT INTO speaker_segments (id, transcricao_id, speaker, speaker_confidence, text, start_time, end_time, confidence, words_count, channel) VALUES (871, 21, 'D', 0.80529785, 'Não se recorda? Não. Durante essa ocorrência, o senhor chegou a notar se algum policial pegou algum dinheiro para ele?', 257456, 266216, 0.80529785, 20, 0);
INSERT INTO speaker_segments (id, transcricao_id, speaker, speaker_confidence, text, start_time, end_time, confidence, words_count, channel) VALUES (872, 21, 'B', 0.919, 'Ouviu, Douglas?', 272472, 276872, 0.919, 2, 0);
INSERT INTO speaker_segments (id, transcricao_id, speaker, speaker_confidence, text, start_time, end_time, confidence, words_count, channel) VALUES (873, 21, 'C', 0.849, 'Douglas.', 276872, 279872, 0.849, 1, 0);
INSERT INTO speaker_segments (id, transcricao_id, speaker, speaker_confidence, text, start_time, end_time, confidence, words_count, channel) VALUES (874, 21, 'D', 0.82240105, 'Está me ouvindo?', 281672, 284852, 0.82240105, 3, 0);
INSERT INTO speaker_segments (id, transcricao_id, speaker, speaker_confidence, text, start_time, end_time, confidence, words_count, channel) VALUES (875, 21, 'B', 0.73709244, 'De novo deu.', 286132, 290772, 0.73709244, 3, 0);
INSERT INTO speaker_segments (id, transcricao_id, speaker, speaker_confidence, text, start_time, end_time, confidence, words_count, channel) VALUES (876, 21, 'A', 0.79088366, 'Ele continua aqui na tela, doutor, PK Douglas. Douglas, você está nos ouvindo? Porque ele não caiu, ele está aqui no… Vamos ver, espera aí. Agora caiu, estou colocando ele de novo.', 290772, 317713, 0.79088366, 32, 0);
INSERT INTO speaker_segments (id, transcricao_id, speaker, speaker_confidence, text, start_time, end_time, confidence, words_count, channel) VALUES (877, 21, 'B', 0.31982422, 'Você.', 317713, 320713, 0.31982422, 1, 0);
INSERT INTO speaker_segments (id, transcricao_id, speaker, speaker_confidence, text, start_time, end_time, confidence, words_count, channel) VALUES (878, 21, 'A', 0.679965, 'Está saindo da APK que está… Coloca o Diogo de novo. Coloca o Douglas de novo.', 328033, 336490, 0.679965, 16, 0);
INSERT INTO speaker_segments (id, transcricao_id, speaker, speaker_confidence, text, start_time, end_time, confidence, words_count, channel) VALUES (879, 21, 'C', 0.67762816, 'Tá, só um momento que eu tô configurando aqui.', 336490, 339010, 0.67762816, 9, 0);
INSERT INTO speaker_segments (id, transcricao_id, speaker, speaker_confidence, text, start_time, end_time, confidence, words_count, channel) VALUES (880, 21, 'B', 0.8497435, 'Tá certo. Pronto.', 339010, 347070, 0.8497435, 3, 0);
INSERT INTO speaker_segments (id, transcricao_id, speaker, speaker_confidence, text, start_time, end_time, confidence, words_count, channel) VALUES (881, 21, 'A', 0.7671834, 'Doutor, ele tá de volta.', 356650, 359050, 0.7671834, 5, 0);
INSERT INTO speaker_segments (id, transcricao_id, speaker, speaker_confidence, text, start_time, end_time, confidence, words_count, channel) VALUES (882, 21, 'D', 0.729, 'Douglas!', 359050, 362050, 0.729, 1, 0);
INSERT INTO speaker_segments (id, transcricao_id, speaker, speaker_confidence, text, start_time, end_time, confidence, words_count, channel) VALUES (883, 21, 'B', 0.834, 'Opa!', 362630, 363610, 0.834, 1, 0);
INSERT INTO speaker_segments (id, transcricao_id, speaker, speaker_confidence, text, start_time, end_time, confidence, words_count, channel) VALUES (884, 21, 'D', 0.71159005, 'Durante essa ocorrência, o senhor chegou a notar se algum policial tinha pego o dinheiro que estava na posse de vocês? Acho que foi agora. Mas não tem certeza.', 364154, 379014, 0.71159005, 29, 0);
INSERT INTO speaker_segments (id, transcricao_id, speaker, speaker_confidence, text, start_time, end_time, confidence, words_count, channel) VALUES (885, 21, 'B', 0.62228644, 'É, não tem certeza.', 379014, 382494, 0.62228644, 4, 0);
INSERT INTO speaker_segments (id, transcricao_id, speaker, speaker_confidence, text, start_time, end_time, confidence, words_count, channel) VALUES (886, 21, 'D', 0.7664448, 'E como eu já tinha lhe perguntado quantidade de droga, quantidade de dinheiro e quantidade de arma, o senhor não se lembra.', 382994, 390634, 0.7664448, 22, 0);
INSERT INTO speaker_segments (id, transcricao_id, speaker, speaker_confidence, text, start_time, end_time, confidence, words_count, channel) VALUES (887, 21, 'C', 0.69259316, 'Não me lembro porque eles não pegaram nada com nós, os sojuíras. Eles chegaram em outra residência.', 391643, 397823, 0.69259316, 17, 0);
INSERT INTO speaker_segments (id, transcricao_id, speaker, speaker_confidence, text, start_time, end_time, confidence, words_count, channel) VALUES (888, 21, 'D', 0.7877884, 'E isso não estava com vocês?', 397823, 400243, 0.7877884, 6, 0);
INSERT INTO speaker_segments (id, transcricao_id, speaker, speaker_confidence, text, start_time, end_time, confidence, words_count, channel) VALUES (889, 21, 'C', 0.78967446, 'Não, não estava com nós. Eles pegaram em outra residência e daí botaram em nós.', 400243, 405563, 0.78967446, 15, 0);
INSERT INTO speaker_segments (id, transcricao_id, speaker, speaker_confidence, text, start_time, end_time, confidence, words_count, channel) VALUES (890, 21, 'D', 0.78441405, 'E você estava perto dessa residência?', 405563, 408923, 0.78441405, 6, 0);
INSERT INTO speaker_segments (id, transcricao_id, speaker, speaker_confidence, text, start_time, end_time, confidence, words_count, channel) VALUES (891, 21, 'C', 0.70424235, 'Ah, no caso, eu moro umas duas quartas dessa residência. Tá.', 408923, 413403, 0.70424235, 11, 0);
INSERT INTO speaker_segments (id, transcricao_id, speaker, speaker_confidence, text, start_time, end_time, confidence, words_count, channel) VALUES (892, 21, 'D', 0.8431563, 'E o senhor está preso por tráfico?', 413403, 415743, 0.8431563, 7, 0);
INSERT INTO speaker_segments (id, transcricao_id, speaker, speaker_confidence, text, start_time, end_time, confidence, words_count, channel) VALUES (893, 21, 'C', 0.69946146, 'Agora eu estou preso por tráfico? Poxa, eu fiquei quatro dias na rua só. Tá iniciado de novo.', 415743, 424297, 0.69946146, 18, 0);
INSERT INTO speaker_segments (id, transcricao_id, speaker, speaker_confidence, text, start_time, end_time, confidence, words_count, channel) VALUES (894, 21, 'D', 0.69945425, 'Tá certo. Palavra ao conselho, Capitão Marcelo.', 424297, 428797, 0.69945425, 7, 0);
INSERT INTO speaker_segments (id, transcricao_id, speaker, speaker_confidence, text, start_time, end_time, confidence, words_count, channel) VALUES (895, 21, 'B', 0.7757904, 'Sem perguntas, Excelência.', 428797, 433337, 0.7757904, 3, 0);
INSERT INTO speaker_segments (id, transcricao_id, speaker, speaker_confidence, text, start_time, end_time, confidence, words_count, channel) VALUES (896, 21, 'D', 0.69968057, 'Ao Capitão Koniki.', 433337, 435937, 0.69968057, 3, 0);
INSERT INTO speaker_segments (id, transcricao_id, speaker, speaker_confidence, text, start_time, end_time, confidence, words_count, channel) VALUES (897, 21, 'C', 0.78916794, 'Sem perguntas.', 435937, 436777, 0.78916794, 2, 0);
INSERT INTO speaker_segments (id, transcricao_id, speaker, speaker_confidence, text, start_time, end_time, confidence, words_count, channel) VALUES (898, 21, 'D', 0.8342305, 'Ministério Público.', 436777, 441077, 0.8342305, 2, 0);
INSERT INTO speaker_segments (id, transcricao_id, speaker, speaker_confidence, text, start_time, end_time, confidence, words_count, channel) VALUES (899, 21, 'E', 0.78305614, 'Boa tarde. Exatamente o que aconteceu nesse dia, Douglas? O senhor conheceu os policiais militares?', 441077, 449757, 0.78305614, 15, 0);
INSERT INTO speaker_segments (id, transcricao_id, speaker, speaker_confidence, text, start_time, end_time, confidence, words_count, channel) VALUES (900, 21, 'C', 0.7280621, 'No caso, eu estava sem medir o meio para levar meus primos para o colégio e tomei uma abordagem da polícia. Nisso eu tomei uma abordagem. Eles tinham abordado outro guri que morava em frente da minha casa e estava saindo para trabalhar. Eles queriam saber de droga, de arma. A gente, sabe, falava... Falava que a gente não sabia de nada e eles começaram a bater na gente e me enxertaram mais com as drogas. Falaram que se a gente não falasse nada, eles enxertariam mais e levariam mais primos.', 452596, 481096, 0.7280621, 91, 0);
INSERT INTO speaker_segments (id, transcricao_id, speaker, speaker_confidence, text, start_time, end_time, confidence, words_count, channel) VALUES (901, 21, 'E', 0.7521145, 'Você já conhecia os policiais?', 482785, 485525, 0.7521145, 5, 0);
INSERT INTO speaker_segments (id, transcricao_id, speaker, speaker_confidence, text, start_time, end_time, confidence, words_count, channel) VALUES (902, 21, 'C', 0.66991013, 'Não, não conhecia.', 485525, 488065, 0.66991013, 3, 0);
INSERT INTO speaker_segments (id, transcricao_id, speaker, speaker_confidence, text, start_time, end_time, confidence, words_count, channel) VALUES (903, 21, 'E', 0.8003854, 'Nem de vista?', 488065, 490045, 0.8003854, 3, 0);
INSERT INTO speaker_segments (id, transcricao_id, speaker, speaker_confidence, text, start_time, end_time, confidence, words_count, channel) VALUES (904, 21, 'C', 0.69729936, 'Não, nunca tinha visto.', 490045, 492665, 0.69729936, 4, 0);
INSERT INTO speaker_segments (id, transcricao_id, speaker, speaker_confidence, text, start_time, end_time, confidence, words_count, channel) VALUES (905, 21, 'E', 0.72353125, 'Eles te exigiram algum dinheiro, algo? Para não fazer isso?', 492665, 498105, 0.72353125, 10, 0);
INSERT INTO speaker_segments (id, transcricao_id, speaker, speaker_confidence, text, start_time, end_time, confidence, words_count, channel) VALUES (906, 21, 'C', 0.8508152, 'Não, não pediram nada.', 498105, 501085, 0.8508152, 4, 0);
INSERT INTO speaker_segments (id, transcricao_id, speaker, speaker_confidence, text, start_time, end_time, confidence, words_count, channel) VALUES (907, 21, 'E', 0.79725605, 'Você estava acompanhado de quem nesse momento?', 501085, 504685, 0.79725605, 7, 0);
INSERT INTO speaker_segments (id, transcricao_id, speaker, speaker_confidence, text, start_time, end_time, confidence, words_count, channel) VALUES (908, 21, 'C', 0.88972265, 'Acompanhada da minha irmã.', 504685, 506465, 0.88972265, 4, 0);
INSERT INTO speaker_segments (id, transcricao_id, speaker, speaker_confidence, text, start_time, end_time, confidence, words_count, channel) VALUES (909, 21, 'E', 0.8079838, 'Como é que é o nome dela?', 506465, 508225, 0.8079838, 7, 0);
INSERT INTO speaker_segments (id, transcricao_id, speaker, speaker_confidence, text, start_time, end_time, confidence, words_count, channel) VALUES (910, 21, 'C', 0.904, 'Cristiane.', 508225, 510085, 0.904, 1, 0);
INSERT INTO speaker_segments (id, transcricao_id, speaker, speaker_confidence, text, start_time, end_time, confidence, words_count, channel) VALUES (911, 21, 'E', 0.8019225, 'Só ela estava contigo? Mais ninguém?', 510085, 512525, 0.8019225, 6, 0);
INSERT INTO speaker_segments (id, transcricao_id, speaker, speaker_confidence, text, start_time, end_time, confidence, words_count, channel) VALUES (912, 21, 'C', 0.72663534, 'Estava só eu e as minhas crianças em casa.', 513160, 515340, 0.72663534, 9, 0);
INSERT INTO speaker_segments (id, transcricao_id, speaker, speaker_confidence, text, start_time, end_time, confidence, words_count, channel) VALUES (913, 21, 'E', 0.72180855, 'E por que eles fizeram isso contigo? Tu afirma que não conhecia eles, que.', 515340, 524360, 0.72180855, 14, 0);
INSERT INTO speaker_segments (id, transcricao_id, speaker, speaker_confidence, text, start_time, end_time, confidence, words_count, channel) VALUES (914, 21, 'C', 0.7487738, 'Não foi exigido... Nada, eu já não sei. Não tenho o que dizer.', 524360, 533140, 0.7487738, 13, 0);
INSERT INTO speaker_segments (id, transcricao_id, speaker, speaker_confidence, text, start_time, end_time, confidence, words_count, channel) VALUES (915, 21, 'E', 0.8020814, 'Tu está preso por esse fato?', 533140, 536780, 0.8020814, 6, 0);
INSERT INTO speaker_segments (id, transcricao_id, speaker, speaker_confidence, text, start_time, end_time, confidence, words_count, channel) VALUES (916, 21, 'C', 0.7264756, 'Não, no caso desse fato, eu fui embora e voltei de novo para uma outra pronta.', 536780, 542060, 0.7264756, 16, 0);
INSERT INTO speaker_segments (id, transcricao_id, speaker, speaker_confidence, text, start_time, end_time, confidence, words_count, channel) VALUES (917, 21, 'E', 0.7795394, 'Além de droga, arma, teve alguma questão envolvendo arma em relação a esse fato que o juiz questionou para ti?', 543738, 554478, 0.7795394, 20, 0);
INSERT INTO speaker_segments (id, transcricao_id, speaker, speaker_confidence, text, start_time, end_time, confidence, words_count, channel) VALUES (918, 21, 'C', 0.8512734, 'Não entendi.', 554478, 555998, 0.8512734, 2, 0);
INSERT INTO speaker_segments (id, transcricao_id, speaker, speaker_confidence, text, start_time, end_time, confidence, words_count, channel) VALUES (919, 21, 'E', 0.6748876, 'Em relação a arma, tem alguma coisa de enxertar um arma também ou não?', 555998, 561438, 0.6748876, 14, 0);
INSERT INTO speaker_segments (id, transcricao_id, speaker, speaker_confidence, text, start_time, end_time, confidence, words_count, channel) VALUES (920, 21, 'C', 0.5796897, 'Podemos enxertar também um revólver.', 561438, 564758, 0.5796897, 5, 0);
INSERT INTO speaker_segments (id, transcricao_id, speaker, speaker_confidence, text, start_time, end_time, confidence, words_count, channel) VALUES (921, 21, 'E', 0.8969453, 'Qual revólver?', 564758, 566798, 0.8969453, 2, 0);
INSERT INTO speaker_segments (id, transcricao_id, speaker, speaker_confidence, text, start_time, end_time, confidence, words_count, channel) VALUES (922, 21, 'C', 0.66213214, 'Calibre 38.', 566798, 569718, 0.66213214, 2, 0);
INSERT INTO speaker_segments (id, transcricao_id, speaker, speaker_confidence, text, start_time, end_time, confidence, words_count, channel) VALUES (923, 21, 'E', 0.8207299, 'E como é que foi esse enxerto?', 569718, 572178, 0.8207299, 7, 0);
INSERT INTO speaker_segments (id, transcricao_id, speaker, speaker_confidence, text, start_time, end_time, confidence, words_count, channel) VALUES (924, 21, 'C', 0.66026735, 'Na hora da abordagem.', 573505, 575965, 0.66026735, 4, 0);
INSERT INTO speaker_segments (id, transcricao_id, speaker, speaker_confidence, text, start_time, end_time, confidence, words_count, channel) VALUES (925, 21, 'E', 0.76930076, 'O que eles falaram?', 575965, 579205, 0.76930076, 4, 0);
INSERT INTO speaker_segments (id, transcricao_id, speaker, speaker_confidence, text, start_time, end_time, confidence, words_count, channel) VALUES (926, 21, 'C', 0.74619275, 'Eles falaram que se a gente não falasse nada, eles iam chutar nós. Iam botar droga, arma e iam botar nós na cadeira.', 579205, 588105, 0.74619275, 23, 0);
INSERT INTO speaker_segments (id, transcricao_id, speaker, speaker_confidence, text, start_time, end_time, confidence, words_count, channel) VALUES (927, 21, 'E', 0.6953336, 'Tu tem vínculo com alguma facção?', 589245, 592865, 0.6953336, 6, 0);
INSERT INTO speaker_segments (id, transcricao_id, speaker, speaker_confidence, text, start_time, end_time, confidence, words_count, channel) VALUES (928, 21, 'C', 0.873, 'Não, não.', 592865, 594665, 0.873, 2, 0);
INSERT INTO speaker_segments (id, transcricao_id, speaker, speaker_confidence, text, start_time, end_time, confidence, words_count, channel) VALUES (929, 21, 'E', 0.77933985, 'Nada mais.', 594665, 597225, 0.77933985, 2, 0);
INSERT INTO speaker_segments (id, transcricao_id, speaker, speaker_confidence, text, start_time, end_time, confidence, words_count, channel) VALUES (930, 21, 'D', 0.73941714, 'Doutora Edna, pelo soldado Josimar.', 597225, 601205, 0.73941714, 5, 0);
INSERT INTO speaker_segments (id, transcricao_id, speaker, speaker_confidence, text, start_time, end_time, confidence, words_count, channel) VALUES (931, 21, 'B', 0.57749087, 'Nada, em silêncio.', 604302, 606462, 0.57749087, 3, 0);
INSERT INTO speaker_segments (id, transcricao_id, speaker, speaker_confidence, text, start_time, end_time, confidence, words_count, channel) VALUES (932, 21, 'D', 0.7052441, 'A doutora Ciomara pelo soldado Felipe.', 606462, 609702, 0.7052441, 6, 0);
INSERT INTO speaker_segments (id, transcricao_id, speaker, speaker_confidence, text, start_time, end_time, confidence, words_count, channel) VALUES (933, 21, 'B', 0.86127216, 'Nada, em silêncio.', 609702, 612302, 0.86127216, 3, 0);
INSERT INTO speaker_segments (id, transcricao_id, speaker, speaker_confidence, text, start_time, end_time, confidence, words_count, channel) VALUES (934, 21, 'D', 0.8705577, 'Pelo soldado Mateus, doutor Márcio Barcelos.', 612302, 616602, 0.8705577, 6, 0);
INSERT INTO speaker_segments (id, transcricao_id, speaker, speaker_confidence, text, start_time, end_time, confidence, words_count, channel) VALUES (935, 21, 'F', 0.74845076, 'Sim, doutor. Só para confirmar com ele, se o Mateus Alicênio, ele lembra do Mateus nessa data, presente no fato da abordagem?', 616602, 626802, 0.74845076, 22, 0);
INSERT INTO speaker_segments (id, transcricao_id, speaker, speaker_confidence, text, start_time, end_time, confidence, words_count, channel) VALUES (936, 21, 'B', 0.7406413, 'Eu não entendi.', 626802, 629762, 0.7406413, 3, 0);
INSERT INTO speaker_segments (id, transcricao_id, speaker, speaker_confidence, text, start_time, end_time, confidence, words_count, channel) VALUES (937, 21, 'F', 0.7200159, 'Se ele lembra os policiais que abordaram ele, especialmente no meu caso, o Mateus Arsene.', 631505, 636805, 0.7200159, 15, 0);
INSERT INTO speaker_segments (id, transcricao_id, speaker, speaker_confidence, text, start_time, end_time, confidence, words_count, channel) VALUES (938, 21, 'D', 0.80663544, 'O senhor lembra quem foram os policiais que lhe abordaram?', 636805, 641285, 0.80663544, 10, 0);
INSERT INTO speaker_segments (id, transcricao_id, speaker, speaker_confidence, text, start_time, end_time, confidence, words_count, channel) VALUES (939, 21, 'C', 0.78309196, 'Ah, se eu olhar pelo rosto até lembro, mas pelo nome eu não lembro.', 641285, 648185, 0.78309196, 14, 0);
INSERT INTO speaker_segments (id, transcricao_id, speaker, speaker_confidence, text, start_time, end_time, confidence, words_count, channel) VALUES (940, 21, 'F', 0.81894606, 'Chegaram a te convidar para fazer a cariação no inquérito?', 650065, 654765, 0.81894606, 10, 0);
INSERT INTO speaker_segments (id, transcricao_id, speaker, speaker_confidence, text, start_time, end_time, confidence, words_count, channel) VALUES (941, 21, 'C', 0.77893084, 'Vocês chegaram a me bater?', 654765, 657045, 0.77893084, 5, 0);
INSERT INTO speaker_segments (id, transcricao_id, speaker, speaker_confidence, text, start_time, end_time, confidence, words_count, channel) VALUES (942, 21, 'F', 0.774598, 'Não, fazer a cariação para te reconhecer os policiais.', 657045, 659525, 0.774598, 9, 0);
INSERT INTO speaker_segments (id, transcricao_id, speaker, speaker_confidence, text, start_time, end_time, confidence, words_count, channel) VALUES (943, 21, 'C', 0.6902643, 'Não, não fizeram. Isso eu vi só em uma audiência na rua. Em uma audiência na rua eu vi isso.', 660293, 668073, 0.6902643, 20, 0);
INSERT INTO speaker_segments (id, transcricao_id, speaker, speaker_confidence, text, start_time, end_time, confidence, words_count, channel) VALUES (944, 21, 'B', 0.85796076, 'Chegou a ser agredido? Quase me mataram.', 668073, 677353, 0.85796076, 7, 0);
INSERT INTO speaker_segments (id, transcricao_id, speaker, speaker_confidence, text, start_time, end_time, confidence, words_count, channel) VALUES (945, 21, 'F', 0.6855556, 'Tu reagiu ou só um apanhado de graça?', 677933, 682593, 0.6855556, 8, 0);
INSERT INTO speaker_segments (id, transcricao_id, speaker, speaker_confidence, text, start_time, end_time, confidence, words_count, channel) VALUES (946, 21, 'C', 0.64039135, 'Eu reagi contra quatro, não tem condições. Os caras quase me mataram.', 682593, 686813, 0.64039135, 12, 0);
INSERT INTO speaker_segments (id, transcricao_id, speaker, speaker_confidence, text, start_time, end_time, confidence, words_count, channel) VALUES (947, 21, 'F', 0.7464871, 'Tu não viu os nomes deles nas fardas no dia?', 690078, 694558, 0.7464871, 10, 0);
INSERT INTO speaker_segments (id, transcricao_id, speaker, speaker_confidence, text, start_time, end_time, confidence, words_count, channel) VALUES (948, 21, 'C', 0.7254081, 'Não via, não via porque eles me afogavam, eles estavam me afogando com água e botando pano na minha cara.', 694558, 700578, 0.7254081, 20, 0);
INSERT INTO speaker_segments (id, transcricao_id, speaker, speaker_confidence, text, start_time, end_time, confidence, words_count, channel) VALUES (949, 21, 'F', 0.6679251, 'Afogaram onde?', 700578, 701518, 0.6679251, 2, 0);
INSERT INTO speaker_segments (id, transcricao_id, speaker, speaker_confidence, text, start_time, end_time, confidence, words_count, channel) VALUES (950, 21, 'B', 0.5681553, 'Na camisa.', 701518, 703818, 0.5681553, 2, 0);
INSERT INTO speaker_segments (id, transcricao_id, speaker, speaker_confidence, text, start_time, end_time, confidence, words_count, channel) VALUES (951, 21, 'F', 0.8741045, 'Aonde isso?', 703818, 706038, 0.8741045, 2, 0);
INSERT INTO speaker_segments (id, transcricao_id, speaker, speaker_confidence, text, start_time, end_time, confidence, words_count, channel) VALUES (952, 21, 'C', 0.8736531, 'Na casa da minha irmã.', 706038, 707858, 0.8736531, 5, 0);
INSERT INTO speaker_segments (id, transcricao_id, speaker, speaker_confidence, text, start_time, end_time, confidence, words_count, channel) VALUES (953, 21, 'F', 0.6733156, 'Foi dentro, eles entraram na tua casa?', 707858, 709798, 0.6733156, 7, 0);
INSERT INTO speaker_segments (id, transcricao_id, speaker, speaker_confidence, text, start_time, end_time, confidence, words_count, channel) VALUES (954, 21, 'C', 0.8884495, 'Dentro da casa, na frente das crianças.', 709798, 712658, 0.8884495, 7, 0);
INSERT INTO speaker_segments (id, transcricao_id, speaker, speaker_confidence, text, start_time, end_time, confidence, words_count, channel) VALUES (955, 21, 'F', 0.82803386, 'Alguém viu, alguém filmou? O senhor registrou isso?', 712658, 717018, 0.82803386, 8, 0);
INSERT INTO speaker_segments (id, transcricao_id, speaker, speaker_confidence, text, start_time, end_time, confidence, words_count, channel) VALUES (956, 21, 'C', 0.7774581, 'Eu não sei se a minha irmã já vai registrar, mas ela viu. Isso foi de manhã cedo, umas oito e meia da manhã.', 718107, 727947, 0.7774581, 24, 0);
INSERT INTO speaker_segments (id, transcricao_id, speaker, speaker_confidence, text, start_time, end_time, confidence, words_count, channel) VALUES (957, 21, 'B', 0.8415, 'Satisfeito, doutor.', 727947, 730907, 0.8415, 2, 0);
INSERT INTO speaker_segments (id, transcricao_id, speaker, speaker_confidence, text, start_time, end_time, confidence, words_count, channel) VALUES (958, 21, 'C', 0.9115, 'Certo, doutor.', 730907, 734187, 0.9115, 2, 0);
INSERT INTO speaker_segments (id, transcricao_id, speaker, speaker_confidence, text, start_time, end_time, confidence, words_count, channel) VALUES (959, 21, 'D', 0.7872133, 'Doutor Márcio Rossano.', 734187, 738087, 0.7872133, 3, 0);
INSERT INTO speaker_segments (id, transcricao_id, speaker, speaker_confidence, text, start_time, end_time, confidence, words_count, channel) VALUES (960, 21, 'F', 0.92025554, 'Sem perguntas, doutor Francisco.', 738087, 741507, 0.92025554, 4, 0);
INSERT INTO speaker_segments (id, transcricao_id, speaker, speaker_confidence, text, start_time, end_time, confidence, words_count, channel) VALUES (961, 21, 'D', 0.8994798, 'Doutor Alfredo.', 741507, 743167, 0.8994798, 2, 0);
INSERT INTO speaker_segments (id, transcricao_id, speaker, speaker_confidence, text, start_time, end_time, confidence, words_count, channel) VALUES (962, 21, 'C', 0.5951634, 'Sem perguntas, doutor.', 747487, 749347, 0.5951634, 3, 0);
INSERT INTO speaker_segments (id, transcricao_id, speaker, speaker_confidence, text, start_time, end_time, confidence, words_count, channel) VALUES (963, 21, 'D', 0.66517645, 'A doutora Paloma?', 749347, 751767, 0.66517645, 3, 0);
INSERT INTO speaker_segments (id, transcricao_id, speaker, speaker_confidence, text, start_time, end_time, confidence, words_count, channel) VALUES (964, 21, 'B', 0.8847656, 'Sem perguntas.', 751767, 754287, 0.8847656, 2, 0);
INSERT INTO speaker_segments (id, transcricao_id, speaker, speaker_confidence, text, start_time, end_time, confidence, words_count, channel) VALUES (965, 21, 'D', 0.82061243, 'Não ficou nenhum advogado de fora?', 754287, 757167, 0.82061243, 6, 0);
INSERT INTO speaker_segments (id, transcricao_id, speaker, speaker_confidence, text, start_time, end_time, confidence, words_count, channel) VALUES (966, 21, 'B', 0.439, 'Ok.', 757167, 759807, 0.439, 1, 0);
INSERT INTO speaker_segments (id, transcricao_id, speaker, speaker_confidence, text, start_time, end_time, confidence, words_count, channel) VALUES (967, 21, 'D', 0.8296425, 'Está liberado, então, a testemunha. O Douglas pode deixar a sala. Obrigado pela colaboração da Suzette.', 759807, 768327, 0.8296425, 16, 0);
INSERT INTO speaker_segments (id, transcricao_id, speaker, speaker_confidence, text, start_time, end_time, confidence, words_count, channel) VALUES (968, 21, 'C', 0.80823046, 'Muito obrigado.', 768327, 771647, 0.80823046, 2, 0);
INSERT INTO speaker_segments (id, transcricao_id, speaker, speaker_confidence, text, start_time, end_time, confidence, words_count, channel) VALUES (969, 23, 'A', 0.75352925, 'Douglas, tu me diz o teu nome completo.', 42, 4322, 0.75352925, 8, 0);
INSERT INTO speaker_segments (id, transcricao_id, speaker, speaker_confidence, text, start_time, end_time, confidence, words_count, channel) VALUES (970, 23, 'B', 0.726, 'Nome?', 4322, 7322, 0.726, 1, 0);
INSERT INTO speaker_segments (id, transcricao_id, speaker, speaker_confidence, text, start_time, end_time, confidence, words_count, channel) VALUES (971, 23, 'A', 0.7632965, 'Tu me diz o teu nome completo, por favor.', 8442, 11442, 0.7632965, 9, 0);
INSERT INTO speaker_segments (id, transcricao_id, speaker, speaker_confidence, text, start_time, end_time, confidence, words_count, channel) VALUES (972, 23, 'C', 0.886487, 'Douglas Oliveira Mafalda.', 11442, 13982, 0.886487, 3, 0);
INSERT INTO speaker_segments (id, transcricao_id, speaker, speaker_confidence, text, start_time, end_time, confidence, words_count, channel) VALUES (973, 23, 'A', 0.81675136, 'Tu me diz a tua filiação, o nome dos teus pais.', 13982, 19502, 0.81675136, 11, 0);
INSERT INTO speaker_segments (id, transcricao_id, speaker, speaker_confidence, text, start_time, end_time, confidence, words_count, channel) VALUES (974, 23, 'C', 0.7998016, 'José Leomar de Oliveira Mafalda e Eliane Silva de Oliveira.', 19502, 23962, 0.7998016, 10, 0);
INSERT INTO speaker_segments (id, transcricao_id, speaker, speaker_confidence, text, start_time, end_time, confidence, words_count, channel) VALUES (975, 23, 'A', 0.78990275, 'E qual é o princípio que tu está aí?', 23962, 26982, 0.78990275, 9, 0);
INSERT INTO speaker_segments (id, transcricao_id, speaker, speaker_confidence, text, start_time, end_time, confidence, words_count, channel) VALUES (976, 23, 'C', 0.43456835, 'Não entendi.', 29945, 31005, 0.43456835, 2, 0);
INSERT INTO speaker_segments (id, transcricao_id, speaker, speaker_confidence, text, start_time, end_time, confidence, words_count, channel) VALUES (977, 23, 'A', 0.698109, 'Tu tá preso em qual presídio?', 31005, 34025, 0.698109, 6, 0);
INSERT INTO speaker_segments (id, transcricao_id, speaker, speaker_confidence, text, start_time, end_time, confidence, words_count, channel) VALUES (978, 23, 'C', 0.70301366, 'Tô na APK.', 34025, 35345, 0.70301366, 3, 0);
INSERT INTO speaker_segments (id, transcricao_id, speaker, speaker_confidence, text, start_time, end_time, confidence, words_count, channel) VALUES (979, 23, 'A', 0.67789453, 'Na APK.', 35345, 37085, 0.67789453, 2, 0);
INSERT INTO speaker_segments (id, transcricao_id, speaker, speaker_confidence, text, start_time, end_time, confidence, words_count, channel) VALUES (980, 23, 'B', 0.89524025, 'Tá certo.', 37085, 39445, 0.89524025, 2, 0);
INSERT INTO speaker_segments (id, transcricao_id, speaker, speaker_confidence, text, start_time, end_time, confidence, words_count, channel) VALUES (981, 23, 'D', 0.479, 'Ok.', 39445, 40885, 0.479, 1, 0);
INSERT INTO speaker_segments (id, transcricao_id, speaker, speaker_confidence, text, start_time, end_time, confidence, words_count, channel) VALUES (982, 23, 'A', 0.8647018, 'Aqui sim, doutor.', 40885, 43645, 0.8647018, 3, 0);
INSERT INTO speaker_segments (id, transcricao_id, speaker, speaker_confidence, text, start_time, end_time, confidence, words_count, channel) VALUES (983, 23, 'D', 0.71908075, 'Boa tarde, Douglas.', 43645, 45565, 0.71908075, 3, 0);
INSERT INTO speaker_segments (id, transcricao_id, speaker, speaker_confidence, text, start_time, end_time, confidence, words_count, channel) VALUES (984, 23, 'C', 0.71542776, 'Boa tarde.', 45565, 46285, 0.71542776, 2, 0);
INSERT INTO speaker_segments (id, transcricao_id, speaker, speaker_confidence, text, start_time, end_time, confidence, words_count, channel) VALUES (985, 23, 'D', 0.79165494, 'Douglas, o senhor vai ser ouvido sobre o fato número 5º da denúncia, ok? Eu vou fazer a leitura do fato para ver se o senhor se recorda, porque já faz algum tempo. No dia 22 de outubro de 2019, por volta das 22h30, na Rua Lago Azul, número 248, no bairro Santa Bárbara, cidade de Alvorada, os soldados Josimar da Silva Pereira, Felipe Ferreira Janiquim e Mateus Arcenes de Voraes, em comunhão de resposta e condição de vontade, todos de serviço pilotado no vigésimo quarto PTM, apropriaram-se de valores que tinham força e razão da função apreendido durante a ocorrência policial registrada sob o número 100-464-2019-14700, relativa aos crimes de tráfego de entorpecentes e porte legal de arma. Na oportunidade, os denunciados prenderam Douglas de Oliveira Mafalda e Rafael de Cidade Barbosa por tráfico de estropecentes e porte ilegal de arma, aprendendo, dentre outros materiais, dois coletes balísticos, uma pistola calibre .380, um revólver calibre .38, um revólver calibre .32 e uma espigada calibre .12. também 2.289 gramas de cocaína, 79 gramas de maconha e, ao menos, um grama de crack. E R$331 em dinheiro.', 47967, 142062, 0.79165494, 186, 0);
INSERT INTO speaker_segments (id, transcricao_id, speaker, speaker_confidence, text, start_time, end_time, confidence, words_count, channel) VALUES (986, 23, 'A', 0.614, 'Pergunta.', 142062, 145062, 0.614, 1, 0);
INSERT INTO speaker_segments (id, transcricao_id, speaker, speaker_confidence, text, start_time, end_time, confidence, words_count, channel) VALUES (987, 23, 'D', 0.806027, 'Douglas, sobre essa ocorrência, o que o senhor tem a nos dizer?', 149702, 154242, 0.806027, 12, 0);
INSERT INTO speaker_segments (id, transcricao_id, speaker, speaker_confidence, text, start_time, end_time, confidence, words_count, channel) VALUES (988, 23, 'A', 0.377903, 'E aí e o problema do tornozelo né é alguma coisa aconteceu e tá.', 157115, 168995, 0.377903, 14, 0);
INSERT INTO speaker_segments (id, transcricao_id, speaker, speaker_confidence, text, start_time, end_time, confidence, words_count, channel) VALUES (989, 23, 'B', 0.4907401, 'Voltou a normal E aí E aí.', 168995, 177445, 0.4907401, 7, 0);
INSERT INTO speaker_segments (id, transcricao_id, speaker, speaker_confidence, text, start_time, end_time, confidence, words_count, channel) VALUES (990, 23, 'D', 0.5180132, 'O Bernadete põe ele na tela principal.', 177445, 179135, 0.5180132, 7, 0);
INSERT INTO speaker_segments (id, transcricao_id, speaker, speaker_confidence, text, start_time, end_time, confidence, words_count, channel) VALUES (991, 23, 'A', 0.519529, 'E ele tá na tela doutor tá.', 179135, 184475, 0.519529, 7, 0);
INSERT INTO speaker_segments (id, transcricao_id, speaker, speaker_confidence, text, start_time, end_time, confidence, words_count, channel) VALUES (992, 23, 'C', 0.62781566, 'Mas dá na principal, que eu não estou vendo.', 184475, 190122, 0.62781566, 9, 0);
INSERT INTO speaker_segments (id, transcricao_id, speaker, speaker_confidence, text, start_time, end_time, confidence, words_count, channel) VALUES (993, 23, 'A', 0.62438333, 'Aqui a gente está.', 193302, 196082, 0.62438333, 4, 0);
INSERT INTO speaker_segments (id, transcricao_id, speaker, speaker_confidence, text, start_time, end_time, confidence, words_count, channel) VALUES (994, 23, 'D', 0.8230529, 'Douglas, ouviu sobre essa ocorrência?', 196082, 201222, 0.8230529, 5, 0);
INSERT INTO speaker_segments (id, transcricao_id, speaker, speaker_confidence, text, start_time, end_time, confidence, words_count, channel) VALUES (995, 23, 'C', 0.7735, 'Escutei, escutei.', 201222, 203082, 0.7735, 2, 0);
INSERT INTO speaker_segments (id, transcricao_id, speaker, speaker_confidence, text, start_time, end_time, confidence, words_count, channel) VALUES (996, 23, 'D', 0.81704307, '22 de outubro de 2019, o senhor foi preso, junto com o Rafael, por porte ilegal de drogas e arma. Sobre esse fato, o que o senhor pode nos dizer sobre isso?', 203082, 218612, 0.81704307, 32, 0);
INSERT INTO speaker_segments (id, transcricao_id, speaker, speaker_confidence, text, start_time, end_time, confidence, words_count, channel) VALUES (997, 23, 'C', 0.68094903, 'Não tenho nada a dizer sobre isso.', 218612, 222132, 0.68094903, 7, 0);
INSERT INTO speaker_segments (id, transcricao_id, speaker, speaker_confidence, text, start_time, end_time, confidence, words_count, channel) VALUES (998, 23, 'D', 0.79700947, 'O senhor estava na posse de entorpecente e armas?', 222132, 226592, 0.79700947, 9, 0);
INSERT INTO speaker_segments (id, transcricao_id, speaker, speaker_confidence, text, start_time, end_time, confidence, words_count, channel) VALUES (999, 23, 'C', 0.7912666, 'Estava na posse, estava.', 226592, 229692, 0.7912666, 4, 0);
INSERT INTO speaker_segments (id, transcricao_id, speaker, speaker_confidence, text, start_time, end_time, confidence, words_count, channel) VALUES (1000, 23, 'D', 0.7679148, 'E o senhor se recorda de quantas armas o senhor tinha?', 229692, 236392, 0.7679148, 11, 0);
INSERT INTO speaker_segments (id, transcricao_id, speaker, speaker_confidence, text, start_time, end_time, confidence, words_count, channel) VALUES (1001, 23, 'C', 0.70098877, 'Claro, não me lembro.', 236392, 238532, 0.70098877, 4, 0);
INSERT INTO speaker_segments (id, transcricao_id, speaker, speaker_confidence, text, start_time, end_time, confidence, words_count, channel) VALUES (1002, 23, 'D', 0.9268195, 'E a quantidade de drogas?', 238532, 240612, 0.9268195, 5, 0);
INSERT INTO speaker_segments (id, transcricao_id, speaker, speaker_confidence, text, start_time, end_time, confidence, words_count, channel) VALUES (1003, 23, 'C', 0.6927886, 'Também não sei, não era eu que vendia.', 241996, 244876, 0.6927886, 8, 0);
INSERT INTO speaker_segments (id, transcricao_id, speaker, speaker_confidence, text, start_time, end_time, confidence, words_count, channel) VALUES (1004, 23, 'D', 0.76619697, 'Valores em dinheiro, o senhor saberia dizer quanto de dinheiro o senhor tinha nessa oportunidade, junto com o Rafael?', 244876, 255336, 0.76619697, 19, 0);
INSERT INTO speaker_segments (id, transcricao_id, speaker, speaker_confidence, text, start_time, end_time, confidence, words_count, channel) VALUES (1005, 23, 'C', 0.773043, 'Não sei.', 255336, 257456, 0.773043, 2, 0);
INSERT INTO speaker_segments (id, transcricao_id, speaker, speaker_confidence, text, start_time, end_time, confidence, words_count, channel) VALUES (1006, 23, 'D', 0.80529785, 'Não se recorda? Não. Durante essa ocorrência, o senhor chegou a notar se algum policial pegou algum dinheiro para ele?', 257456, 266216, 0.80529785, 20, 0);
INSERT INTO speaker_segments (id, transcricao_id, speaker, speaker_confidence, text, start_time, end_time, confidence, words_count, channel) VALUES (1007, 23, 'B', 0.919, 'Ouviu, Douglas?', 272472, 276872, 0.919, 2, 0);
INSERT INTO speaker_segments (id, transcricao_id, speaker, speaker_confidence, text, start_time, end_time, confidence, words_count, channel) VALUES (1008, 23, 'C', 0.849, 'Douglas.', 276872, 279872, 0.849, 1, 0);
INSERT INTO speaker_segments (id, transcricao_id, speaker, speaker_confidence, text, start_time, end_time, confidence, words_count, channel) VALUES (1009, 23, 'D', 0.82240105, 'Está me ouvindo?', 281672, 284852, 0.82240105, 3, 0);
INSERT INTO speaker_segments (id, transcricao_id, speaker, speaker_confidence, text, start_time, end_time, confidence, words_count, channel) VALUES (1010, 23, 'B', 0.73709244, 'De novo deu.', 286132, 290772, 0.73709244, 3, 0);
INSERT INTO speaker_segments (id, transcricao_id, speaker, speaker_confidence, text, start_time, end_time, confidence, words_count, channel) VALUES (1011, 23, 'A', 0.79088366, 'Ele continua aqui na tela, doutor, PK Douglas. Douglas, você está nos ouvindo? Porque ele não caiu, ele está aqui no… Vamos ver, espera aí. Agora caiu, estou colocando ele de novo.', 290772, 317713, 0.79088366, 32, 0);
INSERT INTO speaker_segments (id, transcricao_id, speaker, speaker_confidence, text, start_time, end_time, confidence, words_count, channel) VALUES (1012, 23, 'B', 0.31982422, 'Você.', 317713, 320713, 0.31982422, 1, 0);
INSERT INTO speaker_segments (id, transcricao_id, speaker, speaker_confidence, text, start_time, end_time, confidence, words_count, channel) VALUES (1013, 23, 'A', 0.679965, 'Está saindo da APK que está… Coloca o Diogo de novo. Coloca o Douglas de novo.', 328033, 336490, 0.679965, 16, 0);
INSERT INTO speaker_segments (id, transcricao_id, speaker, speaker_confidence, text, start_time, end_time, confidence, words_count, channel) VALUES (1014, 23, 'C', 0.67762816, 'Tá, só um momento que eu tô configurando aqui.', 336490, 339010, 0.67762816, 9, 0);
INSERT INTO speaker_segments (id, transcricao_id, speaker, speaker_confidence, text, start_time, end_time, confidence, words_count, channel) VALUES (1015, 23, 'B', 0.8497435, 'Tá certo. Pronto.', 339010, 347070, 0.8497435, 3, 0);
INSERT INTO speaker_segments (id, transcricao_id, speaker, speaker_confidence, text, start_time, end_time, confidence, words_count, channel) VALUES (1016, 23, 'A', 0.7671834, 'Doutor, ele tá de volta.', 356650, 359050, 0.7671834, 5, 0);
INSERT INTO speaker_segments (id, transcricao_id, speaker, speaker_confidence, text, start_time, end_time, confidence, words_count, channel) VALUES (1017, 23, 'D', 0.729, 'Douglas!', 359050, 362050, 0.729, 1, 0);
INSERT INTO speaker_segments (id, transcricao_id, speaker, speaker_confidence, text, start_time, end_time, confidence, words_count, channel) VALUES (1018, 23, 'B', 0.834, 'Opa!', 362630, 363610, 0.834, 1, 0);
INSERT INTO speaker_segments (id, transcricao_id, speaker, speaker_confidence, text, start_time, end_time, confidence, words_count, channel) VALUES (1019, 23, 'D', 0.71159005, 'Durante essa ocorrência, o senhor chegou a notar se algum policial tinha pego o dinheiro que estava na posse de vocês? Acho que foi agora. Mas não tem certeza.', 364154, 379014, 0.71159005, 29, 0);
INSERT INTO speaker_segments (id, transcricao_id, speaker, speaker_confidence, text, start_time, end_time, confidence, words_count, channel) VALUES (1020, 23, 'B', 0.62228644, 'É, não tem certeza.', 379014, 382494, 0.62228644, 4, 0);
INSERT INTO speaker_segments (id, transcricao_id, speaker, speaker_confidence, text, start_time, end_time, confidence, words_count, channel) VALUES (1021, 23, 'D', 0.7664448, 'E como eu já tinha lhe perguntado quantidade de droga, quantidade de dinheiro e quantidade de arma, o senhor não se lembra.', 382994, 390634, 0.7664448, 22, 0);
INSERT INTO speaker_segments (id, transcricao_id, speaker, speaker_confidence, text, start_time, end_time, confidence, words_count, channel) VALUES (1022, 23, 'C', 0.69259316, 'Não me lembro porque eles não pegaram nada com nós, os sojuíras. Eles chegaram em outra residência.', 391643, 397823, 0.69259316, 17, 0);
INSERT INTO speaker_segments (id, transcricao_id, speaker, speaker_confidence, text, start_time, end_time, confidence, words_count, channel) VALUES (1023, 23, 'D', 0.7877884, 'E isso não estava com vocês?', 397823, 400243, 0.7877884, 6, 0);
INSERT INTO speaker_segments (id, transcricao_id, speaker, speaker_confidence, text, start_time, end_time, confidence, words_count, channel) VALUES (1024, 23, 'C', 0.78967446, 'Não, não estava com nós. Eles pegaram em outra residência e daí botaram em nós.', 400243, 405563, 0.78967446, 15, 0);
INSERT INTO speaker_segments (id, transcricao_id, speaker, speaker_confidence, text, start_time, end_time, confidence, words_count, channel) VALUES (1025, 23, 'D', 0.78441405, 'E você estava perto dessa residência?', 405563, 408923, 0.78441405, 6, 0);
INSERT INTO speaker_segments (id, transcricao_id, speaker, speaker_confidence, text, start_time, end_time, confidence, words_count, channel) VALUES (1026, 23, 'C', 0.70424235, 'Ah, no caso, eu moro umas duas quartas dessa residência. Tá.', 408923, 413403, 0.70424235, 11, 0);
INSERT INTO speaker_segments (id, transcricao_id, speaker, speaker_confidence, text, start_time, end_time, confidence, words_count, channel) VALUES (1027, 23, 'D', 0.8431563, 'E o senhor está preso por tráfico?', 413403, 415743, 0.8431563, 7, 0);
INSERT INTO speaker_segments (id, transcricao_id, speaker, speaker_confidence, text, start_time, end_time, confidence, words_count, channel) VALUES (1028, 23, 'C', 0.69946146, 'Agora eu estou preso por tráfico? Poxa, eu fiquei quatro dias na rua só. Tá iniciado de novo.', 415743, 424297, 0.69946146, 18, 0);
INSERT INTO speaker_segments (id, transcricao_id, speaker, speaker_confidence, text, start_time, end_time, confidence, words_count, channel) VALUES (1029, 23, 'D', 0.69945425, 'Tá certo. Palavra ao conselho, Capitão Marcelo.', 424297, 428797, 0.69945425, 7, 0);
INSERT INTO speaker_segments (id, transcricao_id, speaker, speaker_confidence, text, start_time, end_time, confidence, words_count, channel) VALUES (1030, 23, 'B', 0.7757904, 'Sem perguntas, Excelência.', 428797, 433337, 0.7757904, 3, 0);
INSERT INTO speaker_segments (id, transcricao_id, speaker, speaker_confidence, text, start_time, end_time, confidence, words_count, channel) VALUES (1031, 23, 'D', 0.69968057, 'Ao Capitão Koniki.', 433337, 435937, 0.69968057, 3, 0);
INSERT INTO speaker_segments (id, transcricao_id, speaker, speaker_confidence, text, start_time, end_time, confidence, words_count, channel) VALUES (1032, 23, 'C', 0.78916794, 'Sem perguntas.', 435937, 436777, 0.78916794, 2, 0);
INSERT INTO speaker_segments (id, transcricao_id, speaker, speaker_confidence, text, start_time, end_time, confidence, words_count, channel) VALUES (1033, 23, 'D', 0.8342305, 'Ministério Público.', 436777, 441077, 0.8342305, 2, 0);
INSERT INTO speaker_segments (id, transcricao_id, speaker, speaker_confidence, text, start_time, end_time, confidence, words_count, channel) VALUES (1034, 23, 'E', 0.78305614, 'Boa tarde. Exatamente o que aconteceu nesse dia, Douglas? O senhor conheceu os policiais militares?', 441077, 449757, 0.78305614, 15, 0);
INSERT INTO speaker_segments (id, transcricao_id, speaker, speaker_confidence, text, start_time, end_time, confidence, words_count, channel) VALUES (1035, 23, 'C', 0.7280621, 'No caso, eu estava sem medir o meio para levar meus primos para o colégio e tomei uma abordagem da polícia. Nisso eu tomei uma abordagem. Eles tinham abordado outro guri que morava em frente da minha casa e estava saindo para trabalhar. Eles queriam saber de droga, de arma. A gente, sabe, falava... Falava que a gente não sabia de nada e eles começaram a bater na gente e me enxertaram mais com as drogas. Falaram que se a gente não falasse nada, eles enxertariam mais e levariam mais primos.', 452596, 481096, 0.7280621, 91, 0);
INSERT INTO speaker_segments (id, transcricao_id, speaker, speaker_confidence, text, start_time, end_time, confidence, words_count, channel) VALUES (1036, 23, 'E', 0.7521145, 'Você já conhecia os policiais?', 482785, 485525, 0.7521145, 5, 0);
INSERT INTO speaker_segments (id, transcricao_id, speaker, speaker_confidence, text, start_time, end_time, confidence, words_count, channel) VALUES (1037, 23, 'C', 0.66991013, 'Não, não conhecia.', 485525, 488065, 0.66991013, 3, 0);
INSERT INTO speaker_segments (id, transcricao_id, speaker, speaker_confidence, text, start_time, end_time, confidence, words_count, channel) VALUES (1038, 23, 'E', 0.8003854, 'Nem de vista?', 488065, 490045, 0.8003854, 3, 0);
INSERT INTO speaker_segments (id, transcricao_id, speaker, speaker_confidence, text, start_time, end_time, confidence, words_count, channel) VALUES (1039, 23, 'C', 0.69729936, 'Não, nunca tinha visto.', 490045, 492665, 0.69729936, 4, 0);
INSERT INTO speaker_segments (id, transcricao_id, speaker, speaker_confidence, text, start_time, end_time, confidence, words_count, channel) VALUES (1040, 23, 'E', 0.72353125, 'Eles te exigiram algum dinheiro, algo? Para não fazer isso?', 492665, 498105, 0.72353125, 10, 0);
INSERT INTO speaker_segments (id, transcricao_id, speaker, speaker_confidence, text, start_time, end_time, confidence, words_count, channel) VALUES (1041, 23, 'C', 0.8508152, 'Não, não pediram nada.', 498105, 501085, 0.8508152, 4, 0);
INSERT INTO speaker_segments (id, transcricao_id, speaker, speaker_confidence, text, start_time, end_time, confidence, words_count, channel) VALUES (1042, 23, 'E', 0.79725605, 'Você estava acompanhado de quem nesse momento?', 501085, 504685, 0.79725605, 7, 0);
INSERT INTO speaker_segments (id, transcricao_id, speaker, speaker_confidence, text, start_time, end_time, confidence, words_count, channel) VALUES (1043, 23, 'C', 0.88972265, 'Acompanhada da minha irmã.', 504685, 506465, 0.88972265, 4, 0);
INSERT INTO speaker_segments (id, transcricao_id, speaker, speaker_confidence, text, start_time, end_time, confidence, words_count, channel) VALUES (1044, 23, 'E', 0.8079838, 'Como é que é o nome dela?', 506465, 508225, 0.8079838, 7, 0);
INSERT INTO speaker_segments (id, transcricao_id, speaker, speaker_confidence, text, start_time, end_time, confidence, words_count, channel) VALUES (1045, 23, 'C', 0.904, 'Cristiane.', 508225, 510085, 0.904, 1, 0);
INSERT INTO speaker_segments (id, transcricao_id, speaker, speaker_confidence, text, start_time, end_time, confidence, words_count, channel) VALUES (1046, 23, 'E', 0.8019225, 'Só ela estava contigo? Mais ninguém?', 510085, 512525, 0.8019225, 6, 0);
INSERT INTO speaker_segments (id, transcricao_id, speaker, speaker_confidence, text, start_time, end_time, confidence, words_count, channel) VALUES (1047, 23, 'C', 0.72663534, 'Estava só eu e as minhas crianças em casa.', 513160, 515340, 0.72663534, 9, 0);
INSERT INTO speaker_segments (id, transcricao_id, speaker, speaker_confidence, text, start_time, end_time, confidence, words_count, channel) VALUES (1048, 23, 'E', 0.72180855, 'E por que eles fizeram isso contigo? Tu afirma que não conhecia eles, que.', 515340, 524360, 0.72180855, 14, 0);
INSERT INTO speaker_segments (id, transcricao_id, speaker, speaker_confidence, text, start_time, end_time, confidence, words_count, channel) VALUES (1049, 23, 'C', 0.7487738, 'Não foi exigido... Nada, eu já não sei. Não tenho o que dizer.', 524360, 533140, 0.7487738, 13, 0);
INSERT INTO speaker_segments (id, transcricao_id, speaker, speaker_confidence, text, start_time, end_time, confidence, words_count, channel) VALUES (1050, 23, 'E', 0.8020814, 'Tu está preso por esse fato?', 533140, 536780, 0.8020814, 6, 0);
INSERT INTO speaker_segments (id, transcricao_id, speaker, speaker_confidence, text, start_time, end_time, confidence, words_count, channel) VALUES (1051, 23, 'C', 0.7264756, 'Não, no caso desse fato, eu fui embora e voltei de novo para uma outra pronta.', 536780, 542060, 0.7264756, 16, 0);
INSERT INTO speaker_segments (id, transcricao_id, speaker, speaker_confidence, text, start_time, end_time, confidence, words_count, channel) VALUES (1052, 23, 'E', 0.7795394, 'Além de droga, arma, teve alguma questão envolvendo arma em relação a esse fato que o juiz questionou para ti?', 543738, 554478, 0.7795394, 20, 0);
INSERT INTO speaker_segments (id, transcricao_id, speaker, speaker_confidence, text, start_time, end_time, confidence, words_count, channel) VALUES (1053, 23, 'C', 0.8512734, 'Não entendi.', 554478, 555998, 0.8512734, 2, 0);
INSERT INTO speaker_segments (id, transcricao_id, speaker, speaker_confidence, text, start_time, end_time, confidence, words_count, channel) VALUES (1054, 23, 'E', 0.6748876, 'Em relação a arma, tem alguma coisa de enxertar um arma também ou não?', 555998, 561438, 0.6748876, 14, 0);
INSERT INTO speaker_segments (id, transcricao_id, speaker, speaker_confidence, text, start_time, end_time, confidence, words_count, channel) VALUES (1055, 23, 'C', 0.5796897, 'Podemos enxertar também um revólver.', 561438, 564758, 0.5796897, 5, 0);
INSERT INTO speaker_segments (id, transcricao_id, speaker, speaker_confidence, text, start_time, end_time, confidence, words_count, channel) VALUES (1056, 23, 'E', 0.8969453, 'Qual revólver?', 564758, 566798, 0.8969453, 2, 0);
INSERT INTO speaker_segments (id, transcricao_id, speaker, speaker_confidence, text, start_time, end_time, confidence, words_count, channel) VALUES (1057, 23, 'C', 0.66213214, 'Calibre 38.', 566798, 569718, 0.66213214, 2, 0);
INSERT INTO speaker_segments (id, transcricao_id, speaker, speaker_confidence, text, start_time, end_time, confidence, words_count, channel) VALUES (1058, 23, 'E', 0.8207299, 'E como é que foi esse enxerto?', 569718, 572178, 0.8207299, 7, 0);
INSERT INTO speaker_segments (id, transcricao_id, speaker, speaker_confidence, text, start_time, end_time, confidence, words_count, channel) VALUES (1059, 23, 'C', 0.66026735, 'Na hora da abordagem.', 573505, 575965, 0.66026735, 4, 0);
INSERT INTO speaker_segments (id, transcricao_id, speaker, speaker_confidence, text, start_time, end_time, confidence, words_count, channel) VALUES (1060, 23, 'E', 0.76930076, 'O que eles falaram?', 575965, 579205, 0.76930076, 4, 0);
INSERT INTO speaker_segments (id, transcricao_id, speaker, speaker_confidence, text, start_time, end_time, confidence, words_count, channel) VALUES (1061, 23, 'C', 0.74619275, 'Eles falaram que se a gente não falasse nada, eles iam chutar nós. Iam botar droga, arma e iam botar nós na cadeira.', 579205, 588105, 0.74619275, 23, 0);
INSERT INTO speaker_segments (id, transcricao_id, speaker, speaker_confidence, text, start_time, end_time, confidence, words_count, channel) VALUES (1062, 23, 'E', 0.6953336, 'Tu tem vínculo com alguma facção?', 589245, 592865, 0.6953336, 6, 0);
INSERT INTO speaker_segments (id, transcricao_id, speaker, speaker_confidence, text, start_time, end_time, confidence, words_count, channel) VALUES (1063, 23, 'C', 0.873, 'Não, não.', 592865, 594665, 0.873, 2, 0);
INSERT INTO speaker_segments (id, transcricao_id, speaker, speaker_confidence, text, start_time, end_time, confidence, words_count, channel) VALUES (1064, 23, 'E', 0.77933985, 'Nada mais.', 594665, 597225, 0.77933985, 2, 0);
INSERT INTO speaker_segments (id, transcricao_id, speaker, speaker_confidence, text, start_time, end_time, confidence, words_count, channel) VALUES (1065, 23, 'D', 0.73941714, 'Doutora Edna, pelo soldado Josimar.', 597225, 601205, 0.73941714, 5, 0);
INSERT INTO speaker_segments (id, transcricao_id, speaker, speaker_confidence, text, start_time, end_time, confidence, words_count, channel) VALUES (1066, 23, 'B', 0.57749087, 'Nada, em silêncio.', 604302, 606462, 0.57749087, 3, 0);
INSERT INTO speaker_segments (id, transcricao_id, speaker, speaker_confidence, text, start_time, end_time, confidence, words_count, channel) VALUES (1067, 23, 'D', 0.7052441, 'A doutora Ciomara pelo soldado Felipe.', 606462, 609702, 0.7052441, 6, 0);
INSERT INTO speaker_segments (id, transcricao_id, speaker, speaker_confidence, text, start_time, end_time, confidence, words_count, channel) VALUES (1068, 23, 'B', 0.86127216, 'Nada, em silêncio.', 609702, 612302, 0.86127216, 3, 0);
INSERT INTO speaker_segments (id, transcricao_id, speaker, speaker_confidence, text, start_time, end_time, confidence, words_count, channel) VALUES (1069, 23, 'D', 0.8705577, 'Pelo soldado Mateus, doutor Márcio Barcelos.', 612302, 616602, 0.8705577, 6, 0);
INSERT INTO speaker_segments (id, transcricao_id, speaker, speaker_confidence, text, start_time, end_time, confidence, words_count, channel) VALUES (1070, 23, 'F', 0.74845076, 'Sim, doutor. Só para confirmar com ele, se o Mateus Alicênio, ele lembra do Mateus nessa data, presente no fato da abordagem?', 616602, 626802, 0.74845076, 22, 0);
INSERT INTO speaker_segments (id, transcricao_id, speaker, speaker_confidence, text, start_time, end_time, confidence, words_count, channel) VALUES (1071, 23, 'B', 0.7406413, 'Eu não entendi.', 626802, 629762, 0.7406413, 3, 0);
INSERT INTO speaker_segments (id, transcricao_id, speaker, speaker_confidence, text, start_time, end_time, confidence, words_count, channel) VALUES (1072, 23, 'F', 0.7200159, 'Se ele lembra os policiais que abordaram ele, especialmente no meu caso, o Mateus Arsene.', 631505, 636805, 0.7200159, 15, 0);
INSERT INTO speaker_segments (id, transcricao_id, speaker, speaker_confidence, text, start_time, end_time, confidence, words_count, channel) VALUES (1073, 23, 'D', 0.80663544, 'O senhor lembra quem foram os policiais que lhe abordaram?', 636805, 641285, 0.80663544, 10, 0);
INSERT INTO speaker_segments (id, transcricao_id, speaker, speaker_confidence, text, start_time, end_time, confidence, words_count, channel) VALUES (1074, 23, 'C', 0.78309196, 'Ah, se eu olhar pelo rosto até lembro, mas pelo nome eu não lembro.', 641285, 648185, 0.78309196, 14, 0);
INSERT INTO speaker_segments (id, transcricao_id, speaker, speaker_confidence, text, start_time, end_time, confidence, words_count, channel) VALUES (1075, 23, 'F', 0.81894606, 'Chegaram a te convidar para fazer a cariação no inquérito?', 650065, 654765, 0.81894606, 10, 0);
INSERT INTO speaker_segments (id, transcricao_id, speaker, speaker_confidence, text, start_time, end_time, confidence, words_count, channel) VALUES (1076, 23, 'C', 0.77893084, 'Vocês chegaram a me bater?', 654765, 657045, 0.77893084, 5, 0);
INSERT INTO speaker_segments (id, transcricao_id, speaker, speaker_confidence, text, start_time, end_time, confidence, words_count, channel) VALUES (1077, 23, 'F', 0.774598, 'Não, fazer a cariação para te reconhecer os policiais.', 657045, 659525, 0.774598, 9, 0);
INSERT INTO speaker_segments (id, transcricao_id, speaker, speaker_confidence, text, start_time, end_time, confidence, words_count, channel) VALUES (1078, 23, 'C', 0.6902643, 'Não, não fizeram. Isso eu vi só em uma audiência na rua. Em uma audiência na rua eu vi isso.', 660293, 668073, 0.6902643, 20, 0);
INSERT INTO speaker_segments (id, transcricao_id, speaker, speaker_confidence, text, start_time, end_time, confidence, words_count, channel) VALUES (1079, 23, 'B', 0.85796076, 'Chegou a ser agredido? Quase me mataram.', 668073, 677353, 0.85796076, 7, 0);
INSERT INTO speaker_segments (id, transcricao_id, speaker, speaker_confidence, text, start_time, end_time, confidence, words_count, channel) VALUES (1080, 23, 'F', 0.6855556, 'Tu reagiu ou só um apanhado de graça?', 677933, 682593, 0.6855556, 8, 0);
INSERT INTO speaker_segments (id, transcricao_id, speaker, speaker_confidence, text, start_time, end_time, confidence, words_count, channel) VALUES (1081, 23, 'C', 0.64039135, 'Eu reagi contra quatro, não tem condições. Os caras quase me mataram.', 682593, 686813, 0.64039135, 12, 0);
INSERT INTO speaker_segments (id, transcricao_id, speaker, speaker_confidence, text, start_time, end_time, confidence, words_count, channel) VALUES (1082, 23, 'F', 0.7464871, 'Tu não viu os nomes deles nas fardas no dia?', 690078, 694558, 0.7464871, 10, 0);
INSERT INTO speaker_segments (id, transcricao_id, speaker, speaker_confidence, text, start_time, end_time, confidence, words_count, channel) VALUES (1083, 23, 'C', 0.7254081, 'Não via, não via porque eles me afogavam, eles estavam me afogando com água e botando pano na minha cara.', 694558, 700578, 0.7254081, 20, 0);
INSERT INTO speaker_segments (id, transcricao_id, speaker, speaker_confidence, text, start_time, end_time, confidence, words_count, channel) VALUES (1084, 23, 'F', 0.6679251, 'Afogaram onde?', 700578, 701518, 0.6679251, 2, 0);
INSERT INTO speaker_segments (id, transcricao_id, speaker, speaker_confidence, text, start_time, end_time, confidence, words_count, channel) VALUES (1085, 23, 'B', 0.5681553, 'Na camisa.', 701518, 703818, 0.5681553, 2, 0);
INSERT INTO speaker_segments (id, transcricao_id, speaker, speaker_confidence, text, start_time, end_time, confidence, words_count, channel) VALUES (1086, 23, 'F', 0.8741045, 'Aonde isso?', 703818, 706038, 0.8741045, 2, 0);
INSERT INTO speaker_segments (id, transcricao_id, speaker, speaker_confidence, text, start_time, end_time, confidence, words_count, channel) VALUES (1087, 23, 'C', 0.8736531, 'Na casa da minha irmã.', 706038, 707858, 0.8736531, 5, 0);
INSERT INTO speaker_segments (id, transcricao_id, speaker, speaker_confidence, text, start_time, end_time, confidence, words_count, channel) VALUES (1088, 23, 'F', 0.6733156, 'Foi dentro, eles entraram na tua casa?', 707858, 709798, 0.6733156, 7, 0);
INSERT INTO speaker_segments (id, transcricao_id, speaker, speaker_confidence, text, start_time, end_time, confidence, words_count, channel) VALUES (1089, 23, 'C', 0.8884495, 'Dentro da casa, na frente das crianças.', 709798, 712658, 0.8884495, 7, 0);
INSERT INTO speaker_segments (id, transcricao_id, speaker, speaker_confidence, text, start_time, end_time, confidence, words_count, channel) VALUES (1090, 23, 'F', 0.82803386, 'Alguém viu, alguém filmou? O senhor registrou isso?', 712658, 717018, 0.82803386, 8, 0);
INSERT INTO speaker_segments (id, transcricao_id, speaker, speaker_confidence, text, start_time, end_time, confidence, words_count, channel) VALUES (1091, 23, 'C', 0.7774581, 'Eu não sei se a minha irmã já vai registrar, mas ela viu. Isso foi de manhã cedo, umas oito e meia da manhã.', 718107, 727947, 0.7774581, 24, 0);
INSERT INTO speaker_segments (id, transcricao_id, speaker, speaker_confidence, text, start_time, end_time, confidence, words_count, channel) VALUES (1092, 23, 'B', 0.8415, 'Satisfeito, doutor.', 727947, 730907, 0.8415, 2, 0);
INSERT INTO speaker_segments (id, transcricao_id, speaker, speaker_confidence, text, start_time, end_time, confidence, words_count, channel) VALUES (1093, 23, 'C', 0.9115, 'Certo, doutor.', 730907, 734187, 0.9115, 2, 0);
INSERT INTO speaker_segments (id, transcricao_id, speaker, speaker_confidence, text, start_time, end_time, confidence, words_count, channel) VALUES (1094, 23, 'D', 0.7872133, 'Doutor Márcio Rossano.', 734187, 738087, 0.7872133, 3, 0);
INSERT INTO speaker_segments (id, transcricao_id, speaker, speaker_confidence, text, start_time, end_time, confidence, words_count, channel) VALUES (1095, 23, 'F', 0.92025554, 'Sem perguntas, doutor Francisco.', 738087, 741507, 0.92025554, 4, 0);
INSERT INTO speaker_segments (id, transcricao_id, speaker, speaker_confidence, text, start_time, end_time, confidence, words_count, channel) VALUES (1096, 23, 'D', 0.8994798, 'Doutor Alfredo.', 741507, 743167, 0.8994798, 2, 0);
INSERT INTO speaker_segments (id, transcricao_id, speaker, speaker_confidence, text, start_time, end_time, confidence, words_count, channel) VALUES (1097, 23, 'C', 0.5951634, 'Sem perguntas, doutor.', 747487, 749347, 0.5951634, 3, 0);
INSERT INTO speaker_segments (id, transcricao_id, speaker, speaker_confidence, text, start_time, end_time, confidence, words_count, channel) VALUES (1098, 23, 'D', 0.66517645, 'A doutora Paloma?', 749347, 751767, 0.66517645, 3, 0);
INSERT INTO speaker_segments (id, transcricao_id, speaker, speaker_confidence, text, start_time, end_time, confidence, words_count, channel) VALUES (1099, 23, 'B', 0.8847656, 'Sem perguntas.', 751767, 754287, 0.8847656, 2, 0);
INSERT INTO speaker_segments (id, transcricao_id, speaker, speaker_confidence, text, start_time, end_time, confidence, words_count, channel) VALUES (1100, 23, 'D', 0.82061243, 'Não ficou nenhum advogado de fora?', 754287, 757167, 0.82061243, 6, 0);
INSERT INTO speaker_segments (id, transcricao_id, speaker, speaker_confidence, text, start_time, end_time, confidence, words_count, channel) VALUES (1101, 23, 'B', 0.439, 'Ok.', 757167, 759807, 0.439, 1, 0);
INSERT INTO speaker_segments (id, transcricao_id, speaker, speaker_confidence, text, start_time, end_time, confidence, words_count, channel) VALUES (1102, 23, 'D', 0.8296425, 'Está liberado, então, a testemunha. O Douglas pode deixar a sala. Obrigado pela colaboração da Suzette.', 759807, 768327, 0.8296425, 16, 0);
INSERT INTO speaker_segments (id, transcricao_id, speaker, speaker_confidence, text, start_time, end_time, confidence, words_count, channel) VALUES (1103, 23, 'C', 0.80823046, 'Muito obrigado.', 768327, 771647, 0.80823046, 2, 0);
INSERT INTO speaker_segments (id, transcricao_id, speaker, speaker_confidence, text, start_time, end_time, confidence, words_count, channel) VALUES (1104, 25, 'A', 0.75352925, 'Douglas, tu me diz o teu nome completo.', 42, 4322, 0.75352925, 8, 0);
INSERT INTO speaker_segments (id, transcricao_id, speaker, speaker_confidence, text, start_time, end_time, confidence, words_count, channel) VALUES (1105, 25, 'B', 0.726, 'Nome?', 4322, 7322, 0.726, 1, 0);
INSERT INTO speaker_segments (id, transcricao_id, speaker, speaker_confidence, text, start_time, end_time, confidence, words_count, channel) VALUES (1106, 25, 'A', 0.7632965, 'Tu me diz o teu nome completo, por favor.', 8442, 11442, 0.7632965, 9, 0);
INSERT INTO speaker_segments (id, transcricao_id, speaker, speaker_confidence, text, start_time, end_time, confidence, words_count, channel) VALUES (1107, 25, 'C', 0.886487, 'Douglas Oliveira Mafalda.', 11442, 13982, 0.886487, 3, 0);
INSERT INTO speaker_segments (id, transcricao_id, speaker, speaker_confidence, text, start_time, end_time, confidence, words_count, channel) VALUES (1108, 25, 'A', 0.81675136, 'Tu me diz a tua filiação, o nome dos teus pais.', 13982, 19502, 0.81675136, 11, 0);
INSERT INTO speaker_segments (id, transcricao_id, speaker, speaker_confidence, text, start_time, end_time, confidence, words_count, channel) VALUES (1109, 25, 'C', 0.7998016, 'José Leomar de Oliveira Mafalda e Eliane Silva de Oliveira.', 19502, 23962, 0.7998016, 10, 0);
INSERT INTO speaker_segments (id, transcricao_id, speaker, speaker_confidence, text, start_time, end_time, confidence, words_count, channel) VALUES (1110, 25, 'A', 0.78990275, 'E qual é o princípio que tu está aí?', 23962, 26982, 0.78990275, 9, 0);
INSERT INTO speaker_segments (id, transcricao_id, speaker, speaker_confidence, text, start_time, end_time, confidence, words_count, channel) VALUES (1111, 25, 'C', 0.43456835, 'Não entendi.', 29945, 31005, 0.43456835, 2, 0);
INSERT INTO speaker_segments (id, transcricao_id, speaker, speaker_confidence, text, start_time, end_time, confidence, words_count, channel) VALUES (1112, 25, 'A', 0.698109, 'Tu tá preso em qual presídio?', 31005, 34025, 0.698109, 6, 0);
INSERT INTO speaker_segments (id, transcricao_id, speaker, speaker_confidence, text, start_time, end_time, confidence, words_count, channel) VALUES (1113, 25, 'C', 0.70301366, 'Tô na APK.', 34025, 35345, 0.70301366, 3, 0);
INSERT INTO speaker_segments (id, transcricao_id, speaker, speaker_confidence, text, start_time, end_time, confidence, words_count, channel) VALUES (1114, 25, 'A', 0.67789453, 'Na APK.', 35345, 37085, 0.67789453, 2, 0);
INSERT INTO speaker_segments (id, transcricao_id, speaker, speaker_confidence, text, start_time, end_time, confidence, words_count, channel) VALUES (1115, 25, 'B', 0.89524025, 'Tá certo.', 37085, 39445, 0.89524025, 2, 0);
INSERT INTO speaker_segments (id, transcricao_id, speaker, speaker_confidence, text, start_time, end_time, confidence, words_count, channel) VALUES (1116, 25, 'D', 0.479, 'Ok.', 39445, 40885, 0.479, 1, 0);
INSERT INTO speaker_segments (id, transcricao_id, speaker, speaker_confidence, text, start_time, end_time, confidence, words_count, channel) VALUES (1117, 25, 'A', 0.8647018, 'Aqui sim, doutor.', 40885, 43645, 0.8647018, 3, 0);
INSERT INTO speaker_segments (id, transcricao_id, speaker, speaker_confidence, text, start_time, end_time, confidence, words_count, channel) VALUES (1118, 25, 'D', 0.71908075, 'Boa tarde, Douglas.', 43645, 45565, 0.71908075, 3, 0);
INSERT INTO speaker_segments (id, transcricao_id, speaker, speaker_confidence, text, start_time, end_time, confidence, words_count, channel) VALUES (1119, 25, 'C', 0.71542776, 'Boa tarde.', 45565, 46285, 0.71542776, 2, 0);
INSERT INTO speaker_segments (id, transcricao_id, speaker, speaker_confidence, text, start_time, end_time, confidence, words_count, channel) VALUES (1170, 25, 'C', 0.7280621, 'No caso, eu estava sem medir o meio para levar meus primos para o colégio e tomei uma abordagem da polícia. Nisso eu tomei uma abordagem. Eles tinham abordado outro guri que morava em frente da minha casa e estava saindo para trabalhar. Eles queriam saber de droga, de arma. A gente, sabe, falava... Falava que a gente não sabia de nada e eles começaram a bater na gente e me enxertaram mais com as drogas. Falaram que se a gente não falasse nada, eles enxertariam mais e levariam mais primos.', 452596, 481096, 0.7280621, 91, 0);
INSERT INTO speaker_segments (id, transcricao_id, speaker, speaker_confidence, text, start_time, end_time, confidence, words_count, channel) VALUES (1171, 25, 'E', 0.7521145, 'Você já conhecia os policiais?', 482785, 485525, 0.7521145, 5, 0);
INSERT INTO speaker_segments (id, transcricao_id, speaker, speaker_confidence, text, start_time, end_time, confidence, words_count, channel) VALUES (1172, 25, 'C', 0.66991013, 'Não, não conhecia.', 485525, 488065, 0.66991013, 3, 0);
INSERT INTO speaker_segments (id, transcricao_id, speaker, speaker_confidence, text, start_time, end_time, confidence, words_count, channel) VALUES (1120, 25, 'D', 0.79165494, 'Douglas, o senhor vai ser ouvido sobre o fato número 5º da denúncia, ok? Eu vou fazer a leitura do fato para ver se o senhor se recorda, porque já faz algum tempo. No dia 22 de outubro de 2019, por volta das 22h30, na Rua Lago Azul, número 248, no bairro Santa Bárbara, cidade de Alvorada, os soldados Josimar da Silva Pereira, Felipe Ferreira Janiquim e Mateus Arcenes de Voraes, em comunhão de resposta e condição de vontade, todos de serviço pilotado no vigésimo quarto PTM, apropriaram-se de valores que tinham força e razão da função apreendido durante a ocorrência policial registrada sob o número 100-464-2019-14700, relativa aos crimes de tráfego de entorpecentes e porte legal de arma. Na oportunidade, os denunciados prenderam Douglas de Oliveira Mafalda e Rafael de Cidade Barbosa por tráfico de estropecentes e porte ilegal de arma, aprendendo, dentre outros materiais, dois coletes balísticos, uma pistola calibre .380, um revólver calibre .38, um revólver calibre .32 e uma espigada calibre .12. também 2.289 gramas de cocaína, 79 gramas de maconha e, ao menos, um grama de crack. E R$331 em dinheiro.', 47967, 142062, 0.79165494, 186, 0);
INSERT INTO speaker_segments (id, transcricao_id, speaker, speaker_confidence, text, start_time, end_time, confidence, words_count, channel) VALUES (1121, 25, 'A', 0.614, 'Pergunta.', 142062, 145062, 0.614, 1, 0);
INSERT INTO speaker_segments (id, transcricao_id, speaker, speaker_confidence, text, start_time, end_time, confidence, words_count, channel) VALUES (1122, 25, 'D', 0.806027, 'Douglas, sobre essa ocorrência, o que o senhor tem a nos dizer?', 149702, 154242, 0.806027, 12, 0);
INSERT INTO speaker_segments (id, transcricao_id, speaker, speaker_confidence, text, start_time, end_time, confidence, words_count, channel) VALUES (1123, 25, 'A', 0.377903, 'E aí e o problema do tornozelo né é alguma coisa aconteceu e tá.', 157115, 168995, 0.377903, 14, 0);
INSERT INTO speaker_segments (id, transcricao_id, speaker, speaker_confidence, text, start_time, end_time, confidence, words_count, channel) VALUES (1124, 25, 'B', 0.4907401, 'Voltou a normal E aí E aí.', 168995, 177445, 0.4907401, 7, 0);
INSERT INTO speaker_segments (id, transcricao_id, speaker, speaker_confidence, text, start_time, end_time, confidence, words_count, channel) VALUES (1125, 25, 'D', 0.5180132, 'O Bernadete põe ele na tela principal.', 177445, 179135, 0.5180132, 7, 0);
INSERT INTO speaker_segments (id, transcricao_id, speaker, speaker_confidence, text, start_time, end_time, confidence, words_count, channel) VALUES (1126, 25, 'A', 0.519529, 'E ele tá na tela doutor tá.', 179135, 184475, 0.519529, 7, 0);
INSERT INTO speaker_segments (id, transcricao_id, speaker, speaker_confidence, text, start_time, end_time, confidence, words_count, channel) VALUES (1127, 25, 'C', 0.62781566, 'Mas dá na principal, que eu não estou vendo.', 184475, 190122, 0.62781566, 9, 0);
INSERT INTO speaker_segments (id, transcricao_id, speaker, speaker_confidence, text, start_time, end_time, confidence, words_count, channel) VALUES (1128, 25, 'A', 0.62438333, 'Aqui a gente está.', 193302, 196082, 0.62438333, 4, 0);
INSERT INTO speaker_segments (id, transcricao_id, speaker, speaker_confidence, text, start_time, end_time, confidence, words_count, channel) VALUES (1129, 25, 'D', 0.8230529, 'Douglas, ouviu sobre essa ocorrência?', 196082, 201222, 0.8230529, 5, 0);
INSERT INTO speaker_segments (id, transcricao_id, speaker, speaker_confidence, text, start_time, end_time, confidence, words_count, channel) VALUES (1130, 25, 'C', 0.7735, 'Escutei, escutei.', 201222, 203082, 0.7735, 2, 0);
INSERT INTO speaker_segments (id, transcricao_id, speaker, speaker_confidence, text, start_time, end_time, confidence, words_count, channel) VALUES (1131, 25, 'D', 0.81704307, '22 de outubro de 2019, o senhor foi preso, junto com o Rafael, por porte ilegal de drogas e arma. Sobre esse fato, o que o senhor pode nos dizer sobre isso?', 203082, 218612, 0.81704307, 32, 0);
INSERT INTO speaker_segments (id, transcricao_id, speaker, speaker_confidence, text, start_time, end_time, confidence, words_count, channel) VALUES (1132, 25, 'C', 0.68094903, 'Não tenho nada a dizer sobre isso.', 218612, 222132, 0.68094903, 7, 0);
INSERT INTO speaker_segments (id, transcricao_id, speaker, speaker_confidence, text, start_time, end_time, confidence, words_count, channel) VALUES (1133, 25, 'D', 0.79700947, 'O senhor estava na posse de entorpecente e armas?', 222132, 226592, 0.79700947, 9, 0);
INSERT INTO speaker_segments (id, transcricao_id, speaker, speaker_confidence, text, start_time, end_time, confidence, words_count, channel) VALUES (1134, 25, 'C', 0.7912666, 'Estava na posse, estava.', 226592, 229692, 0.7912666, 4, 0);
INSERT INTO speaker_segments (id, transcricao_id, speaker, speaker_confidence, text, start_time, end_time, confidence, words_count, channel) VALUES (1135, 25, 'D', 0.7679148, 'E o senhor se recorda de quantas armas o senhor tinha?', 229692, 236392, 0.7679148, 11, 0);
INSERT INTO speaker_segments (id, transcricao_id, speaker, speaker_confidence, text, start_time, end_time, confidence, words_count, channel) VALUES (1136, 25, 'C', 0.70098877, 'Claro, não me lembro.', 236392, 238532, 0.70098877, 4, 0);
INSERT INTO speaker_segments (id, transcricao_id, speaker, speaker_confidence, text, start_time, end_time, confidence, words_count, channel) VALUES (1137, 25, 'D', 0.9268195, 'E a quantidade de drogas?', 238532, 240612, 0.9268195, 5, 0);
INSERT INTO speaker_segments (id, transcricao_id, speaker, speaker_confidence, text, start_time, end_time, confidence, words_count, channel) VALUES (1138, 25, 'C', 0.6927886, 'Também não sei, não era eu que vendia.', 241996, 244876, 0.6927886, 8, 0);
INSERT INTO speaker_segments (id, transcricao_id, speaker, speaker_confidence, text, start_time, end_time, confidence, words_count, channel) VALUES (1139, 25, 'D', 0.76619697, 'Valores em dinheiro, o senhor saberia dizer quanto de dinheiro o senhor tinha nessa oportunidade, junto com o Rafael?', 244876, 255336, 0.76619697, 19, 0);
INSERT INTO speaker_segments (id, transcricao_id, speaker, speaker_confidence, text, start_time, end_time, confidence, words_count, channel) VALUES (1140, 25, 'C', 0.773043, 'Não sei.', 255336, 257456, 0.773043, 2, 0);
INSERT INTO speaker_segments (id, transcricao_id, speaker, speaker_confidence, text, start_time, end_time, confidence, words_count, channel) VALUES (1141, 25, 'D', 0.80529785, 'Não se recorda? Não. Durante essa ocorrência, o senhor chegou a notar se algum policial pegou algum dinheiro para ele?', 257456, 266216, 0.80529785, 20, 0);
INSERT INTO speaker_segments (id, transcricao_id, speaker, speaker_confidence, text, start_time, end_time, confidence, words_count, channel) VALUES (1142, 25, 'B', 0.919, 'Ouviu, Douglas?', 272472, 276872, 0.919, 2, 0);
INSERT INTO speaker_segments (id, transcricao_id, speaker, speaker_confidence, text, start_time, end_time, confidence, words_count, channel) VALUES (1143, 25, 'C', 0.849, 'Douglas.', 276872, 279872, 0.849, 1, 0);
INSERT INTO speaker_segments (id, transcricao_id, speaker, speaker_confidence, text, start_time, end_time, confidence, words_count, channel) VALUES (1144, 25, 'D', 0.82240105, 'Está me ouvindo?', 281672, 284852, 0.82240105, 3, 0);
INSERT INTO speaker_segments (id, transcricao_id, speaker, speaker_confidence, text, start_time, end_time, confidence, words_count, channel) VALUES (1145, 25, 'B', 0.73709244, 'De novo deu.', 286132, 290772, 0.73709244, 3, 0);
INSERT INTO speaker_segments (id, transcricao_id, speaker, speaker_confidence, text, start_time, end_time, confidence, words_count, channel) VALUES (1146, 25, 'A', 0.79088366, 'Ele continua aqui na tela, doutor, PK Douglas. Douglas, você está nos ouvindo? Porque ele não caiu, ele está aqui no… Vamos ver, espera aí. Agora caiu, estou colocando ele de novo.', 290772, 317713, 0.79088366, 32, 0);
INSERT INTO speaker_segments (id, transcricao_id, speaker, speaker_confidence, text, start_time, end_time, confidence, words_count, channel) VALUES (1147, 25, 'B', 0.31982422, 'Você.', 317713, 320713, 0.31982422, 1, 0);
INSERT INTO speaker_segments (id, transcricao_id, speaker, speaker_confidence, text, start_time, end_time, confidence, words_count, channel) VALUES (1148, 25, 'A', 0.679965, 'Está saindo da APK que está… Coloca o Diogo de novo. Coloca o Douglas de novo.', 328033, 336490, 0.679965, 16, 0);
INSERT INTO speaker_segments (id, transcricao_id, speaker, speaker_confidence, text, start_time, end_time, confidence, words_count, channel) VALUES (1149, 25, 'C', 0.67762816, 'Tá, só um momento que eu tô configurando aqui.', 336490, 339010, 0.67762816, 9, 0);
INSERT INTO speaker_segments (id, transcricao_id, speaker, speaker_confidence, text, start_time, end_time, confidence, words_count, channel) VALUES (1150, 25, 'B', 0.8497435, 'Tá certo. Pronto.', 339010, 347070, 0.8497435, 3, 0);
INSERT INTO speaker_segments (id, transcricao_id, speaker, speaker_confidence, text, start_time, end_time, confidence, words_count, channel) VALUES (1151, 25, 'A', 0.7671834, 'Doutor, ele tá de volta.', 356650, 359050, 0.7671834, 5, 0);
INSERT INTO speaker_segments (id, transcricao_id, speaker, speaker_confidence, text, start_time, end_time, confidence, words_count, channel) VALUES (1152, 25, 'D', 0.729, 'Douglas!', 359050, 362050, 0.729, 1, 0);
INSERT INTO speaker_segments (id, transcricao_id, speaker, speaker_confidence, text, start_time, end_time, confidence, words_count, channel) VALUES (1153, 25, 'B', 0.834, 'Opa!', 362630, 363610, 0.834, 1, 0);
INSERT INTO speaker_segments (id, transcricao_id, speaker, speaker_confidence, text, start_time, end_time, confidence, words_count, channel) VALUES (1154, 25, 'D', 0.71159005, 'Durante essa ocorrência, o senhor chegou a notar se algum policial tinha pego o dinheiro que estava na posse de vocês? Acho que foi agora. Mas não tem certeza.', 364154, 379014, 0.71159005, 29, 0);
INSERT INTO speaker_segments (id, transcricao_id, speaker, speaker_confidence, text, start_time, end_time, confidence, words_count, channel) VALUES (1155, 25, 'B', 0.62228644, 'É, não tem certeza.', 379014, 382494, 0.62228644, 4, 0);
INSERT INTO speaker_segments (id, transcricao_id, speaker, speaker_confidence, text, start_time, end_time, confidence, words_count, channel) VALUES (1156, 25, 'D', 0.7664448, 'E como eu já tinha lhe perguntado quantidade de droga, quantidade de dinheiro e quantidade de arma, o senhor não se lembra.', 382994, 390634, 0.7664448, 22, 0);
INSERT INTO speaker_segments (id, transcricao_id, speaker, speaker_confidence, text, start_time, end_time, confidence, words_count, channel) VALUES (1157, 25, 'C', 0.69259316, 'Não me lembro porque eles não pegaram nada com nós, os sojuíras. Eles chegaram em outra residência.', 391643, 397823, 0.69259316, 17, 0);
INSERT INTO speaker_segments (id, transcricao_id, speaker, speaker_confidence, text, start_time, end_time, confidence, words_count, channel) VALUES (1158, 25, 'D', 0.7877884, 'E isso não estava com vocês?', 397823, 400243, 0.7877884, 6, 0);
INSERT INTO speaker_segments (id, transcricao_id, speaker, speaker_confidence, text, start_time, end_time, confidence, words_count, channel) VALUES (1159, 25, 'C', 0.78967446, 'Não, não estava com nós. Eles pegaram em outra residência e daí botaram em nós.', 400243, 405563, 0.78967446, 15, 0);
INSERT INTO speaker_segments (id, transcricao_id, speaker, speaker_confidence, text, start_time, end_time, confidence, words_count, channel) VALUES (1160, 25, 'D', 0.78441405, 'E você estava perto dessa residência?', 405563, 408923, 0.78441405, 6, 0);
INSERT INTO speaker_segments (id, transcricao_id, speaker, speaker_confidence, text, start_time, end_time, confidence, words_count, channel) VALUES (1161, 25, 'C', 0.70424235, 'Ah, no caso, eu moro umas duas quartas dessa residência. Tá.', 408923, 413403, 0.70424235, 11, 0);
INSERT INTO speaker_segments (id, transcricao_id, speaker, speaker_confidence, text, start_time, end_time, confidence, words_count, channel) VALUES (1162, 25, 'D', 0.8431563, 'E o senhor está preso por tráfico?', 413403, 415743, 0.8431563, 7, 0);
INSERT INTO speaker_segments (id, transcricao_id, speaker, speaker_confidence, text, start_time, end_time, confidence, words_count, channel) VALUES (1163, 25, 'C', 0.69946146, 'Agora eu estou preso por tráfico? Poxa, eu fiquei quatro dias na rua só. Tá iniciado de novo.', 415743, 424297, 0.69946146, 18, 0);
INSERT INTO speaker_segments (id, transcricao_id, speaker, speaker_confidence, text, start_time, end_time, confidence, words_count, channel) VALUES (1164, 25, 'D', 0.69945425, 'Tá certo. Palavra ao conselho, Capitão Marcelo.', 424297, 428797, 0.69945425, 7, 0);
INSERT INTO speaker_segments (id, transcricao_id, speaker, speaker_confidence, text, start_time, end_time, confidence, words_count, channel) VALUES (1165, 25, 'B', 0.7757904, 'Sem perguntas, Excelência.', 428797, 433337, 0.7757904, 3, 0);
INSERT INTO speaker_segments (id, transcricao_id, speaker, speaker_confidence, text, start_time, end_time, confidence, words_count, channel) VALUES (1166, 25, 'D', 0.69968057, 'Ao Capitão Koniki.', 433337, 435937, 0.69968057, 3, 0);
INSERT INTO speaker_segments (id, transcricao_id, speaker, speaker_confidence, text, start_time, end_time, confidence, words_count, channel) VALUES (1167, 25, 'C', 0.78916794, 'Sem perguntas.', 435937, 436777, 0.78916794, 2, 0);
INSERT INTO speaker_segments (id, transcricao_id, speaker, speaker_confidence, text, start_time, end_time, confidence, words_count, channel) VALUES (1168, 25, 'D', 0.8342305, 'Ministério Público.', 436777, 441077, 0.8342305, 2, 0);
INSERT INTO speaker_segments (id, transcricao_id, speaker, speaker_confidence, text, start_time, end_time, confidence, words_count, channel) VALUES (1169, 25, 'E', 0.78305614, 'Boa tarde. Exatamente o que aconteceu nesse dia, Douglas? O senhor conheceu os policiais militares?', 441077, 449757, 0.78305614, 15, 0);
INSERT INTO speaker_segments (id, transcricao_id, speaker, speaker_confidence, text, start_time, end_time, confidence, words_count, channel) VALUES (1173, 25, 'E', 0.8003854, 'Nem de vista?', 488065, 490045, 0.8003854, 3, 0);
INSERT INTO speaker_segments (id, transcricao_id, speaker, speaker_confidence, text, start_time, end_time, confidence, words_count, channel) VALUES (1174, 25, 'C', 0.69729936, 'Não, nunca tinha visto.', 490045, 492665, 0.69729936, 4, 0);
INSERT INTO speaker_segments (id, transcricao_id, speaker, speaker_confidence, text, start_time, end_time, confidence, words_count, channel) VALUES (1175, 25, 'E', 0.72353125, 'Eles te exigiram algum dinheiro, algo? Para não fazer isso?', 492665, 498105, 0.72353125, 10, 0);
INSERT INTO speaker_segments (id, transcricao_id, speaker, speaker_confidence, text, start_time, end_time, confidence, words_count, channel) VALUES (1176, 25, 'C', 0.8508152, 'Não, não pediram nada.', 498105, 501085, 0.8508152, 4, 0);
INSERT INTO speaker_segments (id, transcricao_id, speaker, speaker_confidence, text, start_time, end_time, confidence, words_count, channel) VALUES (1177, 25, 'E', 0.79725605, 'Você estava acompanhado de quem nesse momento?', 501085, 504685, 0.79725605, 7, 0);
INSERT INTO speaker_segments (id, transcricao_id, speaker, speaker_confidence, text, start_time, end_time, confidence, words_count, channel) VALUES (1178, 25, 'C', 0.88972265, 'Acompanhada da minha irmã.', 504685, 506465, 0.88972265, 4, 0);
INSERT INTO speaker_segments (id, transcricao_id, speaker, speaker_confidence, text, start_time, end_time, confidence, words_count, channel) VALUES (1179, 25, 'E', 0.8079838, 'Como é que é o nome dela?', 506465, 508225, 0.8079838, 7, 0);
INSERT INTO speaker_segments (id, transcricao_id, speaker, speaker_confidence, text, start_time, end_time, confidence, words_count, channel) VALUES (1180, 25, 'C', 0.904, 'Cristiane.', 508225, 510085, 0.904, 1, 0);
INSERT INTO speaker_segments (id, transcricao_id, speaker, speaker_confidence, text, start_time, end_time, confidence, words_count, channel) VALUES (1181, 25, 'E', 0.8019225, 'Só ela estava contigo? Mais ninguém?', 510085, 512525, 0.8019225, 6, 0);
INSERT INTO speaker_segments (id, transcricao_id, speaker, speaker_confidence, text, start_time, end_time, confidence, words_count, channel) VALUES (1182, 25, 'C', 0.72663534, 'Estava só eu e as minhas crianças em casa.', 513160, 515340, 0.72663534, 9, 0);
INSERT INTO speaker_segments (id, transcricao_id, speaker, speaker_confidence, text, start_time, end_time, confidence, words_count, channel) VALUES (1183, 25, 'E', 0.72180855, 'E por que eles fizeram isso contigo? Tu afirma que não conhecia eles, que.', 515340, 524360, 0.72180855, 14, 0);
INSERT INTO speaker_segments (id, transcricao_id, speaker, speaker_confidence, text, start_time, end_time, confidence, words_count, channel) VALUES (1184, 25, 'C', 0.7487738, 'Não foi exigido... Nada, eu já não sei. Não tenho o que dizer.', 524360, 533140, 0.7487738, 13, 0);
INSERT INTO speaker_segments (id, transcricao_id, speaker, speaker_confidence, text, start_time, end_time, confidence, words_count, channel) VALUES (1185, 25, 'E', 0.8020814, 'Tu está preso por esse fato?', 533140, 536780, 0.8020814, 6, 0);
INSERT INTO speaker_segments (id, transcricao_id, speaker, speaker_confidence, text, start_time, end_time, confidence, words_count, channel) VALUES (1186, 25, 'C', 0.7264756, 'Não, no caso desse fato, eu fui embora e voltei de novo para uma outra pronta.', 536780, 542060, 0.7264756, 16, 0);
INSERT INTO speaker_segments (id, transcricao_id, speaker, speaker_confidence, text, start_time, end_time, confidence, words_count, channel) VALUES (1187, 25, 'E', 0.7795394, 'Além de droga, arma, teve alguma questão envolvendo arma em relação a esse fato que o juiz questionou para ti?', 543738, 554478, 0.7795394, 20, 0);
INSERT INTO speaker_segments (id, transcricao_id, speaker, speaker_confidence, text, start_time, end_time, confidence, words_count, channel) VALUES (1188, 25, 'C', 0.8512734, 'Não entendi.', 554478, 555998, 0.8512734, 2, 0);
INSERT INTO speaker_segments (id, transcricao_id, speaker, speaker_confidence, text, start_time, end_time, confidence, words_count, channel) VALUES (1189, 25, 'E', 0.6748876, 'Em relação a arma, tem alguma coisa de enxertar um arma também ou não?', 555998, 561438, 0.6748876, 14, 0);
INSERT INTO speaker_segments (id, transcricao_id, speaker, speaker_confidence, text, start_time, end_time, confidence, words_count, channel) VALUES (1190, 25, 'C', 0.5796897, 'Podemos enxertar também um revólver.', 561438, 564758, 0.5796897, 5, 0);
INSERT INTO speaker_segments (id, transcricao_id, speaker, speaker_confidence, text, start_time, end_time, confidence, words_count, channel) VALUES (1191, 25, 'E', 0.8969453, 'Qual revólver?', 564758, 566798, 0.8969453, 2, 0);
INSERT INTO speaker_segments (id, transcricao_id, speaker, speaker_confidence, text, start_time, end_time, confidence, words_count, channel) VALUES (1192, 25, 'C', 0.66213214, 'Calibre 38.', 566798, 569718, 0.66213214, 2, 0);
INSERT INTO speaker_segments (id, transcricao_id, speaker, speaker_confidence, text, start_time, end_time, confidence, words_count, channel) VALUES (1193, 25, 'E', 0.8207299, 'E como é que foi esse enxerto?', 569718, 572178, 0.8207299, 7, 0);
INSERT INTO speaker_segments (id, transcricao_id, speaker, speaker_confidence, text, start_time, end_time, confidence, words_count, channel) VALUES (1194, 25, 'C', 0.66026735, 'Na hora da abordagem.', 573505, 575965, 0.66026735, 4, 0);
INSERT INTO speaker_segments (id, transcricao_id, speaker, speaker_confidence, text, start_time, end_time, confidence, words_count, channel) VALUES (1195, 25, 'E', 0.76930076, 'O que eles falaram?', 575965, 579205, 0.76930076, 4, 0);
INSERT INTO speaker_segments (id, transcricao_id, speaker, speaker_confidence, text, start_time, end_time, confidence, words_count, channel) VALUES (1196, 25, 'C', 0.74619275, 'Eles falaram que se a gente não falasse nada, eles iam chutar nós. Iam botar droga, arma e iam botar nós na cadeira.', 579205, 588105, 0.74619275, 23, 0);
INSERT INTO speaker_segments (id, transcricao_id, speaker, speaker_confidence, text, start_time, end_time, confidence, words_count, channel) VALUES (1197, 25, 'E', 0.6953336, 'Tu tem vínculo com alguma facção?', 589245, 592865, 0.6953336, 6, 0);
INSERT INTO speaker_segments (id, transcricao_id, speaker, speaker_confidence, text, start_time, end_time, confidence, words_count, channel) VALUES (1198, 25, 'C', 0.873, 'Não, não.', 592865, 594665, 0.873, 2, 0);
INSERT INTO speaker_segments (id, transcricao_id, speaker, speaker_confidence, text, start_time, end_time, confidence, words_count, channel) VALUES (1199, 25, 'E', 0.77933985, 'Nada mais.', 594665, 597225, 0.77933985, 2, 0);
INSERT INTO speaker_segments (id, transcricao_id, speaker, speaker_confidence, text, start_time, end_time, confidence, words_count, channel) VALUES (1200, 25, 'D', 0.73941714, 'Doutora Edna, pelo soldado Josimar.', 597225, 601205, 0.73941714, 5, 0);
INSERT INTO speaker_segments (id, transcricao_id, speaker, speaker_confidence, text, start_time, end_time, confidence, words_count, channel) VALUES (1201, 25, 'B', 0.57749087, 'Nada, em silêncio.', 604302, 606462, 0.57749087, 3, 0);
INSERT INTO speaker_segments (id, transcricao_id, speaker, speaker_confidence, text, start_time, end_time, confidence, words_count, channel) VALUES (1202, 25, 'D', 0.7052441, 'A doutora Ciomara pelo soldado Felipe.', 606462, 609702, 0.7052441, 6, 0);
INSERT INTO speaker_segments (id, transcricao_id, speaker, speaker_confidence, text, start_time, end_time, confidence, words_count, channel) VALUES (1203, 25, 'B', 0.86127216, 'Nada, em silêncio.', 609702, 612302, 0.86127216, 3, 0);
INSERT INTO speaker_segments (id, transcricao_id, speaker, speaker_confidence, text, start_time, end_time, confidence, words_count, channel) VALUES (1204, 25, 'D', 0.8705577, 'Pelo soldado Mateus, doutor Márcio Barcelos.', 612302, 616602, 0.8705577, 6, 0);
INSERT INTO speaker_segments (id, transcricao_id, speaker, speaker_confidence, text, start_time, end_time, confidence, words_count, channel) VALUES (1205, 25, 'F', 0.74845076, 'Sim, doutor. Só para confirmar com ele, se o Mateus Alicênio, ele lembra do Mateus nessa data, presente no fato da abordagem?', 616602, 626802, 0.74845076, 22, 0);
INSERT INTO speaker_segments (id, transcricao_id, speaker, speaker_confidence, text, start_time, end_time, confidence, words_count, channel) VALUES (1206, 25, 'B', 0.7406413, 'Eu não entendi.', 626802, 629762, 0.7406413, 3, 0);
INSERT INTO speaker_segments (id, transcricao_id, speaker, speaker_confidence, text, start_time, end_time, confidence, words_count, channel) VALUES (1207, 25, 'F', 0.7200159, 'Se ele lembra os policiais que abordaram ele, especialmente no meu caso, o Mateus Arsene.', 631505, 636805, 0.7200159, 15, 0);
INSERT INTO speaker_segments (id, transcricao_id, speaker, speaker_confidence, text, start_time, end_time, confidence, words_count, channel) VALUES (1208, 25, 'D', 0.80663544, 'O senhor lembra quem foram os policiais que lhe abordaram?', 636805, 641285, 0.80663544, 10, 0);
INSERT INTO speaker_segments (id, transcricao_id, speaker, speaker_confidence, text, start_time, end_time, confidence, words_count, channel) VALUES (1209, 25, 'C', 0.78309196, 'Ah, se eu olhar pelo rosto até lembro, mas pelo nome eu não lembro.', 641285, 648185, 0.78309196, 14, 0);
INSERT INTO speaker_segments (id, transcricao_id, speaker, speaker_confidence, text, start_time, end_time, confidence, words_count, channel) VALUES (1210, 25, 'F', 0.81894606, 'Chegaram a te convidar para fazer a cariação no inquérito?', 650065, 654765, 0.81894606, 10, 0);
INSERT INTO speaker_segments (id, transcricao_id, speaker, speaker_confidence, text, start_time, end_time, confidence, words_count, channel) VALUES (1211, 25, 'C', 0.77893084, 'Vocês chegaram a me bater?', 654765, 657045, 0.77893084, 5, 0);
INSERT INTO speaker_segments (id, transcricao_id, speaker, speaker_confidence, text, start_time, end_time, confidence, words_count, channel) VALUES (1212, 25, 'F', 0.774598, 'Não, fazer a cariação para te reconhecer os policiais.', 657045, 659525, 0.774598, 9, 0);
INSERT INTO speaker_segments (id, transcricao_id, speaker, speaker_confidence, text, start_time, end_time, confidence, words_count, channel) VALUES (1213, 25, 'C', 0.6902643, 'Não, não fizeram. Isso eu vi só em uma audiência na rua. Em uma audiência na rua eu vi isso.', 660293, 668073, 0.6902643, 20, 0);
INSERT INTO speaker_segments (id, transcricao_id, speaker, speaker_confidence, text, start_time, end_time, confidence, words_count, channel) VALUES (1214, 25, 'B', 0.85796076, 'Chegou a ser agredido? Quase me mataram.', 668073, 677353, 0.85796076, 7, 0);
INSERT INTO speaker_segments (id, transcricao_id, speaker, speaker_confidence, text, start_time, end_time, confidence, words_count, channel) VALUES (1215, 25, 'F', 0.6855556, 'Tu reagiu ou só um apanhado de graça?', 677933, 682593, 0.6855556, 8, 0);
INSERT INTO speaker_segments (id, transcricao_id, speaker, speaker_confidence, text, start_time, end_time, confidence, words_count, channel) VALUES (1216, 25, 'C', 0.64039135, 'Eu reagi contra quatro, não tem condições. Os caras quase me mataram.', 682593, 686813, 0.64039135, 12, 0);
INSERT INTO speaker_segments (id, transcricao_id, speaker, speaker_confidence, text, start_time, end_time, confidence, words_count, channel) VALUES (1217, 25, 'F', 0.7464871, 'Tu não viu os nomes deles nas fardas no dia?', 690078, 694558, 0.7464871, 10, 0);
INSERT INTO speaker_segments (id, transcricao_id, speaker, speaker_confidence, text, start_time, end_time, confidence, words_count, channel) VALUES (1218, 25, 'C', 0.7254081, 'Não via, não via porque eles me afogavam, eles estavam me afogando com água e botando pano na minha cara.', 694558, 700578, 0.7254081, 20, 0);
INSERT INTO speaker_segments (id, transcricao_id, speaker, speaker_confidence, text, start_time, end_time, confidence, words_count, channel) VALUES (1219, 25, 'F', 0.6679251, 'Afogaram onde?', 700578, 701518, 0.6679251, 2, 0);
INSERT INTO speaker_segments (id, transcricao_id, speaker, speaker_confidence, text, start_time, end_time, confidence, words_count, channel) VALUES (1220, 25, 'B', 0.5681553, 'Na camisa.', 701518, 703818, 0.5681553, 2, 0);
INSERT INTO speaker_segments (id, transcricao_id, speaker, speaker_confidence, text, start_time, end_time, confidence, words_count, channel) VALUES (1221, 25, 'F', 0.8741045, 'Aonde isso?', 703818, 706038, 0.8741045, 2, 0);
INSERT INTO speaker_segments (id, transcricao_id, speaker, speaker_confidence, text, start_time, end_time, confidence, words_count, channel) VALUES (1222, 25, 'C', 0.8736531, 'Na casa da minha irmã.', 706038, 707858, 0.8736531, 5, 0);
INSERT INTO speaker_segments (id, transcricao_id, speaker, speaker_confidence, text, start_time, end_time, confidence, words_count, channel) VALUES (1223, 25, 'F', 0.6733156, 'Foi dentro, eles entraram na tua casa?', 707858, 709798, 0.6733156, 7, 0);
INSERT INTO speaker_segments (id, transcricao_id, speaker, speaker_confidence, text, start_time, end_time, confidence, words_count, channel) VALUES (1224, 25, 'C', 0.8884495, 'Dentro da casa, na frente das crianças.', 709798, 712658, 0.8884495, 7, 0);
INSERT INTO speaker_segments (id, transcricao_id, speaker, speaker_confidence, text, start_time, end_time, confidence, words_count, channel) VALUES (1225, 25, 'F', 0.82803386, 'Alguém viu, alguém filmou? O senhor registrou isso?', 712658, 717018, 0.82803386, 8, 0);
INSERT INTO speaker_segments (id, transcricao_id, speaker, speaker_confidence, text, start_time, end_time, confidence, words_count, channel) VALUES (1226, 25, 'C', 0.7774581, 'Eu não sei se a minha irmã já vai registrar, mas ela viu. Isso foi de manhã cedo, umas oito e meia da manhã.', 718107, 727947, 0.7774581, 24, 0);
INSERT INTO speaker_segments (id, transcricao_id, speaker, speaker_confidence, text, start_time, end_time, confidence, words_count, channel) VALUES (1227, 25, 'B', 0.8415, 'Satisfeito, doutor.', 727947, 730907, 0.8415, 2, 0);
INSERT INTO speaker_segments (id, transcricao_id, speaker, speaker_confidence, text, start_time, end_time, confidence, words_count, channel) VALUES (1228, 25, 'C', 0.9115, 'Certo, doutor.', 730907, 734187, 0.9115, 2, 0);
INSERT INTO speaker_segments (id, transcricao_id, speaker, speaker_confidence, text, start_time, end_time, confidence, words_count, channel) VALUES (1229, 25, 'D', 0.7872133, 'Doutor Márcio Rossano.', 734187, 738087, 0.7872133, 3, 0);
INSERT INTO speaker_segments (id, transcricao_id, speaker, speaker_confidence, text, start_time, end_time, confidence, words_count, channel) VALUES (1230, 25, 'F', 0.92025554, 'Sem perguntas, doutor Francisco.', 738087, 741507, 0.92025554, 4, 0);
INSERT INTO speaker_segments (id, transcricao_id, speaker, speaker_confidence, text, start_time, end_time, confidence, words_count, channel) VALUES (1231, 25, 'D', 0.8994798, 'Doutor Alfredo.', 741507, 743167, 0.8994798, 2, 0);
INSERT INTO speaker_segments (id, transcricao_id, speaker, speaker_confidence, text, start_time, end_time, confidence, words_count, channel) VALUES (1232, 25, 'C', 0.5951634, 'Sem perguntas, doutor.', 747487, 749347, 0.5951634, 3, 0);
INSERT INTO speaker_segments (id, transcricao_id, speaker, speaker_confidence, text, start_time, end_time, confidence, words_count, channel) VALUES (1233, 25, 'D', 0.66517645, 'A doutora Paloma?', 749347, 751767, 0.66517645, 3, 0);
INSERT INTO speaker_segments (id, transcricao_id, speaker, speaker_confidence, text, start_time, end_time, confidence, words_count, channel) VALUES (1234, 25, 'B', 0.8847656, 'Sem perguntas.', 751767, 754287, 0.8847656, 2, 0);
INSERT INTO speaker_segments (id, transcricao_id, speaker, speaker_confidence, text, start_time, end_time, confidence, words_count, channel) VALUES (1235, 25, 'D', 0.82061243, 'Não ficou nenhum advogado de fora?', 754287, 757167, 0.82061243, 6, 0);
INSERT INTO speaker_segments (id, transcricao_id, speaker, speaker_confidence, text, start_time, end_time, confidence, words_count, channel) VALUES (1236, 25, 'B', 0.439, 'Ok.', 757167, 759807, 0.439, 1, 0);
INSERT INTO speaker_segments (id, transcricao_id, speaker, speaker_confidence, text, start_time, end_time, confidence, words_count, channel) VALUES (1237, 25, 'D', 0.8296425, 'Está liberado, então, a testemunha. O Douglas pode deixar a sala. Obrigado pela colaboração da Suzette.', 759807, 768327, 0.8296425, 16, 0);
INSERT INTO speaker_segments (id, transcricao_id, speaker, speaker_confidence, text, start_time, end_time, confidence, words_count, channel) VALUES (1238, 25, 'C', 0.80823046, 'Muito obrigado.', 768327, 771647, 0.80823046, 2, 0);
INSERT INTO speaker_segments (id, transcricao_id, speaker, speaker_confidence, text, start_time, end_time, confidence, words_count, channel) VALUES (1239, 27, 'A', 0.75352925, 'Douglas, tu me diz o teu nome completo.', 42, 4322, 0.75352925, 8, 0);
INSERT INTO speaker_segments (id, transcricao_id, speaker, speaker_confidence, text, start_time, end_time, confidence, words_count, channel) VALUES (1240, 27, 'B', 0.726, 'Nome?', 4322, 7322, 0.726, 1, 0);
INSERT INTO speaker_segments (id, transcricao_id, speaker, speaker_confidence, text, start_time, end_time, confidence, words_count, channel) VALUES (1241, 27, 'A', 0.7632965, 'Tu me diz o teu nome completo, por favor.', 8442, 11442, 0.7632965, 9, 0);
INSERT INTO speaker_segments (id, transcricao_id, speaker, speaker_confidence, text, start_time, end_time, confidence, words_count, channel) VALUES (1242, 27, 'C', 0.886487, 'Douglas Oliveira Mafalda.', 11442, 13982, 0.886487, 3, 0);
INSERT INTO speaker_segments (id, transcricao_id, speaker, speaker_confidence, text, start_time, end_time, confidence, words_count, channel) VALUES (1420, 29, 'B', 0.8497435, 'Tá certo. Pronto.', 339010, 347070, 0.8497435, 3, 0);
INSERT INTO speaker_segments (id, transcricao_id, speaker, speaker_confidence, text, start_time, end_time, confidence, words_count, channel) VALUES (1243, 27, 'A', 0.81675136, 'Tu me diz a tua filiação, o nome dos teus pais.', 13982, 19502, 0.81675136, 11, 0);
INSERT INTO speaker_segments (id, transcricao_id, speaker, speaker_confidence, text, start_time, end_time, confidence, words_count, channel) VALUES (1244, 27, 'C', 0.7998016, 'José Leomar de Oliveira Mafalda e Eliane Silva de Oliveira.', 19502, 23962, 0.7998016, 10, 0);
INSERT INTO speaker_segments (id, transcricao_id, speaker, speaker_confidence, text, start_time, end_time, confidence, words_count, channel) VALUES (1245, 27, 'A', 0.78990275, 'E qual é o princípio que tu está aí?', 23962, 26982, 0.78990275, 9, 0);
INSERT INTO speaker_segments (id, transcricao_id, speaker, speaker_confidence, text, start_time, end_time, confidence, words_count, channel) VALUES (1246, 27, 'C', 0.43456835, 'Não entendi.', 29945, 31005, 0.43456835, 2, 0);
INSERT INTO speaker_segments (id, transcricao_id, speaker, speaker_confidence, text, start_time, end_time, confidence, words_count, channel) VALUES (1247, 27, 'A', 0.698109, 'Tu tá preso em qual presídio?', 31005, 34025, 0.698109, 6, 0);
INSERT INTO speaker_segments (id, transcricao_id, speaker, speaker_confidence, text, start_time, end_time, confidence, words_count, channel) VALUES (1248, 27, 'C', 0.70301366, 'Tô na APK.', 34025, 35345, 0.70301366, 3, 0);
INSERT INTO speaker_segments (id, transcricao_id, speaker, speaker_confidence, text, start_time, end_time, confidence, words_count, channel) VALUES (1249, 27, 'A', 0.67789453, 'Na APK.', 35345, 37085, 0.67789453, 2, 0);
INSERT INTO speaker_segments (id, transcricao_id, speaker, speaker_confidence, text, start_time, end_time, confidence, words_count, channel) VALUES (1250, 27, 'B', 0.89524025, 'Tá certo.', 37085, 39445, 0.89524025, 2, 0);
INSERT INTO speaker_segments (id, transcricao_id, speaker, speaker_confidence, text, start_time, end_time, confidence, words_count, channel) VALUES (1251, 27, 'D', 0.479, 'Ok.', 39445, 40885, 0.479, 1, 0);
INSERT INTO speaker_segments (id, transcricao_id, speaker, speaker_confidence, text, start_time, end_time, confidence, words_count, channel) VALUES (1252, 27, 'A', 0.8647018, 'Aqui sim, doutor.', 40885, 43645, 0.8647018, 3, 0);
INSERT INTO speaker_segments (id, transcricao_id, speaker, speaker_confidence, text, start_time, end_time, confidence, words_count, channel) VALUES (1253, 27, 'D', 0.71908075, 'Boa tarde, Douglas.', 43645, 45565, 0.71908075, 3, 0);
INSERT INTO speaker_segments (id, transcricao_id, speaker, speaker_confidence, text, start_time, end_time, confidence, words_count, channel) VALUES (1254, 27, 'C', 0.71542776, 'Boa tarde.', 45565, 46285, 0.71542776, 2, 0);
INSERT INTO speaker_segments (id, transcricao_id, speaker, speaker_confidence, text, start_time, end_time, confidence, words_count, channel) VALUES (1255, 27, 'D', 0.79165494, 'Douglas, o senhor vai ser ouvido sobre o fato número 5º da denúncia, ok? Eu vou fazer a leitura do fato para ver se o senhor se recorda, porque já faz algum tempo. No dia 22 de outubro de 2019, por volta das 22h30, na Rua Lago Azul, número 248, no bairro Santa Bárbara, cidade de Alvorada, os soldados Josimar da Silva Pereira, Felipe Ferreira Janiquim e Mateus Arcenes de Voraes, em comunhão de resposta e condição de vontade, todos de serviço pilotado no vigésimo quarto PTM, apropriaram-se de valores que tinham força e razão da função apreendido durante a ocorrência policial registrada sob o número 100-464-2019-14700, relativa aos crimes de tráfego de entorpecentes e porte legal de arma. Na oportunidade, os denunciados prenderam Douglas de Oliveira Mafalda e Rafael de Cidade Barbosa por tráfico de estropecentes e porte ilegal de arma, aprendendo, dentre outros materiais, dois coletes balísticos, uma pistola calibre .380, um revólver calibre .38, um revólver calibre .32 e uma espigada calibre .12. também 2.289 gramas de cocaína, 79 gramas de maconha e, ao menos, um grama de crack. E R$331 em dinheiro.', 47967, 142062, 0.79165494, 186, 0);
INSERT INTO speaker_segments (id, transcricao_id, speaker, speaker_confidence, text, start_time, end_time, confidence, words_count, channel) VALUES (1256, 27, 'A', 0.614, 'Pergunta.', 142062, 145062, 0.614, 1, 0);
INSERT INTO speaker_segments (id, transcricao_id, speaker, speaker_confidence, text, start_time, end_time, confidence, words_count, channel) VALUES (1257, 27, 'D', 0.806027, 'Douglas, sobre essa ocorrência, o que o senhor tem a nos dizer?', 149702, 154242, 0.806027, 12, 0);
INSERT INTO speaker_segments (id, transcricao_id, speaker, speaker_confidence, text, start_time, end_time, confidence, words_count, channel) VALUES (1258, 27, 'A', 0.377903, 'E aí e o problema do tornozelo né é alguma coisa aconteceu e tá.', 157115, 168995, 0.377903, 14, 0);
INSERT INTO speaker_segments (id, transcricao_id, speaker, speaker_confidence, text, start_time, end_time, confidence, words_count, channel) VALUES (1259, 27, 'B', 0.4907401, 'Voltou a normal E aí E aí.', 168995, 177445, 0.4907401, 7, 0);
INSERT INTO speaker_segments (id, transcricao_id, speaker, speaker_confidence, text, start_time, end_time, confidence, words_count, channel) VALUES (1260, 27, 'D', 0.5180132, 'O Bernadete põe ele na tela principal.', 177445, 179135, 0.5180132, 7, 0);
INSERT INTO speaker_segments (id, transcricao_id, speaker, speaker_confidence, text, start_time, end_time, confidence, words_count, channel) VALUES (1261, 27, 'A', 0.519529, 'E ele tá na tela doutor tá.', 179135, 184475, 0.519529, 7, 0);
INSERT INTO speaker_segments (id, transcricao_id, speaker, speaker_confidence, text, start_time, end_time, confidence, words_count, channel) VALUES (1262, 27, 'C', 0.62781566, 'Mas dá na principal, que eu não estou vendo.', 184475, 190122, 0.62781566, 9, 0);
INSERT INTO speaker_segments (id, transcricao_id, speaker, speaker_confidence, text, start_time, end_time, confidence, words_count, channel) VALUES (1263, 27, 'A', 0.62438333, 'Aqui a gente está.', 193302, 196082, 0.62438333, 4, 0);
INSERT INTO speaker_segments (id, transcricao_id, speaker, speaker_confidence, text, start_time, end_time, confidence, words_count, channel) VALUES (1264, 27, 'D', 0.8230529, 'Douglas, ouviu sobre essa ocorrência?', 196082, 201222, 0.8230529, 5, 0);
INSERT INTO speaker_segments (id, transcricao_id, speaker, speaker_confidence, text, start_time, end_time, confidence, words_count, channel) VALUES (1265, 27, 'C', 0.7735, 'Escutei, escutei.', 201222, 203082, 0.7735, 2, 0);
INSERT INTO speaker_segments (id, transcricao_id, speaker, speaker_confidence, text, start_time, end_time, confidence, words_count, channel) VALUES (1266, 27, 'D', 0.81704307, '22 de outubro de 2019, o senhor foi preso, junto com o Rafael, por porte ilegal de drogas e arma. Sobre esse fato, o que o senhor pode nos dizer sobre isso?', 203082, 218612, 0.81704307, 32, 0);
INSERT INTO speaker_segments (id, transcricao_id, speaker, speaker_confidence, text, start_time, end_time, confidence, words_count, channel) VALUES (1267, 27, 'C', 0.68094903, 'Não tenho nada a dizer sobre isso.', 218612, 222132, 0.68094903, 7, 0);
INSERT INTO speaker_segments (id, transcricao_id, speaker, speaker_confidence, text, start_time, end_time, confidence, words_count, channel) VALUES (1268, 27, 'D', 0.79700947, 'O senhor estava na posse de entorpecente e armas?', 222132, 226592, 0.79700947, 9, 0);
INSERT INTO speaker_segments (id, transcricao_id, speaker, speaker_confidence, text, start_time, end_time, confidence, words_count, channel) VALUES (1269, 27, 'C', 0.7912666, 'Estava na posse, estava.', 226592, 229692, 0.7912666, 4, 0);
INSERT INTO speaker_segments (id, transcricao_id, speaker, speaker_confidence, text, start_time, end_time, confidence, words_count, channel) VALUES (1270, 27, 'D', 0.7679148, 'E o senhor se recorda de quantas armas o senhor tinha?', 229692, 236392, 0.7679148, 11, 0);
INSERT INTO speaker_segments (id, transcricao_id, speaker, speaker_confidence, text, start_time, end_time, confidence, words_count, channel) VALUES (1271, 27, 'C', 0.70098877, 'Claro, não me lembro.', 236392, 238532, 0.70098877, 4, 0);
INSERT INTO speaker_segments (id, transcricao_id, speaker, speaker_confidence, text, start_time, end_time, confidence, words_count, channel) VALUES (1272, 27, 'D', 0.9268195, 'E a quantidade de drogas?', 238532, 240612, 0.9268195, 5, 0);
INSERT INTO speaker_segments (id, transcricao_id, speaker, speaker_confidence, text, start_time, end_time, confidence, words_count, channel) VALUES (1273, 27, 'C', 0.6927886, 'Também não sei, não era eu que vendia.', 241996, 244876, 0.6927886, 8, 0);
INSERT INTO speaker_segments (id, transcricao_id, speaker, speaker_confidence, text, start_time, end_time, confidence, words_count, channel) VALUES (1274, 27, 'D', 0.76619697, 'Valores em dinheiro, o senhor saberia dizer quanto de dinheiro o senhor tinha nessa oportunidade, junto com o Rafael?', 244876, 255336, 0.76619697, 19, 0);
INSERT INTO speaker_segments (id, transcricao_id, speaker, speaker_confidence, text, start_time, end_time, confidence, words_count, channel) VALUES (1275, 27, 'C', 0.773043, 'Não sei.', 255336, 257456, 0.773043, 2, 0);
INSERT INTO speaker_segments (id, transcricao_id, speaker, speaker_confidence, text, start_time, end_time, confidence, words_count, channel) VALUES (1276, 27, 'D', 0.80529785, 'Não se recorda? Não. Durante essa ocorrência, o senhor chegou a notar se algum policial pegou algum dinheiro para ele?', 257456, 266216, 0.80529785, 20, 0);
INSERT INTO speaker_segments (id, transcricao_id, speaker, speaker_confidence, text, start_time, end_time, confidence, words_count, channel) VALUES (1277, 27, 'B', 0.919, 'Ouviu, Douglas?', 272472, 276872, 0.919, 2, 0);
INSERT INTO speaker_segments (id, transcricao_id, speaker, speaker_confidence, text, start_time, end_time, confidence, words_count, channel) VALUES (1278, 27, 'C', 0.849, 'Douglas.', 276872, 279872, 0.849, 1, 0);
INSERT INTO speaker_segments (id, transcricao_id, speaker, speaker_confidence, text, start_time, end_time, confidence, words_count, channel) VALUES (1279, 27, 'D', 0.82240105, 'Está me ouvindo?', 281672, 284852, 0.82240105, 3, 0);
INSERT INTO speaker_segments (id, transcricao_id, speaker, speaker_confidence, text, start_time, end_time, confidence, words_count, channel) VALUES (1280, 27, 'B', 0.73709244, 'De novo deu.', 286132, 290772, 0.73709244, 3, 0);
INSERT INTO speaker_segments (id, transcricao_id, speaker, speaker_confidence, text, start_time, end_time, confidence, words_count, channel) VALUES (1281, 27, 'A', 0.79088366, 'Ele continua aqui na tela, doutor, PK Douglas. Douglas, você está nos ouvindo? Porque ele não caiu, ele está aqui no… Vamos ver, espera aí. Agora caiu, estou colocando ele de novo.', 290772, 317713, 0.79088366, 32, 0);
INSERT INTO speaker_segments (id, transcricao_id, speaker, speaker_confidence, text, start_time, end_time, confidence, words_count, channel) VALUES (1282, 27, 'B', 0.31982422, 'Você.', 317713, 320713, 0.31982422, 1, 0);
INSERT INTO speaker_segments (id, transcricao_id, speaker, speaker_confidence, text, start_time, end_time, confidence, words_count, channel) VALUES (1283, 27, 'A', 0.679965, 'Está saindo da APK que está… Coloca o Diogo de novo. Coloca o Douglas de novo.', 328033, 336490, 0.679965, 16, 0);
INSERT INTO speaker_segments (id, transcricao_id, speaker, speaker_confidence, text, start_time, end_time, confidence, words_count, channel) VALUES (1284, 27, 'C', 0.67762816, 'Tá, só um momento que eu tô configurando aqui.', 336490, 339010, 0.67762816, 9, 0);
INSERT INTO speaker_segments (id, transcricao_id, speaker, speaker_confidence, text, start_time, end_time, confidence, words_count, channel) VALUES (1285, 27, 'B', 0.8497435, 'Tá certo. Pronto.', 339010, 347070, 0.8497435, 3, 0);
INSERT INTO speaker_segments (id, transcricao_id, speaker, speaker_confidence, text, start_time, end_time, confidence, words_count, channel) VALUES (1286, 27, 'A', 0.7671834, 'Doutor, ele tá de volta.', 356650, 359050, 0.7671834, 5, 0);
INSERT INTO speaker_segments (id, transcricao_id, speaker, speaker_confidence, text, start_time, end_time, confidence, words_count, channel) VALUES (1287, 27, 'D', 0.729, 'Douglas!', 359050, 362050, 0.729, 1, 0);
INSERT INTO speaker_segments (id, transcricao_id, speaker, speaker_confidence, text, start_time, end_time, confidence, words_count, channel) VALUES (1288, 27, 'B', 0.834, 'Opa!', 362630, 363610, 0.834, 1, 0);
INSERT INTO speaker_segments (id, transcricao_id, speaker, speaker_confidence, text, start_time, end_time, confidence, words_count, channel) VALUES (1289, 27, 'D', 0.71159005, 'Durante essa ocorrência, o senhor chegou a notar se algum policial tinha pego o dinheiro que estava na posse de vocês? Acho que foi agora. Mas não tem certeza.', 364154, 379014, 0.71159005, 29, 0);
INSERT INTO speaker_segments (id, transcricao_id, speaker, speaker_confidence, text, start_time, end_time, confidence, words_count, channel) VALUES (1290, 27, 'B', 0.62228644, 'É, não tem certeza.', 379014, 382494, 0.62228644, 4, 0);
INSERT INTO speaker_segments (id, transcricao_id, speaker, speaker_confidence, text, start_time, end_time, confidence, words_count, channel) VALUES (1291, 27, 'D', 0.7664448, 'E como eu já tinha lhe perguntado quantidade de droga, quantidade de dinheiro e quantidade de arma, o senhor não se lembra.', 382994, 390634, 0.7664448, 22, 0);
INSERT INTO speaker_segments (id, transcricao_id, speaker, speaker_confidence, text, start_time, end_time, confidence, words_count, channel) VALUES (1292, 27, 'C', 0.69259316, 'Não me lembro porque eles não pegaram nada com nós, os sojuíras. Eles chegaram em outra residência.', 391643, 397823, 0.69259316, 17, 0);
INSERT INTO speaker_segments (id, transcricao_id, speaker, speaker_confidence, text, start_time, end_time, confidence, words_count, channel) VALUES (1293, 27, 'D', 0.7877884, 'E isso não estava com vocês?', 397823, 400243, 0.7877884, 6, 0);
INSERT INTO speaker_segments (id, transcricao_id, speaker, speaker_confidence, text, start_time, end_time, confidence, words_count, channel) VALUES (1294, 27, 'C', 0.78967446, 'Não, não estava com nós. Eles pegaram em outra residência e daí botaram em nós.', 400243, 405563, 0.78967446, 15, 0);
INSERT INTO speaker_segments (id, transcricao_id, speaker, speaker_confidence, text, start_time, end_time, confidence, words_count, channel) VALUES (1295, 27, 'D', 0.78441405, 'E você estava perto dessa residência?', 405563, 408923, 0.78441405, 6, 0);
INSERT INTO speaker_segments (id, transcricao_id, speaker, speaker_confidence, text, start_time, end_time, confidence, words_count, channel) VALUES (1296, 27, 'C', 0.70424235, 'Ah, no caso, eu moro umas duas quartas dessa residência. Tá.', 408923, 413403, 0.70424235, 11, 0);
INSERT INTO speaker_segments (id, transcricao_id, speaker, speaker_confidence, text, start_time, end_time, confidence, words_count, channel) VALUES (1297, 27, 'D', 0.8431563, 'E o senhor está preso por tráfico?', 413403, 415743, 0.8431563, 7, 0);
INSERT INTO speaker_segments (id, transcricao_id, speaker, speaker_confidence, text, start_time, end_time, confidence, words_count, channel) VALUES (1298, 27, 'C', 0.69946146, 'Agora eu estou preso por tráfico? Poxa, eu fiquei quatro dias na rua só. Tá iniciado de novo.', 415743, 424297, 0.69946146, 18, 0);
INSERT INTO speaker_segments (id, transcricao_id, speaker, speaker_confidence, text, start_time, end_time, confidence, words_count, channel) VALUES (1299, 27, 'D', 0.69945425, 'Tá certo. Palavra ao conselho, Capitão Marcelo.', 424297, 428797, 0.69945425, 7, 0);
INSERT INTO speaker_segments (id, transcricao_id, speaker, speaker_confidence, text, start_time, end_time, confidence, words_count, channel) VALUES (1300, 27, 'B', 0.7757904, 'Sem perguntas, Excelência.', 428797, 433337, 0.7757904, 3, 0);
INSERT INTO speaker_segments (id, transcricao_id, speaker, speaker_confidence, text, start_time, end_time, confidence, words_count, channel) VALUES (1301, 27, 'D', 0.69968057, 'Ao Capitão Koniki.', 433337, 435937, 0.69968057, 3, 0);
INSERT INTO speaker_segments (id, transcricao_id, speaker, speaker_confidence, text, start_time, end_time, confidence, words_count, channel) VALUES (1302, 27, 'C', 0.78916794, 'Sem perguntas.', 435937, 436777, 0.78916794, 2, 0);
INSERT INTO speaker_segments (id, transcricao_id, speaker, speaker_confidence, text, start_time, end_time, confidence, words_count, channel) VALUES (1303, 27, 'D', 0.8342305, 'Ministério Público.', 436777, 441077, 0.8342305, 2, 0);
INSERT INTO speaker_segments (id, transcricao_id, speaker, speaker_confidence, text, start_time, end_time, confidence, words_count, channel) VALUES (1304, 27, 'E', 0.78305614, 'Boa tarde. Exatamente o que aconteceu nesse dia, Douglas? O senhor conheceu os policiais militares?', 441077, 449757, 0.78305614, 15, 0);
INSERT INTO speaker_segments (id, transcricao_id, speaker, speaker_confidence, text, start_time, end_time, confidence, words_count, channel) VALUES (1305, 27, 'C', 0.7280621, 'No caso, eu estava sem medir o meio para levar meus primos para o colégio e tomei uma abordagem da polícia. Nisso eu tomei uma abordagem. Eles tinham abordado outro guri que morava em frente da minha casa e estava saindo para trabalhar. Eles queriam saber de droga, de arma. A gente, sabe, falava... Falava que a gente não sabia de nada e eles começaram a bater na gente e me enxertaram mais com as drogas. Falaram que se a gente não falasse nada, eles enxertariam mais e levariam mais primos.', 452596, 481096, 0.7280621, 91, 0);
INSERT INTO speaker_segments (id, transcricao_id, speaker, speaker_confidence, text, start_time, end_time, confidence, words_count, channel) VALUES (1306, 27, 'E', 0.7521145, 'Você já conhecia os policiais?', 482785, 485525, 0.7521145, 5, 0);
INSERT INTO speaker_segments (id, transcricao_id, speaker, speaker_confidence, text, start_time, end_time, confidence, words_count, channel) VALUES (1307, 27, 'C', 0.66991013, 'Não, não conhecia.', 485525, 488065, 0.66991013, 3, 0);
INSERT INTO speaker_segments (id, transcricao_id, speaker, speaker_confidence, text, start_time, end_time, confidence, words_count, channel) VALUES (1308, 27, 'E', 0.8003854, 'Nem de vista?', 488065, 490045, 0.8003854, 3, 0);
INSERT INTO speaker_segments (id, transcricao_id, speaker, speaker_confidence, text, start_time, end_time, confidence, words_count, channel) VALUES (1309, 27, 'C', 0.69729936, 'Não, nunca tinha visto.', 490045, 492665, 0.69729936, 4, 0);
INSERT INTO speaker_segments (id, transcricao_id, speaker, speaker_confidence, text, start_time, end_time, confidence, words_count, channel) VALUES (1310, 27, 'E', 0.72353125, 'Eles te exigiram algum dinheiro, algo? Para não fazer isso?', 492665, 498105, 0.72353125, 10, 0);
INSERT INTO speaker_segments (id, transcricao_id, speaker, speaker_confidence, text, start_time, end_time, confidence, words_count, channel) VALUES (1311, 27, 'C', 0.8508152, 'Não, não pediram nada.', 498105, 501085, 0.8508152, 4, 0);
INSERT INTO speaker_segments (id, transcricao_id, speaker, speaker_confidence, text, start_time, end_time, confidence, words_count, channel) VALUES (1312, 27, 'E', 0.79725605, 'Você estava acompanhado de quem nesse momento?', 501085, 504685, 0.79725605, 7, 0);
INSERT INTO speaker_segments (id, transcricao_id, speaker, speaker_confidence, text, start_time, end_time, confidence, words_count, channel) VALUES (1313, 27, 'C', 0.88972265, 'Acompanhada da minha irmã.', 504685, 506465, 0.88972265, 4, 0);
INSERT INTO speaker_segments (id, transcricao_id, speaker, speaker_confidence, text, start_time, end_time, confidence, words_count, channel) VALUES (1314, 27, 'E', 0.8079838, 'Como é que é o nome dela?', 506465, 508225, 0.8079838, 7, 0);
INSERT INTO speaker_segments (id, transcricao_id, speaker, speaker_confidence, text, start_time, end_time, confidence, words_count, channel) VALUES (1315, 27, 'C', 0.904, 'Cristiane.', 508225, 510085, 0.904, 1, 0);
INSERT INTO speaker_segments (id, transcricao_id, speaker, speaker_confidence, text, start_time, end_time, confidence, words_count, channel) VALUES (1316, 27, 'E', 0.8019225, 'Só ela estava contigo? Mais ninguém?', 510085, 512525, 0.8019225, 6, 0);
INSERT INTO speaker_segments (id, transcricao_id, speaker, speaker_confidence, text, start_time, end_time, confidence, words_count, channel) VALUES (1317, 27, 'C', 0.72663534, 'Estava só eu e as minhas crianças em casa.', 513160, 515340, 0.72663534, 9, 0);
INSERT INTO speaker_segments (id, transcricao_id, speaker, speaker_confidence, text, start_time, end_time, confidence, words_count, channel) VALUES (1318, 27, 'E', 0.72180855, 'E por que eles fizeram isso contigo? Tu afirma que não conhecia eles, que.', 515340, 524360, 0.72180855, 14, 0);
INSERT INTO speaker_segments (id, transcricao_id, speaker, speaker_confidence, text, start_time, end_time, confidence, words_count, channel) VALUES (1319, 27, 'C', 0.7487738, 'Não foi exigido... Nada, eu já não sei. Não tenho o que dizer.', 524360, 533140, 0.7487738, 13, 0);
INSERT INTO speaker_segments (id, transcricao_id, speaker, speaker_confidence, text, start_time, end_time, confidence, words_count, channel) VALUES (1320, 27, 'E', 0.8020814, 'Tu está preso por esse fato?', 533140, 536780, 0.8020814, 6, 0);
INSERT INTO speaker_segments (id, transcricao_id, speaker, speaker_confidence, text, start_time, end_time, confidence, words_count, channel) VALUES (1321, 27, 'C', 0.7264756, 'Não, no caso desse fato, eu fui embora e voltei de novo para uma outra pronta.', 536780, 542060, 0.7264756, 16, 0);
INSERT INTO speaker_segments (id, transcricao_id, speaker, speaker_confidence, text, start_time, end_time, confidence, words_count, channel) VALUES (1322, 27, 'E', 0.7795394, 'Além de droga, arma, teve alguma questão envolvendo arma em relação a esse fato que o juiz questionou para ti?', 543738, 554478, 0.7795394, 20, 0);
INSERT INTO speaker_segments (id, transcricao_id, speaker, speaker_confidence, text, start_time, end_time, confidence, words_count, channel) VALUES (1323, 27, 'C', 0.8512734, 'Não entendi.', 554478, 555998, 0.8512734, 2, 0);
INSERT INTO speaker_segments (id, transcricao_id, speaker, speaker_confidence, text, start_time, end_time, confidence, words_count, channel) VALUES (1324, 27, 'E', 0.6748876, 'Em relação a arma, tem alguma coisa de enxertar um arma também ou não?', 555998, 561438, 0.6748876, 14, 0);
INSERT INTO speaker_segments (id, transcricao_id, speaker, speaker_confidence, text, start_time, end_time, confidence, words_count, channel) VALUES (1325, 27, 'C', 0.5796897, 'Podemos enxertar também um revólver.', 561438, 564758, 0.5796897, 5, 0);
INSERT INTO speaker_segments (id, transcricao_id, speaker, speaker_confidence, text, start_time, end_time, confidence, words_count, channel) VALUES (1326, 27, 'E', 0.8969453, 'Qual revólver?', 564758, 566798, 0.8969453, 2, 0);
INSERT INTO speaker_segments (id, transcricao_id, speaker, speaker_confidence, text, start_time, end_time, confidence, words_count, channel) VALUES (1327, 27, 'C', 0.66213214, 'Calibre 38.', 566798, 569718, 0.66213214, 2, 0);
INSERT INTO speaker_segments (id, transcricao_id, speaker, speaker_confidence, text, start_time, end_time, confidence, words_count, channel) VALUES (1328, 27, 'E', 0.8207299, 'E como é que foi esse enxerto?', 569718, 572178, 0.8207299, 7, 0);
INSERT INTO speaker_segments (id, transcricao_id, speaker, speaker_confidence, text, start_time, end_time, confidence, words_count, channel) VALUES (1329, 27, 'C', 0.66026735, 'Na hora da abordagem.', 573505, 575965, 0.66026735, 4, 0);
INSERT INTO speaker_segments (id, transcricao_id, speaker, speaker_confidence, text, start_time, end_time, confidence, words_count, channel) VALUES (1330, 27, 'E', 0.76930076, 'O que eles falaram?', 575965, 579205, 0.76930076, 4, 0);
INSERT INTO speaker_segments (id, transcricao_id, speaker, speaker_confidence, text, start_time, end_time, confidence, words_count, channel) VALUES (1331, 27, 'C', 0.74619275, 'Eles falaram que se a gente não falasse nada, eles iam chutar nós. Iam botar droga, arma e iam botar nós na cadeira.', 579205, 588105, 0.74619275, 23, 0);
INSERT INTO speaker_segments (id, transcricao_id, speaker, speaker_confidence, text, start_time, end_time, confidence, words_count, channel) VALUES (1332, 27, 'E', 0.6953336, 'Tu tem vínculo com alguma facção?', 589245, 592865, 0.6953336, 6, 0);
INSERT INTO speaker_segments (id, transcricao_id, speaker, speaker_confidence, text, start_time, end_time, confidence, words_count, channel) VALUES (1333, 27, 'C', 0.873, 'Não, não.', 592865, 594665, 0.873, 2, 0);
INSERT INTO speaker_segments (id, transcricao_id, speaker, speaker_confidence, text, start_time, end_time, confidence, words_count, channel) VALUES (1334, 27, 'E', 0.77933985, 'Nada mais.', 594665, 597225, 0.77933985, 2, 0);
INSERT INTO speaker_segments (id, transcricao_id, speaker, speaker_confidence, text, start_time, end_time, confidence, words_count, channel) VALUES (1335, 27, 'D', 0.73941714, 'Doutora Edna, pelo soldado Josimar.', 597225, 601205, 0.73941714, 5, 0);
INSERT INTO speaker_segments (id, transcricao_id, speaker, speaker_confidence, text, start_time, end_time, confidence, words_count, channel) VALUES (1336, 27, 'B', 0.57749087, 'Nada, em silêncio.', 604302, 606462, 0.57749087, 3, 0);
INSERT INTO speaker_segments (id, transcricao_id, speaker, speaker_confidence, text, start_time, end_time, confidence, words_count, channel) VALUES (1337, 27, 'D', 0.7052441, 'A doutora Ciomara pelo soldado Felipe.', 606462, 609702, 0.7052441, 6, 0);
INSERT INTO speaker_segments (id, transcricao_id, speaker, speaker_confidence, text, start_time, end_time, confidence, words_count, channel) VALUES (1338, 27, 'B', 0.86127216, 'Nada, em silêncio.', 609702, 612302, 0.86127216, 3, 0);
INSERT INTO speaker_segments (id, transcricao_id, speaker, speaker_confidence, text, start_time, end_time, confidence, words_count, channel) VALUES (1339, 27, 'D', 0.8705577, 'Pelo soldado Mateus, doutor Márcio Barcelos.', 612302, 616602, 0.8705577, 6, 0);
INSERT INTO speaker_segments (id, transcricao_id, speaker, speaker_confidence, text, start_time, end_time, confidence, words_count, channel) VALUES (1340, 27, 'F', 0.74845076, 'Sim, doutor. Só para confirmar com ele, se o Mateus Alicênio, ele lembra do Mateus nessa data, presente no fato da abordagem?', 616602, 626802, 0.74845076, 22, 0);
INSERT INTO speaker_segments (id, transcricao_id, speaker, speaker_confidence, text, start_time, end_time, confidence, words_count, channel) VALUES (1341, 27, 'B', 0.7406413, 'Eu não entendi.', 626802, 629762, 0.7406413, 3, 0);
INSERT INTO speaker_segments (id, transcricao_id, speaker, speaker_confidence, text, start_time, end_time, confidence, words_count, channel) VALUES (1342, 27, 'F', 0.7200159, 'Se ele lembra os policiais que abordaram ele, especialmente no meu caso, o Mateus Arsene.', 631505, 636805, 0.7200159, 15, 0);
INSERT INTO speaker_segments (id, transcricao_id, speaker, speaker_confidence, text, start_time, end_time, confidence, words_count, channel) VALUES (1343, 27, 'D', 0.80663544, 'O senhor lembra quem foram os policiais que lhe abordaram?', 636805, 641285, 0.80663544, 10, 0);
INSERT INTO speaker_segments (id, transcricao_id, speaker, speaker_confidence, text, start_time, end_time, confidence, words_count, channel) VALUES (1344, 27, 'C', 0.78309196, 'Ah, se eu olhar pelo rosto até lembro, mas pelo nome eu não lembro.', 641285, 648185, 0.78309196, 14, 0);
INSERT INTO speaker_segments (id, transcricao_id, speaker, speaker_confidence, text, start_time, end_time, confidence, words_count, channel) VALUES (1345, 27, 'F', 0.81894606, 'Chegaram a te convidar para fazer a cariação no inquérito?', 650065, 654765, 0.81894606, 10, 0);
INSERT INTO speaker_segments (id, transcricao_id, speaker, speaker_confidence, text, start_time, end_time, confidence, words_count, channel) VALUES (1346, 27, 'C', 0.77893084, 'Vocês chegaram a me bater?', 654765, 657045, 0.77893084, 5, 0);
INSERT INTO speaker_segments (id, transcricao_id, speaker, speaker_confidence, text, start_time, end_time, confidence, words_count, channel) VALUES (1347, 27, 'F', 0.774598, 'Não, fazer a cariação para te reconhecer os policiais.', 657045, 659525, 0.774598, 9, 0);
INSERT INTO speaker_segments (id, transcricao_id, speaker, speaker_confidence, text, start_time, end_time, confidence, words_count, channel) VALUES (1348, 27, 'C', 0.6902643, 'Não, não fizeram. Isso eu vi só em uma audiência na rua. Em uma audiência na rua eu vi isso.', 660293, 668073, 0.6902643, 20, 0);
INSERT INTO speaker_segments (id, transcricao_id, speaker, speaker_confidence, text, start_time, end_time, confidence, words_count, channel) VALUES (1349, 27, 'B', 0.85796076, 'Chegou a ser agredido? Quase me mataram.', 668073, 677353, 0.85796076, 7, 0);
INSERT INTO speaker_segments (id, transcricao_id, speaker, speaker_confidence, text, start_time, end_time, confidence, words_count, channel) VALUES (1350, 27, 'F', 0.6855556, 'Tu reagiu ou só um apanhado de graça?', 677933, 682593, 0.6855556, 8, 0);
INSERT INTO speaker_segments (id, transcricao_id, speaker, speaker_confidence, text, start_time, end_time, confidence, words_count, channel) VALUES (1351, 27, 'C', 0.64039135, 'Eu reagi contra quatro, não tem condições. Os caras quase me mataram.', 682593, 686813, 0.64039135, 12, 0);
INSERT INTO speaker_segments (id, transcricao_id, speaker, speaker_confidence, text, start_time, end_time, confidence, words_count, channel) VALUES (1352, 27, 'F', 0.7464871, 'Tu não viu os nomes deles nas fardas no dia?', 690078, 694558, 0.7464871, 10, 0);
INSERT INTO speaker_segments (id, transcricao_id, speaker, speaker_confidence, text, start_time, end_time, confidence, words_count, channel) VALUES (1353, 27, 'C', 0.7254081, 'Não via, não via porque eles me afogavam, eles estavam me afogando com água e botando pano na minha cara.', 694558, 700578, 0.7254081, 20, 0);
INSERT INTO speaker_segments (id, transcricao_id, speaker, speaker_confidence, text, start_time, end_time, confidence, words_count, channel) VALUES (1354, 27, 'F', 0.6679251, 'Afogaram onde?', 700578, 701518, 0.6679251, 2, 0);
INSERT INTO speaker_segments (id, transcricao_id, speaker, speaker_confidence, text, start_time, end_time, confidence, words_count, channel) VALUES (1355, 27, 'B', 0.5681553, 'Na camisa.', 701518, 703818, 0.5681553, 2, 0);
INSERT INTO speaker_segments (id, transcricao_id, speaker, speaker_confidence, text, start_time, end_time, confidence, words_count, channel) VALUES (1356, 27, 'F', 0.8741045, 'Aonde isso?', 703818, 706038, 0.8741045, 2, 0);
INSERT INTO speaker_segments (id, transcricao_id, speaker, speaker_confidence, text, start_time, end_time, confidence, words_count, channel) VALUES (1357, 27, 'C', 0.8736531, 'Na casa da minha irmã.', 706038, 707858, 0.8736531, 5, 0);
INSERT INTO speaker_segments (id, transcricao_id, speaker, speaker_confidence, text, start_time, end_time, confidence, words_count, channel) VALUES (1358, 27, 'F', 0.6733156, 'Foi dentro, eles entraram na tua casa?', 707858, 709798, 0.6733156, 7, 0);
INSERT INTO speaker_segments (id, transcricao_id, speaker, speaker_confidence, text, start_time, end_time, confidence, words_count, channel) VALUES (1359, 27, 'C', 0.8884495, 'Dentro da casa, na frente das crianças.', 709798, 712658, 0.8884495, 7, 0);
INSERT INTO speaker_segments (id, transcricao_id, speaker, speaker_confidence, text, start_time, end_time, confidence, words_count, channel) VALUES (1360, 27, 'F', 0.82803386, 'Alguém viu, alguém filmou? O senhor registrou isso?', 712658, 717018, 0.82803386, 8, 0);
INSERT INTO speaker_segments (id, transcricao_id, speaker, speaker_confidence, text, start_time, end_time, confidence, words_count, channel) VALUES (1361, 27, 'C', 0.7774581, 'Eu não sei se a minha irmã já vai registrar, mas ela viu. Isso foi de manhã cedo, umas oito e meia da manhã.', 718107, 727947, 0.7774581, 24, 0);
INSERT INTO speaker_segments (id, transcricao_id, speaker, speaker_confidence, text, start_time, end_time, confidence, words_count, channel) VALUES (1362, 27, 'B', 0.8415, 'Satisfeito, doutor.', 727947, 730907, 0.8415, 2, 0);
INSERT INTO speaker_segments (id, transcricao_id, speaker, speaker_confidence, text, start_time, end_time, confidence, words_count, channel) VALUES (1363, 27, 'C', 0.9115, 'Certo, doutor.', 730907, 734187, 0.9115, 2, 0);
INSERT INTO speaker_segments (id, transcricao_id, speaker, speaker_confidence, text, start_time, end_time, confidence, words_count, channel) VALUES (1364, 27, 'D', 0.7872133, 'Doutor Márcio Rossano.', 734187, 738087, 0.7872133, 3, 0);
INSERT INTO speaker_segments (id, transcricao_id, speaker, speaker_confidence, text, start_time, end_time, confidence, words_count, channel) VALUES (1365, 27, 'F', 0.92025554, 'Sem perguntas, doutor Francisco.', 738087, 741507, 0.92025554, 4, 0);
INSERT INTO speaker_segments (id, transcricao_id, speaker, speaker_confidence, text, start_time, end_time, confidence, words_count, channel) VALUES (1366, 27, 'D', 0.8994798, 'Doutor Alfredo.', 741507, 743167, 0.8994798, 2, 0);
INSERT INTO speaker_segments (id, transcricao_id, speaker, speaker_confidence, text, start_time, end_time, confidence, words_count, channel) VALUES (1367, 27, 'C', 0.5951634, 'Sem perguntas, doutor.', 747487, 749347, 0.5951634, 3, 0);
INSERT INTO speaker_segments (id, transcricao_id, speaker, speaker_confidence, text, start_time, end_time, confidence, words_count, channel) VALUES (1368, 27, 'D', 0.66517645, 'A doutora Paloma?', 749347, 751767, 0.66517645, 3, 0);
INSERT INTO speaker_segments (id, transcricao_id, speaker, speaker_confidence, text, start_time, end_time, confidence, words_count, channel) VALUES (1369, 27, 'B', 0.8847656, 'Sem perguntas.', 751767, 754287, 0.8847656, 2, 0);
INSERT INTO speaker_segments (id, transcricao_id, speaker, speaker_confidence, text, start_time, end_time, confidence, words_count, channel) VALUES (1370, 27, 'D', 0.82061243, 'Não ficou nenhum advogado de fora?', 754287, 757167, 0.82061243, 6, 0);
INSERT INTO speaker_segments (id, transcricao_id, speaker, speaker_confidence, text, start_time, end_time, confidence, words_count, channel) VALUES (1371, 27, 'B', 0.439, 'Ok.', 757167, 759807, 0.439, 1, 0);
INSERT INTO speaker_segments (id, transcricao_id, speaker, speaker_confidence, text, start_time, end_time, confidence, words_count, channel) VALUES (1372, 27, 'D', 0.8296425, 'Está liberado, então, a testemunha. O Douglas pode deixar a sala. Obrigado pela colaboração da Suzette.', 759807, 768327, 0.8296425, 16, 0);
INSERT INTO speaker_segments (id, transcricao_id, speaker, speaker_confidence, text, start_time, end_time, confidence, words_count, channel) VALUES (1373, 27, 'C', 0.80823046, 'Muito obrigado.', 768327, 771647, 0.80823046, 2, 0);
INSERT INTO speaker_segments (id, transcricao_id, speaker, speaker_confidence, text, start_time, end_time, confidence, words_count, channel) VALUES (1374, 29, 'A', 0.75352925, 'Douglas, tu me diz o teu nome completo.', 42, 4322, 0.75352925, 8, 0);
INSERT INTO speaker_segments (id, transcricao_id, speaker, speaker_confidence, text, start_time, end_time, confidence, words_count, channel) VALUES (1375, 29, 'B', 0.726, 'Nome?', 4322, 7322, 0.726, 1, 0);
INSERT INTO speaker_segments (id, transcricao_id, speaker, speaker_confidence, text, start_time, end_time, confidence, words_count, channel) VALUES (1376, 29, 'A', 0.7632965, 'Tu me diz o teu nome completo, por favor.', 8442, 11442, 0.7632965, 9, 0);
INSERT INTO speaker_segments (id, transcricao_id, speaker, speaker_confidence, text, start_time, end_time, confidence, words_count, channel) VALUES (1377, 29, 'C', 0.886487, 'Douglas Oliveira Mafalda.', 11442, 13982, 0.886487, 3, 0);
INSERT INTO speaker_segments (id, transcricao_id, speaker, speaker_confidence, text, start_time, end_time, confidence, words_count, channel) VALUES (1378, 29, 'A', 0.81675136, 'Tu me diz a tua filiação, o nome dos teus pais.', 13982, 19502, 0.81675136, 11, 0);
INSERT INTO speaker_segments (id, transcricao_id, speaker, speaker_confidence, text, start_time, end_time, confidence, words_count, channel) VALUES (1379, 29, 'C', 0.7998016, 'José Leomar de Oliveira Mafalda e Eliane Silva de Oliveira.', 19502, 23962, 0.7998016, 10, 0);
INSERT INTO speaker_segments (id, transcricao_id, speaker, speaker_confidence, text, start_time, end_time, confidence, words_count, channel) VALUES (1380, 29, 'A', 0.78990275, 'E qual é o princípio que tu está aí?', 23962, 26982, 0.78990275, 9, 0);
INSERT INTO speaker_segments (id, transcricao_id, speaker, speaker_confidence, text, start_time, end_time, confidence, words_count, channel) VALUES (1381, 29, 'C', 0.43456835, 'Não entendi.', 29945, 31005, 0.43456835, 2, 0);
INSERT INTO speaker_segments (id, transcricao_id, speaker, speaker_confidence, text, start_time, end_time, confidence, words_count, channel) VALUES (1382, 29, 'A', 0.698109, 'Tu tá preso em qual presídio?', 31005, 34025, 0.698109, 6, 0);
INSERT INTO speaker_segments (id, transcricao_id, speaker, speaker_confidence, text, start_time, end_time, confidence, words_count, channel) VALUES (1383, 29, 'C', 0.70301366, 'Tô na APK.', 34025, 35345, 0.70301366, 3, 0);
INSERT INTO speaker_segments (id, transcricao_id, speaker, speaker_confidence, text, start_time, end_time, confidence, words_count, channel) VALUES (1384, 29, 'A', 0.67789453, 'Na APK.', 35345, 37085, 0.67789453, 2, 0);
INSERT INTO speaker_segments (id, transcricao_id, speaker, speaker_confidence, text, start_time, end_time, confidence, words_count, channel) VALUES (1385, 29, 'B', 0.89524025, 'Tá certo.', 37085, 39445, 0.89524025, 2, 0);
INSERT INTO speaker_segments (id, transcricao_id, speaker, speaker_confidence, text, start_time, end_time, confidence, words_count, channel) VALUES (1386, 29, 'D', 0.479, 'Ok.', 39445, 40885, 0.479, 1, 0);
INSERT INTO speaker_segments (id, transcricao_id, speaker, speaker_confidence, text, start_time, end_time, confidence, words_count, channel) VALUES (1387, 29, 'A', 0.8647018, 'Aqui sim, doutor.', 40885, 43645, 0.8647018, 3, 0);
INSERT INTO speaker_segments (id, transcricao_id, speaker, speaker_confidence, text, start_time, end_time, confidence, words_count, channel) VALUES (1388, 29, 'D', 0.71908075, 'Boa tarde, Douglas.', 43645, 45565, 0.71908075, 3, 0);
INSERT INTO speaker_segments (id, transcricao_id, speaker, speaker_confidence, text, start_time, end_time, confidence, words_count, channel) VALUES (1389, 29, 'C', 0.71542776, 'Boa tarde.', 45565, 46285, 0.71542776, 2, 0);
INSERT INTO speaker_segments (id, transcricao_id, speaker, speaker_confidence, text, start_time, end_time, confidence, words_count, channel) VALUES (1390, 29, 'D', 0.79165494, 'Douglas, o senhor vai ser ouvido sobre o fato número 5º da denúncia, ok? Eu vou fazer a leitura do fato para ver se o senhor se recorda, porque já faz algum tempo. No dia 22 de outubro de 2019, por volta das 22h30, na Rua Lago Azul, número 248, no bairro Santa Bárbara, cidade de Alvorada, os soldados Josimar da Silva Pereira, Felipe Ferreira Janiquim e Mateus Arcenes de Voraes, em comunhão de resposta e condição de vontade, todos de serviço pilotado no vigésimo quarto PTM, apropriaram-se de valores que tinham força e razão da função apreendido durante a ocorrência policial registrada sob o número 100-464-2019-14700, relativa aos crimes de tráfego de entorpecentes e porte legal de arma. Na oportunidade, os denunciados prenderam Douglas de Oliveira Mafalda e Rafael de Cidade Barbosa por tráfico de estropecentes e porte ilegal de arma, aprendendo, dentre outros materiais, dois coletes balísticos, uma pistola calibre .380, um revólver calibre .38, um revólver calibre .32 e uma espigada calibre .12. também 2.289 gramas de cocaína, 79 gramas de maconha e, ao menos, um grama de crack. E R$331 em dinheiro.', 47967, 142062, 0.79165494, 186, 0);
INSERT INTO speaker_segments (id, transcricao_id, speaker, speaker_confidence, text, start_time, end_time, confidence, words_count, channel) VALUES (1391, 29, 'A', 0.614, 'Pergunta.', 142062, 145062, 0.614, 1, 0);
INSERT INTO speaker_segments (id, transcricao_id, speaker, speaker_confidence, text, start_time, end_time, confidence, words_count, channel) VALUES (1392, 29, 'D', 0.806027, 'Douglas, sobre essa ocorrência, o que o senhor tem a nos dizer?', 149702, 154242, 0.806027, 12, 0);
INSERT INTO speaker_segments (id, transcricao_id, speaker, speaker_confidence, text, start_time, end_time, confidence, words_count, channel) VALUES (1393, 29, 'A', 0.377903, 'E aí e o problema do tornozelo né é alguma coisa aconteceu e tá.', 157115, 168995, 0.377903, 14, 0);
INSERT INTO speaker_segments (id, transcricao_id, speaker, speaker_confidence, text, start_time, end_time, confidence, words_count, channel) VALUES (1394, 29, 'B', 0.4907401, 'Voltou a normal E aí E aí.', 168995, 177445, 0.4907401, 7, 0);
INSERT INTO speaker_segments (id, transcricao_id, speaker, speaker_confidence, text, start_time, end_time, confidence, words_count, channel) VALUES (1395, 29, 'D', 0.5180132, 'O Bernadete põe ele na tela principal.', 177445, 179135, 0.5180132, 7, 0);
INSERT INTO speaker_segments (id, transcricao_id, speaker, speaker_confidence, text, start_time, end_time, confidence, words_count, channel) VALUES (1396, 29, 'A', 0.519529, 'E ele tá na tela doutor tá.', 179135, 184475, 0.519529, 7, 0);
INSERT INTO speaker_segments (id, transcricao_id, speaker, speaker_confidence, text, start_time, end_time, confidence, words_count, channel) VALUES (1397, 29, 'C', 0.62781566, 'Mas dá na principal, que eu não estou vendo.', 184475, 190122, 0.62781566, 9, 0);
INSERT INTO speaker_segments (id, transcricao_id, speaker, speaker_confidence, text, start_time, end_time, confidence, words_count, channel) VALUES (1398, 29, 'A', 0.62438333, 'Aqui a gente está.', 193302, 196082, 0.62438333, 4, 0);
INSERT INTO speaker_segments (id, transcricao_id, speaker, speaker_confidence, text, start_time, end_time, confidence, words_count, channel) VALUES (1399, 29, 'D', 0.8230529, 'Douglas, ouviu sobre essa ocorrência?', 196082, 201222, 0.8230529, 5, 0);
INSERT INTO speaker_segments (id, transcricao_id, speaker, speaker_confidence, text, start_time, end_time, confidence, words_count, channel) VALUES (1400, 29, 'C', 0.7735, 'Escutei, escutei.', 201222, 203082, 0.7735, 2, 0);
INSERT INTO speaker_segments (id, transcricao_id, speaker, speaker_confidence, text, start_time, end_time, confidence, words_count, channel) VALUES (1401, 29, 'D', 0.81704307, '22 de outubro de 2019, o senhor foi preso, junto com o Rafael, por porte ilegal de drogas e arma. Sobre esse fato, o que o senhor pode nos dizer sobre isso?', 203082, 218612, 0.81704307, 32, 0);
INSERT INTO speaker_segments (id, transcricao_id, speaker, speaker_confidence, text, start_time, end_time, confidence, words_count, channel) VALUES (1402, 29, 'C', 0.68094903, 'Não tenho nada a dizer sobre isso.', 218612, 222132, 0.68094903, 7, 0);
INSERT INTO speaker_segments (id, transcricao_id, speaker, speaker_confidence, text, start_time, end_time, confidence, words_count, channel) VALUES (1403, 29, 'D', 0.79700947, 'O senhor estava na posse de entorpecente e armas?', 222132, 226592, 0.79700947, 9, 0);
INSERT INTO speaker_segments (id, transcricao_id, speaker, speaker_confidence, text, start_time, end_time, confidence, words_count, channel) VALUES (1404, 29, 'C', 0.7912666, 'Estava na posse, estava.', 226592, 229692, 0.7912666, 4, 0);
INSERT INTO speaker_segments (id, transcricao_id, speaker, speaker_confidence, text, start_time, end_time, confidence, words_count, channel) VALUES (1405, 29, 'D', 0.7679148, 'E o senhor se recorda de quantas armas o senhor tinha?', 229692, 236392, 0.7679148, 11, 0);
INSERT INTO speaker_segments (id, transcricao_id, speaker, speaker_confidence, text, start_time, end_time, confidence, words_count, channel) VALUES (1406, 29, 'C', 0.70098877, 'Claro, não me lembro.', 236392, 238532, 0.70098877, 4, 0);
INSERT INTO speaker_segments (id, transcricao_id, speaker, speaker_confidence, text, start_time, end_time, confidence, words_count, channel) VALUES (1407, 29, 'D', 0.9268195, 'E a quantidade de drogas?', 238532, 240612, 0.9268195, 5, 0);
INSERT INTO speaker_segments (id, transcricao_id, speaker, speaker_confidence, text, start_time, end_time, confidence, words_count, channel) VALUES (1408, 29, 'C', 0.6927886, 'Também não sei, não era eu que vendia.', 241996, 244876, 0.6927886, 8, 0);
INSERT INTO speaker_segments (id, transcricao_id, speaker, speaker_confidence, text, start_time, end_time, confidence, words_count, channel) VALUES (1409, 29, 'D', 0.76619697, 'Valores em dinheiro, o senhor saberia dizer quanto de dinheiro o senhor tinha nessa oportunidade, junto com o Rafael?', 244876, 255336, 0.76619697, 19, 0);
INSERT INTO speaker_segments (id, transcricao_id, speaker, speaker_confidence, text, start_time, end_time, confidence, words_count, channel) VALUES (1410, 29, 'C', 0.773043, 'Não sei.', 255336, 257456, 0.773043, 2, 0);
INSERT INTO speaker_segments (id, transcricao_id, speaker, speaker_confidence, text, start_time, end_time, confidence, words_count, channel) VALUES (1411, 29, 'D', 0.80529785, 'Não se recorda? Não. Durante essa ocorrência, o senhor chegou a notar se algum policial pegou algum dinheiro para ele?', 257456, 266216, 0.80529785, 20, 0);
INSERT INTO speaker_segments (id, transcricao_id, speaker, speaker_confidence, text, start_time, end_time, confidence, words_count, channel) VALUES (1412, 29, 'B', 0.919, 'Ouviu, Douglas?', 272472, 276872, 0.919, 2, 0);
INSERT INTO speaker_segments (id, transcricao_id, speaker, speaker_confidence, text, start_time, end_time, confidence, words_count, channel) VALUES (1413, 29, 'C', 0.849, 'Douglas.', 276872, 279872, 0.849, 1, 0);
INSERT INTO speaker_segments (id, transcricao_id, speaker, speaker_confidence, text, start_time, end_time, confidence, words_count, channel) VALUES (1414, 29, 'D', 0.82240105, 'Está me ouvindo?', 281672, 284852, 0.82240105, 3, 0);
INSERT INTO speaker_segments (id, transcricao_id, speaker, speaker_confidence, text, start_time, end_time, confidence, words_count, channel) VALUES (1415, 29, 'B', 0.73709244, 'De novo deu.', 286132, 290772, 0.73709244, 3, 0);
INSERT INTO speaker_segments (id, transcricao_id, speaker, speaker_confidence, text, start_time, end_time, confidence, words_count, channel) VALUES (1416, 29, 'A', 0.79088366, 'Ele continua aqui na tela, doutor, PK Douglas. Douglas, você está nos ouvindo? Porque ele não caiu, ele está aqui no… Vamos ver, espera aí. Agora caiu, estou colocando ele de novo.', 290772, 317713, 0.79088366, 32, 0);
INSERT INTO speaker_segments (id, transcricao_id, speaker, speaker_confidence, text, start_time, end_time, confidence, words_count, channel) VALUES (1417, 29, 'B', 0.31982422, 'Você.', 317713, 320713, 0.31982422, 1, 0);
INSERT INTO speaker_segments (id, transcricao_id, speaker, speaker_confidence, text, start_time, end_time, confidence, words_count, channel) VALUES (1418, 29, 'A', 0.679965, 'Está saindo da APK que está… Coloca o Diogo de novo. Coloca o Douglas de novo.', 328033, 336490, 0.679965, 16, 0);
INSERT INTO speaker_segments (id, transcricao_id, speaker, speaker_confidence, text, start_time, end_time, confidence, words_count, channel) VALUES (1419, 29, 'C', 0.67762816, 'Tá, só um momento que eu tô configurando aqui.', 336490, 339010, 0.67762816, 9, 0);
INSERT INTO speaker_segments (id, transcricao_id, speaker, speaker_confidence, text, start_time, end_time, confidence, words_count, channel) VALUES (1421, 29, 'A', 0.7671834, 'Doutor, ele tá de volta.', 356650, 359050, 0.7671834, 5, 0);
INSERT INTO speaker_segments (id, transcricao_id, speaker, speaker_confidence, text, start_time, end_time, confidence, words_count, channel) VALUES (1422, 29, 'D', 0.729, 'Douglas!', 359050, 362050, 0.729, 1, 0);
INSERT INTO speaker_segments (id, transcricao_id, speaker, speaker_confidence, text, start_time, end_time, confidence, words_count, channel) VALUES (1423, 29, 'B', 0.834, 'Opa!', 362630, 363610, 0.834, 1, 0);
INSERT INTO speaker_segments (id, transcricao_id, speaker, speaker_confidence, text, start_time, end_time, confidence, words_count, channel) VALUES (1424, 29, 'D', 0.71159005, 'Durante essa ocorrência, o senhor chegou a notar se algum policial tinha pego o dinheiro que estava na posse de vocês? Acho que foi agora. Mas não tem certeza.', 364154, 379014, 0.71159005, 29, 0);
INSERT INTO speaker_segments (id, transcricao_id, speaker, speaker_confidence, text, start_time, end_time, confidence, words_count, channel) VALUES (1425, 29, 'B', 0.62228644, 'É, não tem certeza.', 379014, 382494, 0.62228644, 4, 0);
INSERT INTO speaker_segments (id, transcricao_id, speaker, speaker_confidence, text, start_time, end_time, confidence, words_count, channel) VALUES (1426, 29, 'D', 0.7664448, 'E como eu já tinha lhe perguntado quantidade de droga, quantidade de dinheiro e quantidade de arma, o senhor não se lembra.', 382994, 390634, 0.7664448, 22, 0);
INSERT INTO speaker_segments (id, transcricao_id, speaker, speaker_confidence, text, start_time, end_time, confidence, words_count, channel) VALUES (1427, 29, 'C', 0.69259316, 'Não me lembro porque eles não pegaram nada com nós, os sojuíras. Eles chegaram em outra residência.', 391643, 397823, 0.69259316, 17, 0);
INSERT INTO speaker_segments (id, transcricao_id, speaker, speaker_confidence, text, start_time, end_time, confidence, words_count, channel) VALUES (1428, 29, 'D', 0.7877884, 'E isso não estava com vocês?', 397823, 400243, 0.7877884, 6, 0);
INSERT INTO speaker_segments (id, transcricao_id, speaker, speaker_confidence, text, start_time, end_time, confidence, words_count, channel) VALUES (1429, 29, 'C', 0.78967446, 'Não, não estava com nós. Eles pegaram em outra residência e daí botaram em nós.', 400243, 405563, 0.78967446, 15, 0);
INSERT INTO speaker_segments (id, transcricao_id, speaker, speaker_confidence, text, start_time, end_time, confidence, words_count, channel) VALUES (1430, 29, 'D', 0.78441405, 'E você estava perto dessa residência?', 405563, 408923, 0.78441405, 6, 0);
INSERT INTO speaker_segments (id, transcricao_id, speaker, speaker_confidence, text, start_time, end_time, confidence, words_count, channel) VALUES (1431, 29, 'C', 0.70424235, 'Ah, no caso, eu moro umas duas quartas dessa residência. Tá.', 408923, 413403, 0.70424235, 11, 0);
INSERT INTO speaker_segments (id, transcricao_id, speaker, speaker_confidence, text, start_time, end_time, confidence, words_count, channel) VALUES (1432, 29, 'D', 0.8431563, 'E o senhor está preso por tráfico?', 413403, 415743, 0.8431563, 7, 0);
INSERT INTO speaker_segments (id, transcricao_id, speaker, speaker_confidence, text, start_time, end_time, confidence, words_count, channel) VALUES (1433, 29, 'C', 0.69946146, 'Agora eu estou preso por tráfico? Poxa, eu fiquei quatro dias na rua só. Tá iniciado de novo.', 415743, 424297, 0.69946146, 18, 0);
INSERT INTO speaker_segments (id, transcricao_id, speaker, speaker_confidence, text, start_time, end_time, confidence, words_count, channel) VALUES (1434, 29, 'D', 0.69945425, 'Tá certo. Palavra ao conselho, Capitão Marcelo.', 424297, 428797, 0.69945425, 7, 0);
INSERT INTO speaker_segments (id, transcricao_id, speaker, speaker_confidence, text, start_time, end_time, confidence, words_count, channel) VALUES (1435, 29, 'B', 0.7757904, 'Sem perguntas, Excelência.', 428797, 433337, 0.7757904, 3, 0);
INSERT INTO speaker_segments (id, transcricao_id, speaker, speaker_confidence, text, start_time, end_time, confidence, words_count, channel) VALUES (1436, 29, 'D', 0.69968057, 'Ao Capitão Koniki.', 433337, 435937, 0.69968057, 3, 0);
INSERT INTO speaker_segments (id, transcricao_id, speaker, speaker_confidence, text, start_time, end_time, confidence, words_count, channel) VALUES (1437, 29, 'C', 0.78916794, 'Sem perguntas.', 435937, 436777, 0.78916794, 2, 0);
INSERT INTO speaker_segments (id, transcricao_id, speaker, speaker_confidence, text, start_time, end_time, confidence, words_count, channel) VALUES (1438, 29, 'D', 0.8342305, 'Ministério Público.', 436777, 441077, 0.8342305, 2, 0);
INSERT INTO speaker_segments (id, transcricao_id, speaker, speaker_confidence, text, start_time, end_time, confidence, words_count, channel) VALUES (1439, 29, 'E', 0.78305614, 'Boa tarde. Exatamente o que aconteceu nesse dia, Douglas? O senhor conheceu os policiais militares?', 441077, 449757, 0.78305614, 15, 0);
INSERT INTO speaker_segments (id, transcricao_id, speaker, speaker_confidence, text, start_time, end_time, confidence, words_count, channel) VALUES (1440, 29, 'C', 0.7280621, 'No caso, eu estava sem medir o meio para levar meus primos para o colégio e tomei uma abordagem da polícia. Nisso eu tomei uma abordagem. Eles tinham abordado outro guri que morava em frente da minha casa e estava saindo para trabalhar. Eles queriam saber de droga, de arma. A gente, sabe, falava... Falava que a gente não sabia de nada e eles começaram a bater na gente e me enxertaram mais com as drogas. Falaram que se a gente não falasse nada, eles enxertariam mais e levariam mais primos.', 452596, 481096, 0.7280621, 91, 0);
INSERT INTO speaker_segments (id, transcricao_id, speaker, speaker_confidence, text, start_time, end_time, confidence, words_count, channel) VALUES (1441, 29, 'E', 0.7521145, 'Você já conhecia os policiais?', 482785, 485525, 0.7521145, 5, 0);
INSERT INTO speaker_segments (id, transcricao_id, speaker, speaker_confidence, text, start_time, end_time, confidence, words_count, channel) VALUES (1442, 29, 'C', 0.66991013, 'Não, não conhecia.', 485525, 488065, 0.66991013, 3, 0);
INSERT INTO speaker_segments (id, transcricao_id, speaker, speaker_confidence, text, start_time, end_time, confidence, words_count, channel) VALUES (1443, 29, 'E', 0.8003854, 'Nem de vista?', 488065, 490045, 0.8003854, 3, 0);
INSERT INTO speaker_segments (id, transcricao_id, speaker, speaker_confidence, text, start_time, end_time, confidence, words_count, channel) VALUES (1444, 29, 'C', 0.69729936, 'Não, nunca tinha visto.', 490045, 492665, 0.69729936, 4, 0);
INSERT INTO speaker_segments (id, transcricao_id, speaker, speaker_confidence, text, start_time, end_time, confidence, words_count, channel) VALUES (1445, 29, 'E', 0.72353125, 'Eles te exigiram algum dinheiro, algo? Para não fazer isso?', 492665, 498105, 0.72353125, 10, 0);
INSERT INTO speaker_segments (id, transcricao_id, speaker, speaker_confidence, text, start_time, end_time, confidence, words_count, channel) VALUES (1446, 29, 'C', 0.8508152, 'Não, não pediram nada.', 498105, 501085, 0.8508152, 4, 0);
INSERT INTO speaker_segments (id, transcricao_id, speaker, speaker_confidence, text, start_time, end_time, confidence, words_count, channel) VALUES (1447, 29, 'E', 0.79725605, 'Você estava acompanhado de quem nesse momento?', 501085, 504685, 0.79725605, 7, 0);
INSERT INTO speaker_segments (id, transcricao_id, speaker, speaker_confidence, text, start_time, end_time, confidence, words_count, channel) VALUES (1448, 29, 'C', 0.88972265, 'Acompanhada da minha irmã.', 504685, 506465, 0.88972265, 4, 0);
INSERT INTO speaker_segments (id, transcricao_id, speaker, speaker_confidence, text, start_time, end_time, confidence, words_count, channel) VALUES (1449, 29, 'E', 0.8079838, 'Como é que é o nome dela?', 506465, 508225, 0.8079838, 7, 0);
INSERT INTO speaker_segments (id, transcricao_id, speaker, speaker_confidence, text, start_time, end_time, confidence, words_count, channel) VALUES (1450, 29, 'C', 0.904, 'Cristiane.', 508225, 510085, 0.904, 1, 0);
INSERT INTO speaker_segments (id, transcricao_id, speaker, speaker_confidence, text, start_time, end_time, confidence, words_count, channel) VALUES (1451, 29, 'E', 0.8019225, 'Só ela estava contigo? Mais ninguém?', 510085, 512525, 0.8019225, 6, 0);
INSERT INTO speaker_segments (id, transcricao_id, speaker, speaker_confidence, text, start_time, end_time, confidence, words_count, channel) VALUES (1452, 29, 'C', 0.72663534, 'Estava só eu e as minhas crianças em casa.', 513160, 515340, 0.72663534, 9, 0);
INSERT INTO speaker_segments (id, transcricao_id, speaker, speaker_confidence, text, start_time, end_time, confidence, words_count, channel) VALUES (1453, 29, 'E', 0.72180855, 'E por que eles fizeram isso contigo? Tu afirma que não conhecia eles, que.', 515340, 524360, 0.72180855, 14, 0);
INSERT INTO speaker_segments (id, transcricao_id, speaker, speaker_confidence, text, start_time, end_time, confidence, words_count, channel) VALUES (1454, 29, 'C', 0.7487738, 'Não foi exigido... Nada, eu já não sei. Não tenho o que dizer.', 524360, 533140, 0.7487738, 13, 0);
INSERT INTO speaker_segments (id, transcricao_id, speaker, speaker_confidence, text, start_time, end_time, confidence, words_count, channel) VALUES (1455, 29, 'E', 0.8020814, 'Tu está preso por esse fato?', 533140, 536780, 0.8020814, 6, 0);
INSERT INTO speaker_segments (id, transcricao_id, speaker, speaker_confidence, text, start_time, end_time, confidence, words_count, channel) VALUES (1456, 29, 'C', 0.7264756, 'Não, no caso desse fato, eu fui embora e voltei de novo para uma outra pronta.', 536780, 542060, 0.7264756, 16, 0);
INSERT INTO speaker_segments (id, transcricao_id, speaker, speaker_confidence, text, start_time, end_time, confidence, words_count, channel) VALUES (1457, 29, 'E', 0.7795394, 'Além de droga, arma, teve alguma questão envolvendo arma em relação a esse fato que o juiz questionou para ti?', 543738, 554478, 0.7795394, 20, 0);
INSERT INTO speaker_segments (id, transcricao_id, speaker, speaker_confidence, text, start_time, end_time, confidence, words_count, channel) VALUES (1458, 29, 'C', 0.8512734, 'Não entendi.', 554478, 555998, 0.8512734, 2, 0);
INSERT INTO speaker_segments (id, transcricao_id, speaker, speaker_confidence, text, start_time, end_time, confidence, words_count, channel) VALUES (1459, 29, 'E', 0.6748876, 'Em relação a arma, tem alguma coisa de enxertar um arma também ou não?', 555998, 561438, 0.6748876, 14, 0);
INSERT INTO speaker_segments (id, transcricao_id, speaker, speaker_confidence, text, start_time, end_time, confidence, words_count, channel) VALUES (1460, 29, 'C', 0.5796897, 'Podemos enxertar também um revólver.', 561438, 564758, 0.5796897, 5, 0);
INSERT INTO speaker_segments (id, transcricao_id, speaker, speaker_confidence, text, start_time, end_time, confidence, words_count, channel) VALUES (1461, 29, 'E', 0.8969453, 'Qual revólver?', 564758, 566798, 0.8969453, 2, 0);
INSERT INTO speaker_segments (id, transcricao_id, speaker, speaker_confidence, text, start_time, end_time, confidence, words_count, channel) VALUES (1462, 29, 'C', 0.66213214, 'Calibre 38.', 566798, 569718, 0.66213214, 2, 0);
INSERT INTO speaker_segments (id, transcricao_id, speaker, speaker_confidence, text, start_time, end_time, confidence, words_count, channel) VALUES (1463, 29, 'E', 0.8207299, 'E como é que foi esse enxerto?', 569718, 572178, 0.8207299, 7, 0);
INSERT INTO speaker_segments (id, transcricao_id, speaker, speaker_confidence, text, start_time, end_time, confidence, words_count, channel) VALUES (1464, 29, 'C', 0.66026735, 'Na hora da abordagem.', 573505, 575965, 0.66026735, 4, 0);
INSERT INTO speaker_segments (id, transcricao_id, speaker, speaker_confidence, text, start_time, end_time, confidence, words_count, channel) VALUES (1465, 29, 'E', 0.76930076, 'O que eles falaram?', 575965, 579205, 0.76930076, 4, 0);
INSERT INTO speaker_segments (id, transcricao_id, speaker, speaker_confidence, text, start_time, end_time, confidence, words_count, channel) VALUES (1466, 29, 'C', 0.74619275, 'Eles falaram que se a gente não falasse nada, eles iam chutar nós. Iam botar droga, arma e iam botar nós na cadeira.', 579205, 588105, 0.74619275, 23, 0);
INSERT INTO speaker_segments (id, transcricao_id, speaker, speaker_confidence, text, start_time, end_time, confidence, words_count, channel) VALUES (1467, 29, 'E', 0.6953336, 'Tu tem vínculo com alguma facção?', 589245, 592865, 0.6953336, 6, 0);
INSERT INTO speaker_segments (id, transcricao_id, speaker, speaker_confidence, text, start_time, end_time, confidence, words_count, channel) VALUES (1468, 29, 'C', 0.873, 'Não, não.', 592865, 594665, 0.873, 2, 0);
INSERT INTO speaker_segments (id, transcricao_id, speaker, speaker_confidence, text, start_time, end_time, confidence, words_count, channel) VALUES (1469, 29, 'E', 0.77933985, 'Nada mais.', 594665, 597225, 0.77933985, 2, 0);
INSERT INTO speaker_segments (id, transcricao_id, speaker, speaker_confidence, text, start_time, end_time, confidence, words_count, channel) VALUES (1470, 29, 'D', 0.73941714, 'Doutora Edna, pelo soldado Josimar.', 597225, 601205, 0.73941714, 5, 0);
INSERT INTO speaker_segments (id, transcricao_id, speaker, speaker_confidence, text, start_time, end_time, confidence, words_count, channel) VALUES (1471, 29, 'B', 0.57749087, 'Nada, em silêncio.', 604302, 606462, 0.57749087, 3, 0);
INSERT INTO speaker_segments (id, transcricao_id, speaker, speaker_confidence, text, start_time, end_time, confidence, words_count, channel) VALUES (1472, 29, 'D', 0.7052441, 'A doutora Ciomara pelo soldado Felipe.', 606462, 609702, 0.7052441, 6, 0);
INSERT INTO speaker_segments (id, transcricao_id, speaker, speaker_confidence, text, start_time, end_time, confidence, words_count, channel) VALUES (1473, 29, 'B', 0.86127216, 'Nada, em silêncio.', 609702, 612302, 0.86127216, 3, 0);
INSERT INTO speaker_segments (id, transcricao_id, speaker, speaker_confidence, text, start_time, end_time, confidence, words_count, channel) VALUES (1474, 29, 'D', 0.8705577, 'Pelo soldado Mateus, doutor Márcio Barcelos.', 612302, 616602, 0.8705577, 6, 0);
INSERT INTO speaker_segments (id, transcricao_id, speaker, speaker_confidence, text, start_time, end_time, confidence, words_count, channel) VALUES (1475, 29, 'F', 0.74845076, 'Sim, doutor. Só para confirmar com ele, se o Mateus Alicênio, ele lembra do Mateus nessa data, presente no fato da abordagem?', 616602, 626802, 0.74845076, 22, 0);
INSERT INTO speaker_segments (id, transcricao_id, speaker, speaker_confidence, text, start_time, end_time, confidence, words_count, channel) VALUES (1476, 29, 'B', 0.7406413, 'Eu não entendi.', 626802, 629762, 0.7406413, 3, 0);
INSERT INTO speaker_segments (id, transcricao_id, speaker, speaker_confidence, text, start_time, end_time, confidence, words_count, channel) VALUES (1477, 29, 'F', 0.7200159, 'Se ele lembra os policiais que abordaram ele, especialmente no meu caso, o Mateus Arsene.', 631505, 636805, 0.7200159, 15, 0);
INSERT INTO speaker_segments (id, transcricao_id, speaker, speaker_confidence, text, start_time, end_time, confidence, words_count, channel) VALUES (1478, 29, 'D', 0.80663544, 'O senhor lembra quem foram os policiais que lhe abordaram?', 636805, 641285, 0.80663544, 10, 0);
INSERT INTO speaker_segments (id, transcricao_id, speaker, speaker_confidence, text, start_time, end_time, confidence, words_count, channel) VALUES (1479, 29, 'C', 0.78309196, 'Ah, se eu olhar pelo rosto até lembro, mas pelo nome eu não lembro.', 641285, 648185, 0.78309196, 14, 0);
INSERT INTO speaker_segments (id, transcricao_id, speaker, speaker_confidence, text, start_time, end_time, confidence, words_count, channel) VALUES (1480, 29, 'F', 0.81894606, 'Chegaram a te convidar para fazer a cariação no inquérito?', 650065, 654765, 0.81894606, 10, 0);
INSERT INTO speaker_segments (id, transcricao_id, speaker, speaker_confidence, text, start_time, end_time, confidence, words_count, channel) VALUES (1481, 29, 'C', 0.77893084, 'Vocês chegaram a me bater?', 654765, 657045, 0.77893084, 5, 0);
INSERT INTO speaker_segments (id, transcricao_id, speaker, speaker_confidence, text, start_time, end_time, confidence, words_count, channel) VALUES (1482, 29, 'F', 0.774598, 'Não, fazer a cariação para te reconhecer os policiais.', 657045, 659525, 0.774598, 9, 0);
INSERT INTO speaker_segments (id, transcricao_id, speaker, speaker_confidence, text, start_time, end_time, confidence, words_count, channel) VALUES (1483, 29, 'C', 0.6902643, 'Não, não fizeram. Isso eu vi só em uma audiência na rua. Em uma audiência na rua eu vi isso.', 660293, 668073, 0.6902643, 20, 0);
INSERT INTO speaker_segments (id, transcricao_id, speaker, speaker_confidence, text, start_time, end_time, confidence, words_count, channel) VALUES (1484, 29, 'B', 0.85796076, 'Chegou a ser agredido? Quase me mataram.', 668073, 677353, 0.85796076, 7, 0);
INSERT INTO speaker_segments (id, transcricao_id, speaker, speaker_confidence, text, start_time, end_time, confidence, words_count, channel) VALUES (1485, 29, 'F', 0.6855556, 'Tu reagiu ou só um apanhado de graça?', 677933, 682593, 0.6855556, 8, 0);
INSERT INTO speaker_segments (id, transcricao_id, speaker, speaker_confidence, text, start_time, end_time, confidence, words_count, channel) VALUES (1486, 29, 'C', 0.64039135, 'Eu reagi contra quatro, não tem condições. Os caras quase me mataram.', 682593, 686813, 0.64039135, 12, 0);
INSERT INTO speaker_segments (id, transcricao_id, speaker, speaker_confidence, text, start_time, end_time, confidence, words_count, channel) VALUES (1487, 29, 'F', 0.7464871, 'Tu não viu os nomes deles nas fardas no dia?', 690078, 694558, 0.7464871, 10, 0);
INSERT INTO speaker_segments (id, transcricao_id, speaker, speaker_confidence, text, start_time, end_time, confidence, words_count, channel) VALUES (1488, 29, 'C', 0.7254081, 'Não via, não via porque eles me afogavam, eles estavam me afogando com água e botando pano na minha cara.', 694558, 700578, 0.7254081, 20, 0);
INSERT INTO speaker_segments (id, transcricao_id, speaker, speaker_confidence, text, start_time, end_time, confidence, words_count, channel) VALUES (1489, 29, 'F', 0.6679251, 'Afogaram onde?', 700578, 701518, 0.6679251, 2, 0);
INSERT INTO speaker_segments (id, transcricao_id, speaker, speaker_confidence, text, start_time, end_time, confidence, words_count, channel) VALUES (1490, 29, 'B', 0.5681553, 'Na camisa.', 701518, 703818, 0.5681553, 2, 0);
INSERT INTO speaker_segments (id, transcricao_id, speaker, speaker_confidence, text, start_time, end_time, confidence, words_count, channel) VALUES (1491, 29, 'F', 0.8741045, 'Aonde isso?', 703818, 706038, 0.8741045, 2, 0);
INSERT INTO speaker_segments (id, transcricao_id, speaker, speaker_confidence, text, start_time, end_time, confidence, words_count, channel) VALUES (1492, 29, 'C', 0.8736531, 'Na casa da minha irmã.', 706038, 707858, 0.8736531, 5, 0);
INSERT INTO speaker_segments (id, transcricao_id, speaker, speaker_confidence, text, start_time, end_time, confidence, words_count, channel) VALUES (1493, 29, 'F', 0.6733156, 'Foi dentro, eles entraram na tua casa?', 707858, 709798, 0.6733156, 7, 0);
INSERT INTO speaker_segments (id, transcricao_id, speaker, speaker_confidence, text, start_time, end_time, confidence, words_count, channel) VALUES (1494, 29, 'C', 0.8884495, 'Dentro da casa, na frente das crianças.', 709798, 712658, 0.8884495, 7, 0);
INSERT INTO speaker_segments (id, transcricao_id, speaker, speaker_confidence, text, start_time, end_time, confidence, words_count, channel) VALUES (1495, 29, 'F', 0.82803386, 'Alguém viu, alguém filmou? O senhor registrou isso?', 712658, 717018, 0.82803386, 8, 0);
INSERT INTO speaker_segments (id, transcricao_id, speaker, speaker_confidence, text, start_time, end_time, confidence, words_count, channel) VALUES (1496, 29, 'C', 0.7774581, 'Eu não sei se a minha irmã já vai registrar, mas ela viu. Isso foi de manhã cedo, umas oito e meia da manhã.', 718107, 727947, 0.7774581, 24, 0);
INSERT INTO speaker_segments (id, transcricao_id, speaker, speaker_confidence, text, start_time, end_time, confidence, words_count, channel) VALUES (1497, 29, 'B', 0.8415, 'Satisfeito, doutor.', 727947, 730907, 0.8415, 2, 0);
INSERT INTO speaker_segments (id, transcricao_id, speaker, speaker_confidence, text, start_time, end_time, confidence, words_count, channel) VALUES (1498, 29, 'C', 0.9115, 'Certo, doutor.', 730907, 734187, 0.9115, 2, 0);
INSERT INTO speaker_segments (id, transcricao_id, speaker, speaker_confidence, text, start_time, end_time, confidence, words_count, channel) VALUES (1499, 29, 'D', 0.7872133, 'Doutor Márcio Rossano.', 734187, 738087, 0.7872133, 3, 0);
INSERT INTO speaker_segments (id, transcricao_id, speaker, speaker_confidence, text, start_time, end_time, confidence, words_count, channel) VALUES (1500, 29, 'F', 0.92025554, 'Sem perguntas, doutor Francisco.', 738087, 741507, 0.92025554, 4, 0);
INSERT INTO speaker_segments (id, transcricao_id, speaker, speaker_confidence, text, start_time, end_time, confidence, words_count, channel) VALUES (1501, 29, 'D', 0.8994798, 'Doutor Alfredo.', 741507, 743167, 0.8994798, 2, 0);
INSERT INTO speaker_segments (id, transcricao_id, speaker, speaker_confidence, text, start_time, end_time, confidence, words_count, channel) VALUES (1502, 29, 'C', 0.5951634, 'Sem perguntas, doutor.', 747487, 749347, 0.5951634, 3, 0);
INSERT INTO speaker_segments (id, transcricao_id, speaker, speaker_confidence, text, start_time, end_time, confidence, words_count, channel) VALUES (1503, 29, 'D', 0.66517645, 'A doutora Paloma?', 749347, 751767, 0.66517645, 3, 0);
INSERT INTO speaker_segments (id, transcricao_id, speaker, speaker_confidence, text, start_time, end_time, confidence, words_count, channel) VALUES (1504, 29, 'B', 0.8847656, 'Sem perguntas.', 751767, 754287, 0.8847656, 2, 0);
INSERT INTO speaker_segments (id, transcricao_id, speaker, speaker_confidence, text, start_time, end_time, confidence, words_count, channel) VALUES (1505, 29, 'D', 0.82061243, 'Não ficou nenhum advogado de fora?', 754287, 757167, 0.82061243, 6, 0);
INSERT INTO speaker_segments (id, transcricao_id, speaker, speaker_confidence, text, start_time, end_time, confidence, words_count, channel) VALUES (1506, 29, 'B', 0.439, 'Ok.', 757167, 759807, 0.439, 1, 0);
INSERT INTO speaker_segments (id, transcricao_id, speaker, speaker_confidence, text, start_time, end_time, confidence, words_count, channel) VALUES (1507, 29, 'D', 0.8296425, 'Está liberado, então, a testemunha. O Douglas pode deixar a sala. Obrigado pela colaboração da Suzette.', 759807, 768327, 0.8296425, 16, 0);
INSERT INTO speaker_segments (id, transcricao_id, speaker, speaker_confidence, text, start_time, end_time, confidence, words_count, channel) VALUES (1508, 29, 'C', 0.80823046, 'Muito obrigado.', 768327, 771647, 0.80823046, 2, 0);
INSERT INTO speaker_segments (id, transcricao_id, speaker, speaker_confidence, text, start_time, end_time, confidence, words_count, channel) VALUES (1509, 31, 'A', 0.75352925, 'Douglas, tu me diz o teu nome completo.', 42, 4322, 0.75352925, 8, 0);
INSERT INTO speaker_segments (id, transcricao_id, speaker, speaker_confidence, text, start_time, end_time, confidence, words_count, channel) VALUES (1510, 31, 'B', 0.726, 'Nome?', 4322, 7322, 0.726, 1, 0);
INSERT INTO speaker_segments (id, transcricao_id, speaker, speaker_confidence, text, start_time, end_time, confidence, words_count, channel) VALUES (1511, 31, 'A', 0.7632965, 'Tu me diz o teu nome completo, por favor.', 8442, 11442, 0.7632965, 9, 0);
INSERT INTO speaker_segments (id, transcricao_id, speaker, speaker_confidence, text, start_time, end_time, confidence, words_count, channel) VALUES (1512, 31, 'C', 0.886487, 'Douglas Oliveira Mafalda.', 11442, 13982, 0.886487, 3, 0);
INSERT INTO speaker_segments (id, transcricao_id, speaker, speaker_confidence, text, start_time, end_time, confidence, words_count, channel) VALUES (1513, 31, 'A', 0.81675136, 'Tu me diz a tua filiação, o nome dos teus pais.', 13982, 19502, 0.81675136, 11, 0);
INSERT INTO speaker_segments (id, transcricao_id, speaker, speaker_confidence, text, start_time, end_time, confidence, words_count, channel) VALUES (1514, 31, 'C', 0.7998016, 'José Leomar de Oliveira Mafalda e Eliane Silva de Oliveira.', 19502, 23962, 0.7998016, 10, 0);
INSERT INTO speaker_segments (id, transcricao_id, speaker, speaker_confidence, text, start_time, end_time, confidence, words_count, channel) VALUES (1515, 31, 'A', 0.78990275, 'E qual é o princípio que tu está aí?', 23962, 26982, 0.78990275, 9, 0);
INSERT INTO speaker_segments (id, transcricao_id, speaker, speaker_confidence, text, start_time, end_time, confidence, words_count, channel) VALUES (1516, 31, 'C', 0.43456835, 'Não entendi.', 29945, 31005, 0.43456835, 2, 0);
INSERT INTO speaker_segments (id, transcricao_id, speaker, speaker_confidence, text, start_time, end_time, confidence, words_count, channel) VALUES (1517, 31, 'A', 0.698109, 'Tu tá preso em qual presídio?', 31005, 34025, 0.698109, 6, 0);
INSERT INTO speaker_segments (id, transcricao_id, speaker, speaker_confidence, text, start_time, end_time, confidence, words_count, channel) VALUES (1518, 31, 'C', 0.70301366, 'Tô na APK.', 34025, 35345, 0.70301366, 3, 0);
INSERT INTO speaker_segments (id, transcricao_id, speaker, speaker_confidence, text, start_time, end_time, confidence, words_count, channel) VALUES (1519, 31, 'A', 0.67789453, 'Na APK.', 35345, 37085, 0.67789453, 2, 0);
INSERT INTO speaker_segments (id, transcricao_id, speaker, speaker_confidence, text, start_time, end_time, confidence, words_count, channel) VALUES (1520, 31, 'B', 0.89524025, 'Tá certo.', 37085, 39445, 0.89524025, 2, 0);
INSERT INTO speaker_segments (id, transcricao_id, speaker, speaker_confidence, text, start_time, end_time, confidence, words_count, channel) VALUES (1521, 31, 'D', 0.479, 'Ok.', 39445, 40885, 0.479, 1, 0);
INSERT INTO speaker_segments (id, transcricao_id, speaker, speaker_confidence, text, start_time, end_time, confidence, words_count, channel) VALUES (1522, 31, 'A', 0.8647018, 'Aqui sim, doutor.', 40885, 43645, 0.8647018, 3, 0);
INSERT INTO speaker_segments (id, transcricao_id, speaker, speaker_confidence, text, start_time, end_time, confidence, words_count, channel) VALUES (1523, 31, 'D', 0.71908075, 'Boa tarde, Douglas.', 43645, 45565, 0.71908075, 3, 0);
INSERT INTO speaker_segments (id, transcricao_id, speaker, speaker_confidence, text, start_time, end_time, confidence, words_count, channel) VALUES (1524, 31, 'C', 0.71542776, 'Boa tarde.', 45565, 46285, 0.71542776, 2, 0);
INSERT INTO speaker_segments (id, transcricao_id, speaker, speaker_confidence, text, start_time, end_time, confidence, words_count, channel) VALUES (1525, 31, 'D', 0.79165494, 'Douglas, o senhor vai ser ouvido sobre o fato número 5º da denúncia, ok? Eu vou fazer a leitura do fato para ver se o senhor se recorda, porque já faz algum tempo. No dia 22 de outubro de 2019, por volta das 22h30, na Rua Lago Azul, número 248, no bairro Santa Bárbara, cidade de Alvorada, os soldados Josimar da Silva Pereira, Felipe Ferreira Janiquim e Mateus Arcenes de Voraes, em comunhão de resposta e condição de vontade, todos de serviço pilotado no vigésimo quarto PTM, apropriaram-se de valores que tinham força e razão da função apreendido durante a ocorrência policial registrada sob o número 100-464-2019-14700, relativa aos crimes de tráfego de entorpecentes e porte legal de arma. Na oportunidade, os denunciados prenderam Douglas de Oliveira Mafalda e Rafael de Cidade Barbosa por tráfico de estropecentes e porte ilegal de arma, aprendendo, dentre outros materiais, dois coletes balísticos, uma pistola calibre .380, um revólver calibre .38, um revólver calibre .32 e uma espigada calibre .12. também 2.289 gramas de cocaína, 79 gramas de maconha e, ao menos, um grama de crack. E R$331 em dinheiro.', 47967, 142062, 0.79165494, 186, 0);
INSERT INTO speaker_segments (id, transcricao_id, speaker, speaker_confidence, text, start_time, end_time, confidence, words_count, channel) VALUES (1526, 31, 'A', 0.614, 'Pergunta.', 142062, 145062, 0.614, 1, 0);
INSERT INTO speaker_segments (id, transcricao_id, speaker, speaker_confidence, text, start_time, end_time, confidence, words_count, channel) VALUES (1527, 31, 'D', 0.806027, 'Douglas, sobre essa ocorrência, o que o senhor tem a nos dizer?', 149702, 154242, 0.806027, 12, 0);
INSERT INTO speaker_segments (id, transcricao_id, speaker, speaker_confidence, text, start_time, end_time, confidence, words_count, channel) VALUES (1528, 31, 'A', 0.377903, 'E aí e o problema do tornozelo né é alguma coisa aconteceu e tá.', 157115, 168995, 0.377903, 14, 0);
INSERT INTO speaker_segments (id, transcricao_id, speaker, speaker_confidence, text, start_time, end_time, confidence, words_count, channel) VALUES (1529, 31, 'B', 0.4907401, 'Voltou a normal E aí E aí.', 168995, 177445, 0.4907401, 7, 0);
INSERT INTO speaker_segments (id, transcricao_id, speaker, speaker_confidence, text, start_time, end_time, confidence, words_count, channel) VALUES (1530, 31, 'D', 0.5180132, 'O Bernadete põe ele na tela principal.', 177445, 179135, 0.5180132, 7, 0);
INSERT INTO speaker_segments (id, transcricao_id, speaker, speaker_confidence, text, start_time, end_time, confidence, words_count, channel) VALUES (1531, 31, 'A', 0.519529, 'E ele tá na tela doutor tá.', 179135, 184475, 0.519529, 7, 0);
INSERT INTO speaker_segments (id, transcricao_id, speaker, speaker_confidence, text, start_time, end_time, confidence, words_count, channel) VALUES (1532, 31, 'C', 0.62781566, 'Mas dá na principal, que eu não estou vendo.', 184475, 190122, 0.62781566, 9, 0);
INSERT INTO speaker_segments (id, transcricao_id, speaker, speaker_confidence, text, start_time, end_time, confidence, words_count, channel) VALUES (1533, 31, 'A', 0.62438333, 'Aqui a gente está.', 193302, 196082, 0.62438333, 4, 0);
INSERT INTO speaker_segments (id, transcricao_id, speaker, speaker_confidence, text, start_time, end_time, confidence, words_count, channel) VALUES (1534, 31, 'D', 0.8230529, 'Douglas, ouviu sobre essa ocorrência?', 196082, 201222, 0.8230529, 5, 0);
INSERT INTO speaker_segments (id, transcricao_id, speaker, speaker_confidence, text, start_time, end_time, confidence, words_count, channel) VALUES (1535, 31, 'C', 0.7735, 'Escutei, escutei.', 201222, 203082, 0.7735, 2, 0);
INSERT INTO speaker_segments (id, transcricao_id, speaker, speaker_confidence, text, start_time, end_time, confidence, words_count, channel) VALUES (1536, 31, 'D', 0.81704307, '22 de outubro de 2019, o senhor foi preso, junto com o Rafael, por porte ilegal de drogas e arma. Sobre esse fato, o que o senhor pode nos dizer sobre isso?', 203082, 218612, 0.81704307, 32, 0);
INSERT INTO speaker_segments (id, transcricao_id, speaker, speaker_confidence, text, start_time, end_time, confidence, words_count, channel) VALUES (1537, 31, 'C', 0.68094903, 'Não tenho nada a dizer sobre isso.', 218612, 222132, 0.68094903, 7, 0);
INSERT INTO speaker_segments (id, transcricao_id, speaker, speaker_confidence, text, start_time, end_time, confidence, words_count, channel) VALUES (1538, 31, 'D', 0.79700947, 'O senhor estava na posse de entorpecente e armas?', 222132, 226592, 0.79700947, 9, 0);
INSERT INTO speaker_segments (id, transcricao_id, speaker, speaker_confidence, text, start_time, end_time, confidence, words_count, channel) VALUES (1539, 31, 'C', 0.7912666, 'Estava na posse, estava.', 226592, 229692, 0.7912666, 4, 0);
INSERT INTO speaker_segments (id, transcricao_id, speaker, speaker_confidence, text, start_time, end_time, confidence, words_count, channel) VALUES (1540, 31, 'D', 0.7679148, 'E o senhor se recorda de quantas armas o senhor tinha?', 229692, 236392, 0.7679148, 11, 0);
INSERT INTO speaker_segments (id, transcricao_id, speaker, speaker_confidence, text, start_time, end_time, confidence, words_count, channel) VALUES (1541, 31, 'C', 0.70098877, 'Claro, não me lembro.', 236392, 238532, 0.70098877, 4, 0);
INSERT INTO speaker_segments (id, transcricao_id, speaker, speaker_confidence, text, start_time, end_time, confidence, words_count, channel) VALUES (1542, 31, 'D', 0.9268195, 'E a quantidade de drogas?', 238532, 240612, 0.9268195, 5, 0);
INSERT INTO speaker_segments (id, transcricao_id, speaker, speaker_confidence, text, start_time, end_time, confidence, words_count, channel) VALUES (1543, 31, 'C', 0.6927886, 'Também não sei, não era eu que vendia.', 241996, 244876, 0.6927886, 8, 0);
INSERT INTO speaker_segments (id, transcricao_id, speaker, speaker_confidence, text, start_time, end_time, confidence, words_count, channel) VALUES (1544, 31, 'D', 0.76619697, 'Valores em dinheiro, o senhor saberia dizer quanto de dinheiro o senhor tinha nessa oportunidade, junto com o Rafael?', 244876, 255336, 0.76619697, 19, 0);
INSERT INTO speaker_segments (id, transcricao_id, speaker, speaker_confidence, text, start_time, end_time, confidence, words_count, channel) VALUES (1545, 31, 'C', 0.773043, 'Não sei.', 255336, 257456, 0.773043, 2, 0);
INSERT INTO speaker_segments (id, transcricao_id, speaker, speaker_confidence, text, start_time, end_time, confidence, words_count, channel) VALUES (1546, 31, 'D', 0.80529785, 'Não se recorda? Não. Durante essa ocorrência, o senhor chegou a notar se algum policial pegou algum dinheiro para ele?', 257456, 266216, 0.80529785, 20, 0);
INSERT INTO speaker_segments (id, transcricao_id, speaker, speaker_confidence, text, start_time, end_time, confidence, words_count, channel) VALUES (1547, 31, 'B', 0.919, 'Ouviu, Douglas?', 272472, 276872, 0.919, 2, 0);
INSERT INTO speaker_segments (id, transcricao_id, speaker, speaker_confidence, text, start_time, end_time, confidence, words_count, channel) VALUES (1548, 31, 'C', 0.849, 'Douglas.', 276872, 279872, 0.849, 1, 0);
INSERT INTO speaker_segments (id, transcricao_id, speaker, speaker_confidence, text, start_time, end_time, confidence, words_count, channel) VALUES (1549, 31, 'D', 0.82240105, 'Está me ouvindo?', 281672, 284852, 0.82240105, 3, 0);
INSERT INTO speaker_segments (id, transcricao_id, speaker, speaker_confidence, text, start_time, end_time, confidence, words_count, channel) VALUES (1550, 31, 'B', 0.73709244, 'De novo deu.', 286132, 290772, 0.73709244, 3, 0);
INSERT INTO speaker_segments (id, transcricao_id, speaker, speaker_confidence, text, start_time, end_time, confidence, words_count, channel) VALUES (1551, 31, 'A', 0.79088366, 'Ele continua aqui na tela, doutor, PK Douglas. Douglas, você está nos ouvindo? Porque ele não caiu, ele está aqui no… Vamos ver, espera aí. Agora caiu, estou colocando ele de novo.', 290772, 317713, 0.79088366, 32, 0);
INSERT INTO speaker_segments (id, transcricao_id, speaker, speaker_confidence, text, start_time, end_time, confidence, words_count, channel) VALUES (1552, 31, 'B', 0.31982422, 'Você.', 317713, 320713, 0.31982422, 1, 0);
INSERT INTO speaker_segments (id, transcricao_id, speaker, speaker_confidence, text, start_time, end_time, confidence, words_count, channel) VALUES (1553, 31, 'A', 0.679965, 'Está saindo da APK que está… Coloca o Diogo de novo. Coloca o Douglas de novo.', 328033, 336490, 0.679965, 16, 0);
INSERT INTO speaker_segments (id, transcricao_id, speaker, speaker_confidence, text, start_time, end_time, confidence, words_count, channel) VALUES (1554, 31, 'C', 0.67762816, 'Tá, só um momento que eu tô configurando aqui.', 336490, 339010, 0.67762816, 9, 0);
INSERT INTO speaker_segments (id, transcricao_id, speaker, speaker_confidence, text, start_time, end_time, confidence, words_count, channel) VALUES (1555, 31, 'B', 0.8497435, 'Tá certo. Pronto.', 339010, 347070, 0.8497435, 3, 0);
INSERT INTO speaker_segments (id, transcricao_id, speaker, speaker_confidence, text, start_time, end_time, confidence, words_count, channel) VALUES (1556, 31, 'A', 0.7671834, 'Doutor, ele tá de volta.', 356650, 359050, 0.7671834, 5, 0);
INSERT INTO speaker_segments (id, transcricao_id, speaker, speaker_confidence, text, start_time, end_time, confidence, words_count, channel) VALUES (1557, 31, 'D', 0.729, 'Douglas!', 359050, 362050, 0.729, 1, 0);
INSERT INTO speaker_segments (id, transcricao_id, speaker, speaker_confidence, text, start_time, end_time, confidence, words_count, channel) VALUES (1558, 31, 'B', 0.834, 'Opa!', 362630, 363610, 0.834, 1, 0);
INSERT INTO speaker_segments (id, transcricao_id, speaker, speaker_confidence, text, start_time, end_time, confidence, words_count, channel) VALUES (1559, 31, 'D', 0.71159005, 'Durante essa ocorrência, o senhor chegou a notar se algum policial tinha pego o dinheiro que estava na posse de vocês? Acho que foi agora. Mas não tem certeza.', 364154, 379014, 0.71159005, 29, 0);
INSERT INTO speaker_segments (id, transcricao_id, speaker, speaker_confidence, text, start_time, end_time, confidence, words_count, channel) VALUES (1560, 31, 'B', 0.62228644, 'É, não tem certeza.', 379014, 382494, 0.62228644, 4, 0);
INSERT INTO speaker_segments (id, transcricao_id, speaker, speaker_confidence, text, start_time, end_time, confidence, words_count, channel) VALUES (1561, 31, 'D', 0.7664448, 'E como eu já tinha lhe perguntado quantidade de droga, quantidade de dinheiro e quantidade de arma, o senhor não se lembra.', 382994, 390634, 0.7664448, 22, 0);
INSERT INTO speaker_segments (id, transcricao_id, speaker, speaker_confidence, text, start_time, end_time, confidence, words_count, channel) VALUES (1562, 31, 'C', 0.69259316, 'Não me lembro porque eles não pegaram nada com nós, os sojuíras. Eles chegaram em outra residência.', 391643, 397823, 0.69259316, 17, 0);
INSERT INTO speaker_segments (id, transcricao_id, speaker, speaker_confidence, text, start_time, end_time, confidence, words_count, channel) VALUES (1563, 31, 'D', 0.7877884, 'E isso não estava com vocês?', 397823, 400243, 0.7877884, 6, 0);
INSERT INTO speaker_segments (id, transcricao_id, speaker, speaker_confidence, text, start_time, end_time, confidence, words_count, channel) VALUES (1564, 31, 'C', 0.78967446, 'Não, não estava com nós. Eles pegaram em outra residência e daí botaram em nós.', 400243, 405563, 0.78967446, 15, 0);
INSERT INTO speaker_segments (id, transcricao_id, speaker, speaker_confidence, text, start_time, end_time, confidence, words_count, channel) VALUES (1565, 31, 'D', 0.78441405, 'E você estava perto dessa residência?', 405563, 408923, 0.78441405, 6, 0);
INSERT INTO speaker_segments (id, transcricao_id, speaker, speaker_confidence, text, start_time, end_time, confidence, words_count, channel) VALUES (1566, 31, 'C', 0.70424235, 'Ah, no caso, eu moro umas duas quartas dessa residência. Tá.', 408923, 413403, 0.70424235, 11, 0);
INSERT INTO speaker_segments (id, transcricao_id, speaker, speaker_confidence, text, start_time, end_time, confidence, words_count, channel) VALUES (1567, 31, 'D', 0.8431563, 'E o senhor está preso por tráfico?', 413403, 415743, 0.8431563, 7, 0);
INSERT INTO speaker_segments (id, transcricao_id, speaker, speaker_confidence, text, start_time, end_time, confidence, words_count, channel) VALUES (1568, 31, 'C', 0.69946146, 'Agora eu estou preso por tráfico? Poxa, eu fiquei quatro dias na rua só. Tá iniciado de novo.', 415743, 424297, 0.69946146, 18, 0);
INSERT INTO speaker_segments (id, transcricao_id, speaker, speaker_confidence, text, start_time, end_time, confidence, words_count, channel) VALUES (1569, 31, 'D', 0.69945425, 'Tá certo. Palavra ao conselho, Capitão Marcelo.', 424297, 428797, 0.69945425, 7, 0);
INSERT INTO speaker_segments (id, transcricao_id, speaker, speaker_confidence, text, start_time, end_time, confidence, words_count, channel) VALUES (1570, 31, 'B', 0.7757904, 'Sem perguntas, Excelência.', 428797, 433337, 0.7757904, 3, 0);
INSERT INTO speaker_segments (id, transcricao_id, speaker, speaker_confidence, text, start_time, end_time, confidence, words_count, channel) VALUES (1571, 31, 'D', 0.69968057, 'Ao Capitão Koniki.', 433337, 435937, 0.69968057, 3, 0);
INSERT INTO speaker_segments (id, transcricao_id, speaker, speaker_confidence, text, start_time, end_time, confidence, words_count, channel) VALUES (1572, 31, 'C', 0.78916794, 'Sem perguntas.', 435937, 436777, 0.78916794, 2, 0);
INSERT INTO speaker_segments (id, transcricao_id, speaker, speaker_confidence, text, start_time, end_time, confidence, words_count, channel) VALUES (1573, 31, 'D', 0.8342305, 'Ministério Público.', 436777, 441077, 0.8342305, 2, 0);
INSERT INTO speaker_segments (id, transcricao_id, speaker, speaker_confidence, text, start_time, end_time, confidence, words_count, channel) VALUES (1574, 31, 'E', 0.78305614, 'Boa tarde. Exatamente o que aconteceu nesse dia, Douglas? O senhor conheceu os policiais militares?', 441077, 449757, 0.78305614, 15, 0);
INSERT INTO speaker_segments (id, transcricao_id, speaker, speaker_confidence, text, start_time, end_time, confidence, words_count, channel) VALUES (1575, 31, 'C', 0.7280621, 'No caso, eu estava sem medir o meio para levar meus primos para o colégio e tomei uma abordagem da polícia. Nisso eu tomei uma abordagem. Eles tinham abordado outro guri que morava em frente da minha casa e estava saindo para trabalhar. Eles queriam saber de droga, de arma. A gente, sabe, falava... Falava que a gente não sabia de nada e eles começaram a bater na gente e me enxertaram mais com as drogas. Falaram que se a gente não falasse nada, eles enxertariam mais e levariam mais primos.', 452596, 481096, 0.7280621, 91, 0);
INSERT INTO speaker_segments (id, transcricao_id, speaker, speaker_confidence, text, start_time, end_time, confidence, words_count, channel) VALUES (1576, 31, 'E', 0.7521145, 'Você já conhecia os policiais?', 482785, 485525, 0.7521145, 5, 0);
INSERT INTO speaker_segments (id, transcricao_id, speaker, speaker_confidence, text, start_time, end_time, confidence, words_count, channel) VALUES (1577, 31, 'C', 0.66991013, 'Não, não conhecia.', 485525, 488065, 0.66991013, 3, 0);
INSERT INTO speaker_segments (id, transcricao_id, speaker, speaker_confidence, text, start_time, end_time, confidence, words_count, channel) VALUES (1578, 31, 'E', 0.8003854, 'Nem de vista?', 488065, 490045, 0.8003854, 3, 0);
INSERT INTO speaker_segments (id, transcricao_id, speaker, speaker_confidence, text, start_time, end_time, confidence, words_count, channel) VALUES (1579, 31, 'C', 0.69729936, 'Não, nunca tinha visto.', 490045, 492665, 0.69729936, 4, 0);
INSERT INTO speaker_segments (id, transcricao_id, speaker, speaker_confidence, text, start_time, end_time, confidence, words_count, channel) VALUES (1580, 31, 'E', 0.72353125, 'Eles te exigiram algum dinheiro, algo? Para não fazer isso?', 492665, 498105, 0.72353125, 10, 0);
INSERT INTO speaker_segments (id, transcricao_id, speaker, speaker_confidence, text, start_time, end_time, confidence, words_count, channel) VALUES (1581, 31, 'C', 0.8508152, 'Não, não pediram nada.', 498105, 501085, 0.8508152, 4, 0);
INSERT INTO speaker_segments (id, transcricao_id, speaker, speaker_confidence, text, start_time, end_time, confidence, words_count, channel) VALUES (1582, 31, 'E', 0.79725605, 'Você estava acompanhado de quem nesse momento?', 501085, 504685, 0.79725605, 7, 0);
INSERT INTO speaker_segments (id, transcricao_id, speaker, speaker_confidence, text, start_time, end_time, confidence, words_count, channel) VALUES (1583, 31, 'C', 0.88972265, 'Acompanhada da minha irmã.', 504685, 506465, 0.88972265, 4, 0);
INSERT INTO speaker_segments (id, transcricao_id, speaker, speaker_confidence, text, start_time, end_time, confidence, words_count, channel) VALUES (1584, 31, 'E', 0.8079838, 'Como é que é o nome dela?', 506465, 508225, 0.8079838, 7, 0);
INSERT INTO speaker_segments (id, transcricao_id, speaker, speaker_confidence, text, start_time, end_time, confidence, words_count, channel) VALUES (1585, 31, 'C', 0.904, 'Cristiane.', 508225, 510085, 0.904, 1, 0);
INSERT INTO speaker_segments (id, transcricao_id, speaker, speaker_confidence, text, start_time, end_time, confidence, words_count, channel) VALUES (1586, 31, 'E', 0.8019225, 'Só ela estava contigo? Mais ninguém?', 510085, 512525, 0.8019225, 6, 0);
INSERT INTO speaker_segments (id, transcricao_id, speaker, speaker_confidence, text, start_time, end_time, confidence, words_count, channel) VALUES (1587, 31, 'C', 0.72663534, 'Estava só eu e as minhas crianças em casa.', 513160, 515340, 0.72663534, 9, 0);
INSERT INTO speaker_segments (id, transcricao_id, speaker, speaker_confidence, text, start_time, end_time, confidence, words_count, channel) VALUES (1588, 31, 'E', 0.72180855, 'E por que eles fizeram isso contigo? Tu afirma que não conhecia eles, que.', 515340, 524360, 0.72180855, 14, 0);
INSERT INTO speaker_segments (id, transcricao_id, speaker, speaker_confidence, text, start_time, end_time, confidence, words_count, channel) VALUES (1589, 31, 'C', 0.7487738, 'Não foi exigido... Nada, eu já não sei. Não tenho o que dizer.', 524360, 533140, 0.7487738, 13, 0);
INSERT INTO speaker_segments (id, transcricao_id, speaker, speaker_confidence, text, start_time, end_time, confidence, words_count, channel) VALUES (1590, 31, 'E', 0.8020814, 'Tu está preso por esse fato?', 533140, 536780, 0.8020814, 6, 0);
INSERT INTO speaker_segments (id, transcricao_id, speaker, speaker_confidence, text, start_time, end_time, confidence, words_count, channel) VALUES (1591, 31, 'C', 0.7264756, 'Não, no caso desse fato, eu fui embora e voltei de novo para uma outra pronta.', 536780, 542060, 0.7264756, 16, 0);
INSERT INTO speaker_segments (id, transcricao_id, speaker, speaker_confidence, text, start_time, end_time, confidence, words_count, channel) VALUES (1592, 31, 'E', 0.7795394, 'Além de droga, arma, teve alguma questão envolvendo arma em relação a esse fato que o juiz questionou para ti?', 543738, 554478, 0.7795394, 20, 0);
INSERT INTO speaker_segments (id, transcricao_id, speaker, speaker_confidence, text, start_time, end_time, confidence, words_count, channel) VALUES (1593, 31, 'C', 0.8512734, 'Não entendi.', 554478, 555998, 0.8512734, 2, 0);
INSERT INTO speaker_segments (id, transcricao_id, speaker, speaker_confidence, text, start_time, end_time, confidence, words_count, channel) VALUES (1594, 31, 'E', 0.6748876, 'Em relação a arma, tem alguma coisa de enxertar um arma também ou não?', 555998, 561438, 0.6748876, 14, 0);
INSERT INTO speaker_segments (id, transcricao_id, speaker, speaker_confidence, text, start_time, end_time, confidence, words_count, channel) VALUES (1595, 31, 'C', 0.5796897, 'Podemos enxertar também um revólver.', 561438, 564758, 0.5796897, 5, 0);
INSERT INTO speaker_segments (id, transcricao_id, speaker, speaker_confidence, text, start_time, end_time, confidence, words_count, channel) VALUES (1596, 31, 'E', 0.8969453, 'Qual revólver?', 564758, 566798, 0.8969453, 2, 0);
INSERT INTO speaker_segments (id, transcricao_id, speaker, speaker_confidence, text, start_time, end_time, confidence, words_count, channel) VALUES (1597, 31, 'C', 0.66213214, 'Calibre 38.', 566798, 569718, 0.66213214, 2, 0);
INSERT INTO speaker_segments (id, transcricao_id, speaker, speaker_confidence, text, start_time, end_time, confidence, words_count, channel) VALUES (1598, 31, 'E', 0.8207299, 'E como é que foi esse enxerto?', 569718, 572178, 0.8207299, 7, 0);
INSERT INTO speaker_segments (id, transcricao_id, speaker, speaker_confidence, text, start_time, end_time, confidence, words_count, channel) VALUES (1599, 31, 'C', 0.66026735, 'Na hora da abordagem.', 573505, 575965, 0.66026735, 4, 0);
INSERT INTO speaker_segments (id, transcricao_id, speaker, speaker_confidence, text, start_time, end_time, confidence, words_count, channel) VALUES (1600, 31, 'E', 0.76930076, 'O que eles falaram?', 575965, 579205, 0.76930076, 4, 0);
INSERT INTO speaker_segments (id, transcricao_id, speaker, speaker_confidence, text, start_time, end_time, confidence, words_count, channel) VALUES (1601, 31, 'C', 0.74619275, 'Eles falaram que se a gente não falasse nada, eles iam chutar nós. Iam botar droga, arma e iam botar nós na cadeira.', 579205, 588105, 0.74619275, 23, 0);
INSERT INTO speaker_segments (id, transcricao_id, speaker, speaker_confidence, text, start_time, end_time, confidence, words_count, channel) VALUES (1602, 31, 'E', 0.6953336, 'Tu tem vínculo com alguma facção?', 589245, 592865, 0.6953336, 6, 0);
INSERT INTO speaker_segments (id, transcricao_id, speaker, speaker_confidence, text, start_time, end_time, confidence, words_count, channel) VALUES (1603, 31, 'C', 0.873, 'Não, não.', 592865, 594665, 0.873, 2, 0);
INSERT INTO speaker_segments (id, transcricao_id, speaker, speaker_confidence, text, start_time, end_time, confidence, words_count, channel) VALUES (1604, 31, 'E', 0.77933985, 'Nada mais.', 594665, 597225, 0.77933985, 2, 0);
INSERT INTO speaker_segments (id, transcricao_id, speaker, speaker_confidence, text, start_time, end_time, confidence, words_count, channel) VALUES (1605, 31, 'D', 0.73941714, 'Doutora Edna, pelo soldado Josimar.', 597225, 601205, 0.73941714, 5, 0);
INSERT INTO speaker_segments (id, transcricao_id, speaker, speaker_confidence, text, start_time, end_time, confidence, words_count, channel) VALUES (1606, 31, 'B', 0.57749087, 'Nada, em silêncio.', 604302, 606462, 0.57749087, 3, 0);
INSERT INTO speaker_segments (id, transcricao_id, speaker, speaker_confidence, text, start_time, end_time, confidence, words_count, channel) VALUES (1607, 31, 'D', 0.7052441, 'A doutora Ciomara pelo soldado Felipe.', 606462, 609702, 0.7052441, 6, 0);
INSERT INTO speaker_segments (id, transcricao_id, speaker, speaker_confidence, text, start_time, end_time, confidence, words_count, channel) VALUES (1608, 31, 'B', 0.86127216, 'Nada, em silêncio.', 609702, 612302, 0.86127216, 3, 0);
INSERT INTO speaker_segments (id, transcricao_id, speaker, speaker_confidence, text, start_time, end_time, confidence, words_count, channel) VALUES (1609, 31, 'D', 0.8705577, 'Pelo soldado Mateus, doutor Márcio Barcelos.', 612302, 616602, 0.8705577, 6, 0);
INSERT INTO speaker_segments (id, transcricao_id, speaker, speaker_confidence, text, start_time, end_time, confidence, words_count, channel) VALUES (1610, 31, 'F', 0.74845076, 'Sim, doutor. Só para confirmar com ele, se o Mateus Alicênio, ele lembra do Mateus nessa data, presente no fato da abordagem?', 616602, 626802, 0.74845076, 22, 0);
INSERT INTO speaker_segments (id, transcricao_id, speaker, speaker_confidence, text, start_time, end_time, confidence, words_count, channel) VALUES (1611, 31, 'B', 0.7406413, 'Eu não entendi.', 626802, 629762, 0.7406413, 3, 0);
INSERT INTO speaker_segments (id, transcricao_id, speaker, speaker_confidence, text, start_time, end_time, confidence, words_count, channel) VALUES (1612, 31, 'F', 0.7200159, 'Se ele lembra os policiais que abordaram ele, especialmente no meu caso, o Mateus Arsene.', 631505, 636805, 0.7200159, 15, 0);
INSERT INTO speaker_segments (id, transcricao_id, speaker, speaker_confidence, text, start_time, end_time, confidence, words_count, channel) VALUES (1613, 31, 'D', 0.80663544, 'O senhor lembra quem foram os policiais que lhe abordaram?', 636805, 641285, 0.80663544, 10, 0);
INSERT INTO speaker_segments (id, transcricao_id, speaker, speaker_confidence, text, start_time, end_time, confidence, words_count, channel) VALUES (1614, 31, 'C', 0.78309196, 'Ah, se eu olhar pelo rosto até lembro, mas pelo nome eu não lembro.', 641285, 648185, 0.78309196, 14, 0);
INSERT INTO speaker_segments (id, transcricao_id, speaker, speaker_confidence, text, start_time, end_time, confidence, words_count, channel) VALUES (1615, 31, 'F', 0.81894606, 'Chegaram a te convidar para fazer a cariação no inquérito?', 650065, 654765, 0.81894606, 10, 0);
INSERT INTO speaker_segments (id, transcricao_id, speaker, speaker_confidence, text, start_time, end_time, confidence, words_count, channel) VALUES (1616, 31, 'C', 0.77893084, 'Vocês chegaram a me bater?', 654765, 657045, 0.77893084, 5, 0);
INSERT INTO speaker_segments (id, transcricao_id, speaker, speaker_confidence, text, start_time, end_time, confidence, words_count, channel) VALUES (1617, 31, 'F', 0.774598, 'Não, fazer a cariação para te reconhecer os policiais.', 657045, 659525, 0.774598, 9, 0);
INSERT INTO speaker_segments (id, transcricao_id, speaker, speaker_confidence, text, start_time, end_time, confidence, words_count, channel) VALUES (1618, 31, 'C', 0.6902643, 'Não, não fizeram. Isso eu vi só em uma audiência na rua. Em uma audiência na rua eu vi isso.', 660293, 668073, 0.6902643, 20, 0);
INSERT INTO speaker_segments (id, transcricao_id, speaker, speaker_confidence, text, start_time, end_time, confidence, words_count, channel) VALUES (1619, 31, 'B', 0.85796076, 'Chegou a ser agredido? Quase me mataram.', 668073, 677353, 0.85796076, 7, 0);
INSERT INTO speaker_segments (id, transcricao_id, speaker, speaker_confidence, text, start_time, end_time, confidence, words_count, channel) VALUES (1620, 31, 'F', 0.6855556, 'Tu reagiu ou só um apanhado de graça?', 677933, 682593, 0.6855556, 8, 0);
INSERT INTO speaker_segments (id, transcricao_id, speaker, speaker_confidence, text, start_time, end_time, confidence, words_count, channel) VALUES (1621, 31, 'C', 0.64039135, 'Eu reagi contra quatro, não tem condições. Os caras quase me mataram.', 682593, 686813, 0.64039135, 12, 0);
INSERT INTO speaker_segments (id, transcricao_id, speaker, speaker_confidence, text, start_time, end_time, confidence, words_count, channel) VALUES (1622, 31, 'F', 0.7464871, 'Tu não viu os nomes deles nas fardas no dia?', 690078, 694558, 0.7464871, 10, 0);
INSERT INTO speaker_segments (id, transcricao_id, speaker, speaker_confidence, text, start_time, end_time, confidence, words_count, channel) VALUES (1623, 31, 'C', 0.7254081, 'Não via, não via porque eles me afogavam, eles estavam me afogando com água e botando pano na minha cara.', 694558, 700578, 0.7254081, 20, 0);
INSERT INTO speaker_segments (id, transcricao_id, speaker, speaker_confidence, text, start_time, end_time, confidence, words_count, channel) VALUES (1624, 31, 'F', 0.6679251, 'Afogaram onde?', 700578, 701518, 0.6679251, 2, 0);
INSERT INTO speaker_segments (id, transcricao_id, speaker, speaker_confidence, text, start_time, end_time, confidence, words_count, channel) VALUES (1625, 31, 'B', 0.5681553, 'Na camisa.', 701518, 703818, 0.5681553, 2, 0);
INSERT INTO speaker_segments (id, transcricao_id, speaker, speaker_confidence, text, start_time, end_time, confidence, words_count, channel) VALUES (1626, 31, 'F', 0.8741045, 'Aonde isso?', 703818, 706038, 0.8741045, 2, 0);
INSERT INTO speaker_segments (id, transcricao_id, speaker, speaker_confidence, text, start_time, end_time, confidence, words_count, channel) VALUES (1627, 31, 'C', 0.8736531, 'Na casa da minha irmã.', 706038, 707858, 0.8736531, 5, 0);
INSERT INTO speaker_segments (id, transcricao_id, speaker, speaker_confidence, text, start_time, end_time, confidence, words_count, channel) VALUES (1628, 31, 'F', 0.6733156, 'Foi dentro, eles entraram na tua casa?', 707858, 709798, 0.6733156, 7, 0);
INSERT INTO speaker_segments (id, transcricao_id, speaker, speaker_confidence, text, start_time, end_time, confidence, words_count, channel) VALUES (1629, 31, 'C', 0.8884495, 'Dentro da casa, na frente das crianças.', 709798, 712658, 0.8884495, 7, 0);
INSERT INTO speaker_segments (id, transcricao_id, speaker, speaker_confidence, text, start_time, end_time, confidence, words_count, channel) VALUES (1630, 31, 'F', 0.82803386, 'Alguém viu, alguém filmou? O senhor registrou isso?', 712658, 717018, 0.82803386, 8, 0);
INSERT INTO speaker_segments (id, transcricao_id, speaker, speaker_confidence, text, start_time, end_time, confidence, words_count, channel) VALUES (1631, 31, 'C', 0.7774581, 'Eu não sei se a minha irmã já vai registrar, mas ela viu. Isso foi de manhã cedo, umas oito e meia da manhã.', 718107, 727947, 0.7774581, 24, 0);
INSERT INTO speaker_segments (id, transcricao_id, speaker, speaker_confidence, text, start_time, end_time, confidence, words_count, channel) VALUES (1632, 31, 'B', 0.8415, 'Satisfeito, doutor.', 727947, 730907, 0.8415, 2, 0);
INSERT INTO speaker_segments (id, transcricao_id, speaker, speaker_confidence, text, start_time, end_time, confidence, words_count, channel) VALUES (1633, 31, 'C', 0.9115, 'Certo, doutor.', 730907, 734187, 0.9115, 2, 0);
INSERT INTO speaker_segments (id, transcricao_id, speaker, speaker_confidence, text, start_time, end_time, confidence, words_count, channel) VALUES (1634, 31, 'D', 0.7872133, 'Doutor Márcio Rossano.', 734187, 738087, 0.7872133, 3, 0);
INSERT INTO speaker_segments (id, transcricao_id, speaker, speaker_confidence, text, start_time, end_time, confidence, words_count, channel) VALUES (1635, 31, 'F', 0.92025554, 'Sem perguntas, doutor Francisco.', 738087, 741507, 0.92025554, 4, 0);
INSERT INTO speaker_segments (id, transcricao_id, speaker, speaker_confidence, text, start_time, end_time, confidence, words_count, channel) VALUES (1636, 31, 'D', 0.8994798, 'Doutor Alfredo.', 741507, 743167, 0.8994798, 2, 0);
INSERT INTO speaker_segments (id, transcricao_id, speaker, speaker_confidence, text, start_time, end_time, confidence, words_count, channel) VALUES (1637, 31, 'C', 0.5951634, 'Sem perguntas, doutor.', 747487, 749347, 0.5951634, 3, 0);
INSERT INTO speaker_segments (id, transcricao_id, speaker, speaker_confidence, text, start_time, end_time, confidence, words_count, channel) VALUES (1638, 31, 'D', 0.66517645, 'A doutora Paloma?', 749347, 751767, 0.66517645, 3, 0);
INSERT INTO speaker_segments (id, transcricao_id, speaker, speaker_confidence, text, start_time, end_time, confidence, words_count, channel) VALUES (1639, 31, 'B', 0.8847656, 'Sem perguntas.', 751767, 754287, 0.8847656, 2, 0);
INSERT INTO speaker_segments (id, transcricao_id, speaker, speaker_confidence, text, start_time, end_time, confidence, words_count, channel) VALUES (1640, 31, 'D', 0.82061243, 'Não ficou nenhum advogado de fora?', 754287, 757167, 0.82061243, 6, 0);
INSERT INTO speaker_segments (id, transcricao_id, speaker, speaker_confidence, text, start_time, end_time, confidence, words_count, channel) VALUES (1641, 31, 'B', 0.439, 'Ok.', 757167, 759807, 0.439, 1, 0);
INSERT INTO speaker_segments (id, transcricao_id, speaker, speaker_confidence, text, start_time, end_time, confidence, words_count, channel) VALUES (1642, 31, 'D', 0.8296425, 'Está liberado, então, a testemunha. O Douglas pode deixar a sala. Obrigado pela colaboração da Suzette.', 759807, 768327, 0.8296425, 16, 0);
INSERT INTO speaker_segments (id, transcricao_id, speaker, speaker_confidence, text, start_time, end_time, confidence, words_count, channel) VALUES (1643, 31, 'C', 0.80823046, 'Muito obrigado.', 768327, 771647, 0.80823046, 2, 0);
INSERT INTO speaker_segments (id, transcricao_id, speaker, speaker_confidence, text, start_time, end_time, confidence, words_count, channel) VALUES (1644, 33, 'A', 0.75352925, 'Douglas, tu me diz o teu nome completo.', 42, 4322, 0.75352925, 8, 0);
INSERT INTO speaker_segments (id, transcricao_id, speaker, speaker_confidence, text, start_time, end_time, confidence, words_count, channel) VALUES (1645, 33, 'B', 0.726, 'Nome?', 4322, 7322, 0.726, 1, 0);
INSERT INTO speaker_segments (id, transcricao_id, speaker, speaker_confidence, text, start_time, end_time, confidence, words_count, channel) VALUES (1646, 33, 'A', 0.7632965, 'Tu me diz o teu nome completo, por favor.', 8442, 11442, 0.7632965, 9, 0);
INSERT INTO speaker_segments (id, transcricao_id, speaker, speaker_confidence, text, start_time, end_time, confidence, words_count, channel) VALUES (1647, 33, 'C', 0.886487, 'Douglas Oliveira Mafalda.', 11442, 13982, 0.886487, 3, 0);
INSERT INTO speaker_segments (id, transcricao_id, speaker, speaker_confidence, text, start_time, end_time, confidence, words_count, channel) VALUES (1648, 33, 'A', 0.81675136, 'Tu me diz a tua filiação, o nome dos teus pais.', 13982, 19502, 0.81675136, 11, 0);
INSERT INTO speaker_segments (id, transcricao_id, speaker, speaker_confidence, text, start_time, end_time, confidence, words_count, channel) VALUES (1649, 33, 'C', 0.7998016, 'José Leomar de Oliveira Mafalda e Eliane Silva de Oliveira.', 19502, 23962, 0.7998016, 10, 0);
INSERT INTO speaker_segments (id, transcricao_id, speaker, speaker_confidence, text, start_time, end_time, confidence, words_count, channel) VALUES (1650, 33, 'A', 0.78990275, 'E qual é o princípio que tu está aí?', 23962, 26982, 0.78990275, 9, 0);
INSERT INTO speaker_segments (id, transcricao_id, speaker, speaker_confidence, text, start_time, end_time, confidence, words_count, channel) VALUES (1651, 33, 'C', 0.43456835, 'Não entendi.', 29945, 31005, 0.43456835, 2, 0);
INSERT INTO speaker_segments (id, transcricao_id, speaker, speaker_confidence, text, start_time, end_time, confidence, words_count, channel) VALUES (1652, 33, 'A', 0.698109, 'Tu tá preso em qual presídio?', 31005, 34025, 0.698109, 6, 0);
INSERT INTO speaker_segments (id, transcricao_id, speaker, speaker_confidence, text, start_time, end_time, confidence, words_count, channel) VALUES (1653, 33, 'C', 0.70301366, 'Tô na APK.', 34025, 35345, 0.70301366, 3, 0);
INSERT INTO speaker_segments (id, transcricao_id, speaker, speaker_confidence, text, start_time, end_time, confidence, words_count, channel) VALUES (1654, 33, 'A', 0.67789453, 'Na APK.', 35345, 37085, 0.67789453, 2, 0);
INSERT INTO speaker_segments (id, transcricao_id, speaker, speaker_confidence, text, start_time, end_time, confidence, words_count, channel) VALUES (1655, 33, 'B', 0.89524025, 'Tá certo.', 37085, 39445, 0.89524025, 2, 0);
INSERT INTO speaker_segments (id, transcricao_id, speaker, speaker_confidence, text, start_time, end_time, confidence, words_count, channel) VALUES (1656, 33, 'D', 0.479, 'Ok.', 39445, 40885, 0.479, 1, 0);
INSERT INTO speaker_segments (id, transcricao_id, speaker, speaker_confidence, text, start_time, end_time, confidence, words_count, channel) VALUES (1657, 33, 'A', 0.8647018, 'Aqui sim, doutor.', 40885, 43645, 0.8647018, 3, 0);
INSERT INTO speaker_segments (id, transcricao_id, speaker, speaker_confidence, text, start_time, end_time, confidence, words_count, channel) VALUES (1658, 33, 'D', 0.71908075, 'Boa tarde, Douglas.', 43645, 45565, 0.71908075, 3, 0);
INSERT INTO speaker_segments (id, transcricao_id, speaker, speaker_confidence, text, start_time, end_time, confidence, words_count, channel) VALUES (1659, 33, 'C', 0.71542776, 'Boa tarde.', 45565, 46285, 0.71542776, 2, 0);
INSERT INTO speaker_segments (id, transcricao_id, speaker, speaker_confidence, text, start_time, end_time, confidence, words_count, channel) VALUES (1660, 33, 'D', 0.79165494, 'Douglas, o senhor vai ser ouvido sobre o fato número 5º da denúncia, ok? Eu vou fazer a leitura do fato para ver se o senhor se recorda, porque já faz algum tempo. No dia 22 de outubro de 2019, por volta das 22h30, na Rua Lago Azul, número 248, no bairro Santa Bárbara, cidade de Alvorada, os soldados Josimar da Silva Pereira, Felipe Ferreira Janiquim e Mateus Arcenes de Voraes, em comunhão de resposta e condição de vontade, todos de serviço pilotado no vigésimo quarto PTM, apropriaram-se de valores que tinham força e razão da função apreendido durante a ocorrência policial registrada sob o número 100-464-2019-14700, relativa aos crimes de tráfego de entorpecentes e porte legal de arma. Na oportunidade, os denunciados prenderam Douglas de Oliveira Mafalda e Rafael de Cidade Barbosa por tráfico de estropecentes e porte ilegal de arma, aprendendo, dentre outros materiais, dois coletes balísticos, uma pistola calibre .380, um revólver calibre .38, um revólver calibre .32 e uma espigada calibre .12. também 2.289 gramas de cocaína, 79 gramas de maconha e, ao menos, um grama de crack. E R$331 em dinheiro.', 47967, 142062, 0.79165494, 186, 0);
INSERT INTO speaker_segments (id, transcricao_id, speaker, speaker_confidence, text, start_time, end_time, confidence, words_count, channel) VALUES (1661, 33, 'A', 0.614, 'Pergunta.', 142062, 145062, 0.614, 1, 0);
INSERT INTO speaker_segments (id, transcricao_id, speaker, speaker_confidence, text, start_time, end_time, confidence, words_count, channel) VALUES (1662, 33, 'D', 0.806027, 'Douglas, sobre essa ocorrência, o que o senhor tem a nos dizer?', 149702, 154242, 0.806027, 12, 0);
INSERT INTO speaker_segments (id, transcricao_id, speaker, speaker_confidence, text, start_time, end_time, confidence, words_count, channel) VALUES (1663, 33, 'A', 0.377903, 'E aí e o problema do tornozelo né é alguma coisa aconteceu e tá.', 157115, 168995, 0.377903, 14, 0);
INSERT INTO speaker_segments (id, transcricao_id, speaker, speaker_confidence, text, start_time, end_time, confidence, words_count, channel) VALUES (1664, 33, 'B', 0.4907401, 'Voltou a normal E aí E aí.', 168995, 177445, 0.4907401, 7, 0);
INSERT INTO speaker_segments (id, transcricao_id, speaker, speaker_confidence, text, start_time, end_time, confidence, words_count, channel) VALUES (1665, 33, 'D', 0.5180132, 'O Bernadete põe ele na tela principal.', 177445, 179135, 0.5180132, 7, 0);
INSERT INTO speaker_segments (id, transcricao_id, speaker, speaker_confidence, text, start_time, end_time, confidence, words_count, channel) VALUES (1666, 33, 'A', 0.519529, 'E ele tá na tela doutor tá.', 179135, 184475, 0.519529, 7, 0);
INSERT INTO speaker_segments (id, transcricao_id, speaker, speaker_confidence, text, start_time, end_time, confidence, words_count, channel) VALUES (1667, 33, 'C', 0.62781566, 'Mas dá na principal, que eu não estou vendo.', 184475, 190122, 0.62781566, 9, 0);
INSERT INTO speaker_segments (id, transcricao_id, speaker, speaker_confidence, text, start_time, end_time, confidence, words_count, channel) VALUES (1668, 33, 'A', 0.62438333, 'Aqui a gente está.', 193302, 196082, 0.62438333, 4, 0);
INSERT INTO speaker_segments (id, transcricao_id, speaker, speaker_confidence, text, start_time, end_time, confidence, words_count, channel) VALUES (1669, 33, 'D', 0.8230529, 'Douglas, ouviu sobre essa ocorrência?', 196082, 201222, 0.8230529, 5, 0);
INSERT INTO speaker_segments (id, transcricao_id, speaker, speaker_confidence, text, start_time, end_time, confidence, words_count, channel) VALUES (1670, 33, 'C', 0.7735, 'Escutei, escutei.', 201222, 203082, 0.7735, 2, 0);
INSERT INTO speaker_segments (id, transcricao_id, speaker, speaker_confidence, text, start_time, end_time, confidence, words_count, channel) VALUES (1671, 33, 'D', 0.81704307, '22 de outubro de 2019, o senhor foi preso, junto com o Rafael, por porte ilegal de drogas e arma. Sobre esse fato, o que o senhor pode nos dizer sobre isso?', 203082, 218612, 0.81704307, 32, 0);
INSERT INTO speaker_segments (id, transcricao_id, speaker, speaker_confidence, text, start_time, end_time, confidence, words_count, channel) VALUES (1672, 33, 'C', 0.68094903, 'Não tenho nada a dizer sobre isso.', 218612, 222132, 0.68094903, 7, 0);
INSERT INTO speaker_segments (id, transcricao_id, speaker, speaker_confidence, text, start_time, end_time, confidence, words_count, channel) VALUES (1673, 33, 'D', 0.79700947, 'O senhor estava na posse de entorpecente e armas?', 222132, 226592, 0.79700947, 9, 0);
INSERT INTO speaker_segments (id, transcricao_id, speaker, speaker_confidence, text, start_time, end_time, confidence, words_count, channel) VALUES (1674, 33, 'C', 0.7912666, 'Estava na posse, estava.', 226592, 229692, 0.7912666, 4, 0);
INSERT INTO speaker_segments (id, transcricao_id, speaker, speaker_confidence, text, start_time, end_time, confidence, words_count, channel) VALUES (1675, 33, 'D', 0.7679148, 'E o senhor se recorda de quantas armas o senhor tinha?', 229692, 236392, 0.7679148, 11, 0);
INSERT INTO speaker_segments (id, transcricao_id, speaker, speaker_confidence, text, start_time, end_time, confidence, words_count, channel) VALUES (1676, 33, 'C', 0.70098877, 'Claro, não me lembro.', 236392, 238532, 0.70098877, 4, 0);
INSERT INTO speaker_segments (id, transcricao_id, speaker, speaker_confidence, text, start_time, end_time, confidence, words_count, channel) VALUES (1677, 33, 'D', 0.9268195, 'E a quantidade de drogas?', 238532, 240612, 0.9268195, 5, 0);
INSERT INTO speaker_segments (id, transcricao_id, speaker, speaker_confidence, text, start_time, end_time, confidence, words_count, channel) VALUES (1678, 33, 'C', 0.6927886, 'Também não sei, não era eu que vendia.', 241996, 244876, 0.6927886, 8, 0);
INSERT INTO speaker_segments (id, transcricao_id, speaker, speaker_confidence, text, start_time, end_time, confidence, words_count, channel) VALUES (1679, 33, 'D', 0.76619697, 'Valores em dinheiro, o senhor saberia dizer quanto de dinheiro o senhor tinha nessa oportunidade, junto com o Rafael?', 244876, 255336, 0.76619697, 19, 0);
INSERT INTO speaker_segments (id, transcricao_id, speaker, speaker_confidence, text, start_time, end_time, confidence, words_count, channel) VALUES (1680, 33, 'C', 0.773043, 'Não sei.', 255336, 257456, 0.773043, 2, 0);
INSERT INTO speaker_segments (id, transcricao_id, speaker, speaker_confidence, text, start_time, end_time, confidence, words_count, channel) VALUES (1681, 33, 'D', 0.80529785, 'Não se recorda? Não. Durante essa ocorrência, o senhor chegou a notar se algum policial pegou algum dinheiro para ele?', 257456, 266216, 0.80529785, 20, 0);
INSERT INTO speaker_segments (id, transcricao_id, speaker, speaker_confidence, text, start_time, end_time, confidence, words_count, channel) VALUES (1682, 33, 'B', 0.919, 'Ouviu, Douglas?', 272472, 276872, 0.919, 2, 0);
INSERT INTO speaker_segments (id, transcricao_id, speaker, speaker_confidence, text, start_time, end_time, confidence, words_count, channel) VALUES (1683, 33, 'C', 0.849, 'Douglas.', 276872, 279872, 0.849, 1, 0);
INSERT INTO speaker_segments (id, transcricao_id, speaker, speaker_confidence, text, start_time, end_time, confidence, words_count, channel) VALUES (1684, 33, 'D', 0.82240105, 'Está me ouvindo?', 281672, 284852, 0.82240105, 3, 0);
INSERT INTO speaker_segments (id, transcricao_id, speaker, speaker_confidence, text, start_time, end_time, confidence, words_count, channel) VALUES (1685, 33, 'B', 0.73709244, 'De novo deu.', 286132, 290772, 0.73709244, 3, 0);
INSERT INTO speaker_segments (id, transcricao_id, speaker, speaker_confidence, text, start_time, end_time, confidence, words_count, channel) VALUES (1686, 33, 'A', 0.79088366, 'Ele continua aqui na tela, doutor, PK Douglas. Douglas, você está nos ouvindo? Porque ele não caiu, ele está aqui no… Vamos ver, espera aí. Agora caiu, estou colocando ele de novo.', 290772, 317713, 0.79088366, 32, 0);
INSERT INTO speaker_segments (id, transcricao_id, speaker, speaker_confidence, text, start_time, end_time, confidence, words_count, channel) VALUES (1687, 33, 'B', 0.31982422, 'Você.', 317713, 320713, 0.31982422, 1, 0);
INSERT INTO speaker_segments (id, transcricao_id, speaker, speaker_confidence, text, start_time, end_time, confidence, words_count, channel) VALUES (1688, 33, 'A', 0.679965, 'Está saindo da APK que está… Coloca o Diogo de novo. Coloca o Douglas de novo.', 328033, 336490, 0.679965, 16, 0);
INSERT INTO speaker_segments (id, transcricao_id, speaker, speaker_confidence, text, start_time, end_time, confidence, words_count, channel) VALUES (1689, 33, 'C', 0.67762816, 'Tá, só um momento que eu tô configurando aqui.', 336490, 339010, 0.67762816, 9, 0);
INSERT INTO speaker_segments (id, transcricao_id, speaker, speaker_confidence, text, start_time, end_time, confidence, words_count, channel) VALUES (1690, 33, 'B', 0.8497435, 'Tá certo. Pronto.', 339010, 347070, 0.8497435, 3, 0);
INSERT INTO speaker_segments (id, transcricao_id, speaker, speaker_confidence, text, start_time, end_time, confidence, words_count, channel) VALUES (1691, 33, 'A', 0.7671834, 'Doutor, ele tá de volta.', 356650, 359050, 0.7671834, 5, 0);
INSERT INTO speaker_segments (id, transcricao_id, speaker, speaker_confidence, text, start_time, end_time, confidence, words_count, channel) VALUES (1692, 33, 'D', 0.729, 'Douglas!', 359050, 362050, 0.729, 1, 0);
INSERT INTO speaker_segments (id, transcricao_id, speaker, speaker_confidence, text, start_time, end_time, confidence, words_count, channel) VALUES (1693, 33, 'B', 0.834, 'Opa!', 362630, 363610, 0.834, 1, 0);
INSERT INTO speaker_segments (id, transcricao_id, speaker, speaker_confidence, text, start_time, end_time, confidence, words_count, channel) VALUES (1694, 33, 'D', 0.71159005, 'Durante essa ocorrência, o senhor chegou a notar se algum policial tinha pego o dinheiro que estava na posse de vocês? Acho que foi agora. Mas não tem certeza.', 364154, 379014, 0.71159005, 29, 0);
INSERT INTO speaker_segments (id, transcricao_id, speaker, speaker_confidence, text, start_time, end_time, confidence, words_count, channel) VALUES (1695, 33, 'B', 0.62228644, 'É, não tem certeza.', 379014, 382494, 0.62228644, 4, 0);
INSERT INTO speaker_segments (id, transcricao_id, speaker, speaker_confidence, text, start_time, end_time, confidence, words_count, channel) VALUES (1696, 33, 'D', 0.7664448, 'E como eu já tinha lhe perguntado quantidade de droga, quantidade de dinheiro e quantidade de arma, o senhor não se lembra.', 382994, 390634, 0.7664448, 22, 0);
INSERT INTO speaker_segments (id, transcricao_id, speaker, speaker_confidence, text, start_time, end_time, confidence, words_count, channel) VALUES (1697, 33, 'C', 0.69259316, 'Não me lembro porque eles não pegaram nada com nós, os sojuíras. Eles chegaram em outra residência.', 391643, 397823, 0.69259316, 17, 0);
INSERT INTO speaker_segments (id, transcricao_id, speaker, speaker_confidence, text, start_time, end_time, confidence, words_count, channel) VALUES (1698, 33, 'D', 0.7877884, 'E isso não estava com vocês?', 397823, 400243, 0.7877884, 6, 0);
INSERT INTO speaker_segments (id, transcricao_id, speaker, speaker_confidence, text, start_time, end_time, confidence, words_count, channel) VALUES (1699, 33, 'C', 0.78967446, 'Não, não estava com nós. Eles pegaram em outra residência e daí botaram em nós.', 400243, 405563, 0.78967446, 15, 0);
INSERT INTO speaker_segments (id, transcricao_id, speaker, speaker_confidence, text, start_time, end_time, confidence, words_count, channel) VALUES (1700, 33, 'D', 0.78441405, 'E você estava perto dessa residência?', 405563, 408923, 0.78441405, 6, 0);
INSERT INTO speaker_segments (id, transcricao_id, speaker, speaker_confidence, text, start_time, end_time, confidence, words_count, channel) VALUES (1701, 33, 'C', 0.70424235, 'Ah, no caso, eu moro umas duas quartas dessa residência. Tá.', 408923, 413403, 0.70424235, 11, 0);
INSERT INTO speaker_segments (id, transcricao_id, speaker, speaker_confidence, text, start_time, end_time, confidence, words_count, channel) VALUES (1702, 33, 'D', 0.8431563, 'E o senhor está preso por tráfico?', 413403, 415743, 0.8431563, 7, 0);
INSERT INTO speaker_segments (id, transcricao_id, speaker, speaker_confidence, text, start_time, end_time, confidence, words_count, channel) VALUES (1703, 33, 'C', 0.69946146, 'Agora eu estou preso por tráfico? Poxa, eu fiquei quatro dias na rua só. Tá iniciado de novo.', 415743, 424297, 0.69946146, 18, 0);
INSERT INTO speaker_segments (id, transcricao_id, speaker, speaker_confidence, text, start_time, end_time, confidence, words_count, channel) VALUES (1704, 33, 'D', 0.69945425, 'Tá certo. Palavra ao conselho, Capitão Marcelo.', 424297, 428797, 0.69945425, 7, 0);
INSERT INTO speaker_segments (id, transcricao_id, speaker, speaker_confidence, text, start_time, end_time, confidence, words_count, channel) VALUES (1705, 33, 'B', 0.7757904, 'Sem perguntas, Excelência.', 428797, 433337, 0.7757904, 3, 0);
INSERT INTO speaker_segments (id, transcricao_id, speaker, speaker_confidence, text, start_time, end_time, confidence, words_count, channel) VALUES (1706, 33, 'D', 0.69968057, 'Ao Capitão Koniki.', 433337, 435937, 0.69968057, 3, 0);
INSERT INTO speaker_segments (id, transcricao_id, speaker, speaker_confidence, text, start_time, end_time, confidence, words_count, channel) VALUES (1707, 33, 'C', 0.78916794, 'Sem perguntas.', 435937, 436777, 0.78916794, 2, 0);
INSERT INTO speaker_segments (id, transcricao_id, speaker, speaker_confidence, text, start_time, end_time, confidence, words_count, channel) VALUES (1708, 33, 'D', 0.8342305, 'Ministério Público.', 436777, 441077, 0.8342305, 2, 0);
INSERT INTO speaker_segments (id, transcricao_id, speaker, speaker_confidence, text, start_time, end_time, confidence, words_count, channel) VALUES (1709, 33, 'E', 0.78305614, 'Boa tarde. Exatamente o que aconteceu nesse dia, Douglas? O senhor conheceu os policiais militares?', 441077, 449757, 0.78305614, 15, 0);
INSERT INTO speaker_segments (id, transcricao_id, speaker, speaker_confidence, text, start_time, end_time, confidence, words_count, channel) VALUES (1710, 33, 'C', 0.7280621, 'No caso, eu estava sem medir o meio para levar meus primos para o colégio e tomei uma abordagem da polícia. Nisso eu tomei uma abordagem. Eles tinham abordado outro guri que morava em frente da minha casa e estava saindo para trabalhar. Eles queriam saber de droga, de arma. A gente, sabe, falava... Falava que a gente não sabia de nada e eles começaram a bater na gente e me enxertaram mais com as drogas. Falaram que se a gente não falasse nada, eles enxertariam mais e levariam mais primos.', 452596, 481096, 0.7280621, 91, 0);
INSERT INTO speaker_segments (id, transcricao_id, speaker, speaker_confidence, text, start_time, end_time, confidence, words_count, channel) VALUES (1711, 33, 'E', 0.7521145, 'Você já conhecia os policiais?', 482785, 485525, 0.7521145, 5, 0);
INSERT INTO speaker_segments (id, transcricao_id, speaker, speaker_confidence, text, start_time, end_time, confidence, words_count, channel) VALUES (1712, 33, 'C', 0.66991013, 'Não, não conhecia.', 485525, 488065, 0.66991013, 3, 0);
INSERT INTO speaker_segments (id, transcricao_id, speaker, speaker_confidence, text, start_time, end_time, confidence, words_count, channel) VALUES (1713, 33, 'E', 0.8003854, 'Nem de vista?', 488065, 490045, 0.8003854, 3, 0);
INSERT INTO speaker_segments (id, transcricao_id, speaker, speaker_confidence, text, start_time, end_time, confidence, words_count, channel) VALUES (1714, 33, 'C', 0.69729936, 'Não, nunca tinha visto.', 490045, 492665, 0.69729936, 4, 0);
INSERT INTO speaker_segments (id, transcricao_id, speaker, speaker_confidence, text, start_time, end_time, confidence, words_count, channel) VALUES (1715, 33, 'E', 0.72353125, 'Eles te exigiram algum dinheiro, algo? Para não fazer isso?', 492665, 498105, 0.72353125, 10, 0);
INSERT INTO speaker_segments (id, transcricao_id, speaker, speaker_confidence, text, start_time, end_time, confidence, words_count, channel) VALUES (1716, 33, 'C', 0.8508152, 'Não, não pediram nada.', 498105, 501085, 0.8508152, 4, 0);
INSERT INTO speaker_segments (id, transcricao_id, speaker, speaker_confidence, text, start_time, end_time, confidence, words_count, channel) VALUES (1717, 33, 'E', 0.79725605, 'Você estava acompanhado de quem nesse momento?', 501085, 504685, 0.79725605, 7, 0);
INSERT INTO speaker_segments (id, transcricao_id, speaker, speaker_confidence, text, start_time, end_time, confidence, words_count, channel) VALUES (1718, 33, 'C', 0.88972265, 'Acompanhada da minha irmã.', 504685, 506465, 0.88972265, 4, 0);
INSERT INTO speaker_segments (id, transcricao_id, speaker, speaker_confidence, text, start_time, end_time, confidence, words_count, channel) VALUES (1719, 33, 'E', 0.8079838, 'Como é que é o nome dela?', 506465, 508225, 0.8079838, 7, 0);
INSERT INTO speaker_segments (id, transcricao_id, speaker, speaker_confidence, text, start_time, end_time, confidence, words_count, channel) VALUES (1720, 33, 'C', 0.904, 'Cristiane.', 508225, 510085, 0.904, 1, 0);
INSERT INTO speaker_segments (id, transcricao_id, speaker, speaker_confidence, text, start_time, end_time, confidence, words_count, channel) VALUES (1721, 33, 'E', 0.8019225, 'Só ela estava contigo? Mais ninguém?', 510085, 512525, 0.8019225, 6, 0);
INSERT INTO speaker_segments (id, transcricao_id, speaker, speaker_confidence, text, start_time, end_time, confidence, words_count, channel) VALUES (1722, 33, 'C', 0.72663534, 'Estava só eu e as minhas crianças em casa.', 513160, 515340, 0.72663534, 9, 0);
INSERT INTO speaker_segments (id, transcricao_id, speaker, speaker_confidence, text, start_time, end_time, confidence, words_count, channel) VALUES (1723, 33, 'E', 0.72180855, 'E por que eles fizeram isso contigo? Tu afirma que não conhecia eles, que.', 515340, 524360, 0.72180855, 14, 0);
INSERT INTO speaker_segments (id, transcricao_id, speaker, speaker_confidence, text, start_time, end_time, confidence, words_count, channel) VALUES (1724, 33, 'C', 0.7487738, 'Não foi exigido... Nada, eu já não sei. Não tenho o que dizer.', 524360, 533140, 0.7487738, 13, 0);
INSERT INTO speaker_segments (id, transcricao_id, speaker, speaker_confidence, text, start_time, end_time, confidence, words_count, channel) VALUES (1725, 33, 'E', 0.8020814, 'Tu está preso por esse fato?', 533140, 536780, 0.8020814, 6, 0);
INSERT INTO speaker_segments (id, transcricao_id, speaker, speaker_confidence, text, start_time, end_time, confidence, words_count, channel) VALUES (1726, 33, 'C', 0.7264756, 'Não, no caso desse fato, eu fui embora e voltei de novo para uma outra pronta.', 536780, 542060, 0.7264756, 16, 0);
INSERT INTO speaker_segments (id, transcricao_id, speaker, speaker_confidence, text, start_time, end_time, confidence, words_count, channel) VALUES (1727, 33, 'E', 0.7795394, 'Além de droga, arma, teve alguma questão envolvendo arma em relação a esse fato que o juiz questionou para ti?', 543738, 554478, 0.7795394, 20, 0);
INSERT INTO speaker_segments (id, transcricao_id, speaker, speaker_confidence, text, start_time, end_time, confidence, words_count, channel) VALUES (1728, 33, 'C', 0.8512734, 'Não entendi.', 554478, 555998, 0.8512734, 2, 0);
INSERT INTO speaker_segments (id, transcricao_id, speaker, speaker_confidence, text, start_time, end_time, confidence, words_count, channel) VALUES (1729, 33, 'E', 0.6748876, 'Em relação a arma, tem alguma coisa de enxertar um arma também ou não?', 555998, 561438, 0.6748876, 14, 0);
INSERT INTO speaker_segments (id, transcricao_id, speaker, speaker_confidence, text, start_time, end_time, confidence, words_count, channel) VALUES (1730, 33, 'C', 0.5796897, 'Podemos enxertar também um revólver.', 561438, 564758, 0.5796897, 5, 0);
INSERT INTO speaker_segments (id, transcricao_id, speaker, speaker_confidence, text, start_time, end_time, confidence, words_count, channel) VALUES (1731, 33, 'E', 0.8969453, 'Qual revólver?', 564758, 566798, 0.8969453, 2, 0);
INSERT INTO speaker_segments (id, transcricao_id, speaker, speaker_confidence, text, start_time, end_time, confidence, words_count, channel) VALUES (1732, 33, 'C', 0.66213214, 'Calibre 38.', 566798, 569718, 0.66213214, 2, 0);
INSERT INTO speaker_segments (id, transcricao_id, speaker, speaker_confidence, text, start_time, end_time, confidence, words_count, channel) VALUES (1733, 33, 'E', 0.8207299, 'E como é que foi esse enxerto?', 569718, 572178, 0.8207299, 7, 0);
INSERT INTO speaker_segments (id, transcricao_id, speaker, speaker_confidence, text, start_time, end_time, confidence, words_count, channel) VALUES (1734, 33, 'C', 0.66026735, 'Na hora da abordagem.', 573505, 575965, 0.66026735, 4, 0);
INSERT INTO speaker_segments (id, transcricao_id, speaker, speaker_confidence, text, start_time, end_time, confidence, words_count, channel) VALUES (1735, 33, 'E', 0.76930076, 'O que eles falaram?', 575965, 579205, 0.76930076, 4, 0);
INSERT INTO speaker_segments (id, transcricao_id, speaker, speaker_confidence, text, start_time, end_time, confidence, words_count, channel) VALUES (1736, 33, 'C', 0.74619275, 'Eles falaram que se a gente não falasse nada, eles iam chutar nós. Iam botar droga, arma e iam botar nós na cadeira.', 579205, 588105, 0.74619275, 23, 0);
INSERT INTO speaker_segments (id, transcricao_id, speaker, speaker_confidence, text, start_time, end_time, confidence, words_count, channel) VALUES (1737, 33, 'E', 0.6953336, 'Tu tem vínculo com alguma facção?', 589245, 592865, 0.6953336, 6, 0);
INSERT INTO speaker_segments (id, transcricao_id, speaker, speaker_confidence, text, start_time, end_time, confidence, words_count, channel) VALUES (1738, 33, 'C', 0.873, 'Não, não.', 592865, 594665, 0.873, 2, 0);
INSERT INTO speaker_segments (id, transcricao_id, speaker, speaker_confidence, text, start_time, end_time, confidence, words_count, channel) VALUES (1739, 33, 'E', 0.77933985, 'Nada mais.', 594665, 597225, 0.77933985, 2, 0);
INSERT INTO speaker_segments (id, transcricao_id, speaker, speaker_confidence, text, start_time, end_time, confidence, words_count, channel) VALUES (1740, 33, 'D', 0.73941714, 'Doutora Edna, pelo soldado Josimar.', 597225, 601205, 0.73941714, 5, 0);
INSERT INTO speaker_segments (id, transcricao_id, speaker, speaker_confidence, text, start_time, end_time, confidence, words_count, channel) VALUES (1741, 33, 'B', 0.57749087, 'Nada, em silêncio.', 604302, 606462, 0.57749087, 3, 0);
INSERT INTO speaker_segments (id, transcricao_id, speaker, speaker_confidence, text, start_time, end_time, confidence, words_count, channel) VALUES (1742, 33, 'D', 0.7052441, 'A doutora Ciomara pelo soldado Felipe.', 606462, 609702, 0.7052441, 6, 0);
INSERT INTO speaker_segments (id, transcricao_id, speaker, speaker_confidence, text, start_time, end_time, confidence, words_count, channel) VALUES (1743, 33, 'B', 0.86127216, 'Nada, em silêncio.', 609702, 612302, 0.86127216, 3, 0);
INSERT INTO speaker_segments (id, transcricao_id, speaker, speaker_confidence, text, start_time, end_time, confidence, words_count, channel) VALUES (1744, 33, 'D', 0.8705577, 'Pelo soldado Mateus, doutor Márcio Barcelos.', 612302, 616602, 0.8705577, 6, 0);
INSERT INTO speaker_segments (id, transcricao_id, speaker, speaker_confidence, text, start_time, end_time, confidence, words_count, channel) VALUES (1745, 33, 'F', 0.74845076, 'Sim, doutor. Só para confirmar com ele, se o Mateus Alicênio, ele lembra do Mateus nessa data, presente no fato da abordagem?', 616602, 626802, 0.74845076, 22, 0);
INSERT INTO speaker_segments (id, transcricao_id, speaker, speaker_confidence, text, start_time, end_time, confidence, words_count, channel) VALUES (1746, 33, 'B', 0.7406413, 'Eu não entendi.', 626802, 629762, 0.7406413, 3, 0);
INSERT INTO speaker_segments (id, transcricao_id, speaker, speaker_confidence, text, start_time, end_time, confidence, words_count, channel) VALUES (1747, 33, 'F', 0.7200159, 'Se ele lembra os policiais que abordaram ele, especialmente no meu caso, o Mateus Arsene.', 631505, 636805, 0.7200159, 15, 0);
INSERT INTO speaker_segments (id, transcricao_id, speaker, speaker_confidence, text, start_time, end_time, confidence, words_count, channel) VALUES (1748, 33, 'D', 0.80663544, 'O senhor lembra quem foram os policiais que lhe abordaram?', 636805, 641285, 0.80663544, 10, 0);
INSERT INTO speaker_segments (id, transcricao_id, speaker, speaker_confidence, text, start_time, end_time, confidence, words_count, channel) VALUES (1749, 33, 'C', 0.78309196, 'Ah, se eu olhar pelo rosto até lembro, mas pelo nome eu não lembro.', 641285, 648185, 0.78309196, 14, 0);
INSERT INTO speaker_segments (id, transcricao_id, speaker, speaker_confidence, text, start_time, end_time, confidence, words_count, channel) VALUES (1750, 33, 'F', 0.81894606, 'Chegaram a te convidar para fazer a cariação no inquérito?', 650065, 654765, 0.81894606, 10, 0);
INSERT INTO speaker_segments (id, transcricao_id, speaker, speaker_confidence, text, start_time, end_time, confidence, words_count, channel) VALUES (1751, 33, 'C', 0.77893084, 'Vocês chegaram a me bater?', 654765, 657045, 0.77893084, 5, 0);
INSERT INTO speaker_segments (id, transcricao_id, speaker, speaker_confidence, text, start_time, end_time, confidence, words_count, channel) VALUES (1752, 33, 'F', 0.774598, 'Não, fazer a cariação para te reconhecer os policiais.', 657045, 659525, 0.774598, 9, 0);
INSERT INTO speaker_segments (id, transcricao_id, speaker, speaker_confidence, text, start_time, end_time, confidence, words_count, channel) VALUES (1753, 33, 'C', 0.6902643, 'Não, não fizeram. Isso eu vi só em uma audiência na rua. Em uma audiência na rua eu vi isso.', 660293, 668073, 0.6902643, 20, 0);
INSERT INTO speaker_segments (id, transcricao_id, speaker, speaker_confidence, text, start_time, end_time, confidence, words_count, channel) VALUES (1754, 33, 'B', 0.85796076, 'Chegou a ser agredido? Quase me mataram.', 668073, 677353, 0.85796076, 7, 0);
INSERT INTO speaker_segments (id, transcricao_id, speaker, speaker_confidence, text, start_time, end_time, confidence, words_count, channel) VALUES (1755, 33, 'F', 0.6855556, 'Tu reagiu ou só um apanhado de graça?', 677933, 682593, 0.6855556, 8, 0);
INSERT INTO speaker_segments (id, transcricao_id, speaker, speaker_confidence, text, start_time, end_time, confidence, words_count, channel) VALUES (1756, 33, 'C', 0.64039135, 'Eu reagi contra quatro, não tem condições. Os caras quase me mataram.', 682593, 686813, 0.64039135, 12, 0);
INSERT INTO speaker_segments (id, transcricao_id, speaker, speaker_confidence, text, start_time, end_time, confidence, words_count, channel) VALUES (1757, 33, 'F', 0.7464871, 'Tu não viu os nomes deles nas fardas no dia?', 690078, 694558, 0.7464871, 10, 0);
INSERT INTO speaker_segments (id, transcricao_id, speaker, speaker_confidence, text, start_time, end_time, confidence, words_count, channel) VALUES (1758, 33, 'C', 0.7254081, 'Não via, não via porque eles me afogavam, eles estavam me afogando com água e botando pano na minha cara.', 694558, 700578, 0.7254081, 20, 0);
INSERT INTO speaker_segments (id, transcricao_id, speaker, speaker_confidence, text, start_time, end_time, confidence, words_count, channel) VALUES (1759, 33, 'F', 0.6679251, 'Afogaram onde?', 700578, 701518, 0.6679251, 2, 0);
INSERT INTO speaker_segments (id, transcricao_id, speaker, speaker_confidence, text, start_time, end_time, confidence, words_count, channel) VALUES (1760, 33, 'B', 0.5681553, 'Na camisa.', 701518, 703818, 0.5681553, 2, 0);
INSERT INTO speaker_segments (id, transcricao_id, speaker, speaker_confidence, text, start_time, end_time, confidence, words_count, channel) VALUES (1761, 33, 'F', 0.8741045, 'Aonde isso?', 703818, 706038, 0.8741045, 2, 0);
INSERT INTO speaker_segments (id, transcricao_id, speaker, speaker_confidence, text, start_time, end_time, confidence, words_count, channel) VALUES (1762, 33, 'C', 0.8736531, 'Na casa da minha irmã.', 706038, 707858, 0.8736531, 5, 0);
INSERT INTO speaker_segments (id, transcricao_id, speaker, speaker_confidence, text, start_time, end_time, confidence, words_count, channel) VALUES (1763, 33, 'F', 0.6733156, 'Foi dentro, eles entraram na tua casa?', 707858, 709798, 0.6733156, 7, 0);
INSERT INTO speaker_segments (id, transcricao_id, speaker, speaker_confidence, text, start_time, end_time, confidence, words_count, channel) VALUES (1764, 33, 'C', 0.8884495, 'Dentro da casa, na frente das crianças.', 709798, 712658, 0.8884495, 7, 0);
INSERT INTO speaker_segments (id, transcricao_id, speaker, speaker_confidence, text, start_time, end_time, confidence, words_count, channel) VALUES (1765, 33, 'F', 0.82803386, 'Alguém viu, alguém filmou? O senhor registrou isso?', 712658, 717018, 0.82803386, 8, 0);
INSERT INTO speaker_segments (id, transcricao_id, speaker, speaker_confidence, text, start_time, end_time, confidence, words_count, channel) VALUES (1766, 33, 'C', 0.7774581, 'Eu não sei se a minha irmã já vai registrar, mas ela viu. Isso foi de manhã cedo, umas oito e meia da manhã.', 718107, 727947, 0.7774581, 24, 0);
INSERT INTO speaker_segments (id, transcricao_id, speaker, speaker_confidence, text, start_time, end_time, confidence, words_count, channel) VALUES (1767, 33, 'B', 0.8415, 'Satisfeito, doutor.', 727947, 730907, 0.8415, 2, 0);
INSERT INTO speaker_segments (id, transcricao_id, speaker, speaker_confidence, text, start_time, end_time, confidence, words_count, channel) VALUES (1768, 33, 'C', 0.9115, 'Certo, doutor.', 730907, 734187, 0.9115, 2, 0);
INSERT INTO speaker_segments (id, transcricao_id, speaker, speaker_confidence, text, start_time, end_time, confidence, words_count, channel) VALUES (1769, 33, 'D', 0.7872133, 'Doutor Márcio Rossano.', 734187, 738087, 0.7872133, 3, 0);
INSERT INTO speaker_segments (id, transcricao_id, speaker, speaker_confidence, text, start_time, end_time, confidence, words_count, channel) VALUES (1770, 33, 'F', 0.92025554, 'Sem perguntas, doutor Francisco.', 738087, 741507, 0.92025554, 4, 0);
INSERT INTO speaker_segments (id, transcricao_id, speaker, speaker_confidence, text, start_time, end_time, confidence, words_count, channel) VALUES (1771, 33, 'D', 0.8994798, 'Doutor Alfredo.', 741507, 743167, 0.8994798, 2, 0);
INSERT INTO speaker_segments (id, transcricao_id, speaker, speaker_confidence, text, start_time, end_time, confidence, words_count, channel) VALUES (1772, 33, 'C', 0.5951634, 'Sem perguntas, doutor.', 747487, 749347, 0.5951634, 3, 0);
INSERT INTO speaker_segments (id, transcricao_id, speaker, speaker_confidence, text, start_time, end_time, confidence, words_count, channel) VALUES (1773, 33, 'D', 0.66517645, 'A doutora Paloma?', 749347, 751767, 0.66517645, 3, 0);
INSERT INTO speaker_segments (id, transcricao_id, speaker, speaker_confidence, text, start_time, end_time, confidence, words_count, channel) VALUES (1774, 33, 'B', 0.8847656, 'Sem perguntas.', 751767, 754287, 0.8847656, 2, 0);
INSERT INTO speaker_segments (id, transcricao_id, speaker, speaker_confidence, text, start_time, end_time, confidence, words_count, channel) VALUES (1775, 33, 'D', 0.82061243, 'Não ficou nenhum advogado de fora?', 754287, 757167, 0.82061243, 6, 0);
INSERT INTO speaker_segments (id, transcricao_id, speaker, speaker_confidence, text, start_time, end_time, confidence, words_count, channel) VALUES (1776, 33, 'B', 0.439, 'Ok.', 757167, 759807, 0.439, 1, 0);
INSERT INTO speaker_segments (id, transcricao_id, speaker, speaker_confidence, text, start_time, end_time, confidence, words_count, channel) VALUES (1777, 33, 'D', 0.8296425, 'Está liberado, então, a testemunha. O Douglas pode deixar a sala. Obrigado pela colaboração da Suzette.', 759807, 768327, 0.8296425, 16, 0);
INSERT INTO speaker_segments (id, transcricao_id, speaker, speaker_confidence, text, start_time, end_time, confidence, words_count, channel) VALUES (1778, 33, 'C', 0.80823046, 'Muito obrigado.', 768327, 771647, 0.80823046, 2, 0);
INSERT INTO speaker_segments (id, transcricao_id, speaker, speaker_confidence, text, start_time, end_time, confidence, words_count, channel) VALUES (1779, 35, 'A', 0.75352925, 'Douglas, tu me diz o teu nome completo.', 42, 4322, 0.75352925, 8, 0);
INSERT INTO speaker_segments (id, transcricao_id, speaker, speaker_confidence, text, start_time, end_time, confidence, words_count, channel) VALUES (1780, 35, 'B', 0.726, 'Nome?', 4322, 7322, 0.726, 1, 0);
INSERT INTO speaker_segments (id, transcricao_id, speaker, speaker_confidence, text, start_time, end_time, confidence, words_count, channel) VALUES (1781, 35, 'A', 0.7632965, 'Tu me diz o teu nome completo, por favor.', 8442, 11442, 0.7632965, 9, 0);
INSERT INTO speaker_segments (id, transcricao_id, speaker, speaker_confidence, text, start_time, end_time, confidence, words_count, channel) VALUES (1782, 35, 'C', 0.886487, 'Douglas Oliveira Mafalda.', 11442, 13982, 0.886487, 3, 0);
INSERT INTO speaker_segments (id, transcricao_id, speaker, speaker_confidence, text, start_time, end_time, confidence, words_count, channel) VALUES (1783, 35, 'A', 0.81675136, 'Tu me diz a tua filiação, o nome dos teus pais.', 13982, 19502, 0.81675136, 11, 0);
INSERT INTO speaker_segments (id, transcricao_id, speaker, speaker_confidence, text, start_time, end_time, confidence, words_count, channel) VALUES (1784, 35, 'C', 0.7998016, 'José Leomar de Oliveira Mafalda e Eliane Silva de Oliveira.', 19502, 23962, 0.7998016, 10, 0);
INSERT INTO speaker_segments (id, transcricao_id, speaker, speaker_confidence, text, start_time, end_time, confidence, words_count, channel) VALUES (1785, 35, 'A', 0.78990275, 'E qual é o princípio que tu está aí?', 23962, 26982, 0.78990275, 9, 0);
INSERT INTO speaker_segments (id, transcricao_id, speaker, speaker_confidence, text, start_time, end_time, confidence, words_count, channel) VALUES (1786, 35, 'C', 0.43456835, 'Não entendi.', 29945, 31005, 0.43456835, 2, 0);
INSERT INTO speaker_segments (id, transcricao_id, speaker, speaker_confidence, text, start_time, end_time, confidence, words_count, channel) VALUES (1787, 35, 'A', 0.698109, 'Tu tá preso em qual presídio?', 31005, 34025, 0.698109, 6, 0);
INSERT INTO speaker_segments (id, transcricao_id, speaker, speaker_confidence, text, start_time, end_time, confidence, words_count, channel) VALUES (1788, 35, 'C', 0.70301366, 'Tô na APK.', 34025, 35345, 0.70301366, 3, 0);
INSERT INTO speaker_segments (id, transcricao_id, speaker, speaker_confidence, text, start_time, end_time, confidence, words_count, channel) VALUES (1789, 35, 'A', 0.67789453, 'Na APK.', 35345, 37085, 0.67789453, 2, 0);
INSERT INTO speaker_segments (id, transcricao_id, speaker, speaker_confidence, text, start_time, end_time, confidence, words_count, channel) VALUES (1790, 35, 'B', 0.89524025, 'Tá certo.', 37085, 39445, 0.89524025, 2, 0);
INSERT INTO speaker_segments (id, transcricao_id, speaker, speaker_confidence, text, start_time, end_time, confidence, words_count, channel) VALUES (1791, 35, 'D', 0.479, 'Ok.', 39445, 40885, 0.479, 1, 0);
INSERT INTO speaker_segments (id, transcricao_id, speaker, speaker_confidence, text, start_time, end_time, confidence, words_count, channel) VALUES (1792, 35, 'A', 0.8647018, 'Aqui sim, doutor.', 40885, 43645, 0.8647018, 3, 0);
INSERT INTO speaker_segments (id, transcricao_id, speaker, speaker_confidence, text, start_time, end_time, confidence, words_count, channel) VALUES (1793, 35, 'D', 0.71908075, 'Boa tarde, Douglas.', 43645, 45565, 0.71908075, 3, 0);
INSERT INTO speaker_segments (id, transcricao_id, speaker, speaker_confidence, text, start_time, end_time, confidence, words_count, channel) VALUES (1794, 35, 'C', 0.71542776, 'Boa tarde.', 45565, 46285, 0.71542776, 2, 0);
INSERT INTO speaker_segments (id, transcricao_id, speaker, speaker_confidence, text, start_time, end_time, confidence, words_count, channel) VALUES (1795, 35, 'D', 0.79165494, 'Douglas, o senhor vai ser ouvido sobre o fato número 5º da denúncia, ok? Eu vou fazer a leitura do fato para ver se o senhor se recorda, porque já faz algum tempo. No dia 22 de outubro de 2019, por volta das 22h30, na Rua Lago Azul, número 248, no bairro Santa Bárbara, cidade de Alvorada, os soldados Josimar da Silva Pereira, Felipe Ferreira Janiquim e Mateus Arcenes de Voraes, em comunhão de resposta e condição de vontade, todos de serviço pilotado no vigésimo quarto PTM, apropriaram-se de valores que tinham força e razão da função apreendido durante a ocorrência policial registrada sob o número 100-464-2019-14700, relativa aos crimes de tráfego de entorpecentes e porte legal de arma. Na oportunidade, os denunciados prenderam Douglas de Oliveira Mafalda e Rafael de Cidade Barbosa por tráfico de estropecentes e porte ilegal de arma, aprendendo, dentre outros materiais, dois coletes balísticos, uma pistola calibre .380, um revólver calibre .38, um revólver calibre .32 e uma espigada calibre .12. também 2.289 gramas de cocaína, 79 gramas de maconha e, ao menos, um grama de crack. E R$331 em dinheiro.', 47967, 142062, 0.79165494, 186, 0);
INSERT INTO speaker_segments (id, transcricao_id, speaker, speaker_confidence, text, start_time, end_time, confidence, words_count, channel) VALUES (1796, 35, 'A', 0.614, 'Pergunta.', 142062, 145062, 0.614, 1, 0);
INSERT INTO speaker_segments (id, transcricao_id, speaker, speaker_confidence, text, start_time, end_time, confidence, words_count, channel) VALUES (1797, 35, 'D', 0.806027, 'Douglas, sobre essa ocorrência, o que o senhor tem a nos dizer?', 149702, 154242, 0.806027, 12, 0);
INSERT INTO speaker_segments (id, transcricao_id, speaker, speaker_confidence, text, start_time, end_time, confidence, words_count, channel) VALUES (1798, 35, 'A', 0.377903, 'E aí e o problema do tornozelo né é alguma coisa aconteceu e tá.', 157115, 168995, 0.377903, 14, 0);
INSERT INTO speaker_segments (id, transcricao_id, speaker, speaker_confidence, text, start_time, end_time, confidence, words_count, channel) VALUES (1799, 35, 'B', 0.4907401, 'Voltou a normal E aí E aí.', 168995, 177445, 0.4907401, 7, 0);
INSERT INTO speaker_segments (id, transcricao_id, speaker, speaker_confidence, text, start_time, end_time, confidence, words_count, channel) VALUES (1800, 35, 'D', 0.5180132, 'O Bernadete põe ele na tela principal.', 177445, 179135, 0.5180132, 7, 0);
INSERT INTO speaker_segments (id, transcricao_id, speaker, speaker_confidence, text, start_time, end_time, confidence, words_count, channel) VALUES (1801, 35, 'A', 0.519529, 'E ele tá na tela doutor tá.', 179135, 184475, 0.519529, 7, 0);
INSERT INTO speaker_segments (id, transcricao_id, speaker, speaker_confidence, text, start_time, end_time, confidence, words_count, channel) VALUES (1802, 35, 'C', 0.62781566, 'Mas dá na principal, que eu não estou vendo.', 184475, 190122, 0.62781566, 9, 0);
INSERT INTO speaker_segments (id, transcricao_id, speaker, speaker_confidence, text, start_time, end_time, confidence, words_count, channel) VALUES (1803, 35, 'A', 0.62438333, 'Aqui a gente está.', 193302, 196082, 0.62438333, 4, 0);
INSERT INTO speaker_segments (id, transcricao_id, speaker, speaker_confidence, text, start_time, end_time, confidence, words_count, channel) VALUES (1804, 35, 'D', 0.8230529, 'Douglas, ouviu sobre essa ocorrência?', 196082, 201222, 0.8230529, 5, 0);
INSERT INTO speaker_segments (id, transcricao_id, speaker, speaker_confidence, text, start_time, end_time, confidence, words_count, channel) VALUES (1805, 35, 'C', 0.7735, 'Escutei, escutei.', 201222, 203082, 0.7735, 2, 0);
INSERT INTO speaker_segments (id, transcricao_id, speaker, speaker_confidence, text, start_time, end_time, confidence, words_count, channel) VALUES (1806, 35, 'D', 0.81704307, '22 de outubro de 2019, o senhor foi preso, junto com o Rafael, por porte ilegal de drogas e arma. Sobre esse fato, o que o senhor pode nos dizer sobre isso?', 203082, 218612, 0.81704307, 32, 0);
INSERT INTO speaker_segments (id, transcricao_id, speaker, speaker_confidence, text, start_time, end_time, confidence, words_count, channel) VALUES (1807, 35, 'C', 0.68094903, 'Não tenho nada a dizer sobre isso.', 218612, 222132, 0.68094903, 7, 0);
INSERT INTO speaker_segments (id, transcricao_id, speaker, speaker_confidence, text, start_time, end_time, confidence, words_count, channel) VALUES (1808, 35, 'D', 0.79700947, 'O senhor estava na posse de entorpecente e armas?', 222132, 226592, 0.79700947, 9, 0);
INSERT INTO speaker_segments (id, transcricao_id, speaker, speaker_confidence, text, start_time, end_time, confidence, words_count, channel) VALUES (1809, 35, 'C', 0.7912666, 'Estava na posse, estava.', 226592, 229692, 0.7912666, 4, 0);
INSERT INTO speaker_segments (id, transcricao_id, speaker, speaker_confidence, text, start_time, end_time, confidence, words_count, channel) VALUES (1810, 35, 'D', 0.7679148, 'E o senhor se recorda de quantas armas o senhor tinha?', 229692, 236392, 0.7679148, 11, 0);
INSERT INTO speaker_segments (id, transcricao_id, speaker, speaker_confidence, text, start_time, end_time, confidence, words_count, channel) VALUES (1811, 35, 'C', 0.70098877, 'Claro, não me lembro.', 236392, 238532, 0.70098877, 4, 0);
INSERT INTO speaker_segments (id, transcricao_id, speaker, speaker_confidence, text, start_time, end_time, confidence, words_count, channel) VALUES (1812, 35, 'D', 0.9268195, 'E a quantidade de drogas?', 238532, 240612, 0.9268195, 5, 0);
INSERT INTO speaker_segments (id, transcricao_id, speaker, speaker_confidence, text, start_time, end_time, confidence, words_count, channel) VALUES (1813, 35, 'C', 0.6927886, 'Também não sei, não era eu que vendia.', 241996, 244876, 0.6927886, 8, 0);
INSERT INTO speaker_segments (id, transcricao_id, speaker, speaker_confidence, text, start_time, end_time, confidence, words_count, channel) VALUES (1814, 35, 'D', 0.76619697, 'Valores em dinheiro, o senhor saberia dizer quanto de dinheiro o senhor tinha nessa oportunidade, junto com o Rafael?', 244876, 255336, 0.76619697, 19, 0);
INSERT INTO speaker_segments (id, transcricao_id, speaker, speaker_confidence, text, start_time, end_time, confidence, words_count, channel) VALUES (1815, 35, 'C', 0.773043, 'Não sei.', 255336, 257456, 0.773043, 2, 0);
INSERT INTO speaker_segments (id, transcricao_id, speaker, speaker_confidence, text, start_time, end_time, confidence, words_count, channel) VALUES (1816, 35, 'D', 0.80529785, 'Não se recorda? Não. Durante essa ocorrência, o senhor chegou a notar se algum policial pegou algum dinheiro para ele?', 257456, 266216, 0.80529785, 20, 0);
INSERT INTO speaker_segments (id, transcricao_id, speaker, speaker_confidence, text, start_time, end_time, confidence, words_count, channel) VALUES (1817, 35, 'B', 0.919, 'Ouviu, Douglas?', 272472, 276872, 0.919, 2, 0);
INSERT INTO speaker_segments (id, transcricao_id, speaker, speaker_confidence, text, start_time, end_time, confidence, words_count, channel) VALUES (1818, 35, 'C', 0.849, 'Douglas.', 276872, 279872, 0.849, 1, 0);
INSERT INTO speaker_segments (id, transcricao_id, speaker, speaker_confidence, text, start_time, end_time, confidence, words_count, channel) VALUES (1819, 35, 'D', 0.82240105, 'Está me ouvindo?', 281672, 284852, 0.82240105, 3, 0);
INSERT INTO speaker_segments (id, transcricao_id, speaker, speaker_confidence, text, start_time, end_time, confidence, words_count, channel) VALUES (1820, 35, 'B', 0.73709244, 'De novo deu.', 286132, 290772, 0.73709244, 3, 0);
INSERT INTO speaker_segments (id, transcricao_id, speaker, speaker_confidence, text, start_time, end_time, confidence, words_count, channel) VALUES (1821, 35, 'A', 0.79088366, 'Ele continua aqui na tela, doutor, PK Douglas. Douglas, você está nos ouvindo? Porque ele não caiu, ele está aqui no… Vamos ver, espera aí. Agora caiu, estou colocando ele de novo.', 290772, 317713, 0.79088366, 32, 0);
INSERT INTO speaker_segments (id, transcricao_id, speaker, speaker_confidence, text, start_time, end_time, confidence, words_count, channel) VALUES (1822, 35, 'B', 0.31982422, 'Você.', 317713, 320713, 0.31982422, 1, 0);
INSERT INTO speaker_segments (id, transcricao_id, speaker, speaker_confidence, text, start_time, end_time, confidence, words_count, channel) VALUES (1823, 35, 'A', 0.679965, 'Está saindo da APK que está… Coloca o Diogo de novo. Coloca o Douglas de novo.', 328033, 336490, 0.679965, 16, 0);
INSERT INTO speaker_segments (id, transcricao_id, speaker, speaker_confidence, text, start_time, end_time, confidence, words_count, channel) VALUES (1824, 35, 'C', 0.67762816, 'Tá, só um momento que eu tô configurando aqui.', 336490, 339010, 0.67762816, 9, 0);
INSERT INTO speaker_segments (id, transcricao_id, speaker, speaker_confidence, text, start_time, end_time, confidence, words_count, channel) VALUES (1825, 35, 'B', 0.8497435, 'Tá certo. Pronto.', 339010, 347070, 0.8497435, 3, 0);
INSERT INTO speaker_segments (id, transcricao_id, speaker, speaker_confidence, text, start_time, end_time, confidence, words_count, channel) VALUES (1826, 35, 'A', 0.7671834, 'Doutor, ele tá de volta.', 356650, 359050, 0.7671834, 5, 0);
INSERT INTO speaker_segments (id, transcricao_id, speaker, speaker_confidence, text, start_time, end_time, confidence, words_count, channel) VALUES (1827, 35, 'D', 0.729, 'Douglas!', 359050, 362050, 0.729, 1, 0);
INSERT INTO speaker_segments (id, transcricao_id, speaker, speaker_confidence, text, start_time, end_time, confidence, words_count, channel) VALUES (1828, 35, 'B', 0.834, 'Opa!', 362630, 363610, 0.834, 1, 0);
INSERT INTO speaker_segments (id, transcricao_id, speaker, speaker_confidence, text, start_time, end_time, confidence, words_count, channel) VALUES (1829, 35, 'D', 0.71159005, 'Durante essa ocorrência, o senhor chegou a notar se algum policial tinha pego o dinheiro que estava na posse de vocês? Acho que foi agora. Mas não tem certeza.', 364154, 379014, 0.71159005, 29, 0);
INSERT INTO speaker_segments (id, transcricao_id, speaker, speaker_confidence, text, start_time, end_time, confidence, words_count, channel) VALUES (1830, 35, 'B', 0.62228644, 'É, não tem certeza.', 379014, 382494, 0.62228644, 4, 0);
INSERT INTO speaker_segments (id, transcricao_id, speaker, speaker_confidence, text, start_time, end_time, confidence, words_count, channel) VALUES (1831, 35, 'D', 0.7664448, 'E como eu já tinha lhe perguntado quantidade de droga, quantidade de dinheiro e quantidade de arma, o senhor não se lembra.', 382994, 390634, 0.7664448, 22, 0);
INSERT INTO speaker_segments (id, transcricao_id, speaker, speaker_confidence, text, start_time, end_time, confidence, words_count, channel) VALUES (1832, 35, 'C', 0.69259316, 'Não me lembro porque eles não pegaram nada com nós, os sojuíras. Eles chegaram em outra residência.', 391643, 397823, 0.69259316, 17, 0);
INSERT INTO speaker_segments (id, transcricao_id, speaker, speaker_confidence, text, start_time, end_time, confidence, words_count, channel) VALUES (1833, 35, 'D', 0.7877884, 'E isso não estava com vocês?', 397823, 400243, 0.7877884, 6, 0);
INSERT INTO speaker_segments (id, transcricao_id, speaker, speaker_confidence, text, start_time, end_time, confidence, words_count, channel) VALUES (1834, 35, 'C', 0.78967446, 'Não, não estava com nós. Eles pegaram em outra residência e daí botaram em nós.', 400243, 405563, 0.78967446, 15, 0);
INSERT INTO speaker_segments (id, transcricao_id, speaker, speaker_confidence, text, start_time, end_time, confidence, words_count, channel) VALUES (1835, 35, 'D', 0.78441405, 'E você estava perto dessa residência?', 405563, 408923, 0.78441405, 6, 0);
INSERT INTO speaker_segments (id, transcricao_id, speaker, speaker_confidence, text, start_time, end_time, confidence, words_count, channel) VALUES (1836, 35, 'C', 0.70424235, 'Ah, no caso, eu moro umas duas quartas dessa residência. Tá.', 408923, 413403, 0.70424235, 11, 0);
INSERT INTO speaker_segments (id, transcricao_id, speaker, speaker_confidence, text, start_time, end_time, confidence, words_count, channel) VALUES (1837, 35, 'D', 0.8431563, 'E o senhor está preso por tráfico?', 413403, 415743, 0.8431563, 7, 0);
INSERT INTO speaker_segments (id, transcricao_id, speaker, speaker_confidence, text, start_time, end_time, confidence, words_count, channel) VALUES (1838, 35, 'C', 0.69946146, 'Agora eu estou preso por tráfico? Poxa, eu fiquei quatro dias na rua só. Tá iniciado de novo.', 415743, 424297, 0.69946146, 18, 0);
INSERT INTO speaker_segments (id, transcricao_id, speaker, speaker_confidence, text, start_time, end_time, confidence, words_count, channel) VALUES (1839, 35, 'D', 0.69945425, 'Tá certo. Palavra ao conselho, Capitão Marcelo.', 424297, 428797, 0.69945425, 7, 0);
INSERT INTO speaker_segments (id, transcricao_id, speaker, speaker_confidence, text, start_time, end_time, confidence, words_count, channel) VALUES (1840, 35, 'B', 0.7757904, 'Sem perguntas, Excelência.', 428797, 433337, 0.7757904, 3, 0);
INSERT INTO speaker_segments (id, transcricao_id, speaker, speaker_confidence, text, start_time, end_time, confidence, words_count, channel) VALUES (1841, 35, 'D', 0.69968057, 'Ao Capitão Koniki.', 433337, 435937, 0.69968057, 3, 0);
INSERT INTO speaker_segments (id, transcricao_id, speaker, speaker_confidence, text, start_time, end_time, confidence, words_count, channel) VALUES (1842, 35, 'C', 0.78916794, 'Sem perguntas.', 435937, 436777, 0.78916794, 2, 0);
INSERT INTO speaker_segments (id, transcricao_id, speaker, speaker_confidence, text, start_time, end_time, confidence, words_count, channel) VALUES (1843, 35, 'D', 0.8342305, 'Ministério Público.', 436777, 441077, 0.8342305, 2, 0);
INSERT INTO speaker_segments (id, transcricao_id, speaker, speaker_confidence, text, start_time, end_time, confidence, words_count, channel) VALUES (1844, 35, 'E', 0.78305614, 'Boa tarde. Exatamente o que aconteceu nesse dia, Douglas? O senhor conheceu os policiais militares?', 441077, 449757, 0.78305614, 15, 0);
INSERT INTO speaker_segments (id, transcricao_id, speaker, speaker_confidence, text, start_time, end_time, confidence, words_count, channel) VALUES (1845, 35, 'C', 0.7280621, 'No caso, eu estava sem medir o meio para levar meus primos para o colégio e tomei uma abordagem da polícia. Nisso eu tomei uma abordagem. Eles tinham abordado outro guri que morava em frente da minha casa e estava saindo para trabalhar. Eles queriam saber de droga, de arma. A gente, sabe, falava... Falava que a gente não sabia de nada e eles começaram a bater na gente e me enxertaram mais com as drogas. Falaram que se a gente não falasse nada, eles enxertariam mais e levariam mais primos.', 452596, 481096, 0.7280621, 91, 0);
INSERT INTO speaker_segments (id, transcricao_id, speaker, speaker_confidence, text, start_time, end_time, confidence, words_count, channel) VALUES (1846, 35, 'E', 0.7521145, 'Você já conhecia os policiais?', 482785, 485525, 0.7521145, 5, 0);
INSERT INTO speaker_segments (id, transcricao_id, speaker, speaker_confidence, text, start_time, end_time, confidence, words_count, channel) VALUES (1847, 35, 'C', 0.66991013, 'Não, não conhecia.', 485525, 488065, 0.66991013, 3, 0);
INSERT INTO speaker_segments (id, transcricao_id, speaker, speaker_confidence, text, start_time, end_time, confidence, words_count, channel) VALUES (1848, 35, 'E', 0.8003854, 'Nem de vista?', 488065, 490045, 0.8003854, 3, 0);
INSERT INTO speaker_segments (id, transcricao_id, speaker, speaker_confidence, text, start_time, end_time, confidence, words_count, channel) VALUES (1849, 35, 'C', 0.69729936, 'Não, nunca tinha visto.', 490045, 492665, 0.69729936, 4, 0);
INSERT INTO speaker_segments (id, transcricao_id, speaker, speaker_confidence, text, start_time, end_time, confidence, words_count, channel) VALUES (1850, 35, 'E', 0.72353125, 'Eles te exigiram algum dinheiro, algo? Para não fazer isso?', 492665, 498105, 0.72353125, 10, 0);
INSERT INTO speaker_segments (id, transcricao_id, speaker, speaker_confidence, text, start_time, end_time, confidence, words_count, channel) VALUES (1851, 35, 'C', 0.8508152, 'Não, não pediram nada.', 498105, 501085, 0.8508152, 4, 0);
INSERT INTO speaker_segments (id, transcricao_id, speaker, speaker_confidence, text, start_time, end_time, confidence, words_count, channel) VALUES (1852, 35, 'E', 0.79725605, 'Você estava acompanhado de quem nesse momento?', 501085, 504685, 0.79725605, 7, 0);
INSERT INTO speaker_segments (id, transcricao_id, speaker, speaker_confidence, text, start_time, end_time, confidence, words_count, channel) VALUES (1853, 35, 'C', 0.88972265, 'Acompanhada da minha irmã.', 504685, 506465, 0.88972265, 4, 0);
INSERT INTO speaker_segments (id, transcricao_id, speaker, speaker_confidence, text, start_time, end_time, confidence, words_count, channel) VALUES (1854, 35, 'E', 0.8079838, 'Como é que é o nome dela?', 506465, 508225, 0.8079838, 7, 0);
INSERT INTO speaker_segments (id, transcricao_id, speaker, speaker_confidence, text, start_time, end_time, confidence, words_count, channel) VALUES (1855, 35, 'C', 0.904, 'Cristiane.', 508225, 510085, 0.904, 1, 0);
INSERT INTO speaker_segments (id, transcricao_id, speaker, speaker_confidence, text, start_time, end_time, confidence, words_count, channel) VALUES (1856, 35, 'E', 0.8019225, 'Só ela estava contigo? Mais ninguém?', 510085, 512525, 0.8019225, 6, 0);
INSERT INTO speaker_segments (id, transcricao_id, speaker, speaker_confidence, text, start_time, end_time, confidence, words_count, channel) VALUES (1857, 35, 'C', 0.72663534, 'Estava só eu e as minhas crianças em casa.', 513160, 515340, 0.72663534, 9, 0);
INSERT INTO speaker_segments (id, transcricao_id, speaker, speaker_confidence, text, start_time, end_time, confidence, words_count, channel) VALUES (1858, 35, 'E', 0.72180855, 'E por que eles fizeram isso contigo? Tu afirma que não conhecia eles, que.', 515340, 524360, 0.72180855, 14, 0);
INSERT INTO speaker_segments (id, transcricao_id, speaker, speaker_confidence, text, start_time, end_time, confidence, words_count, channel) VALUES (1859, 35, 'C', 0.7487738, 'Não foi exigido... Nada, eu já não sei. Não tenho o que dizer.', 524360, 533140, 0.7487738, 13, 0);
INSERT INTO speaker_segments (id, transcricao_id, speaker, speaker_confidence, text, start_time, end_time, confidence, words_count, channel) VALUES (1860, 35, 'E', 0.8020814, 'Tu está preso por esse fato?', 533140, 536780, 0.8020814, 6, 0);
INSERT INTO speaker_segments (id, transcricao_id, speaker, speaker_confidence, text, start_time, end_time, confidence, words_count, channel) VALUES (1861, 35, 'C', 0.7264756, 'Não, no caso desse fato, eu fui embora e voltei de novo para uma outra pronta.', 536780, 542060, 0.7264756, 16, 0);
INSERT INTO speaker_segments (id, transcricao_id, speaker, speaker_confidence, text, start_time, end_time, confidence, words_count, channel) VALUES (1862, 35, 'E', 0.7795394, 'Além de droga, arma, teve alguma questão envolvendo arma em relação a esse fato que o juiz questionou para ti?', 543738, 554478, 0.7795394, 20, 0);
INSERT INTO speaker_segments (id, transcricao_id, speaker, speaker_confidence, text, start_time, end_time, confidence, words_count, channel) VALUES (1863, 35, 'C', 0.8512734, 'Não entendi.', 554478, 555998, 0.8512734, 2, 0);
INSERT INTO speaker_segments (id, transcricao_id, speaker, speaker_confidence, text, start_time, end_time, confidence, words_count, channel) VALUES (1864, 35, 'E', 0.6748876, 'Em relação a arma, tem alguma coisa de enxertar um arma também ou não?', 555998, 561438, 0.6748876, 14, 0);
INSERT INTO speaker_segments (id, transcricao_id, speaker, speaker_confidence, text, start_time, end_time, confidence, words_count, channel) VALUES (1865, 35, 'C', 0.5796897, 'Podemos enxertar também um revólver.', 561438, 564758, 0.5796897, 5, 0);
INSERT INTO speaker_segments (id, transcricao_id, speaker, speaker_confidence, text, start_time, end_time, confidence, words_count, channel) VALUES (1866, 35, 'E', 0.8969453, 'Qual revólver?', 564758, 566798, 0.8969453, 2, 0);
INSERT INTO speaker_segments (id, transcricao_id, speaker, speaker_confidence, text, start_time, end_time, confidence, words_count, channel) VALUES (1867, 35, 'C', 0.66213214, 'Calibre 38.', 566798, 569718, 0.66213214, 2, 0);
INSERT INTO speaker_segments (id, transcricao_id, speaker, speaker_confidence, text, start_time, end_time, confidence, words_count, channel) VALUES (1868, 35, 'E', 0.8207299, 'E como é que foi esse enxerto?', 569718, 572178, 0.8207299, 7, 0);
INSERT INTO speaker_segments (id, transcricao_id, speaker, speaker_confidence, text, start_time, end_time, confidence, words_count, channel) VALUES (1869, 35, 'C', 0.66026735, 'Na hora da abordagem.', 573505, 575965, 0.66026735, 4, 0);
INSERT INTO speaker_segments (id, transcricao_id, speaker, speaker_confidence, text, start_time, end_time, confidence, words_count, channel) VALUES (1870, 35, 'E', 0.76930076, 'O que eles falaram?', 575965, 579205, 0.76930076, 4, 0);
INSERT INTO speaker_segments (id, transcricao_id, speaker, speaker_confidence, text, start_time, end_time, confidence, words_count, channel) VALUES (1871, 35, 'C', 0.74619275, 'Eles falaram que se a gente não falasse nada, eles iam chutar nós. Iam botar droga, arma e iam botar nós na cadeira.', 579205, 588105, 0.74619275, 23, 0);
INSERT INTO speaker_segments (id, transcricao_id, speaker, speaker_confidence, text, start_time, end_time, confidence, words_count, channel) VALUES (1872, 35, 'E', 0.6953336, 'Tu tem vínculo com alguma facção?', 589245, 592865, 0.6953336, 6, 0);
INSERT INTO speaker_segments (id, transcricao_id, speaker, speaker_confidence, text, start_time, end_time, confidence, words_count, channel) VALUES (1873, 35, 'C', 0.873, 'Não, não.', 592865, 594665, 0.873, 2, 0);
INSERT INTO speaker_segments (id, transcricao_id, speaker, speaker_confidence, text, start_time, end_time, confidence, words_count, channel) VALUES (1874, 35, 'E', 0.77933985, 'Nada mais.', 594665, 597225, 0.77933985, 2, 0);
INSERT INTO speaker_segments (id, transcricao_id, speaker, speaker_confidence, text, start_time, end_time, confidence, words_count, channel) VALUES (1875, 35, 'D', 0.73941714, 'Doutora Edna, pelo soldado Josimar.', 597225, 601205, 0.73941714, 5, 0);
INSERT INTO speaker_segments (id, transcricao_id, speaker, speaker_confidence, text, start_time, end_time, confidence, words_count, channel) VALUES (1876, 35, 'B', 0.57749087, 'Nada, em silêncio.', 604302, 606462, 0.57749087, 3, 0);
INSERT INTO speaker_segments (id, transcricao_id, speaker, speaker_confidence, text, start_time, end_time, confidence, words_count, channel) VALUES (1877, 35, 'D', 0.7052441, 'A doutora Ciomara pelo soldado Felipe.', 606462, 609702, 0.7052441, 6, 0);
INSERT INTO speaker_segments (id, transcricao_id, speaker, speaker_confidence, text, start_time, end_time, confidence, words_count, channel) VALUES (1878, 35, 'B', 0.86127216, 'Nada, em silêncio.', 609702, 612302, 0.86127216, 3, 0);
INSERT INTO speaker_segments (id, transcricao_id, speaker, speaker_confidence, text, start_time, end_time, confidence, words_count, channel) VALUES (1879, 35, 'D', 0.8705577, 'Pelo soldado Mateus, doutor Márcio Barcelos.', 612302, 616602, 0.8705577, 6, 0);
INSERT INTO speaker_segments (id, transcricao_id, speaker, speaker_confidence, text, start_time, end_time, confidence, words_count, channel) VALUES (1880, 35, 'F', 0.74845076, 'Sim, doutor. Só para confirmar com ele, se o Mateus Alicênio, ele lembra do Mateus nessa data, presente no fato da abordagem?', 616602, 626802, 0.74845076, 22, 0);
INSERT INTO speaker_segments (id, transcricao_id, speaker, speaker_confidence, text, start_time, end_time, confidence, words_count, channel) VALUES (1881, 35, 'B', 0.7406413, 'Eu não entendi.', 626802, 629762, 0.7406413, 3, 0);
INSERT INTO speaker_segments (id, transcricao_id, speaker, speaker_confidence, text, start_time, end_time, confidence, words_count, channel) VALUES (1882, 35, 'F', 0.7200159, 'Se ele lembra os policiais que abordaram ele, especialmente no meu caso, o Mateus Arsene.', 631505, 636805, 0.7200159, 15, 0);
INSERT INTO speaker_segments (id, transcricao_id, speaker, speaker_confidence, text, start_time, end_time, confidence, words_count, channel) VALUES (1883, 35, 'D', 0.80663544, 'O senhor lembra quem foram os policiais que lhe abordaram?', 636805, 641285, 0.80663544, 10, 0);
INSERT INTO speaker_segments (id, transcricao_id, speaker, speaker_confidence, text, start_time, end_time, confidence, words_count, channel) VALUES (1884, 35, 'C', 0.78309196, 'Ah, se eu olhar pelo rosto até lembro, mas pelo nome eu não lembro.', 641285, 648185, 0.78309196, 14, 0);
INSERT INTO speaker_segments (id, transcricao_id, speaker, speaker_confidence, text, start_time, end_time, confidence, words_count, channel) VALUES (1885, 35, 'F', 0.81894606, 'Chegaram a te convidar para fazer a cariação no inquérito?', 650065, 654765, 0.81894606, 10, 0);
INSERT INTO speaker_segments (id, transcricao_id, speaker, speaker_confidence, text, start_time, end_time, confidence, words_count, channel) VALUES (1886, 35, 'C', 0.77893084, 'Vocês chegaram a me bater?', 654765, 657045, 0.77893084, 5, 0);
INSERT INTO speaker_segments (id, transcricao_id, speaker, speaker_confidence, text, start_time, end_time, confidence, words_count, channel) VALUES (1887, 35, 'F', 0.774598, 'Não, fazer a cariação para te reconhecer os policiais.', 657045, 659525, 0.774598, 9, 0);
INSERT INTO speaker_segments (id, transcricao_id, speaker, speaker_confidence, text, start_time, end_time, confidence, words_count, channel) VALUES (1888, 35, 'C', 0.6902643, 'Não, não fizeram. Isso eu vi só em uma audiência na rua. Em uma audiência na rua eu vi isso.', 660293, 668073, 0.6902643, 20, 0);
INSERT INTO speaker_segments (id, transcricao_id, speaker, speaker_confidence, text, start_time, end_time, confidence, words_count, channel) VALUES (1889, 35, 'B', 0.85796076, 'Chegou a ser agredido? Quase me mataram.', 668073, 677353, 0.85796076, 7, 0);
INSERT INTO speaker_segments (id, transcricao_id, speaker, speaker_confidence, text, start_time, end_time, confidence, words_count, channel) VALUES (1890, 35, 'F', 0.6855556, 'Tu reagiu ou só um apanhado de graça?', 677933, 682593, 0.6855556, 8, 0);
INSERT INTO speaker_segments (id, transcricao_id, speaker, speaker_confidence, text, start_time, end_time, confidence, words_count, channel) VALUES (1891, 35, 'C', 0.64039135, 'Eu reagi contra quatro, não tem condições. Os caras quase me mataram.', 682593, 686813, 0.64039135, 12, 0);
INSERT INTO speaker_segments (id, transcricao_id, speaker, speaker_confidence, text, start_time, end_time, confidence, words_count, channel) VALUES (1892, 35, 'F', 0.7464871, 'Tu não viu os nomes deles nas fardas no dia?', 690078, 694558, 0.7464871, 10, 0);
INSERT INTO speaker_segments (id, transcricao_id, speaker, speaker_confidence, text, start_time, end_time, confidence, words_count, channel) VALUES (1893, 35, 'C', 0.7254081, 'Não via, não via porque eles me afogavam, eles estavam me afogando com água e botando pano na minha cara.', 694558, 700578, 0.7254081, 20, 0);
INSERT INTO speaker_segments (id, transcricao_id, speaker, speaker_confidence, text, start_time, end_time, confidence, words_count, channel) VALUES (1894, 35, 'F', 0.6679251, 'Afogaram onde?', 700578, 701518, 0.6679251, 2, 0);
INSERT INTO speaker_segments (id, transcricao_id, speaker, speaker_confidence, text, start_time, end_time, confidence, words_count, channel) VALUES (1895, 35, 'B', 0.5681553, 'Na camisa.', 701518, 703818, 0.5681553, 2, 0);
INSERT INTO speaker_segments (id, transcricao_id, speaker, speaker_confidence, text, start_time, end_time, confidence, words_count, channel) VALUES (1896, 35, 'F', 0.8741045, 'Aonde isso?', 703818, 706038, 0.8741045, 2, 0);
INSERT INTO speaker_segments (id, transcricao_id, speaker, speaker_confidence, text, start_time, end_time, confidence, words_count, channel) VALUES (1897, 35, 'C', 0.8736531, 'Na casa da minha irmã.', 706038, 707858, 0.8736531, 5, 0);
INSERT INTO speaker_segments (id, transcricao_id, speaker, speaker_confidence, text, start_time, end_time, confidence, words_count, channel) VALUES (1898, 35, 'F', 0.6733156, 'Foi dentro, eles entraram na tua casa?', 707858, 709798, 0.6733156, 7, 0);
INSERT INTO speaker_segments (id, transcricao_id, speaker, speaker_confidence, text, start_time, end_time, confidence, words_count, channel) VALUES (1899, 35, 'C', 0.8884495, 'Dentro da casa, na frente das crianças.', 709798, 712658, 0.8884495, 7, 0);
INSERT INTO speaker_segments (id, transcricao_id, speaker, speaker_confidence, text, start_time, end_time, confidence, words_count, channel) VALUES (1900, 35, 'F', 0.82803386, 'Alguém viu, alguém filmou? O senhor registrou isso?', 712658, 717018, 0.82803386, 8, 0);
INSERT INTO speaker_segments (id, transcricao_id, speaker, speaker_confidence, text, start_time, end_time, confidence, words_count, channel) VALUES (1901, 35, 'C', 0.7774581, 'Eu não sei se a minha irmã já vai registrar, mas ela viu. Isso foi de manhã cedo, umas oito e meia da manhã.', 718107, 727947, 0.7774581, 24, 0);
INSERT INTO speaker_segments (id, transcricao_id, speaker, speaker_confidence, text, start_time, end_time, confidence, words_count, channel) VALUES (1902, 35, 'B', 0.8415, 'Satisfeito, doutor.', 727947, 730907, 0.8415, 2, 0);
INSERT INTO speaker_segments (id, transcricao_id, speaker, speaker_confidence, text, start_time, end_time, confidence, words_count, channel) VALUES (1903, 35, 'C', 0.9115, 'Certo, doutor.', 730907, 734187, 0.9115, 2, 0);
INSERT INTO speaker_segments (id, transcricao_id, speaker, speaker_confidence, text, start_time, end_time, confidence, words_count, channel) VALUES (1904, 35, 'D', 0.7872133, 'Doutor Márcio Rossano.', 734187, 738087, 0.7872133, 3, 0);
INSERT INTO speaker_segments (id, transcricao_id, speaker, speaker_confidence, text, start_time, end_time, confidence, words_count, channel) VALUES (1905, 35, 'F', 0.92025554, 'Sem perguntas, doutor Francisco.', 738087, 741507, 0.92025554, 4, 0);
INSERT INTO speaker_segments (id, transcricao_id, speaker, speaker_confidence, text, start_time, end_time, confidence, words_count, channel) VALUES (1906, 35, 'D', 0.8994798, 'Doutor Alfredo.', 741507, 743167, 0.8994798, 2, 0);
INSERT INTO speaker_segments (id, transcricao_id, speaker, speaker_confidence, text, start_time, end_time, confidence, words_count, channel) VALUES (1907, 35, 'C', 0.5951634, 'Sem perguntas, doutor.', 747487, 749347, 0.5951634, 3, 0);
INSERT INTO speaker_segments (id, transcricao_id, speaker, speaker_confidence, text, start_time, end_time, confidence, words_count, channel) VALUES (1908, 35, 'D', 0.66517645, 'A doutora Paloma?', 749347, 751767, 0.66517645, 3, 0);
INSERT INTO speaker_segments (id, transcricao_id, speaker, speaker_confidence, text, start_time, end_time, confidence, words_count, channel) VALUES (1909, 35, 'B', 0.8847656, 'Sem perguntas.', 751767, 754287, 0.8847656, 2, 0);
INSERT INTO speaker_segments (id, transcricao_id, speaker, speaker_confidence, text, start_time, end_time, confidence, words_count, channel) VALUES (1910, 35, 'D', 0.82061243, 'Não ficou nenhum advogado de fora?', 754287, 757167, 0.82061243, 6, 0);
INSERT INTO speaker_segments (id, transcricao_id, speaker, speaker_confidence, text, start_time, end_time, confidence, words_count, channel) VALUES (1911, 35, 'B', 0.439, 'Ok.', 757167, 759807, 0.439, 1, 0);
INSERT INTO speaker_segments (id, transcricao_id, speaker, speaker_confidence, text, start_time, end_time, confidence, words_count, channel) VALUES (1912, 35, 'D', 0.8296425, 'Está liberado, então, a testemunha. O Douglas pode deixar a sala. Obrigado pela colaboração da Suzette.', 759807, 768327, 0.8296425, 16, 0);
INSERT INTO speaker_segments (id, transcricao_id, speaker, speaker_confidence, text, start_time, end_time, confidence, words_count, channel) VALUES (1913, 35, 'C', 0.80823046, 'Muito obrigado.', 768327, 771647, 0.80823046, 2, 0);

-- ========================================
-- TABELA: system_config
-- ========================================

DROP TABLE IF EXISTS system_config CASCADE;
CREATE TABLE system_config (
    id INTEGER NOT NULL DEFAULT nextval('system_config_id_seq'::regclass),
    system_name VARCHAR(200),
    debug_mode BOOLEAN,
    log_level VARCHAR(20),
    max_agents INTEGER,
    assemblyai_enabled BOOLEAN,
    whisper_enabled BOOLEAN,
    speaker_detection BOOLEAN,
    auto_summary BOOLEAN,
    openai_model VARCHAR(50),
    anthropic_model VARCHAR(50),
    temperature DOUBLE PRECISION,
    max_tokens INTEGER,
    session_timeout INTEGER,
    max_login_attempts INTEGER,
    lockout_duration INTEGER,
    enable_monitoring BOOLEAN,
    enable_cost_tracking BOOLEAN,
    cost_alert_threshold DOUBLE PRECISION,
    token_limit_daily INTEGER,
    enable_pdf_export BOOLEAN,
    enable_docx_export BOOLEAN,
    default_font_size INTEGER,
    last_updated TIMESTAMP,
    updated_by INTEGER,
    PRIMARY KEY (id)
);

-- Tabela system_config está vazia

