-- ========================================
-- TABELA: templates_documento
-- ========================================

DROP TABLE IF EXISTS templates_documento CASCADE;
CREATE TABLE templates_documento (
    id INTEGER NOT NULL DEFAULT nextval('templates_documento_id_seq'::regclass),
    nome VARCHAR(200) NOT NULL,
    descricao TEXT,
    categoria_id INTEGER NOT NULL,
    template_original_id INTEGER,
    modulo_origem VARCHAR(50),
    modulo_nome VARCHAR(100),
    area_juridica VARCHAR(50),
    icone VARCHAR(50),
    tipo_documento VARCHAR(100),
    complexidade VARCHAR(20),
    campos_obrigatorios JSON,
    campos_opcionais JSON,
    estrutura_template TEXT,
    conteudo_template TEXT,
    variaveis_template JSON,
    requer_assinatura BOOLEAN,
    permite_edicao BOOLEAN,
    versao VARCHAR(10),
    total_utilizacoes INTEGER,
    ultima_utilizacao TIMESTAMP,
    ativo BOOLEAN,
    criado_em TIMESTAMP,
    atualizado_em TIMESTAMP,
    criado_por INTEGER,
    PRIMARY KEY (id)
);

-- Tabela templates_documento está vazia

-- ========================================
-- TABELA: tons_voz
-- ========================================

DROP TABLE IF EXISTS tons_voz CASCADE;
CREATE TABLE tons_voz (
    id INTEGER NOT NULL DEFAULT nextval('tons_voz_id_seq'::regclass),
    nome VARCHAR(100) NOT NULL,
    titulo VARCHAR(200) NOT NULL,
    descricao TEXT NOT NULL,
    instrucao_prompt TEXT NOT NULL,
    velocidade_resposta VARCHAR(50) DEFAULT 'normal'::character varying,
    estrutura_resposta VARCHAR(50) DEFAULT 'organizada'::character varying,
    nivel_detalhe VARCHAR(50) DEFAULT 'equilibrado'::character varying,
    icone VARCHAR(100) DEFAULT 'fas fa-volume-up'::character varying,
    cor_secundaria VARCHAR(7) DEFAULT '#6c757d'::character varying,
    ativo BOOLEAN DEFAULT true,
    criado_em TIMESTAMP DEFAULT now(),
    atualizado_em TIMESTAMP DEFAULT now(),
    PRIMARY KEY (id)
);

INSERT INTO tons_voz (id, nome, titulo, descricao, instrucao_prompt, velocidade_resposta, estrutura_resposta, nivel_detalhe, icone, cor_secundaria, ativo, criado_em, atualizado_em) VALUES (1, 'objetivo', 'Tom Objetivo', 'Comunicação direta e objetiva, focada em resultados e conclusões práticas.', 'Seja direto e objetivo nas suas colocações técnicas. Vá direto ao ponto essencial.', 'rapida', 'linear', 'conciso', 'fas fa-bullseye', '#e53e3e', TRUE, '2025-08-15 19:01:23.475416', '2025-08-15 19:01:23.475416');
INSERT INTO tons_voz (id, nome, titulo, descricao, instrucao_prompt, velocidade_resposta, estrutura_resposta, nivel_detalhe, icone, cor_secundaria, ativo, criado_em, atualizado_em) VALUES (2, 'sistematico', 'Tom Sistemático', 'Análise estruturada e organizada, com sequência lógica e fundamentação clara.', 'Estruture sua análise de forma sistemática e organizada. Use sequência lógica e fundamentação clara.', 'normal', 'organizada', 'equilibrado', 'fas fa-list-ol', '#3182ce', TRUE, '2025-08-15 19:01:23.475416', '2025-08-15 19:01:23.475416');
INSERT INTO tons_voz (id, nome, titulo, descricao, instrucao_prompt, velocidade_resposta, estrutura_resposta, nivel_detalhe, icone, cor_secundaria, ativo, criado_em, atualizado_em) VALUES (3, 'natural', 'Tom Natural', 'Linguagem técnica mas fluida e conversacional, mantendo rigor jurídico.', 'Use linguagem técnica mas fluida e conversacional. Mantenha rigor jurídico com naturalidade.', 'normal', 'topicos', 'completo', 'fas fa-comments', '#38a169', TRUE, '2025-08-15 19:01:23.475416', '2025-08-15 19:01:23.475416');

-- ========================================
-- TABELA: transcricao
-- ========================================

DROP TABLE IF EXISTS transcricao CASCADE;
CREATE TABLE transcricao (
    id VARCHAR(36) NOT NULL,
    usuario_id INTEGER,
    arquivo_id VARCHAR(36),
    data_criacao TIMESTAMP,
    data_atualizacao TIMESTAMP,
    arquivo_nome VARCHAR(255) NOT NULL,
    arquivo_caminho VARCHAR(500),
    arquivo_tamanho INTEGER,
    arquivo_duracao INTEGER,
    status VARCHAR(20),
    provedor VARCHAR(50),
    modelo VARCHAR(50),
    texto TEXT,
    metadados TEXT,
    resultado_json TEXT,
    sentimento VARCHAR(20),
    score_sentimento DOUBLE PRECISION,
    PRIMARY KEY (id)
);

-- Tabela transcricao está vazia

-- ========================================
-- TABELA: transcricoes_audio
-- ========================================

DROP TABLE IF EXISTS transcricoes_audio CASCADE;
CREATE TABLE transcricoes_audio (
    id VARCHAR(255) NOT NULL,
    filename VARCHAR(500) NOT NULL,
    file_size BIGINT NOT NULL,
    file_type VARCHAR(10) NOT NULL,
    user_id INTEGER NOT NULL,
    status VARCHAR(20) DEFAULT 'processing'::character varying,
    speaker_detection BOOLEAN DEFAULT true,
    speaker_count INTEGER DEFAULT 15,
    transcript_data TEXT,
    duration DOUBLE PRECISION,
    error_message TEXT,
    started_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,
    completed_at TIMESTAMP,
    created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,
    updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,
    PRIMARY KEY (id)
);

-- Tabela transcricoes_audio está vazia

-- ========================================
-- TABELA: transcricoes_video
-- ========================================

DROP TABLE IF EXISTS transcricoes_video CASCADE;
CREATE TABLE transcricoes_video (
    id INTEGER NOT NULL DEFAULT nextval('transcricoes_video_id_seq'::regclass),
    filename VARCHAR(255),
    file_size INTEGER,
    file_type VARCHAR(50),
    transcript_id VARCHAR(100),
    status VARCHAR(50),
    text TEXT,
    confidence DOUBLE PRECISION,
    duration INTEGER,
    audio_duration DOUBLE PRECISION,
    speaker_count INTEGER,
    word_count INTEGER,
    utterance_count INTEGER,
    summary TEXT,
    summary_type VARCHAR(50),
    config JSONB,
