-- ========================================
-- TABELA: transcript_words
-- ========================================

DROP TABLE IF EXISTS transcript_words CASCADE;
CREATE TABLE transcript_words (
    id INTEGER NOT NULL DEFAULT nextval('transcript_words_id_seq'::regclass),
    transcricao_id INTEGER,
    speaker_segment_id INTEGER,
    word VARCHAR(255),
    start_time INTEGER,
    end_time INTEGER,
    confidence DOUBLE PRECISION,
    speaker VARCHAR(50),
    punctuated_word VARCHAR(255),
    PRIMARY KEY (id)
);

-- Tabela transcript_words está vazia

-- ========================================
-- TABELA: user
-- ========================================

DROP TABLE IF EXISTS user CASCADE;
CREATE TABLE user (
    id INTEGER NOT NULL DEFAULT nextval('user_id_seq'::regclass),
    username VARCHAR(64) NOT NULL,
    email VARCHAR(120) NOT NULL,
    password_hash VARCHAR(256) NOT NULL,
    first_name VARCHAR(64),
    last_name VARCHAR(64),
    active BOOLEAN,
    is_admin BOOLEAN,
    last_login TIMESTAMP,
    created_at TIMESTAMP,
    updated_at TIMESTAMP,
    role_id INTEGER,
    PRIMARY KEY (id)
);

INSERT INTO user (user) VALUES ('neondb_owner');

-- ========================================
-- TABELA: validacao_multi_agente
-- ========================================

DROP TABLE IF EXISTS validacao_multi_agente CASCADE;
CREATE TABLE validacao_multi_agente (
    id VARCHAR(36) NOT NULL,
    codigo_validacao VARCHAR(20) NOT NULL,
    usuario_id INTEGER NOT NULL,
    data_criacao TIMESTAMP,
    data_atualizacao TIMESTAMP,
    documento_original TEXT NOT NULL,
    documento_nome VARCHAR(255),
    documento_tipo VARCHAR(100),
    agentes_utilizados JSON NOT NULL,
    total_agentes INTEGER NOT NULL,
    areas_juridicas JSON NOT NULL,
    status VARCHAR(30),
    status_mensagem VARCHAR(500),
    tempo_processamento INTEGER,
    opiniao_consolidada TEXT,
    pontos_criticos JSON,
    recomendacoes_gerais TEXT,
    configuracoes JSON,
    PRIMARY KEY (id)
);

-- Tabela validacao_multi_agente está vazia

-- ========================================
-- TABELA: validacao_multi_agente_analise
-- ========================================

DROP TABLE IF EXISTS validacao_multi_agente_analise CASCADE;
CREATE TABLE validacao_multi_agente_analise (
    id INTEGER NOT NULL DEFAULT nextval('validacao_multi_agente_analise_id_seq'::regclass),
    uuid_analise VARCHAR(36) NOT NULL,
    hash_sha256 VARCHAR(64) NOT NULL,
    numero_registro VARCHAR(20) NOT NULL,
    titulo_analise VARCHAR(200) NOT NULL,
    descricao TEXT,
    user_id INTEGER NOT NULL,
    documento_original TEXT NOT NULL,
    documento_nome VARCHAR(255),
    documento_tipo VARCHAR(50),
    documento_tamanho INTEGER,
    total_agentes_utilizados INTEGER NOT NULL,
    areas_juridicas_envolvidas JSON NOT NULL,
    configuracao_analise JSON,
    resultados_agentes JSON NOT NULL,
    opiniao_consolidada TEXT,
    pontos_criticos JSON,
    recomendacoes_prioritarias JSON,
    recomendacoes_importantes JSON,
    recomendacoes_sugeridas JSON,
    tempo_processamento_segundos DOUBLE PRECISION,
    modelos_ia_utilizados JSON,
    tokens_consumidos INTEGER,
    custo_estimado DOUBLE PRECISION,
    status VARCHAR(20),
    status_mensagem TEXT,
    fallback_mode BOOLEAN,
    debug_mode BOOLEAN,
    data_criacao TIMESTAMP,
    data_atualizacao TIMESTAMP,
    data_conclusao TIMESTAMP,
    exportado_pdf BOOLEAN,
    data_ultima_exportacao TIMESTAMP,
    exportado_docx BOOLEAN DEFAULT false,
    exportado_txt BOOLEAN DEFAULT false,
    PRIMARY KEY (id)
);

INSERT INTO validacao_multi_agente_analise (id, uuid_analise, hash_sha256, numero_registro, titulo_analise, descricao, user_id, documento_original, documento_nome, documento_tipo, documento_tamanho, total_agentes_utilizados, areas_juridicas_envolvidas, configuracao_analise, resultados_agentes, opiniao_consolidada, pontos_criticos, recomendacoes_prioritarias, recomendacoes_importantes, recomendacoes_sugeridas, tempo_processamento_segundos, modelos_ia_utilizados, tokens_consumidos, custo_estimado, status, status_mensagem, fallback_mode, debug_mode, data_criacao, data_atualizacao, data_conclusao, exportado_pdf, data_ultima_exportacao, exportado_docx, exportado_txt) VALUES (11, 'f178b160-a138-4235-9b5d-d266f4a51a3e', '92d71d8a379e18e3fdac4c26968159549601519d7d2689d98dbbafacc0c8802f', 'REG-1758212294', 'Análise Multi-Agente - 1758212294323', 'Análise realizada através da interface de validação multi-agente expandida', 1, '



INSTRUMENTO PARTICULAR DE CONTRATO DE PRESTAÇÃO DE SERVIÇOS, QUE ENTRE SI FAZEM xxxxxxxxx& xxxxxxx E MAYMIDIA SERVIÇOS E MARKETING


com sede à Rua xxxxxxxxxx,xxxx, Porto Alegre/RS, inscrita no CNPJ/MF sob nº xx.xxx.xxx/xxxxxx neste ato representada por xxxxxxxx inscrita no CPF xxx.xxx.xxx-xx, doravante denominada CONTRATANTE, e a MAYMIDIA, com sede à Rua Furriel Luiz Antônio de Vargas, 250, Conj 403, Bairro Bela Vista, CEP 90.470-130, Porto Alegre/RS, inscrita no CNPJ/MF sob nº 47.856.359/0001-29, neste ato representada por Karina Ribeiro Guazzelli May, brasileira, empresária, CPF 824.714.360-72, doravante denominada CONTRATADA, têm entre si, justo e acertado, o presente CONTRATO DE PRESTAÇÃO DE SERVIÇOS DE MARKETING DIGITAL, de acordo com as seguintes cláusulas e condições:

DO OBJETO

É objeto do presente contrato a PRESTAÇÃO DE SERVIÇOS DE MARKETING DIGITAL por parte da CONTRATADA para promover os serviços da CONTRATANTE.

DAS OBRIGAÇÕES DA CONTRATADA

Durante a vigência desse contrato, a CONTRATADA obriga-se a:

Realizar reuniões presenciais ou virtuais previamente agendadas para realização das atividades necessárias à prestação de serviços;

Executar os serviços contratados com observância das normas legais aplicáveis;

Adquirir e configurar o provedor de hospedagem contratado (contrato de 12 meses do provedor) conforme proposta comercial anexa a este contrato;

Criação do Site e página de blog entregue ajustados para SEO (incluindo Políticas de Privacidade, Termos de Uso e Cookie Banner adequado as normas da LGPD conforme proposta comercial anexa a este contrato;















DAS OBRIGAÇÕES DA CONTRATANTE

Durante a vigência desse contrato, a CONTRATANTE obriga-se a:

Realizar reuniões presenciais ou virtuais previamente agendadas, para realização das atividades necessárias à prestação de serviços;

Cumprir com as atribuições que lhe forem destinadas pela CONTRATADA para a adequada prestação dos serviços;

Fornecer o material (textos, imagens, vídeos e demais informações) necessário para o adequado desenvolvimento dos serviços contratados;

Efetuar os pagamentos devidos à CONTRATADA nos prazos e condições estabelecidas neste instrumento. Em caso de atraso superior a 10 dias no pagamento, a CONTRATADA pode optar por suspender a prestação dos serviços, retomando-a após a regularização.

DA CONFIDENCIALIDADE

O objeto deste contrato, a CONTRATANTE e os resultados obtidos farão parte do portifólio da CONTRATADA, com o intuito de servirem como referência para serviços já prestados, podendo ser divulgados com o uso de marcas da CONTRATANTE, seja durante ou após o término/rescisão deste CONTRATO.

Resguardando-se o presente no item 4.1, é vedado às PARTES reproduzir ou comunicar a terceiros dados de qualquer dos instrumentos deste CONTRATO sem o consentimento prévio e por escrito da outra PARTE.

Resguardando-se o presente no item 4.1, as PARTES devem guardar sigilo sobre os dados e informações de que tomarem conhecimento em função do CONTRATO, responsabilizando-se por quaisquer danos de qualquer natureza causados à parte prejudicada. 

Não obstante o término do prazo contratual, as obrigações de confidencialidade acima mencionadas permanecerão em vigor pelo prazo de 01 (um) ano a contar da data do encerramento deste CONTRATO.

DO PREÇO 

Pela prestação de serviços objeto deste contrato, a CONTRATANTE deverá pagar à CONTRATADA o valor de R$ 12.678,00 (doze mil seiscentos e setenta e oito reais), sendo entrada de R$ 4.226.00 (quatro mil duzentos e vinte e seis reais) mediante a assinatura deste contrato e mais duas parcela de R$ 4.226.00 (quatro mil duzentos e vinte e seis reais)  em 30 dias.





DO CRONOGRAMA

O planejamento dos serviços constantes na proposta comercial, está previsto para ser realizado em até 20 (vinte) dias úteis após o recebimento das informações e materiais necessários. A partir daí, têm início a sua execução e controle.

DO PRAZO E RESCISÃO

Este contrato tem vigência de 1 (mês) ou até a total entrega dos serviços contratados, podendo ser rescindido conforme itens 7.2, 7.3 

A CONTRATANTE poderá, mediante comunicação por escrito, rescindir o presente contrato sem ônus para a mesma, na hipótese de a CONTRATADA não cumprir com as suas obrigações previstas no presente CONTRATO.

A CONTRATADA poderá, mediante comunicação por escrito, rescindir o presente CONTRATO na hipótese de atraso da CONTRATANTE no pagamento valores faltantes e reserva o direito legal de suspender os serviços de forma total ou parcial até a regularização do débito. 


DAS DISPOSIÇÕES GERAIS

Os procedimentos operacionais deverão ser executados de acordo com os padrões e as normas estabelecidas de comum acordo entre a CONTRATANTE e a CONTRATADA.

Esta proposta contempla a realização das atividades em Porto Alegre. Em caso de necessidade de viagens para outras localidades, os custos envolvidos são responsabilidade da CONTRATANTE.


DA FORÇA MAIOR OU CASO FORTUITO

Nenhuma das partes poderá ser responsabilizada pela falta de cumprimento de suas obrigações contratuais, na efetiva e comprovada ocorrência de caso fortuito ou força maior, na forma do artigo 393 do Código Civil. 












DO FORO

Fica eleito o FORO da Porto Alegre, estado do Rio Grande do Sul, com expressa renúncia a qualquer outro por mais privilegiado que seja ou venha ser, para dirimir e solucionar eventuais dúvidas, questões ou litígios oriundos do presente instrumento.


E por estarem assim justos e contratados, obrigam-se por si e seus sucessores, assinam o presente instrumento. 


Porto Alegre 10 de Julho de 2023.



Pela CONTRATANTE:				Pela CONTRATADA:

Camila Steinmetz	                                          Karina Guazzelli May







    					



























Proposta Comercial


Esta proposta contempla o planejamento e execução e dos 
seguintes serviços:

1 - Domínio e Hospedagem

Configuração e apontamento de 
DNS do domínio, contratação, instalação e configuração do site 
junto ao provedor de hospedagem. 


2 - Criação do Site

Criação do site e página de blog, bem como sua otimização SEO, buscando a máxima 
experiência do usuário e classificação nos motores de busca do 
Google. Tratamento, adequação e otimização de fotos e imagens 
que serão usadas na criação das páginas).

• Hospedagem Wordpress Pro em servidor no Brasil com alta 
capacidade de memória, IP e recursos dedicados proporcionando 
melhor experiência aos visitantes;

• Criação, programação e otimização das páginas para terem 
melhor tempo de resposta e carregamento através de técnicas 
de super cache;
', 'documento_validacao.txt', 'text/plain', 6772, 3, '{Direito Empresarial}', NULL, '{{"agente": "Especialista em Aposentadoria Especial Empresarial (OPENAI)", "api_provider": "OPENAI", "color": "#28a745", "icon": "fas fa-robot", "modelo_usado": "gpt-4o", "resultado": "Para realizar uma análise jurídica detalhada do instrumento particular de contrato de prestação de serviços apresentado, é necessário considerar vários aspectos jurídicos, identificar potenciais riscos e propor recomendações específicas. A análise será fundamentada no Código Civil Brasileiro e em normas pertinentes.\n\n### 1. Aspectos Jurídicos Relevantes\n\n#### a. Natureza do Contrato\nEste contrato é caracterizado como um contrato de prestação de serviços, regido pelos artigos 593 a 609 do Código Civil Brasileiro. É importante que o contrato esteja claro quanto às obrigações das partes, prazo de execução, preço e condições de pagamento.\n\n#### b. Obrigações das Partes\nO contrato especifica as obrigações tanto da CONTRATADA quanto da CONTRATANTE, detalhando os serviços a serem prestados e os materiais a serem fornecidos. É essencial que ambas as partes cumpram com suas obrigações para evitar rescisão ou penalidades.\n\n#### c. Confidencialidade\nO contrato contém cláusula de confidencialidade, o que é crucial para proteger informações sensíveis. Esta cláusula deve ser rigorosamente observada, com penalidades claras para eventuais quebras.\n\n#### d. Rescisão\nAs condições de rescisão estão claramente delineadas, permitindo a rescisão por ambas as partes sob certas circunstâncias, como inadimplência ou descumprimento de obrigações.\n\n#### e. Foro\nFoi eleito o foro de Porto Alegre/RS para dirimir eventuais disputas, conforme permitido pelo artigo 111 do Código de Processo Civil, que permite a escolha do foro pelas partes.\n\n### 2. Riscos Identificados\n\n#### a. Inadimplência\nO risco de inadimplência é presente, especialmente no que tange ao pagamento dos valores devidos pela CONTRATANTE. O contrato prevê a possibilidade de suspensão dos serviços em caso de atraso, mas é importante estar atento à legislação sobre cobrança e suspensão de serviços.\n\n#### b. Confidencialidade e Uso Indevido de Informações\nMesmo com a cláusula de confidencialidade em vigor, existe o risco de vazamento ou uso indevido de informações. Medidas adicionais de segurança e clareza sobre penalidades podem mitigar este risco.\n\n#### c. Cláusulas Abusivas\nÉ importante garantir que não existam cláusulas que possam ser consideradas abusivas ou que coloquem uma das partes em desvantagem significativa, conforme o Código de Defesa do Consumidor, caso aplicável.\n\n### 3. Recomendações Específicas\n\n#### a. Revisão das Cláusulas de Confidencialidade\nRecomenda-se uma revisão detalhada das cláusulas de confidencialidade para garantir que estejam de acordo com a Lei Geral de Proteção de Dados (LGPD), estabelecendo claramente as responsabilidades em caso de vazamento de dados.\n\n#### b. Clareza no Cronograma e Prazos\nOs prazos devem ser claros e bem definidos, incluindo possíveis penalidades por atraso na entrega dos serviços. Isso pode evitar disputas sobre cronogramas não cumpridos.\n\n#### c. Atualização das Cláusulas de Rescisão\nAs cláusulas de rescisão devem ser revisadas para garantir que estão de acordo com a legislação vigente e que protegem ambas as partes de maneira justa.\n\n### 4. Fundamentação Legal\n\n- **Código Civil Brasileiro** (Lei nº 10.406/2002): Regras gerais sobre contratos, incluindo prestação de serviços (artigos 593 a 609).\n- **Lei Geral de Proteção de Dados (LGPD)** (Lei nº 13.709/2018): Normas sobre o tratamento de dados pessoais, especialmente relevantes para a cláusula de confidencialidade.\n- **Código de Defesa do Consumidor** (Lei nº 8.078/1990): Aplicável caso a relação entre as partes se configure como relação de consumo, impondo exigências de clareza e equilíbrio contratual.\n- **Código de Processo Civil** (Lei nº 13.105/2015): Regras sobre a eleição de foro (artigo 111).\n\nA análise jurídica deve ser realizada considerando as especificidades de cada contrato e as circunstâncias das partes envolvidas. É sempre recomendável a consulta com um advogado especializado para uma avaliação mais profunda e personalizada.", "status": "sucesso", "tokens_usados": 2490}, {"agente": "Especialista em RPPS Empresarial (ANTHROPIC)", "api_provider": "ANTHROPIC", "color": "#ff6b35", "icon": "fas fa-brain", "modelo_usado": "claude-3-5-sonnet-20241022", "resultado": "Análise Jurídica Especializada - Contrato de Prestação de Serviços de Marketing Digital\n\n1. ASPECTOS JURÍDICOS RELEVANTES:\n\na) Identificação das partes e objeto\n- Contrato bem estruturado com identificação clara das partes\n- Objeto definido: prestação de serviços de marketing digital\n- Valor e forma de pagamento estabelecidos\n\nb) Conformidade Legal\n- Atende requisitos básicos do Art. 104 do Código Civil\n- Incorpora aspectos da LGPD (menção a políticas de privacidade)\n- Possui cláusulas essenciais (objeto, preço, prazo, obrigações)\n\n2. RISCOS IDENTIFICADOS:\n\na) Ausência de especificações técnicas detalhadas\n- Falta detalhamento das especificações dos serviços\n- Ausência de SLA (Service Level Agreement)\n- Métricas de qualidade não definidas\n\nb) Vulnerabilidades contratuais\n- Prazo de vigência curto (1 mês) x cronograma de 20 dias úteis\n- Ausência de cláusula sobre propriedade intelectual\n- Multas e penalidades não especificadas\n\n3. RECOMENDAÇÕES:\n\na) Inclusões necessárias:\n- Definir SLA e métricas de qualidade\n- Incluir cláusula de propriedade intelectual\n- Estabelecer multas e penalidades\n- Ajustar prazo de vigência para compatibilizar com cronograma\n\nb) Ajustes sugeridos:\n- Detalhar especificações técnicas\n- Incluir cláusula de não vinculação trabalhista\n- Especificar procedimentos de aceite dos serviços\n- Incluir cláusula de compliance/anticorrupção\n\n4. FUNDAMENTAÇÃO LEGAL:\n\n- Código Civil (Lei 10.406/2002):\n  • Art. 104 - Requisitos de validade\n  • Art. 393 - Força maior/caso fortuito\n  • Art. 421 - Função social do contrato\n\n- Lei Geral de Proteção de Dados (Lei 13.709/2018):\n  • Art. 7º - Bases legais para tratamento\n  • Art. 46 - Medidas de segurança\n\n- Marco Civil da Internet (Lei 12.965/2014):\n  • Art. 7º - Direitos dos usuários\n  • Art. 10 - Proteção de registros\n\nEste contrato necessita de ajustes para maior segurança jurídica das partes, especialmente quanto a especificações técnicas e proteção de direitos. Recomenda-se revisão e complementação conforme pontos indicados.", "status": "sucesso", "tokens_usados": 2847}, {"agente": "Risco Societário - Consultor (GEMINI)", "api_provider": "GEMINI", "color": "#4285f4", "icon": "fas fa-search", "modelo_usado": "gemini-1.5-pro", "resultado": "## Análise Jurídica do Contrato de Prestação de Serviços de Marketing Digital\n\n**1. Aspectos Jurídicos Relevantes:**\n\n* **Natureza do Contrato:** Trata-se de um contrato de prestação de serviços, regido pelo Código Civil, especificamente pelos artigos 593 a 609.\n* **Objeto:** Prestação de serviços de marketing digital, incluindo criação de site, blog, hospedagem e otimização para mecanismos de busca (SEO).\n* **Obrigações das Partes:** O contrato define as obrigações da Contratada (Maymidia) e da Contratante, estabelecendo responsabilidades recíprocas.\n* **Preço e Forma de Pagamento:** O valor total é definido, assim como a forma de pagamento, com previsão de entrada e parcelamento.\n* **Cronograma:** Há previsão de prazo para realização dos serviços, condicionado ao recebimento das informações e materiais pela Contratada.\n* **Prazo e Rescisão:** O contrato prevê prazo de vigência de 1 mês ou até a entrega dos serviços, com possibilidade de rescisão por descumprimento das obrigações ou atraso nos pagamentos.\n* **Confidencialidade:**  Há cláusula de confidencialidade, com ressalva para a utilização do projeto no portfólio da Contratada.\n* **Foro:**  Eleição de foro em Porto Alegre/RS.\n\n**2. Riscos Identificados:**\n\n* **Objeto pouco específico:** A descrição do objeto do contrato é genérica ("prestação de serviços de marketing digital").  Falta detalhamento das atividades a serem executadas, métricas de sucesso,  e definição clara dos entregáveis.  Isso pode gerar conflitos sobre o escopo dos serviços.\n* **Cronograma vago:** O cronograma está atrelado ao recebimento das informações da Contratante, sem prazos específicos para a Contratada.  Isso pode causar atrasos e dificultar a responsabilização.\n* **Cláusula de confidencialidade contraditória:** A cláusula permite a utilização dos resultados no portfólio da Contratada, mesmo com informações da Contratante, criando uma contradição com a obrigação de sigilo.  É necessário especificar quais informações serão divulgadas e obter autorização expressa da Contratante.\n* **Prazo curto e impreciso:** O prazo de 1 mês ou até a entrega dos serviços é impreciso e pode ser insuficiente para um projeto de marketing digital, especialmente sem um cronograma detalhado.\n* **Falta de previsão de penalidades:**  Não há previsão de multas ou penalidades para o caso de descumprimento das obrigações por qualquer das partes, exceto a possibilidade de rescisão.\n* **Proposta comercial anexa:** A menção a uma proposta comercial anexa, sem sua inclusão no documento analisado, dificulta a compreensão integral dos serviços contratados e gera insegurança jurídica.\n* **Ausência de SLA (Service Level Agreement):** A falta de um SLA prejudica a mensuração da qualidade dos serviços prestados e a definição de níveis de serviço aceitáveis.\n\n\n**3. Recomendações Específicas:**\n\n* **Especificar o objeto:** Detalhar as atividades de marketing digital a serem realizadas (ex: gestão de redes sociais, campanhas de anúncios, produção de conteúdo, etc.), incluindo métricas, KPIs e entregáveis.\n* **Definir um cronograma preciso:**  Estabelecer prazos específicos para cada etapa do projeto, independentemente do recebimento de informações da Contratante. Criar um fluxo de trabalho com prazos para ambas as partes.\n* **Revisar a cláusula de confidencialidade:** Especificar quais informações podem ser utilizadas no portfólio da Contratada e obter autorização expressa da Contratante para divulgação de qualquer dado ou material.  Considerar a inclusão de um Acordo de Confidencialidade (NDA) separado.\n* **Estabelecer um prazo mais realista:**  Ajustar o prazo de vigência do contrato para um período compatível com a complexidade do projeto.\n* **Prever penalidades:** Incluir cláusulas que prevejam multas ou outras penalidades para o caso de descumprimento das obrigações por qualquer das partes.\n* **Incorporar a proposta comercial:** Anexar a proposta comercial ao contrato ou, preferencialmente, incorporar seu conteúdo diretamente no corpo do documento, evitando ambiguidades.\n* **Incluir um SLA:** Definir os níveis de serviço esperados, métricas de desempenho e procedimentos para o caso de descumprimento dos SLAs.\n\n\n**4. Fundamentação Legal:**\n\n* **Código Civil (Lei nº 10.406/2002):** Artigos 186, 187, 393, 422, 593 a 609 (especialmente 598 e 599).\n* **Lei Geral de Proteção de Dados (Lei nº 13.709/2018):**  Considerando a menção à LGPD no contrato, é importante garantir a conformidade com a lei, principalmente em relação à coleta, utilização e armazenamento de dados pessoais.\n\n\n**Conclusão:**\n\nO contrato apresentado possui pontos que precisam ser revisados e aprimorados para garantir maior segurança jurídica para ambas as partes. A implementação das recomendações acima contribuirá para a mitigação dos riscos identificados e para o estabelecimento de uma relação contratual mais clara, equilibrada e eficaz.  Recomenda-se a consultoria de um advogado especializado para a revisão e adequação do contrato antes de sua assinatura.\n", "status": "sucesso", "tokens_usados": 1500}}', NULL, NULL, '[]', '[]', '[]', 15.0, '{gpt-4o", "claude-3-5-sonnet-20241022", "gemini-1.5-pro}', 6837, 0.6837, 'concluida', NULL, FALSE, FALSE, '2025-09-18 16:18:14.101998', '2025-09-18 16:18:14.102003', NULL, FALSE, NULL, FALSE, FALSE);

-- ========================================
-- TABELA: versao_documento
