DROP TABLE IF EXISTS versao_documento CASCADE;
CREATE TABLE versao_documento (
    id INTEGER NOT NULL DEFAULT nextval('versao_documento_id_seq'::regclass),
    documento_id INTEGER NOT NULL,
    numero_versao INTEGER NOT NULL,
    conteudo TEXT NOT NULL,
    conteudo_html TEXT,
    comentario VARCHAR(255),
    usuario_id INTEGER NOT NULL,
    data_criacao TIMESTAMP,
    hash_conteudo VARCHAR(64),
    PRIMARY KEY (id)
);

-- Tabela versao_documento está vazia


